// Purge all legacy client-side caches immediately on load (100% Live DB Mode)
(function purgeLegacyLocalCaches() {
    try {
        const keysToRemove = [];
        for (let i = 0; i < localStorage.length; i++) {
            const key = localStorage.key(i);
            if (key && (key.startsWith('cm_cache_') || key.startsWith('offline_sync_') || key.startsWith('cm_pending_'))) {
                keysToRemove.push(key);
            }
        }
        keysToRemove.forEach(k => localStorage.removeItem(k));
        if (keysToRemove.length > 0) {
            console.log(`🧹 [LiveMode] Purged ${keysToRemove.length} legacy local cache keys. 100% Live DB Mode Active.`);
        }
    } catch (e) { }
})();

try {
    const rawUser = localStorage.getItem('user');
    if (rawUser && !window.currentUser) {
        window.currentUser = JSON.parse(rawUser);
    }
} catch (e) { }

