let isDatabaseConnected = false;
let isCheckingDb = false;

// ==========================================================================
// ==========================================================================
// UNIVERSAL FULL-SCREEN LOADING OVERLAY & REQUEST TRACKER
// "jab data load hota hai tab uper ek green line chalti hai , ham chahte ki
//  full screen overlay loding animetin chale aur ye universal ho har cheej ke
//  liye jab bhi data laod ho"
// ==========================================================================
let activeRequestsCount = 0;
let topProgressAnimationTimer = null;
let currentProgressWidth = 0;
let dataLoadStartTime = 0;
let dataLoadFadeTimeout = null;
const MIN_LOADER_DISPLAY_MS = 280; // Smooth perception without flicker

function getContextualLoadingText(url, method = 'GET') {
    const u = (url || '').toLowerCase();
    const m = (method || 'GET').toUpperCase();

    if (m === 'POST' || m === 'PUT' || m === 'DELETE' || m === 'PATCH') {
        if (u.includes('/api/customers')) return { title: 'Grahak Data Save Ho Raha Hai...', msg: 'Live database me customer record darz ho raha hai...' };
        if (u.includes('/api/csc')) return { title: 'CSC Aavedan Save Ho Raha Hai...', msg: 'Work Tracker aur fees details sync ho rahi hain...' };
        if (u.includes('/api/transactions')) return { title: 'Transaction Save Ho Rahi Hai...', msg: 'Rokad khata aur balance live update ho raha hai...' };
        if (u.includes('/api/bills') || u.includes('/api/billing')) return { title: 'Bill / Invoice Process Ho Raha Hai...', msg: 'Invoice generate ho kar account me jud raha hai...' };
        return { title: 'Data Surakshit Process Ho Raha Hai...', msg: 'Real-time database me record update ho raha hai...' };
    }

    if (u.includes('/api/customers')) return { title: 'Grahak Data Load Ho Raha Hai...', msg: 'Customer directory aur hisaab-kitaab sync ho raha hai...' };
    if (u.includes('/api/csc')) return { title: 'CSC Sewayein Load Ho Rahi Hain...', msg: 'Work Tracker aavedan aur services sync ho rahe hain...' };
    if (u.includes('/api/transactions')) return { title: 'Transactions Load Ho Rahi Hain...', msg: 'Len-den rokad bahi live fetch ho rahi hai...' };
    if (u.includes('/api/reports')) return { title: 'Reports & Analytics Load Ho Rahi Hain...', msg: 'Audit data aur hisaab-kitaab generate ho raha hai...' };
    if (u.includes('/api/daybook')) return { title: 'Day Book Load Ho Rahi Hai...', msg: 'Aaj ki rokad aur cash-flow aa raha hai...' };
    if (u.includes('/api/khata')) return { title: 'Khatabook Ledger Load Ho Raha Hai...', msg: 'Customer ka master khata hisaab sync ho raha hai...' };
    if (u.includes('/api/accounts')) return { title: 'Bank Khate Load Ho Rahe Hain...', msg: 'Bank balance aur cash accounts sync ho rahe hain...' };
    if (u.includes('/api/documents')) return { title: 'Documents Vault Load Ho Raha Hai...', msg: 'Surakshit dastavez fetch ho rahe hain...' };
    if (u.includes('/api/database')) return { title: 'Database Live Table Load Ho Rahi Hai...', msg: 'SQLite database tables se live data aa raha hai...' };
    if (u.includes('/api/search')) return { title: 'Data Khoja Ja Raha Hai...', msg: 'Live database me search query run ho rahi hai...' };

    return { title: 'Data Load Ho Raha Hai...', msg: 'Live database se taja data prapt kiya ja raha hai...' };
}

function startUniversalLoading(url = '', method = 'GET') {
    // Suppress generic data loader during system update or post-update boot splash
    if (typeof sessionStorage !== 'undefined' && sessionStorage.getItem('cmbc_update_in_progress')) {
        return;
    }
    if (typeof document !== 'undefined' && (document.getElementById('cmbc-post-update-splash') || document.getElementById('cmbcUpdateWizardModal'))) {
        return;
    }
    const lSettings = typeof getCustomLoaderSettings === 'function' ? getCustomLoaderSettings() : { enabled: true, onDataLoad: true, duration: 0 };
    if (!lSettings.enabled || lSettings.speedMode === 'off' || lSettings.displayMode === 'none') {
        return;
    }

    activeRequestsCount++;
    const bar = document.getElementById('topProgressBar');
    if (bar) {
        bar.classList.add('active');
        bar.classList.remove('finishing');
    }

    const syncBadge = document.getElementById('fastSyncBadge');
    if (syncBadge) {
        syncBadge.classList.add('syncing');
        const txt = syncBadge.querySelector('.fsb-text');
        if (txt) txt.textContent = 'SYNCING';
    }

    if (activeRequestsCount === 1) {
        currentProgressWidth = 20;
        if (bar) bar.style.width = currentProgressWidth + '%';

        clearInterval(topProgressAnimationTimer);
        topProgressAnimationTimer = setInterval(() => {
            if (currentProgressWidth < 88) {
                currentProgressWidth += Math.max(0.6, (88 - currentProgressWidth) * 0.28);
                if (bar) bar.style.width = currentProgressWidth + '%';
            }
        }, 60);

        dataLoadStartTime = Date.now();
        clearTimeout(dataLoadFadeTimeout);
        const { title, msg } = getContextualLoadingText(url, method);
        if (lSettings.displayMode !== 'topbar_only' && lSettings.onDataLoad !== false && typeof showUniversalLoader === 'function') {
            showUniversalLoader(title, msg, true);
        }
    }
}

function finishUniversalLoading() {
    activeRequestsCount = Math.max(0, activeRequestsCount - 1);
    if (activeRequestsCount > 0) return;

    clearInterval(topProgressAnimationTimer);
    const bar = document.getElementById('topProgressBar');
    if (bar) {
        bar.style.width = '100%';
        bar.classList.add('finishing');
    }

    const syncBadge = document.getElementById('fastSyncBadge');
    if (syncBadge) {
        syncBadge.classList.remove('syncing');
        const txt = syncBadge.querySelector('.fsb-text');
        if (txt) txt.textContent = 'LIVE';
    }

    const lSettings = typeof getCustomLoaderSettings === 'function' ? getCustomLoaderSettings() : { enabled: true, duration: 0 };

    // If loader is turned OFF or display is none, immediately close without any delay
    if (!lSettings.enabled || lSettings.speedMode === 'off' || lSettings.displayMode === 'none') {
        if (typeof hideUniversalLoader === 'function') hideUniversalLoader(true);
        if (bar) {
            bar.classList.remove('active', 'finishing');
            bar.style.width = '0%';
            currentProgressWidth = 0;
        }
        return;
    }

    const isSystemSpeed = lSettings.speedMode === 'system' || (lSettings.duration || 0) <= 0;
    const elapsed = Date.now() - dataLoadStartTime;

    // Pure Real-Time System Speed: Sirf system jitna time lagaye utna hi chalega (0s extra wait)!
    if (isSystemSpeed) {
        clearTimeout(dataLoadFadeTimeout);
        if (typeof hideUniversalLoader === 'function') {
            hideUniversalLoader(true);
        }
        if (bar) {
            setTimeout(() => {
                if (activeRequestsCount === 0) {
                    bar.classList.remove('active', 'finishing');
                    bar.style.width = '0%';
                    currentProgressWidth = 0;
                }
            }, 80);
        }
        return;
    }

    // Fixed Timer / Custom Speed mode (e.g. 0.2s, 0.5s, 1s, etc.):
    const configuredTargetMs = (lSettings.duration || 1) * 1000;
    const remainingMs = Math.max(0, configuredTargetMs - elapsed);

    clearTimeout(dataLoadFadeTimeout);
    dataLoadFadeTimeout = setTimeout(() => {
        if (activeRequestsCount === 0) {
            const progressBarEl = document.getElementById('loaderProgressBar');
            const statusTextEl = document.getElementById('loaderStatusText');
            if (progressBarEl) progressBarEl.style.width = '100%';
            if (statusTextEl) statusTextEl.textContent = 'Data Load Ho Gaya ✓';

            setTimeout(() => {
                if (activeRequestsCount === 0) {
                    if (typeof hideUniversalLoader === 'function') {
                        hideUniversalLoader(true);
                    }
                    if (bar) {
                        bar.classList.remove('active', 'finishing');
                        bar.style.width = '0%';
                        currentProgressWidth = 0;
                    }
                }
            }, 60);
        }
    }, remainingMs);
}

// Global aliases for backward compatibility
const startTopLoading = startUniversalLoading;
const finishTopLoading = finishUniversalLoading;
const stopTopLoading = finishUniversalLoading;
window.startTopLoading = startUniversalLoading;
window.finishTopLoading = finishUniversalLoading;
window.stopTopLoading = finishUniversalLoading;
window.startUniversalLoading = startUniversalLoading;
window.finishUniversalLoading = finishUniversalLoading;

// 1. Monkey-Patch Global window.fetch for /api/ calls:
// Universal Full-Screen Loading Animation + 100% No-Cache + Auto DB Liveness
const nativeFetch = window.fetch;
window.fetch = async function (resource, init = {}) {
    init = init || {};
    init = { ...init };
    let url = typeof resource === 'string' ? resource : (resource && resource.url ? resource.url : '');
    const requestMethod = String((init && init.method) || (resource && resource.method) || 'GET').toUpperCase();
    const isMutation = !['GET', 'HEAD', 'OPTIONS'].includes(requestMethod);
    const isApiCall = typeof url === 'string' && (url.includes('/api/') || url.startsWith('/api') || url.includes('/api'));
    const isBackgroundApi = typeof url === 'string' && (
        url.includes('/api/health') ||
        url.includes('/api/sync/version') ||
        url.includes('/api/auth/me') ||
        url.includes('/api/app-version') ||
        url.includes('/api/system/check-update') ||
        url.includes('/api/system/update-status') ||
        url.includes('/api/license/status') ||
        url.includes('/api/logs') ||
        url.includes('/api/idempotency/') ||
        url.includes('/api/live-events') ||
        Boolean(init && init.silent) ||
        Boolean(init && init.headers && (init.headers['X-Silent-Load'] || (init.headers.get && init.headers.get('X-Silent-Load'))))
    );

    const resourceHeaders = typeof Request !== 'undefined' && resource instanceof Request ? resource.headers : undefined;
    const callerHeaders = new Headers(init.headers || resourceHeaders);
    const suppliedIdempotencyKey = callerHeaders.get('Idempotency-Key');
    const isOfflineReplay = init._offlineSyncReplay === true;
    const replayUserId = init._offlineSyncUserId;
    delete init._offlineSyncReplay;
    delete init._offlineSyncUserId;
    let preparedOfflineMutation = null;
    let loaderStarted = false;

    try {
        if (isApiCall && isMutation && suppliedIdempotencyKey) {
            if (!isOfflineReplay || !window.offlineSyncEngine ||
                !(await window.offlineSyncEngine.validateReplay({
                    idempotencyKey: suppliedIdempotencyKey,
                    userId: replayUserId,
                    method: requestMethod,
                    url,
                    body: init.body
                }))) {
                const error = new Error('Idempotent request was not found in the durable local queue; request was not sent.');
                error.offlineQueueBlocked = true;
                throw error;
            }
        } else if (isApiCall && isMutation && window.offlineSyncEngine &&
            typeof window.offlineSyncEngine.prepareMutation === 'function') {
            const prepared = await window.offlineSyncEngine.prepareMutation({
                url,
                method: requestMethod,
                body: init.body,
                headers: init.headers
            });
            if (prepared && prepared.blocked) {
                const error = new Error(prepared.reason || 'This mutation cannot be sent safely.');
                error.offlineQueueBlocked = true;
                throw error;
            }
            if (prepared && prepared.status === 'prepared') {
                preparedOfflineMutation = prepared;
                const headers = new Headers(init.headers || {});
                headers.set('Content-Type', 'application/json');
                headers.set('Idempotency-Key', prepared.idempotencyKey);
                headers.set('Authorization', prepared.authorization);
                init.headers = headers;
                init.method = prepared.method;
                url = prepared.url;
                resource = url;
            }
        }

        const headersFromResource = typeof Request !== 'undefined' && resource instanceof Request ? resource.headers : undefined;
        const requestHeaders = new Headers(init.headers || headersFromResource);
        const hasIdempotencyKey = requestHeaders.has('Idempotency-Key');

        // Intercept /api calls for Real-Time Fresh Data.
        if (isApiCall) {
            init.cache = 'no-store';
            // The keyed URL is part of the backend request hash. Keep it byte-for-byte
            // stable for the initial attempt and every replay.
            if (!hasIdempotencyKey) {
                const sep = url.includes('?') ? '&' : '?';
                url = `${url}${sep}_t=${Date.now()}`;
            }

            if (typeof resource === 'string') {
                resource = url;
            } else if (resource && typeof Request !== 'undefined') {
                resource = new Request(url, resource);
            }

            requestHeaders.set('Cache-Control', 'no-cache, no-store, must-revalidate');
            requestHeaders.set('Pragma', 'no-cache');
            requestHeaders.set('Expires', '0');
            init.headers = requestHeaders;
        }

        if (isApiCall && !isBackgroundApi) {
            startUniversalLoading(url, init.method || requestMethod);
            loaderStarted = true;
        }

        const response = await nativeFetch(resource, init);

        // Check for 503 or Database Down
        if (response.status === 503) {
            const clone = response.clone();
            try {
                const json = await clone.json();
                if (json.isDatabaseDown || (json.error && json.error.includes('DATABASE NOT CONNECTED'))) {
                    setDatabaseStatus(false, json.error);
                }
            } catch (e) { }
        } else if (!response.ok && response.status >= 400 && response.status !== 401 && !url.includes('/api/logs') && !url.includes('/api/health')) {
            // Auto capture API 4xx/5xx errors
            try {
                const clone = response.clone();
                clone.text().then(bodyText => {
                    if (typeof window.reportManualError === 'function') {
                        window.reportManualError(`API Error (${response.status}): ${url}`, new Error(`HTTP ${response.status}: ${bodyText ? bodyText.substring(0, 300) : response.statusText}`), { url, status: response.status, method: init.method || 'GET' });
                    }
                }).catch(() => { });
            } catch (e) { }
        }

        if (preparedOfflineMutation && window.offlineSyncEngine) {
            await window.offlineSyncEngine.handleResponse(preparedOfflineMutation, response.clone());
        }

        return response;
    } catch (err) {
        // Network drop or server unreachable
        if (isApiCall) {
            const errorText = String(err && err.message ? err.message : err);
            const isOffline = !navigator.onLine || /failed to fetch|networkerror|offline/i.test(errorText);
            if (!err.offlineQueueBlocked) {
                setDatabaseStatus(false, 'Server ya database se sampark toot gaya hai: ' + errorText);
            }
            if (preparedOfflineMutation && window.offlineSyncEngine) {
                await window.offlineSyncEngine.markUncertain(preparedOfflineMutation);
            } else if ((isOffline || err.offlineQueueBlocked) && isMutation && typeof window.showToast === 'function') {
                window.showToast(err.offlineQueueBlocked
                    ? `${errorText} No server request was sent.`
                    : 'Connection lost. Save outcome is unconfirmed; nothing was queued. Check the record before retrying.', 'error');
            }
            if (!isOffline && !url.includes('/api/logs') && typeof window.reportManualError === 'function') {
                window.reportManualError(`Network/Fetch Failed: ${url}`, err, { url, method: init.method || 'GET' });
            }
        }
        throw err;
    } finally {
        if (loaderStarted) {
            finishUniversalLoading();
        }
    }
};

function setDatabaseStatus(connected, errorMsg = '') {
    isDatabaseConnected = connected;
    const indicator = document.getElementById('dbLiveIndicator');
    const statusText = document.getElementById('dbStatusText');
    const fastSyncBadge = document.getElementById('fastSyncBadge');
    const overlay = document.getElementById('dbLockdownOverlay');
    const footerMsg = document.getElementById('dbLockdownFooter');

    if (connected) {
        document.body.style.overflow = '';
        if (indicator) {
            indicator.className = 'db-live-indicator connected';
            indicator.title = 'SQLite Live Database se connected hai (Real-time active)';
        }
        if (statusText) {
            statusText.textContent = 'LIVE DB';
            statusText.style.color = '';
        }
        if (fastSyncBadge) {
            fastSyncBadge.className = 'fast-sync-badge';
            fastSyncBadge.style.background = '';
            fastSyncBadge.style.border = '';
            const dot = fastSyncBadge.querySelector('.fsb-dot');
            if (dot) dot.style.background = '';
            const txt = fastSyncBadge.querySelector('.fsb-text');
            if (txt) {
                txt.textContent = 'LIVE';
                txt.style.color = '';
            }
        }
        if (overlay) overlay.style.display = 'none';
    } else {
        // DISCONNECTED / OFFLINE — STRICT DATABASE LOCKDOWN
        // Agar database nahi chal raha to project poori tarah se LOCK ho
        document.body.style.overflow = 'hidden';
        if (indicator) {
            indicator.className = 'db-live-indicator disconnected';
            indicator.title = errorMsg || 'Database connection is not confirmed. Project operations are locked.';
        }
        if (statusText) {
            statusText.textContent = 'DB NOT CONFIRMED';
            statusText.style.color = '#ef4444';
        }

        // Topbar badge: Red Lockdown Warning
        if (fastSyncBadge) {
            fastSyncBadge.className = 'fast-sync-badge offline-locked';
            fastSyncBadge.style.background = 'rgba(239, 68, 68, 0.15)';
            fastSyncBadge.style.border = '1.5px solid #ef4444';
            const dot = fastSyncBadge.querySelector('.fsb-dot');
            if (dot) dot.style.background = '#ef4444';
            const txt = fastSyncBadge.querySelector('.fsb-text');
            if (txt) {
                txt.textContent = '● DB NOT CONFIRMED (LOCKED)';
                txt.style.color = '#f87171';
            }
        }

        // Lockdown overlay sabhi screens/users ke liye block karega
        if (overlay) {
            overlay.style.display = 'flex';
            if (window.lucide) lucide.createIcons();
        }
        if (footerMsg && errorMsg) {
            footerMsg.textContent = errorMsg;
        }
    }
}

// Window global alias for lockdown modal
window.showDbLockdownModal = function (msg) {
    setDatabaseStatus(false, msg || 'SQLite database offline hai. Project operations lock hain.');
};

async function checkLiveDatabaseConnection(isManual = false) {
    if (isCheckingDb) return;
    isCheckingDb = true;

    const retryBtn = document.getElementById('dbRetryBtn');
    const footerMsg = document.getElementById('dbLockdownFooter');
    if (isManual && retryBtn) {
        retryBtn.disabled = true;
        retryBtn.innerHTML = '<i data-lucide="loader" class="spinner"></i> Connecting...';
        lucide.createIcons();
    }

    try {
        const res = await nativeFetch(`/api/health?_t=${Date.now()}`, { cache: 'no-store' });
        if (res.ok) {
            const data = await res.json();
            if (data.success && data.status === 'CONNECTED') {
                const wasPreviouslyDown = !isDatabaseConnected;
                setDatabaseStatus(true);
                if (isManual && typeof showToast === 'function') showToast('✅ Database Connected! Project unlocked.', 'success');
                // Reload master data and re-render active page if database was previously disconnected and has recovered!
                if (wasPreviouslyDown || isManual) {
                    if (typeof loadMasterData === 'function') await loadMasterData();
                    if (typeof showPage === 'function') {
                        showPage(currentPage || 'dashboard');
                    }
                }
                return true;
            }
        }
        const errJson = await res.json().catch(() => ({}));
        setDatabaseStatus(false, errJson.error || 'Database connection could not be confirmed.');
        return false;
    } catch (err) {
        setDatabaseStatus(false, 'Database connection could not be confirmed: ' + err.message);
        return false;
    } finally {
        isCheckingDb = false;
        if (retryBtn) {
            retryBtn.disabled = false;
            retryBtn.innerHTML = '<i data-lucide="rotate-ccw"></i> Dobara Connect Karein (Retry Connection)';
            lucide.createIcons();
        }
    }
}

// Dynamic Heartbeat Monitor:
// Jab DB down ho to har 4 second me auto-check karein taaki SQL Server chalu hote hi instant unlock ho jaye.
// Jab DB connected ho to har 15 second me background check karein.
let dbHeartbeatTimer = null;
function scheduleDbHeartbeat() {
    clearTimeout(dbHeartbeatTimer);
    const interval = isDatabaseConnected ? 15000 : 4000;
    dbHeartbeatTimer = setTimeout(async () => {
        try {
            await checkLiveDatabaseConnection(false);
        } catch (e) { }
        scheduleDbHeartbeat();
    }, interval);
}
scheduleDbHeartbeat();


// ==========================================================================
// REAL-TIME AUTO-UPDATE & SSE SYNC (ZERO REFRESH REQUIRED)
// "kisi bhi tranjectin karne par sab kuch auto update hoga realtime koi refresh karne ki jaroorat na pade"
// ==========================================================================

let isRefreshingViews = false;
let lastRefreshTimestamp = 0;
let refreshDebounceTimer = null;

// Universal Real-Time Refresh Function:
// Updates all active views, balances, tables, counters, pipelines and badges simultaneously
async function refreshAllActiveViews(source = '') {
    const now = Date.now();
    if (isRefreshingViews) return;
    if (now - lastRefreshTimestamp < 250) return;
    isRefreshingViews = true;
    lastRefreshTimestamp = now;

    try {
        const tasks = [];

        // 1. Refresh Master Data (Accounts list, categories, parties, sidebar total balance) in parallel
        if (typeof loadMasterData === 'function') {
            tasks.push(loadMasterData());
        }

        // 2. Always refresh bills count badge in background
        if (typeof loadBills === 'function' && currentPage !== 'bills') {
            tasks.push(loadBills());
        }

        // 3. Refresh Active Screen Data instantly (in parallel with master data)

        if (currentPage === 'dashboard' && typeof loadDashboard === 'function') {
            tasks.push(loadDashboard());
        } else if (currentPage === 'bc' && typeof loadBCDashboard === 'function') {
            tasks.push(loadBCDashboard());
            if (typeof currentBCViewTab !== 'undefined' && currentBCViewTab === 'settlement' && typeof loadSettlements === 'function') {
                tasks.push(loadSettlements());
            } else if (typeof loadBCTransactions === 'function') {
                tasks.push(loadBCTransactions(typeof currentBCPage !== 'undefined' ? currentBCPage : 1));
            }
        } else if (currentPage === 'transactions' && typeof loadTransactions === 'function') {
            tasks.push(loadTransactions(typeof currentTransPage !== 'undefined' ? currentTransPage : 1));
        } else if (currentPage === 'accounts' && typeof loadAccounts === 'function') {
            tasks.push(loadAccounts());
        } else if (currentPage === 'parties' && typeof loadParties === 'function') {
            tasks.push(loadParties());
        } else if (currentPage === 'budgets' && typeof loadBudgets === 'function') {
            tasks.push(loadBudgets());
        } else if (currentPage === 'bills' && typeof loadBills === 'function') {
            tasks.push(loadBills());
        } else if (currentPage === 'reports' && typeof loadReports === 'function') {
            tasks.push(loadReports());
        } else if (currentPage === 'customers' && typeof loadCustomersPage === 'function') {
            tasks.push(loadCustomersPage());
        } else if (currentPage === 'billing' && typeof loadBillingPage === 'function') {
            tasks.push(loadBillingPage());
        } else if (currentPage === 'khatabook' && typeof loadKhatabookPage === 'function') {
            tasks.push(loadKhatabookPage());
        } else if (currentPage === 'documents' && typeof loadDocumentsPage === 'function') {
            tasks.push(loadDocumentsPage(true));
        } else if (currentPage === 'csc' && typeof loadCSCPage === 'function') {
            tasks.push(loadCSCPage());
        }

        // Always update all sidebar badges across all sections from live SQL Server
        if (typeof updateAllSidebarBadges === 'function') {
            tasks.push(updateAllSidebarBadges());
        }

        await Promise.allSettled(tasks);
    } catch (e) {
        console.warn('Real-time auto-refresh warning:', e.message);
    } finally {
        isRefreshingViews = false;
        setTimeout(() => {
            if (typeof lucide !== 'undefined') lucide.createIcons();
        }, 60);
    }
}

function triggerRealTimeSync(source = 'local_action') {
    if (refreshDebounceTimer) clearTimeout(refreshDebounceTimer);
    refreshDebounceTimer = setTimeout(() => {
        refreshAllActiveViews(source);
    }, 80);

    // Multi-Tab Broadcast
    if (typeof BroadcastChannel !== 'undefined') {
        try {
            const bc = new BroadcastChannel('cash_mgmt_realtime_sync');
            bc.postMessage({ type: 'DATA_CHANGED', timestamp: Date.now(), source });
            setTimeout(() => bc.close(), 500);
        } catch (e) { }
    }
}

// Multi-Tab Listener
if (typeof BroadcastChannel !== 'undefined') {
    try {
        const listenBc = new BroadcastChannel('cash_mgmt_realtime_sync');
        listenBc.onmessage = (ev) => {
            if (ev.data && ev.data.type === 'DATA_CHANGED') {
                if (refreshDebounceTimer) clearTimeout(refreshDebounceTimer);
                refreshDebounceTimer = setTimeout(() => {
                    refreshAllActiveViews('multi_tab_sync');
                }, 100);
            }
        };
    } catch (e) { }
}

// Server-Sent Events (SSE) Live Real-Time Stream from Server
let sseConnection = null;
let sseStartTimer = null;
let sseReconnectTimer = null;
let sseStableTimer = null;
let sseReconnectAttempts = 0;
const SSE_RECONNECT_BASE_DELAY = 2000;
const SSE_RECONNECT_MAX_DELAY = 60000;

// The event stream is separate from the database health check.
function setLiveStreamIndicator(state, message = '') {
    const badge = document.getElementById('liveEventsBadge');
    const text = badge && badge.querySelector('.fsb-text');
    if (text) {
        text.textContent = state === 'connected' ? 'EVENTS CONNECTED' :
            state === 'offline' ? 'EVENTS UNAVAILABLE' : 'EVENTS RECONNECTING';
    }
    if (badge && message) badge.title = message;
}

function handleLiveEventMessage(event) {
    try {
        const data = JSON.parse(event.data);
        if (data.type === 'DATA_CHANGED') {
            if (refreshDebounceTimer) clearTimeout(refreshDebounceTimer);
            refreshDebounceTimer = setTimeout(() => {
                refreshAllActiveViews('sse_realtime');
            }, 80);
        } else if (data.type === 'UPDATE_PROGRESS' || (data.module === 'SYSTEM_UPDATE' && (data.stage || data.percent > 0))) {
            // Front-facing foreground wizard: auto-update background me nahi, user ke saamne aayega
            if (typeof window.showForegroundUpdateProgress === 'function') {
                window.showForegroundUpdateProgress(data);
            }
        } else if (data.type === 'UPDATE_AVAILABLE' || data.module === 'SYSTEM_UPDATE') {
            if (typeof renderUpdateBanner === 'function') {
                renderUpdateBanner(data);
            }
            if (typeof renderDashboardUpdateBanner === 'function') {
                renderDashboardUpdateBanner(data);
            }
        }
    } catch (err) { }
}

function closeLiveEventStream() {
    if (sseStartTimer) {
        clearTimeout(sseStartTimer);
        sseStartTimer = null;
    }
    if (sseReconnectTimer) {
        clearTimeout(sseReconnectTimer);
        sseReconnectTimer = null;
    }
    if (sseStableTimer) {
        clearTimeout(sseStableTimer);
        sseStableTimer = null;
    }
    if (sseConnection) {
        try { sseConnection.close(); } catch (e) { }
        sseConnection = null;
    }
}

function scheduleLiveEventReconnect() {
    if (sseReconnectTimer || sseConnection) return;
    sseReconnectAttempts++;
    const exponent = Math.min(sseReconnectAttempts - 1, 10);
    const delay = Math.min(SSE_RECONNECT_MAX_DELAY, SSE_RECONNECT_BASE_DELAY * (2 ** exponent));
    setLiveStreamIndicator('reconnecting', `Event updates reconnect in ${Math.round(delay / 1000)}s.`);
    sseReconnectTimer = setTimeout(() => {
        sseReconnectTimer = null;
        initLiveEventStream();
    }, delay);
}

function initLiveEventStream() {
    if (typeof EventSource === 'undefined') {
        setLiveStreamIndicator('offline', 'This browser does not support event updates.');
        return;
    }

    // Already live hai to naya connection mat banao (duplicate listeners avoid)
    if (sseConnection) {
        const state = sseConnection.readyState;
        if (state === EventSource.CONNECTING || state === EventSource.OPEN) return;
        try { sseConnection.close(); } catch (e) { }
        sseConnection = null;
    }
    if (sseReconnectTimer) {
        clearTimeout(sseReconnectTimer);
        sseReconnectTimer = null;
    }

    try {
        const es = new EventSource('/api/live-events');
        sseConnection = es;

        es.onopen = () => {
            if (sseConnection !== es) return;
            setLiveStreamIndicator('connected', 'Event stream connected; database status is checked separately.');
            if (sseStableTimer) clearTimeout(sseStableTimer);
            sseStableTimer = setTimeout(() => {
                if (sseConnection === es) sseReconnectAttempts = 0;
                sseStableTimer = null;
            }, 15000);
        };

        es.addEventListener('message', handleLiveEventMessage);

        es.onerror = () => {
            if (sseConnection !== es) return;
            try { es.close(); } catch (e) { }
            sseConnection = null;
            if (sseStableTimer) {
                clearTimeout(sseStableTimer);
                sseStableTimer = null;
            }
            scheduleLiveEventReconnect();
        };
    } catch (err) {
        console.warn('SSE stream init warning:', err.message);
        scheduleLiveEventReconnect();
    }
}

// Start SSE stream on load
sseStartTimer = setTimeout(() => {
    sseStartTimer = null;
    initLiveEventStream();
}, 300);

// Page unload / navigation par connection band karo (leak aur duplicate listener se bachao)
window.addEventListener('beforeunload', () => {
    closeLiveEventStream();
});


function fixMojibake(str) {
    if (!str || typeof str !== 'string') return str;
    return str
        .replace(/🔄/g, '🔄')
        .replace(/—/g, '—')
        .replace(/➡️[\s\u0080-\u009F\uFE0F]*/g, '➡️ ')
        .replace(/⬅️[\s\u0080-\u009F\uFE0F]*/g, '⬅️ ')
        .replace(/[\u0080-\u009F]/g, '');
}

function escapeHtml(str) {
    if (!str) return '';
    return fixMojibake(String(str))
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
}

// Inline onclick handler ke andar JS string argument ke liye safe escaping.
// escapeHtml sirf HTML ke liye hai: uska &#039; attribute decode hone par wapas
// ' ban jaata hai aur JS string se nikal jaata hai. Isliye yahan apostrophe
// backslash ke saath escape hota hai (JS level par) aur baaki HTML entities
// attribute ke andar rehne layak banaye jaate hain.
function escapeInlineArg(str) {
    if (str === null || str === undefined) return '';
    return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/\\/g, '\\\\')
        .replace(/'/g, "\\'")
        .replace(/\r/g, '\\r')
        .replace(/\n/g, '\\n');
}

// ============ DELEGATED CLICK HANDLERS (data-attribute based) ============
// Inline onclick string me data interpolate karna XSS ka raasta hai, isliye
// jahan bhi database se aaya data handler ko chahiye, wo data-* attribute
// me rakha jaata hai aur yahan ek hi delegated listener se handle hota hai.
let delegatedClickBound = false;
function bindDelegatedClickHandlers() {
    if (delegatedClickBound) return;
    delegatedClickBound = true;

    document.addEventListener('click', (e) => {
        const el = (e.target && typeof e.target.closest === 'function') ? e.target : null;
        if (!el) return;

        const delCustomerBtn = el.closest('[data-del-customer-id]');
        if (delCustomerBtn) {
            confirmDeleteCustomer(delCustomerBtn.dataset.delCustomerId, delCustomerBtn.dataset.delCustomerName || '');
            return;
        }

        const delInvoiceBtn = el.closest('[data-del-invoice-id]');
        if (delInvoiceBtn) {
            confirmDeleteInvoice(delInvoiceBtn.dataset.delInvoiceId, delInvoiceBtn.dataset.delInvoiceNumber || '');
            return;
        }

        const copyPhoneBtn = el.closest('[data-copy-phone]');
        if (copyPhoneBtn) {
            e.preventDefault();
            e.stopPropagation();
            copyPhoneToClipboard(copyPhoneBtn.dataset.copyPhone, {
                currentTarget: copyPhoneBtn,
                target: copyPhoneBtn,
                stopPropagation: () => { },
                preventDefault: () => { }
            });
            return;
        }

        const copyAadhaarBtn = el.closest('[data-copy-aadhaar]');
        if (copyAadhaarBtn) {
            e.preventDefault();
            e.stopPropagation();
            copyAadhaarToClipboard(copyAadhaarBtn.dataset.copyAadhaar, {
                currentTarget: copyAadhaarBtn,
                target: copyAadhaarBtn,
                stopPropagation: () => { },
                preventDefault: () => { }
            });
            return;
        }

        const copyDobBtn = el.closest('[data-copy-dob]');
        if (copyDobBtn) {
            e.preventDefault();
            e.stopPropagation();
            copyDOBToClipboard(copyDobBtn.dataset.copyDob, {
                currentTarget: copyDobBtn,
                target: copyDobBtn,
                stopPropagation: () => { },
                preventDefault: () => { }
            });
            return;
        }

        const copyTextBtn = el.closest('[data-copy-text]');
        if (copyTextBtn) {
            e.preventDefault();
            e.stopPropagation();
            if (typeof copyToClipboard === 'function') {
                copyToClipboard(copyTextBtn.dataset.copyText, copyTextBtn.dataset.copyLabel || 'Copy ho gaya!');
            }
            return;
        }

        const slipBtn = el.closest('[data-slip-json]');
        if (slipBtn) {
            // Fresh DB se fetch karo (AccountBalance stale cache se na aaye)
            try {
                const slipData = JSON.parse(decodeURIComponent(slipBtn.dataset.slipJson));
                if (slipData && slipData.BCID) {
                    openBcSlipById(slipData.BCID);
                } else {
                    openSlipFromData(slipBtn.dataset.slipJson);
                }
            } catch (e) {
                openSlipFromData(slipBtn.dataset.slipJson);
            }
            return;
        }

        const khataSlipBtn = el.closest('[data-khata-slip-json]');
        if (khataSlipBtn) {
            try {
                openKhataSlipFromData(JSON.parse(decodeURIComponent(khataSlipBtn.dataset.khataSlipJson)), true);
            } catch (err) {
                console.warn('Khata slip data parse error:', err.message);
            }
            return;
        }
    }, true);
}

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', bindDelegatedClickHandlers);
} else {
    bindDelegatedClickHandlers();
}

// ==========================================================================
// GLOBAL AUTO-CAPITALIZATION ENGINE (First Character & After Space -> Capital)
// Har text field mein pehla akshar aur space ke baad pehla akshar auto-capital
// ==========================================================================
function toTitleCaseWords(str) {
    if (!str) return '';
    return str.replace(/(^|[\s\(\[\{])\p{L}/gu, match => match.toUpperCase());
}

function handleGlobalAutoCapitalize(e) {
    const el = e.target;
    if (!el || (el.tagName !== 'INPUT' && el.tagName !== 'TEXTAREA')) return;

    // Check input type for input elements
    if (el.tagName === 'INPUT') {
        const type = (el.type || 'text').toLowerCase();
        if (['password', 'email', 'number', 'date', 'time', 'datetime-local', 'month', 'tel', 'color', 'file', 'hidden', 'checkbox', 'radio', 'range', 'url'].includes(type)) {
            return;
        }
    }

    // Exclude if explicitly opted out
    if (el.dataset.noAutoCase === 'true' || el.dataset.noAutocapitalize === 'true' || el.classList.contains('no-auto-case') || el.dataset.case === 'none') {
        return;
    }

    const val = el.value;
    if (!val) return;

    // Check if element is an uppercase-specific field (e.g. IFSC, GSTIN, PAN, RRN, UTR)
    const idLower = (el.id || '').toLowerCase();
    const nameLower = (el.name || '').toLowerCase();
    const isFullUpper = el.dataset.case === 'upper' ||
        el.classList.contains('uppercase-input') ||
        idLower.includes('ifsc') || idLower.includes('gstin') || idLower.includes('panno') ||
        idLower === 'bcrrn' || nameLower.includes('ifsc') || nameLower.includes('gstin');

    if (isFullUpper) {
        const upper = val.toUpperCase();
        if (upper !== val) {
            const start = el.selectionStart;
            const end = el.selectionEnd;
            el.value = upper;
            if (start !== null && end !== null) {
                el.setSelectionRange(start, end);
            }
        }
        return;
    }

    // Title Case: First character of string, and first character after any space/whitespace/bracket
    const titleCased = toTitleCaseWords(val);
    if (titleCased !== val) {
        const start = el.selectionStart;
        const end = el.selectionEnd;
        el.value = titleCased;
        if (start !== null && end !== null) {
            el.setSelectionRange(start, end);
        }
    }
}

// Bind capture-phase input and blur listeners globally across all existing and dynamic elements
document.addEventListener('input', handleGlobalAutoCapitalize, true);
document.addEventListener('blur', handleGlobalAutoCapitalize, true);

