let loaderDelayTimer = null;
let loaderCountdownInterval = null;
let loaderTargetEndTime = 0;
let loaderStartTime = 0;
let isUniversalLoaderActive = false;
let pendingHideRequest = false;

function showUniversalLoader(title = 'Kirpya Pratiksha Karein...', message = 'Data surakshit process ho raha hai...', instant = true, customDurationSec = null, isManualPreview = false) {
    clearInterval(loaderCountdownInterval);
    clearTimeout(loaderDelayTimer);
    pendingHideRequest = false;

    const loader = document.getElementById('universalLoader');
    if (!loader) return;

    const settings = getCustomLoaderSettings();

    // If not manual preview, enforce enable/disable settings
    if (!isManualPreview) {
        if (!settings.enabled || settings.speedMode === 'off' || settings.displayMode === 'none' || settings.displayMode === 'topbar_only') {
            return;
        }
    }

    const style = settings.style || 'quantum';

    // Apply active style class
    loader.classList.remove('loader-style-quantum', 'loader-style-coins', 'loader-style-matrix', 'loader-style-aurora', 'loader-style-rocket', 'loader-style-minimal');
    loader.classList.add(`loader-style-${style}`);

    // Render animation HTML
    renderLoaderAnimationHTML(style);

    const titleEl = document.getElementById('loaderTitle');
    const msgEl = document.getElementById('loaderMessage');
    const timerSecEl = document.getElementById('loaderRemainingSec');
    const progressBarEl = document.getElementById('loaderProgressBar');
    const statusTextEl = document.getElementById('loaderStatusText');

    if (titleEl && title) titleEl.textContent = title;
    if (msgEl && message) msgEl.textContent = message;
    if (statusTextEl) statusTextEl.textContent = 'Live database se data sync ho raha hai...';
    if (progressBarEl) progressBarEl.style.width = '20%';

    const isSystemSpeed = !isManualPreview && (customDurationSec === null || customDurationSec === 0) && (settings.speedMode === 'system' || (settings.duration || 0) <= 0);

    if (timerSecEl) {
        if (isSystemSpeed) {
            timerSecEl.textContent = '⚡ Live';
        } else {
            const displaySec = customDurationSec !== null ? customDurationSec : settings.duration;
            timerSecEl.textContent = displaySec > 0 ? `${displaySec}s` : '⚡ Live';
        }
    }

    clearTimeout(loaderDelayTimer);
    clearInterval(loaderCountdownInterval);

    const activate = () => {
        clearInterval(loaderCountdownInterval);
        isUniversalLoaderActive = true;
        loaderStartTime = Date.now();
        loader.classList.add('active');

        if (!isSystemSpeed && (customDurationSec || settings.duration > 0 || isManualPreview)) {
            // Fixed duration mode (settings preview or custom duration timer)
            const durationSec = isManualPreview ? (customDurationSec || 2) : (customDurationSec !== null ? customDurationSec : settings.duration);
            const durationMs = Math.max(200, durationSec * 1000);
            loaderTargetEndTime = loaderStartTime + durationMs;
            const stepMs = 40;
            loaderCountdownInterval = setInterval(() => {
                const now = Date.now();
                const elapsed = now - loaderStartTime;
                const remainingMs = Math.max(0, loaderTargetEndTime - now);
                const remainingSec = (remainingMs / 1000).toFixed(1);
                const percent = Math.min(100, (elapsed / durationMs) * 100);

                if (progressBarEl) progressBarEl.style.width = `${percent}%`;
                if (timerSecEl) timerSecEl.textContent = remainingMs > 1000 ? `${Math.ceil(remainingMs / 1000)}s` : `${remainingSec}s`;

                if (now >= loaderTargetEndTime) {
                    clearInterval(loaderCountdownInterval);
                    if (progressBarEl) progressBarEl.style.width = '100%';
                    if (statusTextEl) statusTextEl.textContent = 'Complete! ✓';
                    setTimeout(() => closeLoaderVisual(), 80);
                }
            }, stepMs);
        } else {
            // Pure Real-Time System Speed (Indeterminate live progress)
            loaderTargetEndTime = 0;
            let currentPct = 25;
            loaderCountdownInterval = setInterval(() => {
                if (currentPct < 90) {
                    currentPct += Math.max(0.8, (90 - currentPct) * 0.22);
                    if (progressBarEl) progressBarEl.style.width = `${currentPct}%`;
                }
            }, 60);
        }
    };

    if (instant) {
        activate();
    } else {
        loaderDelayTimer = setTimeout(activate, 40);
    }
}

function hideUniversalLoader(force = false) {
    if (force || loaderTargetEndTime === 0 || Date.now() >= loaderTargetEndTime) {
        clearInterval(loaderCountdownInterval);
        clearTimeout(loaderDelayTimer);
        closeLoaderVisual();
        return;
    }

    pendingHideRequest = true;
    const now = Date.now();
    if (now >= loaderTargetEndTime) {
        clearInterval(loaderCountdownInterval);
        closeLoaderVisual();
    }
}

function closeLoaderVisual() {
    isUniversalLoaderActive = false;
    pendingHideRequest = false;
    clearInterval(loaderCountdownInterval);
    clearTimeout(loaderDelayTimer);
    const loader = document.getElementById('universalLoader');
    if (loader) {
        loader.classList.remove('active');
    }
}

// Settings UI Controllers
function onLoaderDurationChange(val) {
    let num = parseFloat(val);
    if (isNaN(num) || num < 0) num = 0;
    if (num > 60) num = 60;
    num = Math.round(num * 10) / 10;

    const isSystem = num === 0;
    const range = document.getElementById('loaderDurationRange');
    const numInput = document.getElementById('loaderDurationNumber');
    const badge = document.getElementById('loaderDurationBadge');

    if (range) range.value = num;
    if (numInput) numInput.value = num;

    if (badge) {
        if (isSystem) {
            badge.innerHTML = `⚡ <b>System Speed</b> (0s Delay — सिर्फ सिस्टम का समय)`;
            badge.style.background = 'rgba(16, 185, 129, 0.18)';
            badge.style.color = '#34d399';
            badge.style.borderColor = '#10b981';
        } else {
            badge.innerHTML = `⏱️ <b>${num}</b> Second${num >= 2 ? 's' : ''} (${Math.round(num * 1000)} ms)`;
            badge.style.background = '';
            badge.style.color = '';
            badge.style.borderColor = '';
        }
    }

    saveCurrentLoaderSettings(false);
}

function setLoaderDurationPreset(val) {
    if (val === 'off') {
        selectLoaderSpeedMode('off');
        return;
    }
    const num = parseFloat(val);
    onLoaderDurationChange(num);
    if (num === 0) {
        selectLoaderSpeedMode('system');
    } else {
        saveCustomLoaderSettings({ enabled: true, speedMode: 'timer', duration: num }, false);
    }
}

function selectLoaderStyle(styleKey) {
    document.querySelectorAll('.anim-style-card').forEach(c => {
        c.classList.toggle('active', c.getAttribute('data-style') === styleKey);
    });

    const styleNames = {
        quantum: 'Quantum Orbit',
        coins: 'Golden Vault & Coins',
        matrix: 'Cyber Matrix Radar',
        aurora: 'Aurora Liquid Glass',
        rocket: 'Turbo Velocity Rocket',
        minimal: 'Minimalist Sleek Ring'
    };
    const badge = document.getElementById('loaderCurrentStyleBadge');
    if (badge) badge.innerHTML = `Chuna Hua: <b>${styleNames[styleKey] || styleKey}</b>`;

    saveCurrentLoaderSettings(false);
}

function saveCurrentLoaderSettings(showToastNotify = true) {
    const range = document.getElementById('loaderDurationRange');
    const duration = range ? parseFloat(range.value) || 0 : 0;
    const activeCard = document.querySelector('.anim-style-card.active');
    const style = activeCard ? activeCard.getAttribute('data-style') : 'quantum';
    const onReload = document.getElementById('loaderToggleReload')?.checked ?? true;
    const onTrans = document.getElementById('loaderToggleTrans')?.checked ?? true;
    const onDataLoad = document.getElementById('loaderToggleDataLoad')?.checked ?? true;

    const activeModeCard = document.querySelector('.loader-mode-card.active');
    let speedMode = activeModeCard ? activeModeCard.getAttribute('data-mode') : (duration === 0 ? 'system' : 'timer');
    let enabled = speedMode !== 'off';

    saveCustomLoaderSettings({
        enabled,
        speedMode,
        duration,
        style,
        onReload,
        onTrans,
        onDataLoad
    }, showToastNotify);
}

function resetLoaderSettingsToDefault() {
    saveCustomLoaderSettings({
        enabled: true,
        speedMode: 'system',
        duration: 0,
        style: 'quantum',
        displayMode: 'fullscreen',
        onReload: true,
        onTrans: true,
        onDataLoad: true
    }, true);
    initLoaderSettingsUI();
}

function updateLoaderSettingsUI(s) {
    const range = document.getElementById('loaderDurationRange');
    const numInput = document.getElementById('loaderDurationNumber');
    const badge = document.getElementById('loaderDurationBadge');
    const chkReload = document.getElementById('loaderToggleReload');
    const chkTrans = document.getElementById('loaderToggleTrans');
    const chkDataLoad = document.getElementById('loaderToggleDataLoad');
    const styleBadge = document.getElementById('loaderCurrentStyleBadge');
    const activeBadge = document.getElementById('loaderSettingsActiveBadge');
    const masterToggleBtn = document.getElementById('loaderMasterToggleBtn');

    if (range) range.value = s.duration;
    if (numInput) numInput.value = s.duration;

    const isSystem = s.speedMode === 'system' || (s.duration || 0) <= 0;

    if (badge) {
        if (!s.enabled || s.speedMode === 'off') {
            badge.innerHTML = `🛑 <b>Animation OFF (पूरी तरह बंद)</b>`;
            badge.style.background = 'rgba(239, 68, 68, 0.15)';
            badge.style.color = '#f87171';
            badge.style.borderColor = 'rgba(239, 68, 68, 0.4)';
        } else if (isSystem) {
            badge.innerHTML = `⚡ <b>System Speed</b> (0s Delay — सिर्फ सिस्टम का समय)`;
            badge.style.background = 'rgba(16, 185, 129, 0.18)';
            badge.style.color = '#34d399';
            badge.style.borderColor = '#10b981';
        } else {
            badge.innerHTML = `⏱️ <b>${s.duration}</b> Second${s.duration >= 2 ? 's' : ''} (${Math.round(s.duration * 1000)} ms)`;
            badge.style.background = '';
            badge.style.color = '';
            badge.style.borderColor = '';
        }
    }

    if (activeBadge) {
        if (!s.enabled || s.speedMode === 'off') {
            activeBadge.className = 'rb-pill-status offline';
            activeBadge.textContent = '🔴 OFF (बंद है)';
        } else if (isSystem) {
            activeBadge.className = 'rb-pill-status live';
            activeBadge.textContent = '⚡ System Speed (0s Delay)';
        } else {
            activeBadge.className = 'rb-pill-status live';
            activeBadge.textContent = `● Active (${s.duration}s)`;
        }
    }

    if (masterToggleBtn) {
        if (!s.enabled || s.speedMode === 'off') {
            masterToggleBtn.innerHTML = '<i data-lucide="power"></i> 🟢 Animation Chalu Karein (Turn ON)';
            masterToggleBtn.className = 'btn-success';
        } else {
            masterToggleBtn.innerHTML = '<i data-lucide="power-off"></i> 🔴 Animation Band Karein (Turn OFF)';
            masterToggleBtn.className = 'btn-danger';
        }
    }

    // Update Mode Cards
    document.querySelectorAll('.loader-mode-card').forEach(card => {
        const mode = card.getAttribute('data-mode');
        if (mode === 'off') {
            card.classList.toggle('active', !s.enabled || s.speedMode === 'off');
        } else if (mode === 'system') {
            card.classList.toggle('active', s.enabled && (s.speedMode === 'system' || (s.duration || 0) <= 0));
        } else if (mode === 'timer') {
            card.classList.toggle('active', s.enabled && s.speedMode === 'timer' && s.duration > 0);
        }
    });

    // Update Display Mode Pills
    document.querySelectorAll('.loader-disp-btn').forEach(btn => {
        const disp = btn.getAttribute('data-disp');
        btn.classList.toggle('active', s.displayMode === disp);
    });

    // Update Presets active class
    document.querySelectorAll('.preset-btn').forEach(btn => {
        const pVal = btn.getAttribute('data-preset');
        if (pVal === 'off') {
            btn.classList.toggle('active', !s.enabled || s.speedMode === 'off');
        } else if (pVal === '0') {
            btn.classList.toggle('active', s.enabled && isSystem);
        } else if (pVal && parseFloat(pVal) === s.duration && s.enabled && !isSystem) {
            btn.classList.toggle('active', true);
        } else {
            btn.classList.toggle('active', false);
        }
    });

    if (chkReload) chkReload.checked = s.onReload;
    if (chkTrans) chkTrans.checked = s.onTrans;
    if (chkDataLoad) chkDataLoad.checked = s.onDataLoad !== false;

    const styleNames = {
        quantum: 'Quantum Orbit',
        coins: 'Golden Vault & Coins',
        matrix: 'Cyber Matrix Radar',
        aurora: 'Aurora Liquid Glass',
        rocket: 'Turbo Velocity Rocket',
        minimal: 'Minimalist Sleek Ring'
    };
    if (styleBadge) styleBadge.innerHTML = `Chuna Hua: <b>${styleNames[s.style] || s.style}</b>`;

    document.querySelectorAll('.anim-style-card').forEach(c => {
        c.classList.toggle('active', c.getAttribute('data-style') === s.style);
    });

    if (window.lucide && typeof lucide.createIcons === 'function') {
        lucide.createIcons();
    }
}

function initLoaderSettingsUI() {
    const s = getCustomLoaderSettings();
    updateLoaderSettingsUI(s);
}

function previewCustomLoader() {
    const range = document.getElementById('loaderDurationRange');
    const duration = range ? parseFloat(range.value) || 0 : 0;
    const activeCard = document.querySelector('.anim-style-card.active');
    const style = activeCard ? activeCard.getAttribute('data-style') : 'quantum';

    const styleNames = {
        quantum: 'Quantum Orbit',
        coins: 'Golden Vault & Coins',
        matrix: 'Cyber Matrix Radar',
        aurora: 'Aurora Liquid Glass',
        rocket: 'Turbo Velocity Rocket',
        minimal: 'Minimalist Sleek Ring'
    };

    const isSystem = duration === 0;
    showUniversalLoader(
        `Preview: ${styleNames[style] || style} (${isSystem ? 'System Speed' : duration + 's'})`,
        isSystem ? '⚡ Live System Speed Test (2.5s auto close)...' : `Live loading animation test (${duration}s)...`,
        true,
        isSystem ? 2.5 : Math.max(duration, 1.2),
        true // isManualPreview = true so it displays even if disabled!
    );
}

// Explicit window bindings for inline HTML onclick handlers
window.showUniversalLoader = showUniversalLoader;
window.hideUniversalLoader = hideUniversalLoader;
window.previewCustomLoader = previewCustomLoader;
window.saveCurrentLoaderSettings = saveCurrentLoaderSettings;
window.resetLoaderSettingsToDefault = resetLoaderSettingsToDefault;
window.selectLoaderStyle = selectLoaderStyle;
window.selectLoaderSpeedMode = selectLoaderSpeedMode;
window.selectLoaderDisplayMode = selectLoaderDisplayMode;
window.toggleLoaderMaster = toggleLoaderMaster;
window.onLoaderDurationChange = onLoaderDurationChange;
window.setLoaderDurationPreset = setLoaderDurationPreset;

// ============ STACKABLE RICH TOAST NOTIFICATION SYSTEM ============
function showToast(msg, type = 'success', title = null) {
    const container = document.getElementById('toastContainer');
    if (!container) {
        const toast = document.getElementById('toast');
        if (toast) {
            toast.style.display = 'block';
            toast.textContent = msg;
            toast.className = `toast ${type} show`;
            setTimeout(() => { toast.classList.remove('show'); }, 3000);
        }
        return;
    }

    const toastItem = document.createElement('div');
    toastItem.className = `toast-item ${type}`;

    let iconSymbol = '✓';
    let defaultTitle = 'Safalta (Success)';
    if (type === 'error') {
        iconSymbol = '✕';
        defaultTitle = 'Truti (Error)';
    } else if (type === 'warning') {
        iconSymbol = '⚠';
        defaultTitle = 'Dhyan Dein (Warning)';
    } else if (type === 'info') {
        iconSymbol = 'ℹ';
        defaultTitle = 'Soochana (Info)';
    }

    const finalTitle = title || defaultTitle;

    toastItem.innerHTML = `
        <div class="toast-icon-wrap">${iconSymbol}</div>
        <div class="toast-body">
            <div class="toast-title">${escapeHtml(finalTitle)}</div>
            <div class="toast-msg">${escapeHtml(msg)}</div>
        </div>
        <button type="button" class="toast-close-btn" title="Band karein">&times;</button>
        <div class="toast-progress"></div>
    `;

    const closeBtn = toastItem.querySelector('.toast-close-btn');
    const dismiss = () => {
        toastItem.classList.add('removing');
        setTimeout(() => toastItem.remove(), 260);
    };

    if (closeBtn) closeBtn.addEventListener('click', (e) => { e.stopPropagation(); dismiss(); });
    toastItem.addEventListener('click', dismiss);

    container.appendChild(toastItem);
    setTimeout(dismiss, 3500);
}
window.showToast = showToast;

// ============ ACTION & SUCCESS NOTIFICATION POPUP MODAL ============
function showActionSuccessModal({ title, subtitle, icon = 'check-circle-2', details = [], actions = [], customHtml = null }) {
    const titleEl = document.getElementById('actionSuccessTitle');
    const subEl = document.getElementById('actionSuccessSubtitle');
    const iconCircle = document.getElementById('actionSuccessIcon');
    const detailsContainer = document.getElementById('actionSuccessDetails');
    const actionsContainer = document.getElementById('actionSuccessActions');

    if (titleEl) titleEl.textContent = title || 'Kaam Safaltapoorvak Ho Gaya!';
    if (subEl) subEl.textContent = subtitle || 'Vivran khate me darz ho chuka hai.';
    if (iconCircle) {
        iconCircle.className = `action-icon-circle ${icon.includes('check') || icon.includes('arrow') ? 'success' : 'info'}`;
        iconCircle.innerHTML = `<i data-lucide="${icon}"></i>`;
    }

    if (detailsContainer) {
        if (customHtml) {
            detailsContainer.style.display = 'block';
            detailsContainer.innerHTML = customHtml;
        } else if (!details || details.length === 0) {
            detailsContainer.style.display = 'none';
        } else {
            detailsContainer.style.display = 'block';
            detailsContainer.innerHTML = `
                <table class="action-success-table">
                    <tbody>
                        ${details.map(d => {
                const isAmt = (d.label || '').toLowerCase().includes('amount') || (d.label || '').toLowerCase().includes('rashi');
                const customValColor = d.color || (isAmt ? '#10b981' : '');
                return `
                                <tr>
                                    <td class="as-label">${escapeHtml(d.label)}</td>
                                    <td class="as-val" style="${customValColor ? `color: ${customValColor}; font-weight: 800;` : ''}">${escapeHtml(d.val)}</td>
                                </tr>
                            `;
            }).join('')}
                    </tbody>
                </table>
            `;
        }
    }

    if (actionsContainer) {
        if (!actions || actions.length === 0) {
            actionsContainer.innerHTML = `<button type="button" class="btn-primary" onclick="closeModal('actionSuccessModal')" style="background: linear-gradient(135deg, #10b981, #059669); color: white; border: none; font-weight: 700; padding: 9px 24px; border-radius: 8px; font-size: 13.5px; box-shadow: 0 2px 8px rgba(16, 185, 129, 0.3); cursor: pointer;">Theek Hai</button>`;
        } else {
            actionsContainer.innerHTML = actions.map((a, idx) => {
                const isPrimary = a.className && a.className.includes('btn-primary');
                const isSuccess = a.className && a.className.includes('btn-success');
                const btnStyle = isPrimary
                    ? 'background: linear-gradient(135deg, #10b981, #059669); color: white; border: none; font-weight: 700; padding: 9px 20px; border-radius: 8px; font-size: 13.5px; box-shadow: 0 2px 8px rgba(16, 185, 129, 0.3); display: inline-flex; align-items: center; gap: 6px; cursor: pointer;'
                    : (isSuccess
                        ? 'background: linear-gradient(135deg, #16a34a, #15803d); color: white; border: none; font-weight: 700; padding: 9px 20px; border-radius: 8px; font-size: 13.5px; box-shadow: 0 2px 8px rgba(22, 163, 74, 0.3); display: inline-flex; align-items: center; gap: 6px; cursor: pointer;'
                        : 'background: var(--bg-card); border: 1.5px solid var(--border-row, #cbd5e1); color: var(--text-primary); font-weight: 700; padding: 9px 20px; border-radius: 8px; font-size: 13.5px; display: inline-flex; align-items: center; gap: 6px; cursor: pointer;');
                return `
                    <button type="button" class="${a.className || 'btn-secondary'}" id="act-btn-${idx}" style="${btnStyle}">
                        ${a.icon ? `<i data-lucide="${a.icon}" style="width: 16px; height: 16px;"></i> ` : ''}${escapeHtml(a.text)}
                    </button>
                `;
            }).join('');

            actions.forEach((a, idx) => {
                const btn = document.getElementById(`act-btn-${idx}`);
                if (btn) {
                    btn.addEventListener('click', () => {
                        if (a.close !== false) closeModal('actionSuccessModal');
                        if (typeof a.onClick === 'function') a.onClick();
                    });
                }
            });
        }
    }

    openModal('actionSuccessModal');
    if (typeof lucide !== 'undefined') lucide.createIcons();
}

// Global Keyboard Shortcuts (Alt + Key, F2)
document.addEventListener('keydown', (e) => {
    // Quick F2 key shortcut to create new customer
    if (e.key === 'F2') {
        e.preventDefault();
        if (activeModalStack.includes('customerModal')) return;
        if (activeModalStack.includes('cscNewAppModal')) {
            openNewCustomerFromCSC();
        } else {
            openCustomerModal();
        }
        return;
    }

    // Only trigger if Alt is pressed
    if (e.altKey && !e.ctrlKey && !e.shiftKey) {
        const key = e.key.toLowerCase();
        if (key === 'b') {
            e.preventDefault();
            openInvoiceModal();
        } else if (key === 'k') {
            e.preventDefault();
            openKhataEntryModal('Got');
        } else if (key === 'c') {
            e.preventDefault();
            if (activeModalStack.includes('customerModal')) return;
            if (activeModalStack.includes('cscNewAppModal')) {
                openNewCustomerFromCSC();
            } else {
                openCustomerModal();
            }
        } else if (key === 'n') {
            e.preventDefault();
            openAddTransaction();
        } else if (key === 'w') {
            e.preventDefault();
            openNewCSCModal();
        } else if (key === 's') {
            e.preventDefault();
            openSettlementModal();
        }
    }
});

function showConfirm(msg, callback) {
    const msgEl = document.getElementById('confirmMessage');
    if (msgEl) msgEl.textContent = msg;
    confirmCallback = callback;
    const btn = document.getElementById('confirmBtn');
    if (btn) {
        btn.onclick = () => { closeModal('confirmModal'); callback(); };
    }
    openModal('confirmModal');
}

const activeModalStack = [];
const BASE_MODAL_Z_INDEX = 2000;

function updateModalScrollLock() {
    const hasActiveModal = activeModalStack.length > 0 || !!document.querySelector('.modal-overlay.active');
    if (hasActiveModal) {
        if (!document.body.classList.contains('modal-open')) {
            // Measure scrollbar width before hiding overflow to prevent layout jump
            const scrollbarWidth = window.innerWidth - document.documentElement.clientWidth;
            if (scrollbarWidth > 0) {
                document.body.style.paddingRight = `${scrollbarWidth}px`;
            }
            document.documentElement.classList.add('modal-open');
            document.body.classList.add('modal-open');
        }
    } else {
        if (document.body.classList.contains('modal-open') || document.documentElement.classList.contains('modal-open')) {
            document.documentElement.classList.remove('modal-open');
            document.body.classList.remove('modal-open');
            document.body.style.removeProperty('padding-right');
        }
    }
}

// ============================================================================
// UNIVERSAL KEYBOARD TAB NAVIGATION ACCELERATOR
// Forms / Modals me Tab dabane par copy/eye/auxiliary buttons skip hokar
// seedhe agle data input/column par jaye.
// ============================================================================
function applyTabSkipToAuxiliaryButtons(root = document) {
    if (!root || typeof root.querySelectorAll !== 'function') return;
    const selector = `
        .btn-copy-mini, 
        .btn-copy, 
        .phone-copy-btn, 
        .aadhaar-copy-btn, 
        .aadhaar-eye-btn, 
        .copy-btn, 
        button[data-copy-phone], 
        button[data-copy-aadhaar], 
        button[data-copy-val],
        .phone-wa-link,
        .btn-icon-mini,
        .modal-body .form-group label button,
        .modal-body .form-section-card label button,
        .modal-body .form-section-title + button,
        .form-group label + button,
        .form-group > div:first-child button
    `;
    try {
        root.querySelectorAll(selector).forEach(btn => {
            if (btn && btn.getAttribute('tabindex') !== '-1') {
                btn.setAttribute('tabindex', '-1');
            }
        });
    } catch (e) { }
}
window.applyTabSkipToAuxiliaryButtons = applyTabSkipToAuxiliaryButtons;

// Global Tab Key Intelligent Skipper
document.addEventListener('keydown', (e) => {
    if (e.key !== 'Tab') return;
    const active = document.activeElement;
    if (!active) return;
    const isField = active.matches && active.matches('input, select, textarea');
    if (isField) {
        const container = active.closest('.modal, form, .modal-body, .form-section-card') || document;
        applyTabSkipToAuxiliaryButtons(container);
    }
}, true);

// MutationObserver: dynamically added copy/eye buttons automatically get tabindex="-1"
try {
    const tabSkipObserver = new MutationObserver((mutations) => {
        for (const m of mutations) {
            if (m.addedNodes && m.addedNodes.length > 0) {
                m.addedNodes.forEach(node => {
                    if (node.nodeType === 1) {
                        applyTabSkipToAuxiliaryButtons(node);
                    }
                });
            }
        }
    });
    if (document.body) {
        tabSkipObserver.observe(document.body, { childList: true, subtree: true });
    } else {
        document.addEventListener('DOMContentLoaded', () => {
            tabSkipObserver.observe(document.body, { childList: true, subtree: true });
            applyTabSkipToAuxiliaryButtons();
        });
    }
} catch (e) { }

// ============================================================================
// UNIVERSAL SMART DATE HELPERS & GLOBAL DOB INITIALIZATION
// ============================================================================
(function initDateHelpers() {
    if (typeof window.initGlobalDobInputs === 'function') {
        window.initGlobalDobInputs();
    }

    // Universal Paste Support for Generic Date Inputs
    document.addEventListener('paste', (e) => {
        const input = e.target;
        if (!input || input.type !== 'date') return;
        const text = e.clipboardData ? e.clipboardData.getData('text') : '';
        if (text && typeof parseApiDate === 'function') {
            const dt = parseApiDate(text);
            if (dt && !isNaN(dt.getTime())) {
                e.preventDefault();
                input.value = toLocalYMD(dt);
                input.dispatchEvent(new Event('input', { bubbles: true }));
                input.dispatchEvent(new Event('change', { bubbles: true }));
            }
        }
    }, true);
})();

function openModal(id) {
    const el = document.getElementById(id);
    if (!el) return;
    if (el.style.display === 'none') {
        el.style.removeProperty('display');
    }

    if (typeof window.initGlobalDobInputs === 'function') {
        window.initGlobalDobInputs();
    }

    // Remove from stack if already present to reposition at the top
    const existingIdx = activeModalStack.indexOf(id);
    if (existingIdx !== -1) {
        activeModalStack.splice(existingIdx, 1);
    }
    activeModalStack.push(id);

    // Compute dynamic z-index (each stacked modal gets higher z-index)
    const zIndex = BASE_MODAL_Z_INDEX + (activeModalStack.length * 40);
    el.style.setProperty('z-index', String(zIndex), 'important');

    // Apply stacked overlay styling if opened on top of another modal
    if (activeModalStack.length > 1) {
        el.classList.add('stacked-modal');
    } else {
        el.classList.remove('stacked-modal');
    }

    el.classList.add('active');

    // Automatically strip Tab stops from all copy and auxiliary buttons in this modal
    applyTabSkipToAuxiliaryButtons(el);

    // Freeze background page scroll immediately
    updateModalScrollLock();

    // INSTANT: Sync ONLY selects inside this modal and render icons scoped to this modal
    requestAnimationFrame(() => {
        if (typeof lucide !== 'undefined') {
            try { lucide.createIcons({ root: el }); } catch (e) { try { lucide.createIcons(); } catch (err) { } }
        }
        el.querySelectorAll('select').forEach(sel => {
            if (sel._ssInstance) sel._ssInstance.syncFromNative();
        });
    });
}

function closeModal(id) {
    if (id === 'bcReceiptModal' && typeof toggleSlipZoomMode === 'function') {
        toggleSlipZoomMode(false);
    }
    const el = document.getElementById(id);
    if (el) {
        el.classList.remove('active');
        el.classList.remove('stacked-modal');
        el.style.removeProperty('z-index');
    }

    // Reset due alerts when closing forms
    if (id === 'billPaymentModal') {
        const c = document.getElementById('bpDueAlertContainer');
        if (c) { c.innerHTML = ''; c.style.display = 'none'; }
    } else if (id === 'cscNewAppModal') {
        const c = document.getElementById('cscDueAlertContainer');
        if (c) { c.innerHTML = ''; c.style.display = 'none'; }
    } else if (id === 'bcModal') {
        const c = document.getElementById('bcDueAlertContainer');
        if (c) { c.innerHTML = ''; c.style.display = 'none'; }
    } else if (id === 'invoiceModal') {
        const c = document.getElementById('invDueAlertContainer');
        if (c) { c.innerHTML = ''; c.style.display = 'none'; }
    } else if (id === 'khataEntryModal') {
        const c = document.getElementById('khataDueAlertContainer');
        if (c) { c.innerHTML = ''; c.style.display = 'none'; }
    }

    const idx = activeModalStack.indexOf(id);
    if (idx !== -1) {
        activeModalStack.splice(idx, 1);
    }

    // Update styling on parent modal underneath if any
    if (activeModalStack.length > 0) {
        const topId = activeModalStack[activeModalStack.length - 1];
        const topEl = document.getElementById(topId);
        if (topEl && activeModalStack.length === 1) {
            topEl.classList.remove('stacked-modal');
        }
    }

    // Update background scroll lock state
    updateModalScrollLock();

    // Close any active searchable select dropdown immediately
    if (window.SearchableSelect && window.SearchableSelect.activeInstance) {
        window.SearchableSelect.activeInstance.close();
    }

    // Close family picker popup (phone auto-fill) if open
    if (typeof hideFamilyPicker === 'function') hideFamilyPicker();
}

window._realOpenModal = openModal;
window.openModal = openModal;
window._realCloseModal = closeModal;
window.closeModal = closeModal;

// Backdrop (bahar) click par modal auto-close DISABLED hai — modal sirf X / Cancel / Band Karo button se band hoga
// taaki form ka data galti se bahar click karne par na ude
document.addEventListener('click', (e) => {
    if (e.target && e.target.classList && e.target.classList.contains('modal-overlay') && e.target.classList.contains('active')) {
        // Outside click ko ignore karo — kuch mat karo
        // Agar kabhi kisi khas modal me bahar-click se band karna ho to us modal id ko MODALS_ALLOW_OUTSIDE_CLOSE me add karo
        if (window.MODALS_ALLOW_OUTSIDE_CLOSE && window.MODALS_ALLOW_OUTSIDE_CLOSE.includes(e.target.id)) {
            if (activeModalStack.length > 0 && e.target.id === activeModalStack[activeModalStack.length - 1]) {
                closeModal(e.target.id);
            }
        }
        return;
    }
});

// Escape key to close the topmost active modal (or Zoom Overlay first if active)
document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
        const zoomOverlay = document.getElementById('bcSlipZoomOverlay');
        if (zoomOverlay && zoomOverlay.style.display !== 'none' && zoomOverlay.style.display !== '') {
            e.preventDefault();
            e.stopPropagation();
            if (typeof toggleSlipZoomMode === 'function') {
                toggleSlipZoomMode(false);
            }
            return;
        }
        if (activeModalStack.length > 0) {
            const topModalId = activeModalStack[activeModalStack.length - 1];
            closeModal(topModalId);
        }
    }
});

// Shortcut 'Z' to toggle Customer Slip Zoom Mode (Option 2A-V3 42px)
document.addEventListener('keydown', (e) => {
    if ((e.key === 'z' || e.key === 'Z') && !e.ctrlKey && !e.altKey && !e.metaKey) {
        const active = document.activeElement;
        if (active && (active.tagName === 'INPUT' || active.tagName === 'TEXTAREA' || active.isContentEditable)) {
            return;
        }
        const bcReceiptModal = document.getElementById('bcReceiptModal');
        if (bcReceiptModal && bcReceiptModal.classList.contains('active')) {
            e.preventDefault();
            if (typeof toggleSlipZoomMode === 'function') {
                toggleSlipZoomMode();
            }
        }
    }
});

// ============ MODAL SCROLL ISOLATION & CHAINING TRAP ============
// Isolate mouse-wheel, touch gestures, and scroll keys so scrolling inside ANY modal
// strictly scrolls that modal only. When hitting top/bottom boundaries or hovering over
// modal header/footer/backdrop, background page scroll is completely prevented.
(function initModalScrollTrap() {
    function getScrollableContainer(target, boundaryOverlay) {
        let curr = target;
        while (curr && curr !== boundaryOverlay && curr !== document.body && curr !== document.documentElement) {
            if (curr.nodeType === 1) {
                const style = window.getComputedStyle(curr);
                const overflowY = style.overflowY;
                const canScrollY = (overflowY === 'auto' || overflowY === 'scroll') && (curr.scrollHeight > curr.clientHeight + 1);
                if (canScrollY) return curr;
            }
            curr = curr.parentElement;
        }
        return null;
    }

    window.addEventListener('wheel', function (e) {
        // Fast exit if no modal is currently active
        if (activeModalStack.length === 0 && !document.querySelector('.modal-overlay.active')) {
            return;
        }

        // Identify topmost active modal overlay
        let activeOverlay = null;
        if (activeModalStack.length > 0) {
            activeOverlay = document.getElementById(activeModalStack[activeModalStack.length - 1]);
        }
        if (!activeOverlay || !activeOverlay.classList.contains('active')) {
            activeOverlay = e.target.closest('.modal-overlay.active') || document.querySelector('.modal-overlay.active');
        }
        if (!activeOverlay) return;

        // If mouse is somehow outside active overlay, freeze page scroll
        if (!activeOverlay.contains(e.target)) {
            e.preventDefault();
            return;
        }

        // Allow horizontal scroll (in tables, tab strips)
        const deltaY = e.deltaY;
        const deltaX = e.deltaX || 0;
        if (Math.abs(deltaY) < Math.abs(deltaX)) {
            return;
        }

        // Find scrollable container under cursor
        let scrollable = getScrollableContainer(e.target, activeOverlay);

        // If hovering over non-scrollable header/footer/card inside modal dialog,
        // redirect scroll to the dialog's scrollable body instead of leaking to background
        const modalDialog = activeOverlay.querySelector('.modal, .customer-360-dialog');
        if (!scrollable && modalDialog && modalDialog.contains(e.target)) {
            const innerScrollable = modalDialog.querySelector('.c360-body, .modal-body, .modal-content') || modalDialog;
            if (innerScrollable && innerScrollable.scrollHeight > innerScrollable.clientHeight + 1) {
                scrollable = innerScrollable;
            } else if (modalDialog.scrollHeight > modalDialog.clientHeight + 1) {
                scrollable = modalDialog;
            }
        }

        // If hovering over empty backdrop overlay or modal has no scrollable content:
        if (!scrollable) {
            e.preventDefault();
            return;
        }

        const scrollTop = scrollable.scrollTop;
        const maxScroll = Math.max(0, scrollable.scrollHeight - scrollable.clientHeight);

        // Boundary check: Top boundary reached and scrolling UP -> freeze!
        if (deltaY < 0 && scrollTop <= 1) {
            scrollable.scrollTop = 0;
            e.preventDefault();
            return;
        }

        // Boundary check: Bottom boundary reached and scrolling DOWN -> freeze!
        if (deltaY > 0 && scrollTop >= maxScroll - 1) {
            scrollable.scrollTop = maxScroll;
            e.preventDefault();
            return;
        }

        // If hovering on header/footer and redirecting scroll to modal body:
        if (!scrollable.contains(e.target)) {
            scrollable.scrollTop += deltaY;
            e.preventDefault();
        }
    }, { passive: false });

    // Touch events protection for touchscreens & trackpads
    let touchStartY = 0;
    window.addEventListener('touchstart', function (e) {
        if (e.touches && e.touches.length > 0) {
            touchStartY = e.touches[0].clientY;
        }
    }, { passive: true });

    window.addEventListener('touchmove', function (e) {
        if (activeModalStack.length === 0 && !document.querySelector('.modal-overlay.active')) {
            return;
        }
        let activeOverlay = null;
        if (activeModalStack.length > 0) {
            activeOverlay = document.getElementById(activeModalStack[activeModalStack.length - 1]);
        }
        if (!activeOverlay || !activeOverlay.classList.contains('active')) {
            activeOverlay = e.target.closest('.modal-overlay.active') || document.querySelector('.modal-overlay.active');
        }
        if (!activeOverlay || !activeOverlay.contains(e.target)) {
            e.preventDefault();
            return;
        }

        const scrollable = getScrollableContainer(e.target, activeOverlay);
        if (!scrollable) {
            e.preventDefault();
            return;
        }

        if (!e.touches || e.touches.length === 0) return;
        const touchY = e.touches[0].clientY;
        const deltaY = touchStartY - touchY;
        const scrollTop = scrollable.scrollTop;
        const maxScroll = Math.max(0, scrollable.scrollHeight - scrollable.clientHeight);

        if (deltaY < 0 && scrollTop <= 1) {
            e.preventDefault();
            return;
        }
        if (deltaY > 0 && scrollTop >= maxScroll - 1) {
            e.preventDefault();
            return;
        }
    }, { passive: false });

    // Keyboard navigation keys (Space, PageUp/Down, Arrows) trap
    window.addEventListener('keydown', function (e) {
        if (activeModalStack.length === 0 && !document.querySelector('.modal-overlay.active')) {
            return;
        }
        const tag = (e.target && e.target.tagName) ? e.target.tagName.toLowerCase() : '';
        if (tag === 'input' || tag === 'textarea' || (e.target && e.target.isContentEditable)) {
            return;
        }
        const scrollKeys = ['ArrowUp', 'ArrowDown', 'PageUp', 'PageDown', 'Space', ' '];
        if (scrollKeys.includes(e.key)) {
            let activeOverlay = null;
            if (activeModalStack.length > 0) {
                activeOverlay = document.getElementById(activeModalStack[activeModalStack.length - 1]);
            }
            if (!activeOverlay) activeOverlay = document.querySelector('.modal-overlay.active');
            if (!activeOverlay) return;

            const modalDialog = activeOverlay.querySelector('.modal, .customer-360-dialog');
            const scrollable = modalDialog ? (modalDialog.querySelector('.c360-body, .modal-body, .modal-content') || modalDialog) : null;
            if (scrollable && scrollable.scrollHeight > scrollable.clientHeight + 1) {
                const step = (e.key === 'PageDown' || e.key === 'Space' || e.key === ' ') ? 220 :
                    (e.key === 'PageUp') ? -220 :
                        (e.key === 'ArrowDown') ? 45 : -45;
                scrollable.scrollTop += step;
                e.preventDefault();
            } else {
                e.preventDefault();
            }
        }
    });

    // Prevent mouse wheel from accidentally incrementing/decrementing number inputs
    window.addEventListener('wheel', function (e) {
        if (document.activeElement && document.activeElement.tagName === 'INPUT' && document.activeElement.type === 'number') {
            document.activeElement.blur();
        }
    }, { passive: true });
})();

function toggleSidebar() {
    const sb = document.getElementById('sidebar');
    if (!sb) return;
    const isCollapsed = sb.classList.toggle('collapsed');
    document.body.classList.toggle('sidebar-collapsed', isCollapsed);
    localStorage.setItem('sidebar_collapsed', isCollapsed ? '1' : '0');

    const icon = document.getElementById('sidebarToggleIcon');
    if (icon) {
        icon.setAttribute('data-lucide', isCollapsed ? 'panel-left-open' : 'panel-left-close');
    }

    // Resize any active Chart.js instances smoothly
    if (window.charts) {
        Object.values(window.charts).forEach(c => {
            if (c && typeof c.resize === 'function') c.resize();
        });
    }

    setTimeout(() => lucide.createIcons(), 50);
}

