// ==========================================================================
// INSTANT INLINE SKELETON LOADERS
// ==========================================================================
function renderTableSkeleton(tbody, colsCount = 6, rowsCount = 5) {
    if (typeof tbody === 'string') tbody = document.getElementById(tbody);
    if (!tbody) return;

    let html = '';
    for (let i = 0; i < rowsCount; i++) {
        html += `
            <tr class="skeleton-row-item" style="border-bottom: 1px solid rgba(255,255,255,0.04);">
                <td style="text-align: center; padding: 12px 10px;">
                    <div class="skeleton-box" style="width: 22px; height: 16px; margin: 0 auto;"></div>
                </td>
                <td style="padding: 12px 14px;">
                    <div class="skeleton-box" style="width: 90px; height: 16px;"></div>
                </td>
                <td style="padding: 12px 14px;">
                    <div class="skeleton-box" style="width: 150px; height: 16px; margin-bottom: 4px;"></div>
                    <div class="skeleton-box" style="width: 75px; height: 12px;"></div>
                </td>
                ${Array.from({ length: Math.max(1, colsCount - 4) }).map(() => `
                    <td style="padding: 12px 14px;">
                        <div class="skeleton-box" style="width: 65%; height: 16px;"></div>
                    </td>
                `).join('')}
                <td style="text-align: right; padding: 12px 14px;">
                    <div class="skeleton-box" style="width: 80px; height: 18px; margin-left: auto;"></div>
                </td>
            </tr>
        `;
    }
    tbody.innerHTML = html;
}

let iconDebounceTimer = null;
function refreshIcons(scope = null) {
    if (typeof lucide === 'undefined') return;
    if (scope && scope.querySelectorAll) {
        try {
            lucide.createIcons({ root: scope });
            return;
        } catch (e) { }
    }
    if (iconDebounceTimer) cancelAnimationFrame(iconDebounceTimer);
    iconDebounceTimer = requestAnimationFrame(() => {
        try { lucide.createIcons(); } catch (e) { }
    });
}

function showPage(page, navEl) {
    if (!page) page = 'dashboard';

    // Reroute relocated modules to their dedicated Settings tabs
    if (page === 'database') {
        navigateToSettingsTab('database');
        return;
    }
    if (page === 'extension') {
        navigateToSettingsTab('extension');
        return;
    }

    // Remove pre-route fallback style if present
    const initStyle = document.getElementById('initial-page-style');
    if (initStyle) initStyle.remove();

    // Persist active page to localStorage
    try {
        localStorage.setItem('cash_mgmt_active_page', page);
    } catch (e) { }

    // Update URL hash cleanly without forcing unwanted scroll jumps
    try {
        if (window.location.hash !== `#${page}`) {
            history.replaceState(null, '', `#${page}`);
        }
    } catch (e) { }

    document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
    document.querySelectorAll('.nav-item').forEach(n => n.classList.remove('active'));

    const pageEl = document.getElementById(`page-${page}`);
    if (pageEl) pageEl.classList.add('active');

    const activeNav = navEl || document.getElementById(`nav-${page}`) || document.querySelector(`.nav-item[onclick*="'${page}'"]`);
    if (activeNav) activeNav.classList.add('active');

    currentPage = page;
    updateBreadcrumb();

    if (page === 'dashboard' && typeof checkLiveUpdate === 'function') {
        checkLiveUpdate(false);
    }

    // Instant top progress visual feedback
    startTopLoading();

    // Ensure page scroll is reset to top cleanly
    window.scrollTo({ top: 0, left: 0, behavior: 'instant' });
    const mc = document.getElementById('mainContent');
    if (mc) mc.scrollTop = 0;

    // Instant skeleton previews
    if (page === 'transactions') {
        const tb = document.getElementById('transTableBody');
        if (tb && (!allTransactions || allTransactions.length === 0)) renderTableSkeleton(tb, 9, 6);
    } else if (page === 'customers') {
        const tb = document.getElementById('customersTableBody');
        if (tb && (!allCustomersData || allCustomersData.length === 0)) renderTableSkeleton(tb, 7, 5);
    } else if (page === 'bc') {
        const tb = document.getElementById('bcTableBody');
        if (tb) renderTableSkeleton(tb, 10, 7);
    } else if (page === 'database' && !activeDbTable) {
        const tb = document.getElementById('dbDataTableBody');
        if (tb) renderTableSkeleton(tb, 6, 6);
    } else if (page === 'csc') {
        const tb = document.getElementById('cscTableBody');
        if (tb && (!allCSCApplications || allCSCApplications.length === 0)) renderTableSkeleton(tb, 8, 6);
    } else if (page === 'billpayments') {
        const tb = document.getElementById('billPaymentsTableBody');
        if (tb && (!allBillPayments || allBillPayments.length === 0)) renderTableSkeleton(tb, 8, 6);
    }

    const loaders = {
        dashboard: loadDashboard,
        bc: loadBCPage,
        transactions: loadTransactions,
        accounts: loadAccounts,
        parties: loadParties,
        customers: loadCustomersPage,
        billing: loadBillingPage,
        khatabook: loadKhatabookPage,
        budgets: loadBudgets,
        bills: loadBills,
        reports: loadReports,
        categories: loadCategories,
        database: loadDatabasePage,
        recyclebin: loadRecycleBinPage,
        documents: loadDocumentsPage,
        csc: loadCSCPage,
        billpayments: loadBillPaymentsPage,
        ucl: loadUCLPage,
        pac: loadPACPage,
        history: loadHistoryPage,
        settings: loadSettingsPage
    };

    const pageLabels = {
        customers: 'Grahak Directory Load Ho Rahi Hai...',
        csc: 'CSC Sewayein Load Ho Rahi Hain...',
        billpayments: 'Bill & EMI Payments Load Ho Rahi Hain...',
        ucl: 'Aadhaar UCL Update Service Load Ho Rahi Hai...',
        pac: 'PAC Code Management Load Ho Raha Hai...',
        transactions: 'Transactions & Rokad Bahi Load Ho Rahi Hai...',
        reports: 'Reports & Analytics Load Ho Rahi Hain...',
        daybook: 'Day Book Load Ho Rahi Hai...',
        khatabook: 'Khatabook Ledger Load Ho Raha Hai...',
        accounts: 'Bank Khate Load Ho Rahe Hain...',
        billing: 'Billing & Invoices Load Ho Rahi Hain...',
        documents: 'Documents Vault Load Ho Raha Hai...',
        database: 'Database Live Table Load Ho Rahi Hai...',
        history: 'Activity History & Audit Logs Load Ho Rahe Hain...',
        dashboard: 'Dashboard Overview Load Ho Raha Hai...',
        settings: 'Settings Load Ho Rahi Hain...'
    };
    const pTitle = pageLabels[page] || 'Page Load Ho Raha Hai...';
    const lSettings = typeof getCustomLoaderSettings === 'function' ? getCustomLoaderSettings() : { enabled: true, onDataLoad: true };
    if (lSettings.enabled && lSettings.onDataLoad !== false && lSettings.displayMode === 'fullscreen') {
        showUniversalLoader(pTitle, 'Live database se data sync ho raha hai...', true);
    }
    if (loaders[page]) {
        Promise.resolve(loaders[page]()).finally(() => {
            finishTopLoading();
        });
    } else {
        finishTopLoading();
    }

    refreshIcons();
}
window._realShowPage = showPage;
window.showPage = showPage;

// If user clicked any navigation link before app.js finished loading, execute it now!
if (window._queuedPage) {
    const qPage = window._queuedPage;
    const qNav = window._queuedNavEl;
    window._queuedPage = null;
    window._queuedNavEl = null;
    showPage(qPage, qNav);
}

// ============ MASTER DATA (100% DIRECT LIVE SQL DATABASE) ============
async function loadMasterData() {
    const loadPart = async (endpoint, label) => {
        try {
            const res = await fetch(`${API}${endpoint}`);
            const json = await res.json();
            if (json && json.success === false) throw new Error(json.error || 'Server ne error return kiya');
            return { json, error: null, label };
        } catch (err) {
            console.warn(`[MasterData] ${label} live server fetch warning:`, err.message);
            return { json: { data: [] }, error: err, label };
        }
    };

    const [accPart, catPart, partyPart, custPart] = await Promise.all([
        loadPart('/accounts', 'Accounts'),
        loadPart('/categories', 'Categories'),
        loadPart('/parties', 'Parties'),
        loadPart('/customers?brief=1', 'Customers')
    ]);

    const failed = [accPart, catPart, partyPart, custPart].filter(p => p.error);
    if (failed.length) {
        showToast(`${failed.map(p => p.label).join(', ')} load nahi ho paye: ${failed[0].error.message}`, 'error', 'Master Data Error');
    }

    allAccounts = (accPart.json.data && accPart.json.data.length > 0) ? accPart.json.data : [
        { AccountID: 1, AccountName: 'Cash in Hand (Galla)', AccountType: 'Cash', CurrentBalance: 0 },
        { AccountID: 2, AccountName: 'Bank Account (Online)', AccountType: 'Bank', CurrentBalance: 0 },
        { AccountID: 3, AccountName: 'BC / AEPS Wallet', AccountType: 'Wallet', CurrentBalance: 0 }
    ];
    allCategories = (catPart.json.data && catPart.json.data.length > 0) ? catPart.json.data : [
        { CategoryID: 1, CategoryName: 'CSC Center Sewa Income', Type: 'Income' },
        { CategoryID: 2, CategoryName: 'BC / AEPS Commission', Type: 'Income' },
        { CategoryID: 3, CategoryName: 'Online Form / Print Out', Type: 'Income' },
        { CategoryID: 4, CategoryName: 'Shop Rent & Bijli', Type: 'Expense' },
        { CategoryID: 5, CategoryName: 'Stationery & Paper', Type: 'Expense' },
        { CategoryID: 6, CategoryName: 'General Expense', Type: 'Expense' }
    ];
    allParties = partyPart.json.data || [];
    allCustomersData = custPart.json.data || [];

    populateSelects();
    populateCustomerDropdowns();
    updateSidebarBalance();
}

function populateSelects() {
    // Account selects
    ['transAccount', 'transToAccount', 'filterAccount', 'invAccountSelect', 'payAccountSelect', 'khataAccountSelect'].forEach(id => {
        const sel = document.getElementById(id);
        if (!sel) return;
        const currentVal = sel.value;
        let prefix = '';
        if (id === 'filterAccount') prefix = '<option value="">Sab Accounts</option>';
        else if (id === 'khataAccountSelect') prefix = '<option value="">-- Sirf Khate me likho (No Account) --</option>';
        else if (id === 'invAccountSelect') prefix = '<option value="">-- Cash/Bank Khata Select Karein --</option>';
        else if (id === 'payAccountSelect') prefix = '<option value="">-- Khata Select Karein --</option>';

        const opts = (allAccounts || []).map(a => `<option value="${a.AccountID}" ${currentVal == a.AccountID ? 'selected' : ''}>${escapeHtml(a.AccountName)}</option>`).join('');
        sel.innerHTML = prefix + opts;
    });

    // Category selects
    ['transCategory', 'budgetCategory', 'billCategory', 'filterCategory'].forEach(id => {
        const sel = document.getElementById(id);
        if (!sel) return;
        const currentVal = sel.value;
        const opts = (allCategories || []).map(c => `<option value="${c.CategoryID}" ${currentVal == c.CategoryID ? 'selected' : ''}>${escapeHtml(c.CategoryName)} (${escapeHtml(c.CategoryType)})</option>`).join('');
        sel.innerHTML = '<option value="">-- Select --</option>' + opts;
    });

    // Party selects
    ['transParty', 'billParty'].forEach(id => {
        const sel = document.getElementById(id);
        if (!sel) return;
        const currentVal = sel.value;
        const opts = (allParties || []).map(p => `<option value="${p.PartyID}" ${currentVal == p.PartyID ? 'selected' : ''}>${escapeHtml(p.PartyName)}</option>`).join('');
        sel.innerHTML = '<option value="">-- None --</option>' + opts;
    });

    if (window.refreshAllSearchableSelects) {
        window.refreshAllSearchableSelects();
    }
}

function updateSidebarBalance() {
    const total = allAccounts.reduce((s, a) => s + parseFloat(a.CurrentBalance || 0), 0);
    document.getElementById('totalBalanceSidebar').textContent = formatMoney(total);
    document.getElementById('totalBalance').textContent = formatMoney(total);
}

// ============ DASHBOARD (100% DIRECT LIVE SQL DATABASE) ============
async function loadDashboard() {
    document.getElementById('selectedMonthLabel').textContent = `${MONTHS[selectedMonth - 1]} ${selectedYear}`;

    try {
        const res = await fetch(`${API}/transactions/summary/dashboard?month=${selectedMonth}&year=${selectedYear}`);
        const data = await res.json();
        if (!data.success) throw new Error(data.error);

        renderDashboardContent(data.data);
    } catch (err) {
        console.warn('[Dashboard] Live fetch error:', err.message);
        showToast('Dashboard load nahi hua: ' + err.message, 'error');
    }
}

function renderDashboardContent(dashboardData) {
    if (!dashboardData) return;
    const { summary, categoryWise, dailyFlow, accountBalances, recentTransactions } = dashboardData;

    // Summary Cards
    if (summary) {
        const incEl = document.getElementById('totalIncome');
        const expEl = document.getElementById('totalExpense');
        if (incEl) incEl.textContent = formatMoney(summary.TotalIncome || 0);
        if (expEl) expEl.textContent = formatMoney(summary.TotalExpense || 0);
        const net = (summary.TotalIncome || 0) - (summary.TotalExpense || 0);
        const netEl = document.getElementById('netAmount');
        if (netEl) {
            netEl.textContent = formatMoney(Math.abs(net));
            netEl.className = `sc-amount ${net >= 0 ? 'positive' : 'negative'}`;
        }
    }

    // Account balances
    if (Array.isArray(accountBalances)) {
        const totalBal = accountBalances.reduce((s, a) => s + parseFloat(a.CurrentBalance || 0), 0);
        const tbEl = document.getElementById('totalBalance');
        const tbsEl = document.getElementById('totalBalanceSidebar');
        if (tbEl) tbEl.textContent = formatMoney(totalBal);
        if (tbsEl) tbsEl.textContent = formatMoney(totalBal);
        renderAccountMiniCards(accountBalances);
    }

    // Charts & Transactions
    if (categoryWise && typeof renderExpenseChart === 'function') renderExpenseChart(categoryWise);
    if (dailyFlow && typeof renderFlowChart === 'function') renderFlowChart(dailyFlow);
    if (recentTransactions && typeof renderRecentTransactions === 'function') renderRecentTransactions(recentTransactions);

    if (window.lucide && typeof lucide.createIcons === 'function') lucide.createIcons();

    // Signal dashboard is 100% rendered to dismiss foreground update splash/wizard cleanly
    if (typeof window.onDashboardFullyLoaded === 'function') {
        try { window.onDashboardFullyLoaded(); } catch (_) { }
    }
}

function renderAccountMiniCards(accounts) {
    const container = document.getElementById('accountCards');
    if (!accounts.length) {
        container.innerHTML = `<div class="empty-state"><p>Koi account nahi. Account add karo!</p></div>`;
        return;
    }
    container.innerHTML = accounts.map(a => {
        const bal = parseFloat(a.CurrentBalance || 0);
        const icon = { Cash: '💵', Bank: '🏦', UPI: '📱', 'Credit Card': '💳', Other: '💰' }[a.AccountType] || '💰';
        return `
            <div class="account-mini-card" onclick="showPage('accounts', document.getElementById('nav-accounts'))">
                <div class="acc-icon" style="background:${a.Color}22">
                    <span>${icon}</span>
                </div>
                <div class="acc-info">
                    <div class="acc-name">${a.AccountName}</div>
                    <div class="acc-type">${a.AccountType}</div>
                </div>
                <div class="acc-balance ${bal >= 0 ? 'positive' : 'negative'}">${formatMoney(bal)}</div>
            </div>`;
    }).join('');
}

function renderExpenseChart(categories) {
    const container = document.querySelector('#page-dashboard .chart-container') || document.querySelector('.chart-container');
    if (!container) return;

    if (charts.expense) {
        charts.expense.destroy();
        charts.expense = null;
    }

    if (!categories || !categories.length) {
        container.innerHTML = '<div class="empty-state" style="padding: 40px 10px; text-align: center;"><p>Is mahine kharcha nahi</p></div>';
        const legend = document.getElementById('categoryLegend');
        if (legend) legend.innerHTML = '';
        return;
    }

    let ctx = document.getElementById('expenseChart');
    if (!ctx) {
        container.innerHTML = '<canvas id="expenseChart"></canvas>';
        ctx = document.getElementById('expenseChart');
    }

    charts.expense = new Chart(ctx, {
        type: 'doughnut',
        data: {
            labels: categories.map(c => c.CategoryName),
            datasets: [{
                data: categories.map(c => c.Total),
                backgroundColor: categories.map(c => c.Color + 'dd'),
                borderColor: '#1a2235',
                borderWidth: 2,
                hoverOffset: 6
            }]
        },
        options: {
            responsive: true, maintainAspectRatio: true,
            cutout: '65%',
            plugins: {
                legend: { display: false },
                tooltip: {
                    callbacks: {
                        label: (ctx) => ` ${ctx.label}: ${formatMoney(ctx.raw)}`
                    }
                }
            }
        }
    });

    // Legend
    const legend = document.getElementById('categoryLegend');
    legend.innerHTML = categories.slice(0, 6).map(c => `
        <div class="legend-item">
            <div class="legend-dot" style="background:${c.Color}"></div>
            <span>${c.CategoryName}</span>
        </div>
    `).join('');
}

function renderFlowChart(dailyFlow) {
    const ctx = document.getElementById('flowChart');
    if (charts.flow) charts.flow.destroy();

    charts.flow = new Chart(ctx, {
        type: 'bar',
        data: {
            labels: dailyFlow.map(d => formatDate(d.TransDate)),
            datasets: [
                {
                    label: 'Income',
                    data: dailyFlow.map(d => d.Income),
                    backgroundColor: 'rgba(16, 185, 129, 0.7)',
                    borderRadius: 4
                },
                {
                    label: 'Expense',
                    data: dailyFlow.map(d => d.Expense),
                    backgroundColor: 'rgba(239, 68, 68, 0.7)',
                    borderRadius: 4
                }
            ]
        },
        options: {
            responsive: true, maintainAspectRatio: false,
            plugins: {
                legend: {
                    labels: { color: '#94a3b8', font: { size: 12 } }
                },
                tooltip: {
                    callbacks: {
                        label: (ctx) => ` ${ctx.dataset.label}: ${formatMoney(ctx.raw)}`
                    }
                }
            },
            scales: {
                x: { grid: { color: '#1e293b' }, ticks: { color: '#64748b', font: { size: 11 } } },
                y: {
                    grid: { color: '#1e293b' },
                    ticks: {
                        color: '#64748b', font: { size: 11 },
                        callback: v => formatMoney(v)
                    }
                }
            }
        }
    });
}

function renderRecentTransactions(transactions) {
    const container = document.getElementById('recentTransactions');
    if (!transactions.length) {
        container.innerHTML = `<div class="empty-state"><i data-lucide="inbox" width="48" height="48"></i><h3>Koi transaction nahi</h3><p>Pehli entry add karo!</p></div>`;
        return;
    }
    container.innerHTML = transactions.map(t => renderTransRow(t)).join('');
}

function renderTransRow(t) {
    const icon = t.CategoryIcon ? '' : '💰';
    const color = t.CategoryColor || '#6366f1';
    const colorClass = getTransColor(t.TransType);
    const sign = getTransSign(t.TransType);
    const emoji = { Income: '📈', Expense: '📉', Transfer: '🔄', 'Loan Given': '🤝', 'Loan Received': '💸', 'Loan Repay': '↩️', 'Loan Recovery': '📥' };

    return `
        <div class="trans-row" onclick="editTransaction(${t.TransactionID})">
            <div class="trans-icon" style="background:${color}22; color:${color}">
                ${emoji[t.TransType] || '💰'}
            </div>
            <div class="trans-info">
                <div class="trans-desc">${t.Description || t.CategoryName || t.TransType}</div>
                <div class="trans-meta">
                    <span>${t.AccountName || ''}</span>
                    ${t.CategoryName ? `<span class="dot">•</span><span>${t.CategoryName}</span>` : ''}
                    ${t.PartyName ? `<span class="dot">•</span><span>${t.PartyName}</span>` : ''}
                </div>
            </div>
            <div class="trans-amount ${colorClass}">${sign}${formatMoney(t.Amount)}</div>
            <div class="trans-date" style="text-align: right;">
                <div style="font-weight: 600;">${formatIndianDate(t.TransDate)}</div>
                <div style="font-size: 11px; color: var(--text-muted); margin-top: 1px;"><i data-lucide="clock" style="width:10px;height:10px;vertical-align:middle;display:inline-block;"></i> ${formatTime(t.TransTime || t.CreatedAt) || '12:00 AM'}</div>
            </div>
            <div class="trans-actions" onclick="event.stopPropagation()">
                <button class="btn-icon" onclick="editTransaction(${t.TransactionID})" title="Edit"><i data-lucide="edit-2" width="16" height="16"></i></button>
                <button class="btn-icon" onclick="deleteTransaction(${t.TransactionID})" title="Delete" style="color:var(--accent-red)"><i data-lucide="trash-2" width="16" height="16"></i></button>
            </div>
        </div>`;
}

function changeMonth(dir) {
    selectedMonth += dir;
    if (selectedMonth > 12) { selectedMonth = 1; selectedYear++; }
    if (selectedMonth < 1) { selectedMonth = 12; selectedYear--; }
    loadDashboard();
}

// ============ TRANSACTIONS ============
let transCurrentPage = 1;
let transLimit = 20;
let transCurrentTypeFilter = '';

async function loadTransactions(page = 1) {
    if (page) transCurrentPage = page;
    const container = document.getElementById('transTableBody');
    if (!container) return;
    renderTableSkeleton(container, 9, 6);

    const params = new URLSearchParams({
        limit: transLimit,
        offset: (transCurrentPage - 1) * transLimit
    });

    const startDate = document.getElementById('filterStartDate')?.value;
    const endDate = document.getElementById('filterEndDate')?.value;
    const type = transCurrentTypeFilter || document.getElementById('filterType')?.value;
    const accountId = document.getElementById('filterAccount')?.value;
    const categoryId = document.getElementById('filterCategory')?.value;
    const search = document.getElementById('searchTrans')?.value;

    if (startDate) params.append('startDate', startDate);
    if (endDate) params.append('endDate', endDate);
    if (type) params.append('type', type);
    if (accountId) params.append('accountId', accountId);
    if (categoryId) params.append('categoryId', categoryId);
    if (search) params.append('search', search);

    try {
        const res = await fetch(`${API}/transactions?${params}`);
        const data = await res.json();
        allTransactions = data.data || [];
        const total = data.total || 0;
        const totals = data.totals || {};

        // Update sidebar badge
        const badge = document.getElementById('badge-transactions');
        if (badge) {
            badge.textContent = total || 0;
            badge.classList.remove('hidden');
            badge.style.display = 'inline-block';
        }
        const badgeAll = document.getElementById('ttBadgeAll');
        if (badgeAll) badgeAll.textContent = total;

        // Update 4 KPI Cards
        updateTransKpiCards(totals, allTransactions);

        if (!allTransactions.length) {
            container.innerHTML = `
                <tr>
                    <td colspan="9" class="text-center" style="padding: 50px;">
                        <div class="empty-state">
                            <i data-lucide="search" width="44" height="44" style="color: var(--text-muted); margin-bottom: 12px;"></i>
                            <h3 style="font-size: 16px; margin-bottom: 6px;">Koi transaction nahi mila</h3>
                            <p style="color: var(--text-muted); font-size: 13px; margin-bottom: 14px;">Filter badlein ya nayi entry add karein</p>
                            <button class="btn-primary" onclick="openAddTransaction()"><i data-lucide="plus"></i> Nayi Entry</button>
                        </div>
                    </td>
                </tr>`;
            renderTransPagination(0);
            lucide.createIcons();
            return;
        }

        container.innerHTML = allTransactions.map((t, i) => {
            const rowIdx = (transCurrentPage - 1) * transLimit + i + 1;
            const sign = getTransSign(t.TransType);
            const colorClass = getTransColor(t.TransType);

            // Format Account display: For transfers, show Source ➔ Destination with pill
            let accountHtml = '';
            if (t.TransType === 'Transfer') {
                accountHtml = `
                    <div class="trans-transfer-route">
                        <span class="route-acc source" title="${escapeHtml(t.AccountName || 'Unknown')}">${escapeHtml(t.AccountName || '-')}</span>
                        <i data-lucide="arrow-right" class="route-arrow"></i>
                        <span class="route-acc dest" title="${escapeHtml(t.ToAccountName || 'Unknown')}">${escapeHtml(t.ToAccountName || '-')}</span>
                    </div>`;
            } else {
                const accColor = t.AccountColor || '#6366f1';
                accountHtml = `
                    <div class="trans-acc-badge">
                        <span class="acc-bullet" style="background:${accColor}"></span>
                        <span class="acc-name">${escapeHtml(t.AccountName || '-')}</span>
                    </div>`;
            }

            // Format Category display with color dot if available
            let catHtml = '<span class="text-muted">-</span>';
            if (t.CategoryName) {
                const catColor = t.CategoryColor || '#94a3b8';
                catHtml = `
                    <span class="cat-pill">
                        <span class="cat-bullet" style="background:${catColor}"></span>
                        ${escapeHtml(t.CategoryName)}
                    </span>`;
            }

            // Type badge styling
            const typeBadgeHtml = `<span class="type-badge ${colorClass}">${escapeHtml(t.TransType)}</span>`;

            // Description and Party
            const descMain = escapeHtml(t.Description || t.CategoryName || t.TransType);
            const partyHtml = t.PartyName ? `<span class="trans-party-pill"><i data-lucide="user"></i> ${escapeHtml(t.PartyName)}</span>` : '';
            const tagHtml = t.Tags ? `<span class="trans-tag-pill">#${escapeHtml(t.Tags)}</span>` : '';

            return `
                <tr class="trans-data-row" onclick="editTransaction(${t.TransactionID})">
                    <td class="cell-center" style="vertical-align: middle; text-align: center;" onclick="event.stopPropagation()">
                        <button type="button" 
                                class="csc-sn-pill uni-sn-pill" 
                                onclick="openUniversalRecordDetail('Cashbook', ${t.TransactionID}, '${escapeInlineArg(t.SNCode || '')}')" 
                                title="Universal Serial No: ${escapeHtml(t.SNCode || ('SN-' + t.GlobalSerialNo))} (Click karke Poori Detail Dekhein)">
                            <i data-lucide="file-text" width="12" height="12"></i>
                            <span>${escapeHtml(t.SNCode || (t.GlobalSerialNo ? 'SN-' + t.GlobalSerialNo : ('#' + rowIdx)))}</span>
                        </button>
                    </td>
                    <td>
                        <div class="trans-date-cell">
                            <span class="date-main">${formatIndianDate(t.TransDate)}</span>
                            <span class="date-sub"><i data-lucide="clock" style="width:10px;height:10px;display:inline-block;vertical-align:middle;"></i> ${formatTime(t.TransTime || t.CreatedAt) || '12:00 AM'}</span>
                        </div>
                    </td>
                    <td>
                        <div class="trans-desc-cell">
                            <span class="desc-title">${descMain}</span>
                            <div class="desc-meta">${partyHtml}${tagHtml}</div>
                        </div>
                    </td>
                    <td>${typeBadgeHtml}</td>
                    <td>${accountHtml}</td>
                    <td>${catHtml}</td>
                    <td>
                        <span class="ref-code" title="${escapeHtml(t.Reference || '')}">${escapeHtml(t.Reference || '-')}</span>
                    </td>
                    <td class="text-right">
                        <div class="trans-amount-cell ${colorClass}" style="font-size: 14px; font-weight: 700;">
                            <span class="amt-sign">${sign === '+' ? '+ ' : '− '}</span>${formatMoney(t.Amount)}
                        </div>
                    </td>
                    <td class="text-center" onclick="event.stopPropagation()">
                        <div class="table-actions" style="justify-content: center; gap: 5px;">
                            <button class="btn-icon" title="Edit" onclick="editTransaction(${t.TransactionID})" style="color: #38bdf8;">
                                <i data-lucide="edit-2" width="14" height="14"></i>
                            </button>
                            <button type="button" class="table-menu-trigger-btn trans-menu-trigger-btn" onclick="toggleTransActionMenu(event, ${t.TransactionID})" title="Sabhi Kriya (3 Dots Menu)">
                                <i data-lucide="more-vertical" width="15" height="15"></i>
                            </button>
                        </div>
                    </td>
                </tr>`;
        }).join('');

        renderTransPagination(total);
        lucide.createIcons();
    } catch (err) {
        console.warn('[Transactions] Live fetch error:', err.message);
        container.innerHTML = `<tr><td colspan="9" class="text-center" style="padding: 30px; color: var(--text-muted); font-size: 13px;">⚠️ Transactions load nahi ho sake: ${escapeHtml(err.message)}</td></tr>`;
        showToast('Transactions load nahi hue: ' + err.message, 'error');
    }
}

// --------------------------------------------------------------------------
// FLOATING 3-DOT ACTION MENU FOR TRANSACTIONS
// --------------------------------------------------------------------------
let activeTransDropdownId = null;

function toggleTransActionMenu(e, transId) {
    if (e) {
        e.preventDefault();
        e.stopPropagation();
    }

    const existingMenu = document.getElementById('transFloatingActionMenu');
    if (existingMenu && activeTransDropdownId === transId) {
        closeTransActionMenu();
        return;
    }

    closeAllActionMenus();

    const t = (allTransactions || []).find(tr => Number(tr.TransactionID) === Number(transId));
    if (!t) return;

    const triggerBtn = (e && e.currentTarget) ? e.currentTarget : (e && e.target ? e.target.closest('.trans-menu-trigger-btn, .table-menu-trigger-btn') : null);
    if (!triggerBtn) return;

    triggerBtn.classList.add('active');
    activeTransDropdownId = transId;

    const descMain = escapeHtml(t.Description || t.CategoryName || t.TransType || 'Transaction');
    const colorClass = getTransColor(t.TransType);
    const sign = getTransSign(t.TransType);
    const safeParty = escapeHtml(t.PartyName || '');

    const menu = document.createElement('div');
    menu.id = 'transFloatingActionMenu';
    menu.className = 'cust-action-dropdown-menu';

    menu.innerHTML = `
        <div class="cad-header">
            <div class="cad-title-row">
                <span class="cad-name" title="${descMain}">${descMain}</span>
                <span class="cad-id font-mono">#${t.TransactionID}</span>
            </div>
            <div style="display: flex; align-items: center; justify-content: space-between; gap: 6px; margin-top: 5px;">
                <span class="type-badge ${colorClass}" style="font-size: 10px; padding: 2px 7px;">${escapeHtml(t.TransType)}</span>
                <span style="font-size: 12px; font-weight: 800;" class="${colorClass}">
                    ${sign}${formatMoney(t.Amount)}
                </span>
            </div>
            <div style="font-size: 11px; color: var(--text-muted); margin-top: 4px;">
                📅 ${formatIndianDate(t.TransDate)} • ${escapeHtml(t.AccountName || '-')}
            </div>
        </div>
        <div class="cad-items">
            <button type="button" class="cad-item" id="transOptEdit">
                <span class="cad-icon cyan"><i data-lucide="edit-2"></i></span>
                <div class="cad-label">
                    <span class="cad-primary">Transaction Edit / Vivran</span>
                    <span class="cad-secondary">Rakam, tarikh, account badlein</span>
                </div>
            </button>
            <button type="button" class="cad-item" id="transOptDuplicate">
                <span class="cad-icon purple"><i data-lucide="copy"></i></span>
                <div class="cad-label">
                    <span class="cad-primary">Entry Dohrayein (Duplicate)</span>
                    <span class="cad-secondary">Is jaisi nayi entry form me bharein</span>
                </div>
            </button>
            ${t.PartyID ? `
                <button type="button" class="cad-item" id="transOptPartyKhata">
                    <span class="cad-icon indigo"><i data-lucide="book-open"></i></span>
                    <div class="cad-label">
                        <span class="cad-primary">Party Khata Passbook</span>
                        <span class="cad-secondary">${safeParty} ka poora hisaab</span>
                    </div>
                </button>
            ` : ''}
            <div class="cad-divider"></div>
            <button type="button" class="cad-item danger" id="transOptDelete">
                <span class="cad-icon red"><i data-lucide="trash-2"></i></span>
                <div class="cad-label">
                    <span class="cad-primary text-danger">Transaction Delete Karein</span>
                    <span class="cad-secondary">Is entry ko accounts se mitaayein</span>
                </div>
            </button>
        </div>
    `;

    menu.querySelector('#transOptEdit')?.addEventListener('click', () => {
        closeTransActionMenu();
        editTransaction(t.TransactionID);
    });
    menu.querySelector('#transOptDuplicate')?.addEventListener('click', () => {
        closeTransActionMenu();
        openAddTransaction(t.TransType, {
            amount: t.Amount,
            desc: t.Description,
            ref: t.Reference,
            account: t.AccountID,
            toAccount: t.ToAccountID,
            party: t.PartyID,
            tags: t.Tags
        });
    });
    menu.querySelector('#transOptPartyKhata')?.addEventListener('click', () => {
        closeTransActionMenu();
        if (t.PartyID) openPartyLedger(t.PartyID, t.PartyName);
    });
    menu.querySelector('#transOptDelete')?.addEventListener('click', () => {
        closeTransActionMenu();
        deleteTransaction(t.TransactionID);
    });

    positionFloatingMenu(menu, triggerBtn, 270);
}

function closeTransActionMenu() {
    activeTransDropdownId = null;
    document.querySelectorAll('.trans-menu-trigger-btn.active').forEach(b => b.classList.remove('active'));
    const m = document.getElementById('transFloatingActionMenu');
    if (m) {
        m.classList.remove('active');
        m.remove();
    }
}
window.toggleTransActionMenu = toggleTransActionMenu;
window.closeTransActionMenu = closeTransActionMenu;

function updateTransKpiCards(totals, list) {
    const income = totals.totalIncome !== undefined ? Number(totals.totalIncome) : list.filter(t => t.TransType === 'Income').reduce((s, t) => s + Number(t.Amount || 0), 0);
    const expense = totals.totalExpense !== undefined ? Number(totals.totalExpense) : list.filter(t => t.TransType === 'Expense').reduce((s, t) => s + Number(t.Amount || 0), 0);
    const transfer = totals.totalTransfer !== undefined ? Number(totals.totalTransfer) : list.filter(t => t.TransType === 'Transfer').reduce((s, t) => s + Number(t.Amount || 0), 0);
    const net = income - expense;

    const elInc = document.getElementById('transKpiIncome');
    const elExp = document.getElementById('transKpiExpense');
    const elTr = document.getElementById('transKpiTransfer');
    const elNet = document.getElementById('transKpiNet');
    const elNetBadge = document.getElementById('transKpiNetBadge');

    if (elInc) elInc.textContent = formatMoney(income);
    if (elExp) elExp.textContent = formatMoney(expense);
    if (elTr) elTr.textContent = formatMoney(transfer);

    if (elNet) {
        elNet.textContent = (net >= 0 ? '+' : '') + formatMoney(net);
        elNet.className = 'tcs-val ' + (net >= 0 ? 'amt-pos' : 'amt-neg');
    }
    if (elNetBadge) {
        if (net >= 0) {
            elNetBadge.textContent = 'Bachat';
            elNetBadge.className = 'tcs-badge net';
        } else {
            elNetBadge.textContent = 'Ghata';
            elNetBadge.className = 'tcs-badge loss';
        }
    }
}

function setTransFilterType(type, btnEl) {
    transCurrentTypeFilter = type;
    document.querySelectorAll('.tt-tab').forEach(b => b.classList.remove('active'));
    if (btnEl) btnEl.classList.add('active');

    const sel = document.getElementById('filterType');
    if (sel) sel.value = type;

    loadTransactions(1);
}

function syncTransTypeSelect(val) {
    transCurrentTypeFilter = val;
    document.querySelectorAll('.tt-tab').forEach(b => {
        b.classList.toggle('active', b.getAttribute('data-type') === val);
    });
    loadTransactions(1);
}

// Accounts page "Passbook" button: is account ka poora ledger dikhaye
function filterByAccount(accountId) {
    if (!accountId) return;
    // Reset date/category/search filters so we see the full passbook for this account
    const sd = document.getElementById('filterStartDate');
    const ed = document.getElementById('filterEndDate');
    const catSel = document.getElementById('filterCategory');
    const searchEl = document.getElementById('searchTrans');
    if (sd) sd.value = '';
    if (ed) ed.value = '';
    if (catSel) catSel.value = '';
    if (searchEl) searchEl.value = '';

    // Jump to transactions page first so the filter selectors exist
    showPage('transactions', document.getElementById('nav-transactions'));

    // Set the account filter (selectors are populated by loadMasterData)
    const applyFilter = () => {
        const accSel = document.getElementById('filterAccount');
        if (!accSel) return;
        // Ensure the option exists (in case account list not yet loaded)
        const hasOption = Array.from(accSel.options).some(o => o.value === String(accountId));
        if (!hasOption) {
            const opt = document.createElement('option');
            opt.value = String(accountId);
            opt.textContent = 'Selected Account';
            accSel.appendChild(opt);
        }
        accSel.value = String(accountId);
        loadTransactions(1);
    };

    // Give the page a tick to render, then apply
    setTimeout(applyFilter, 50);
}

// ==========================================================================
// AUTHENTIC BANK-STYLE ACCOUNT PASSBOOK MODAL (RUNNING BALANCE LEDGER)
// ==========================================================================
let currentPassbookAccountId = null;
let currentPassbookData = null;
let passbookCurrentSort = 'desc'; // 'desc' or 'asc'

async function openAccountPassbookModal(accountId) {
    if (!accountId) return;
    currentPassbookAccountId = accountId;
    passbookCurrentSort = 'desc';

    const modal = document.getElementById('accountPassbookModal');
    if (!modal) return;

    // Reset toolbar inputs
    const searchInp = document.getElementById('pbSearchInput');
    const startInp = document.getElementById('pbStartDate');
    const endInp = document.getElementById('pbEndDate');
    if (searchInp) searchInp.value = '';
    if (startInp) startInp.value = '';
    if (endInp) endInp.value = '';

    // Reset date buttons
    document.querySelectorAll('.pb-quick-date-btn').forEach(b => b.classList.remove('active'));
    const btnAll = document.getElementById('pbDateAll');
    if (btnAll) btnAll.classList.add('active');

    const sortLabel = document.getElementById('pbSortLabel');
    if (sortLabel) sortLabel.textContent = 'Naya Pehle';

    // Show loading in table
    const tbody = document.getElementById('pbPassbookTableBody');
    if (tbody) {
        tbody.innerHTML = `<tr><td colspan="7" class="text-center" style="padding: 40px; color: var(--text-muted);">
            <div style="display:flex; flex-direction:column; align-items:center; gap:10px;">
                <div class="spinner" style="width:28px; height:28px; border:3px solid var(--border); border-top-color:#10b981; border-radius:50%; animation: spin 0.8s linear infinite;"></div>
                <span>Passbook load ho rahi hai...</span>
            </div>
        </td></tr>`;
    }

    openModal('accountPassbookModal');

    // Fetch data
    await fetchPassbookData();

    if (window.lucide && typeof lucide.createIcons === 'function') {
        lucide.createIcons();
    }
}

function closeAccountPassbookModal() {
    closeModal('accountPassbookModal');
}

async function fetchPassbookData() {
    if (!currentPassbookAccountId) return;
    const startVal = document.getElementById('pbStartDate')?.value || '';
    const endVal = document.getElementById('pbEndDate')?.value || '';
    const searchVal = document.getElementById('pbSearchInput')?.value || '';

    let url = `/api/accounts/${currentPassbookAccountId}/passbook?sort=${passbookCurrentSort}`;
    if (startVal) url += `&startDate=${encodeURIComponent(startVal)}`;
    if (endVal) url += `&endDate=${encodeURIComponent(endVal)}`;
    if (searchVal.trim()) url += `&search=${encodeURIComponent(searchVal.trim())}`;

    try {
        const res = await fetch(url);
        const json = await res.json();
        if (!json.success) {
            throw new Error(json.error || 'Failed to load passbook');
        }
        currentPassbookData = json;
        renderPassbookHeaderAndKPI(json);
        renderPassbookRows(json.data || []);
    } catch (err) {
        console.error('Passbook fetch error:', err);
        const tbody = document.getElementById('pbPassbookTableBody');
        if (tbody) {
            tbody.innerHTML = `<tr><td colspan="7" class="text-center" style="padding: 40px; color: var(--accent-red);">
                <i data-lucide="alert-circle" style="width:32px; height:32px; margin-bottom:8px; display:inline-block;"></i>
                <p>Passbook load karne me samasya aayi: ${escapeHtml(err.message)}</p>
            </td></tr>`;
            lucide.createIcons();
        }
    }
}

function renderPassbookHeaderAndKPI(data) {
    const acc = data.account || {};
    const sum = data.summary || {};

    const elName = document.getElementById('pbModalAccountName');
    const elType = document.getElementById('pbModalAccountType');
    const elBank = document.getElementById('pbModalBankName');
    const elAccNo = document.getElementById('pbModalAccNumber');
    const elDate = document.getElementById('pbStatementDate');
    const elEmblem = document.getElementById('pbEmblem');

    if (elName) elName.textContent = acc.AccountName || 'Account Passbook';
    if (elType) elType.textContent = (acc.AccountType || 'Account').toUpperCase();
    if (elBank) elBank.textContent = acc.BankName || (acc.AccountType === 'Cash' ? 'Physical Cash / Galla' : 'Portal / Wallet');
    if (elAccNo) elAccNo.textContent = acc.AccountNumber || (acc.AccountType === 'Cash' ? 'GALLA-COUNTER-01' : 'ACC-' + acc.AccountID);
    if (elDate) {
        const today = new Date().toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' });
        elDate.textContent = today;
    }

    if (elEmblem) {
        let iconName = 'book-open';
        if (acc.AccountType === 'Cash' || (acc.AccountName || '').toLowerCase().includes('cash')) iconName = 'banknote';
        else if (acc.AccountType === 'Bank') iconName = 'landmark';
        else if ((acc.AccountName || '').toLowerCase().includes('digipay')) iconName = 'smartphone';
        elEmblem.innerHTML = `<i data-lucide="${iconName}"></i>`;
    }

    const elOpen = document.getElementById('pbKpiOpening');
    const elCred = document.getElementById('pbKpiCredit');
    const elDeb = document.getElementById('pbKpiDebit');
    const elClose = document.getElementById('pbKpiClosing');

    if (elOpen) elOpen.textContent = formatMoney(sum.openingBalance || 0);
    if (elCred) elCred.textContent = '+' + formatMoney(sum.viewCredit || sum.totalCredit || 0);
    if (elDeb) elDeb.textContent = '-' + formatMoney(sum.viewDebit || sum.totalDebit || 0);
    if (elClose) elClose.textContent = formatMoney(sum.closingBalance || 0);
}

let pbRenderedLimit = 100;
let pbCurrentEntries = [];

function buildPassbookRowHtml(row) {
    const dateStr = row.date ? new Date(row.date).toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' }) : '—';
    const timeStr = row.time || '';
    const debitAmt = parseFloat(row.debit || 0);
    const creditAmt = parseFloat(row.credit || 0);
    const balAmt = parseFloat(row.balanceAfter || 0);

    let typeBadgeColor = 'background: rgba(148, 163, 184, 0.15); color: #94a3b8;';
    const tLower = (row.type || '').toLowerCase();
    if (tLower.includes('nikasi') || tLower.includes('withdrawal') || tLower.includes('out') || tLower.includes('expense')) {
        typeBadgeColor = 'background: rgba(244, 63, 94, 0.15); color: #f43f5e; border: 1px solid rgba(244, 63, 94, 0.3);';
    } else if (tLower.includes('jama') || tLower.includes('deposit') || tLower.includes('in') || tLower.includes('credit') || tLower.includes('income')) {
        typeBadgeColor = 'background: rgba(16, 185, 129, 0.15); color: #34d399; border: 1px solid rgba(16, 185, 129, 0.3);';
    } else if (tLower.includes('transfer') || tLower.includes('payout')) {
        typeBadgeColor = 'background: rgba(139, 92, 246, 0.15); color: #a78bfa; border: 1px solid rgba(139, 92, 246, 0.3);';
    } else if (tLower.includes('qr')) {
        typeBadgeColor = 'background: rgba(249, 115, 22, 0.15); color: #fb923c; border: 1px solid rgba(249, 115, 22, 0.3);';
    }

    const debitCell = debitAmt > 0
        ? `<span class="pb-amount-debit">-₹${debitAmt.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</span>`
        : '<span class="cell-muted">—</span>';

    const creditCell = creditAmt > 0
        ? `<span class="pb-amount-credit">+₹${creditAmt.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</span>`
        : '<span class="cell-muted">—</span>';

    const refCell = row.ref
        ? `<span class="pb-ref-badge" title="RRN/UTR: ${escapeHtml(row.ref)}">${escapeHtml(row.ref)}</span>`
        : '<span class="cell-muted">—</span>';

    return `<tr>
        <td>
            <div class="pb-cell-date">
                <span class="pb-date-main">${dateStr}</span>
                ${timeStr ? `<span class="pb-time-sub">${escapeHtml(timeStr)}</span>` : ''}
            </div>
        </td>
        <td>
            <div class="pb-particulars">${escapeHtml(row.particulars || 'Transaction')}</div>
        </td>
        <td>${refCell}</td>
        <td>
            <span class="pb-type-tag" style="${typeBadgeColor}">${escapeHtml(row.type || 'General')}</span>
        </td>
        <td class="cell-right">${debitCell}</td>
        <td class="cell-right">${creditCell}</td>
        <td class="cell-right" style="background: rgba(16, 185, 129, 0.04);">
            <span class="pb-amount-balance">₹${balAmt.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</span>
        </td>
    </tr>`;
}

function renderPassbookChunk() {
    const tbody = document.getElementById('pbPassbookTableBody');
    const infoEl = document.getElementById('pbFooterInfo');
    if (!tbody) return;

    const slice = pbCurrentEntries.slice(0, pbRenderedLimit);
    const hasMore = pbCurrentEntries.length > pbRenderedLimit;

    if (infoEl) {
        infoEl.innerHTML = `Kul <strong>${pbCurrentEntries.length}</strong> me se <strong>${slice.length}</strong> transactions dikh rahe hain` +
            (hasMore ? ` — <button type="button" class="btn btn-xs btn-outline-primary" style="margin-left: 8px; padding: 3px 10px; font-size: 11.5px; border-radius: 4px; cursor: pointer;" onclick="loadMorePassbookRows()">Aage Ke Dekhein (+100)</button> <button type="button" class="btn btn-xs btn-outline-secondary" style="margin-left: 6px; padding: 3px 10px; font-size: 11.5px; border-radius: 4px; cursor: pointer;" onclick="loadAllPassbookRows()">Sabhi Dekhein</button>` : '');
    }

    tbody.innerHTML = slice.map(row => buildPassbookRowHtml(row)).join('');
}

function loadMorePassbookRows() {
    pbRenderedLimit += 100;
    renderPassbookChunk();
}

function loadAllPassbookRows() {
    pbRenderedLimit = pbCurrentEntries.length;
    renderPassbookChunk();
}

function renderPassbookRows(entries) {
    const tbody = document.getElementById('pbPassbookTableBody');
    const infoEl = document.getElementById('pbFooterInfo');
    if (!tbody) return;

    pbCurrentEntries = entries || [];
    pbRenderedLimit = 100;

    if (!pbCurrentEntries.length) {
        if (infoEl) infoEl.textContent = 'Kul 0 transactions dikh rahe hain';
        tbody.innerHTML = `<tr>
            <td colspan="7" class="text-center" style="padding: 50px 20px; color: var(--text-muted);">
                <i data-lucide="receipt" style="width:40px; height:40px; stroke-width:1.5; margin-bottom:10px; display:inline-block; opacity:0.5;"></i>
                <h4 style="margin:0 0 6px 0; font-size:15px; color:var(--text-primary);">Koi Transaction Nahi Mila</h4>
                <p style="margin:0; font-size:12.5px;">Chune gaye filter me is khate ka koi transaction darj nahi hai.</p>
            </td>
        </tr>`;
        lucide.createIcons();
        return;
    }

    renderPassbookChunk();
}

function filterPassbookClientSide() {
    const q = (document.getElementById('pbSearchInput')?.value || '').toLowerCase().trim();
    if (!currentPassbookData || !currentPassbookData.data) return;

    if (!q) {
        renderPassbookRows(currentPassbookData.data);
        return;
    }

    const filtered = currentPassbookData.data.filter(r => {
        return (r.particulars && r.particulars.toLowerCase().includes(q)) ||
            (r.ref && r.ref.toLowerCase().includes(q)) ||
            (r.type && r.type.toLowerCase().includes(q)) ||
            (r.customerName && r.customerName.toLowerCase().includes(q));
    });
    renderPassbookRows(filtered);
}

function setPassbookDateRange(type) {
    document.querySelectorAll('.pb-quick-date-btn').forEach(b => b.classList.remove('active'));
    const startInp = document.getElementById('pbStartDate');
    const endInp = document.getElementById('pbEndDate');

    const now = new Date();
    const pad = n => String(n).padStart(2, '0');
    const todayStr = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;

    if (type === 'all') {
        document.getElementById('pbDateAll')?.classList.add('active');
        if (startInp) startInp.value = '';
        if (endInp) endInp.value = '';
    } else if (type === 'today') {
        document.getElementById('pbDateToday')?.classList.add('active');
        if (startInp) startInp.value = todayStr;
        if (endInp) endInp.value = todayStr;
    } else if (type === 'month') {
        document.getElementById('pbDateMonth')?.classList.add('active');
        const firstDay = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-01`;
        if (startInp) startInp.value = firstDay;
        if (endInp) endInp.value = todayStr;
    }
    fetchPassbookData();
}

function togglePassbookSort() {
    passbookCurrentSort = passbookCurrentSort === 'desc' ? 'asc' : 'desc';
    const label = document.getElementById('pbSortLabel');
    if (label) {
        label.textContent = passbookCurrentSort === 'desc' ? 'Naya Pehle' : 'Purana Pehle';
    }
    fetchPassbookData();
}

function printPassbookStatement() {
    universalPrint('passbook', { format: 'a4', title: 'Bank Passbook Statement' });
}

function exportPassbookCSV() {
    if (!currentPassbookData || !currentPassbookData.data || !currentPassbookData.data.length) {
        if (typeof showToast === 'function') showToast('Export karne ke liye koi transactions nahi hain', 'warning');
        return;
    }
    const acc = currentPassbookData.account || {};
    const rows = [
        ['Date', 'Time', 'Particulars', 'RRN_UTR', 'Type', 'Debit (Dr)', 'Credit (Cr)', 'Balance After (INR)'],
        ...currentPassbookData.data.map(r => [
            r.date ? r.date.split('T')[0] : '',
            r.time || '',
            `"${(r.particulars || '').replace(/"/g, '""')}"`,
            r.ref || '',
            r.type || '',
            r.debit || 0,
            r.credit || 0,
            r.balanceAfter || 0
        ])
    ];

    const csvContent = 'data:text/csv;charset=utf-8,\uFEFF' + rows.map(e => e.join(',')).join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement('a');
    link.setAttribute('href', encodedUri);
    const fname = `Passbook_${(acc.AccountName || 'Account').replace(/\s+/g, '_')}_${new Date().toISOString().split('T')[0]}.csv`;
    link.setAttribute('download', fname);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
}

// Direct pipeline pillar passbook opener (Galla / Wallets / Bank)
function openPipelinePassbook(type) {
    const doOpen = (accounts) => {
        if (!accounts || !accounts.length) {
            showPage('transactions', document.getElementById('nav-transactions'));
            return;
        }
        let targetAcc = null;
        if (type === 'cash') {
            targetAcc = accounts.find(a => (a.AccountType || '').toLowerCase() === 'cash' || (a.AccountName || '').toLowerCase().includes('cash') || (a.AccountName || '').toLowerCase().includes('galla'));
        } else if (type === 'digipay') {
            targetAcc = accounts.find(a => (a.AccountName || '').toLowerCase().includes('digipay') || (a.AccountType || '').toLowerCase() === 'portal');
        } else if (type === 'bank') {
            targetAcc = accounts.find(a => (a.AccountType || '').toLowerCase() === 'bank' && !(a.AccountName || '').toLowerCase().includes('digipay'));
        }
        if (targetAcc && targetAcc.AccountID) {
            openAccountPassbookModal(targetAcc.AccountID);
        } else {
            showPage('transactions', document.getElementById('nav-transactions'));
        }
    };

    if (typeof allAccounts !== 'undefined' && allAccounts && allAccounts.length) {
        doOpen(allAccounts);
    } else {
        fetch('/api/accounts')
            .then(r => r.json())
            .then(res => {
                if (res.data) allAccounts = res.data;
                doOpen(allAccounts || []);
            })
            .catch(() => {
                showPage('transactions', document.getElementById('nav-transactions'));
            });
    }
}

function renderTransPagination(total) {
    const totalPages = Math.ceil(total / transLimit) || 1;
    const startIdx = total === 0 ? 0 : (transCurrentPage - 1) * transLimit + 1;
    const endIdx = Math.min(transCurrentPage * transLimit, total);

    const infoEl = document.getElementById('transPaginationInfo');
    if (infoEl) infoEl.textContent = total === 0 ? 'Showing 0 of 0 entries' : `Showing ${startIdx}–${endIdx} of ${total} entries (Page ${transCurrentPage} of ${totalPages})`;

    const container = document.getElementById('transPagination');
    if (!container) return;

    if (totalPages <= 1) {
        container.innerHTML = '';
        return;
    }

    container.innerHTML = buildUniversalPaginationHTML(transCurrentPage, totalPages, 'loadTransactions');
    if (window.lucide && typeof lucide.createIcons === 'function') {
        lucide.createIcons();
    }
}

function changeTransPageSize(newSize) {
    transLimit = parseInt(newSize) || 20;
    loadTransactions(1);
}

function clearFilters() {
    document.getElementById('filterStartDate').value = '';
    document.getElementById('filterEndDate').value = '';
    document.getElementById('filterAccount').value = '';
    const catSel = document.getElementById('filterCategory');
    if (catSel) catSel.value = '';
    document.getElementById('searchTrans').value = '';
    setTransFilterType('', document.querySelector('.tt-tab[data-type=""]'));
}

function debounceSearch() {
    clearTimeout(searchTimeout);
    searchTimeout = setTimeout(() => loadTransactions(1), 350);
}

function exportTransactionsExcel() {
    const params = new URLSearchParams();
    const startDate = document.getElementById('filterStartDate')?.value;
    const endDate = document.getElementById('filterEndDate')?.value;
    if (startDate) params.append('startDate', startDate);
    if (endDate) params.append('endDate', endDate);

    window.open(`${API}/reports/export/excel?${params}`, '_blank');
}

// ============ TRANSACTION MODAL ============
function openAddTransaction(initialType = 'Expense', extraValues = {}) {
    document.getElementById('transId').value = '';
    document.getElementById('transDate').value = new Date().toISOString().split('T')[0];
    document.getElementById('transAmount').value = extraValues.amount || '';
    document.getElementById('transDesc').value = extraValues.desc || '';
    document.getElementById('transRef').value = extraValues.ref || '';
    document.getElementById('transTags').value = extraValues.tags || '';

    // Switch to initial type immediately BEFORE opening modal to avoid layout jump/flicker
    const targetTab = document.querySelector(`#transModal .type-tab[data-type="${initialType}"]`) || document.querySelector('#transModal .type-tab[data-type="Expense"]');
    setTransType(initialType, targetTab);

    // Apply any initial account / party values immediately
    if (extraValues.account) {
        const accSelect = document.getElementById('transAccount');
        if (accSelect) {
            accSelect.value = extraValues.account;
            if (accSelect._ssInstance) accSelect._ssInstance.syncFromNative();
        }
    }
    if (extraValues.toAccount) {
        const toAccSelect = document.getElementById('transToAccount');
        if (toAccSelect) {
            toAccSelect.value = extraValues.toAccount;
            if (toAccSelect._ssInstance) toAccSelect._ssInstance.syncFromNative();
        }
    }
    if (extraValues.party) {
        const pSel = document.getElementById('transParty');
        if (pSel) {
            pSel.value = extraValues.party;
            if (pSel._ssInstance) pSel._ssInstance.syncFromNative();
        }
    }

    if (window.UniversalDocUploader) {
        UniversalDocUploader.init('transDocUploader', { entityType: 'transaction', title: '📎 Transaction Slip / Voucher (Upload & Rename)' });
        UniversalDocUploader.reset('transDocUploader');
    }

    if (initialType === 'Transfer') {
        const fromSel = document.getElementById('transAccount');
        const toSel = document.getElementById('transToAccount');
        if (fromSel && toSel) {
            syncMutuallyExclusiveSelects(fromSel, toSel, 'from', updateTransFlowHelper);
        }
    }

    openModal('transModal');
}

function onTransAccountChanged() {
    const type = document.getElementById('transType')?.value;
    if (type === 'Transfer') {
        const fromSel = document.getElementById('transAccount');
        const toSel = document.getElementById('transToAccount');
        syncMutuallyExclusiveSelects(fromSel, toSel, 'from', updateTransFlowHelper);
    } else {
        updateTransFlowHelper();
    }
}
window.onTransAccountChanged = onTransAccountChanged;

function onTransToAccountChanged() {
    const fromSel = document.getElementById('transAccount');
    const toSel = document.getElementById('transToAccount');
    syncMutuallyExclusiveSelects(fromSel, toSel, 'to', updateTransFlowHelper);
}
window.onTransToAccountChanged = onTransToAccountChanged;

function setTransType(type, btn) {
    currentTransType = type;
    document.getElementById('transType').value = type;

    const isEditing = !!document.getElementById('transId').value;
    const titleEl = document.getElementById('transModalTitle');
    const subEl = document.getElementById('transModalSubtitle');
    const badgeEl = document.getElementById('transHeaderBadge');

    if (!isEditing) {
        if (titleEl) {
            titleEl.textContent = type === 'Transfer' ? 'Paisa Transfer' :
                (type === 'Income' ? 'Nayi Aamadani (Income)' :
                    (type === 'Expense' ? 'Naya Kharcha (Expense)' :
                        (type === 'Loan Given' ? 'Loan Diya (Udhaar)' :
                            (type === 'Loan Received' ? 'Loan Liya (Karz)' :
                                (type === 'Loan Repay' ? 'Karz Chukta Kiya (Loan Repay)' :
                                    (type === 'Loan Recovery' ? 'Udhaar Wapas Mila (Recovery)' : 'Nayi Entry'))))));
        }
        if (subEl) {
            subEl.textContent = type === 'Transfer' ? 'Ek khate se doosre khate me paisa transfer karein (Adla-Badli)' :
                (type === 'Income' ? 'Kamai ya aamadni ka hisaab darj karein (Khate me paisa judega 🔺)' :
                    (type === 'Expense' ? 'Dukan ya personal kharche ka hisaab darj karein (Khate se paisa katega 🔻)' :
                        (type === 'Loan Given' ? 'Kisi vyakti ko udhaar diya gaya paisa darj karein (Khate se minus hoga 🔻)' :
                            (type === 'Loan Received' ? 'Kisi vyakti ya bank se udhaar liya gaya paisa darj karein (Khate me judega 🔺)' :
                                (type === 'Loan Repay' ? 'Liye gaye karz ka bhugtan wapas karein (Khate se minus hoga 🔻)' :
                                    'Diye gaye udhaar ka paisa party se wapas mila (Khate me judega 🔺)')))));
        }
        if (badgeEl) {
            badgeEl.textContent = type === 'Transfer' ? 'Self Transfer' :
                (type === 'Income' || type === 'Loan Received' || type === 'Loan Recovery' ? 'Credit (+Cr)' : 'Debit (-Dr)');
        }
    }

    document.querySelectorAll('#transModal .type-tab').forEach(b => {
        b.classList.remove('active', 'income', 'expense', 'transfer', 'loan');
    });
    if (!btn) {
        btn = document.querySelector(`#transModal .type-tab[data-type="${type}"]`);
    }
    if (btn) {
        btn.classList.add('active');
        if (type === 'Income') btn.classList.add('income');
        else if (type === 'Expense') btn.classList.add('expense');
        else if (type === 'Transfer') btn.classList.add('transfer');
        else btn.classList.add('loan');
    }

    const toAccGroup = document.getElementById('toAccountGroup');
    const catGroup = document.getElementById('categoryGroup');
    const partyGroup = document.getElementById('partyGroup');

    if (toAccGroup) toAccGroup.style.setProperty('display', type === 'Transfer' ? 'flex' : 'none', 'important');
    if (catGroup) catGroup.style.setProperty('display', ['Loan Given', 'Loan Received', 'Loan Repay', 'Loan Recovery'].includes(type) ? 'none' : 'flex', 'important');
    if (partyGroup) partyGroup.style.setProperty('display', ['Loan Given', 'Loan Received', 'Loan Repay', 'Loan Recovery', 'Income', 'Expense'].includes(type) ? 'flex' : 'none', 'important');

    // Clear dynamic labels and helper texts for accounts
    const fromLabel = document.getElementById('transAccountLabel');
    const fromHelper = document.getElementById('transAccountHelper');
    const toLabel = document.getElementById('transToAccountLabel');
    const toHelper = document.getElementById('transToAccountHelper');

    if (type === 'Transfer') {
        if (fromLabel) fromLabel.innerHTML = '<i data-lucide="arrow-up-right"></i> Kahan Se Paisa Niklega (Source Account) <span class="req">*</span>';
        if (fromHelper) fromHelper.textContent = '🔻 Is khate se transfer ki rakam minus (debit) hogi';
        if (toLabel) toLabel.innerHTML = '<i data-lucide="arrow-down-left"></i> Kahan Paisa Jama Hoga (Destination Account) <span class="req">*</span>';
        if (toHelper) toHelper.textContent = '🔺 Is doosre khate me yeh rakam jama (credit) ho jayegi';

        const fromSel = document.getElementById('transAccount');
        const toSel = document.getElementById('transToAccount');
        if (fromSel && toSel) {
            syncMutuallyExclusiveSelects(fromSel, toSel, 'from', updateTransFlowHelper);
        }
    } else if (type === 'Income') {
        if (fromLabel) fromLabel.innerHTML = '<i data-lucide="wallet"></i> Kis Khate Me Paisa Aaya (Deposit Account) <span class="req">*</span>';
        if (fromHelper) fromHelper.textContent = '🔺 Is Bank ya Cash khate me kamai ki rakam judegi (+Cr)';
    } else if (type === 'Expense') {
        if (fromLabel) fromLabel.innerHTML = '<i data-lucide="wallet"></i> Kis Khate Se Kharcha Hua (Source Account) <span class="req">*</span>';
        if (fromHelper) fromHelper.textContent = '🔻 Is Bank ya Cash khate se yeh kharcha katega (-Dr)';
    } else if (type === 'Loan Given') {
        if (fromLabel) fromLabel.innerHTML = '<i data-lucide="wallet"></i> Kis Khate Se Udhaar Diya (Source Account) <span class="req">*</span>';
        if (fromHelper) fromHelper.textContent = '🔻 Is khate se paisa nikalkar party ko udhaar diya jayega (-Dr)';
    } else if (type === 'Loan Received') {
        if (fromLabel) fromLabel.innerHTML = '<i data-lucide="wallet"></i> Udhaar Ka Paisa Kis Khate Me Aaya (Deposit Account) <span class="req">*</span>';
        if (fromHelper) fromHelper.textContent = '🔺 Karz ki yeh rakam is khate me jama hogi (+Cr)';
    } else if (type === 'Loan Repay') {
        if (fromLabel) fromLabel.innerHTML = '<i data-lucide="wallet"></i> Kis Khate Se Karz Chukta Kiya (Source Account) <span class="req">*</span>';
        if (fromHelper) fromHelper.textContent = '🔻 Liye gaye karz ka bhugtan is khate se katega (-Dr)';
    } else if (type === 'Loan Recovery') {
        if (fromLabel) fromLabel.innerHTML = '<i data-lucide="wallet"></i> Udhaar Ka Paisa Kis Khate Me Wapas Aaya (Deposit Account) <span class="req">*</span>';
        if (fromHelper) fromHelper.textContent = '🔺 Diye gaye udhaar ki wapsi is khate me jama hogi (+Cr)';
    } else {
        if (fromLabel) fromLabel.innerHTML = '<i data-lucide="wallet"></i> Account <span class="req">*</span>';
    }

    // Filter categories by type
    const catSel = document.getElementById('transCategory');
    if (catSel) {
        catSel.innerHTML = '<option value="">-- Select Category --</option>';
        allCategories.filter(c => c.CategoryType === type || c.CategoryType === 'Both').forEach(c => {
            const opt = document.createElement('option');
            opt.value = c.CategoryID;
            opt.textContent = c.CategoryName;
            catSel.appendChild(opt);
        });
        if (catSel._ssInstance) catSel._ssInstance.refresh();
    }

    if (typeof lucide !== 'undefined') {
        const modalEl = document.getElementById('transModal');
        if (modalEl) {
            try { lucide.createIcons({ root: modalEl }); } catch (e) { }
        }
    }

    updateTransFlowHelper();
}

// Live Flow Helper for Transactions Modal - Har kaam ke liye saaf saaf likha ho kis se kya hoga
function updateTransFlowHelper() {
    const helperBox = document.getElementById('transFlowHelperBox');
    const helperText = document.getElementById('transFlowHelperText');
    if (!helperBox || !helperText) return;

    const type = document.getElementById('transType')?.value || 'Expense';
    const accSel = document.getElementById('transAccount');
    const toAccSel = document.getElementById('transToAccount');
    const partySel = document.getElementById('transParty');
    const catSel = document.getElementById('transCategory');
    const amt = parseFloat(document.getElementById('transAmount')?.value) || 0;
    const amtStr = '₹' + amt.toLocaleString('en-IN', { minimumFractionDigits: 2 });

    const fromName = (accSel?.options[accSel.selectedIndex]?.text || 'Account').split(' - ')[0].trim();
    const toName = (toAccSel?.options[toAccSel.selectedIndex]?.text || 'To Account').split(' - ')[0].trim();
    const rawParty = (partySel?.options[partySel.selectedIndex]?.text || '').trim();
    const cleanParty = (!rawParty || rawParty.includes('-- Koi') || rawParty.includes('-- Select')) ? '' : rawParty.split(' - ')[0].trim();
    const rawCat = (catSel?.options[catSel.selectedIndex]?.text || '').trim();
    const cleanCat = (!rawCat || rawCat.includes('-- Select')) ? '' : rawCat;

    helperBox.style.display = 'block';

    if (type === 'Transfer') {
        helperBox.className = 'form-group full-span trans-flow-box-wrap flow-transfer';
        if (accSel && toAccSel && accSel.value && toAccSel.value && String(accSel.value) === String(toAccSel.value)) {
            helperText.innerHTML = `
                <div class="flow-pill-title" style="color: #f87171;"><i data-lucide="alert-triangle"></i> Galti: Same Account Chuna Hai!</div>
                <div class="flow-pill-content">
                    <span class="flow-chip chip-minus" style="background: rgba(239, 68, 68, 0.2); color: #fca5a5;">⚠️ [${fromName}] se [${toName}] me transfer nahi ho sakta (Same Account). Kripya alag alag khata chunein.</span>
                </div>
            `;
        } else {
            helperText.innerHTML = `
                <div class="flow-pill-title"><i data-lucide="arrow-left-right"></i> Transfer Flow Asar (Kis Khate Par Kya Hoga):</div>
                <div class="flow-pill-content">
                    <span class="flow-chip chip-minus">🔻 [${fromName}] se <b>${amtStr}</b> ghatenge</span>
                    <span class="flow-arrow">➔</span>
                    <span class="flow-chip chip-plus">🔺 [${toName}] me <b>${amtStr}</b> judenge</span>
                </div>
            `;
        }
    } else if (type === 'Income') {
        helperBox.className = 'form-group full-span trans-flow-box-wrap flow-income';
        const meta = [cleanParty ? `Party: ${cleanParty}` : '', cleanCat ? `Mad: ${cleanCat}` : ''].filter(Boolean).join(' | ');
        helperText.innerHTML = `
            <div class="flow-pill-title"><i data-lucide="trending-up"></i> Aamadni Flow Asar (Kis Khate Par Kya Hoga):</div>
            <div class="flow-pill-content">
                <span class="flow-chip chip-plus">🔺 [${fromName}] me <b>${amtStr}</b> jama (Credit) honge</span>
                ${meta ? `<span class="flow-chip chip-info">ℹ️ ${meta}</span>` : ''}
            </div>
        `;
    } else if (type === 'Expense') {
        helperBox.className = 'form-group full-span trans-flow-box-wrap flow-expense';
        const meta = [cleanCat ? `Mad: ${cleanCat}` : '', cleanParty ? `Party: ${cleanParty}` : ''].filter(Boolean).join(' | ');
        helperText.innerHTML = `
            <div class="flow-pill-title"><i data-lucide="trending-down"></i> Kharcha Flow Asar (Kis Khate Par Kya Hoga):</div>
            <div class="flow-pill-content">
                <span class="flow-chip chip-minus">🔻 [${fromName}] se <b>${amtStr}</b> kam (Debit) honge</span>
                ${meta ? `<span class="flow-chip chip-info">ℹ️ ${meta}</span>` : ''}
            </div>
        `;
    } else if (type === 'Loan Given') {
        helperBox.className = 'form-group full-span trans-flow-box-wrap flow-loan';
        const pText = cleanParty ? `[${cleanParty}] ke naam udhaar judega` : 'Chune hue vyakti ke naam udhaar judega';
        helperText.innerHTML = `
            <div class="flow-pill-title"><i data-lucide="hand-coins"></i> Udhaar Diya Asar (Kis Par Kya Hoga):</div>
            <div class="flow-pill-content">
                <span class="flow-chip chip-minus">🔻 [${fromName}] se <b>${amtStr}</b> kam honge</span>
                <span class="flow-arrow">➔</span>
                <span class="flow-chip chip-warn">👤 ${pText} 📤</span>
            </div>
        `;
    } else if (type === 'Loan Received') {
        helperBox.className = 'form-group full-span trans-flow-box-wrap flow-loan';
        const pText = cleanParty ? `[${cleanParty}] ko wapas lautana baki rahega` : 'Karz lautana baki rahega';
        helperText.innerHTML = `
            <div class="flow-pill-title"><i data-lucide="hand-helping"></i> Udhaar Liya Asar (Kis Par Kya Hoga):</div>
            <div class="flow-pill-content">
                <span class="flow-chip chip-plus">🔺 [${fromName}] me <b>${amtStr}</b> jama honge</span>
                <span class="flow-arrow">➔</span>
                <span class="flow-chip chip-warn">👤 ${pText} 📥</span>
            </div>
        `;
    } else if (type === 'Loan Repay') {
        helperBox.className = 'form-group full-span trans-flow-box-wrap flow-loan';
        const pText = cleanParty ? `[${cleanParty}] ka hisaab clear hoga` : 'Party ka hisaab clear hoga';
        helperText.innerHTML = `
            <div class="flow-pill-title"><i data-lucide="rotate-ccw"></i> Loan Wapsi Asar (Kis Par Kya Hoga):</div>
            <div class="flow-pill-content">
                <span class="flow-chip chip-info">🔄 [${fromName}] se <b>${amtStr}</b> ka transaction</span>
                <span class="flow-arrow">➔</span>
                <span class="flow-chip chip-plus">👤 ${pText} ↩️</span>
            </div>
        `;
    } else {
        helperBox.style.display = 'none';
    }

    if (typeof lucide !== 'undefined' && helperBox.style.display !== 'none') {
        try { lucide.createIcons({ root: helperBox }); } catch (e) { }
    }
}
window.updateTransFlowHelper = updateTransFlowHelper;

async function editTransaction(id) {
    try {
        const res = await fetch(`${API}/transactions/${id}`);
        const data = await res.json();
        if (!data.success) throw new Error(data.error);
        const t = data.data;

        document.getElementById('transId').value = t.TransactionID;
        document.getElementById('transModalTitle').textContent = 'Transaction Edit Karo';
        const subEl = document.getElementById('transModalSubtitle');
        if (subEl) subEl.textContent = `Transaction #${t.TransactionID} ki detail badlein aur save karein`;
        const badgeEl = document.getElementById('transHeaderBadge');
        if (badgeEl) badgeEl.textContent = 'Edit Mode';
        document.getElementById('transDate').value = t.TransDate ? t.TransDate.split('T')[0] : '';
        document.getElementById('transAmount').value = t.Amount;
        document.getElementById('transDesc').value = t.Description || '';
        document.getElementById('transRef').value = t.Reference || '';
        document.getElementById('transTags').value = t.Tags || '';

        setTransType(t.TransType, document.querySelector(`#transModal .type-tab[data-type="${t.TransType}"]`));

        const accSelect = document.getElementById('transAccount');
        if (accSelect) { accSelect.value = t.AccountID; if (accSelect._ssInstance) accSelect._ssInstance.syncFromNative(); }
        const toAccSelect = document.getElementById('transToAccount');
        if (toAccSelect) { toAccSelect.value = t.ToAccountID || ''; if (toAccSelect._ssInstance) toAccSelect._ssInstance.syncFromNative(); }
        const catSelect = document.getElementById('transCategory');
        if (catSelect) { catSelect.value = t.CategoryID || ''; if (catSelect._ssInstance) catSelect._ssInstance.syncFromNative(); }
        const partySelect = document.getElementById('transParty');
        if (partySelect) { partySelect.value = t.PartyID || ''; if (partySelect._ssInstance) partySelect._ssInstance.syncFromNative(); }

        if (window.UniversalDocUploader) {
            UniversalDocUploader.init('transDocUploader', { entityType: 'transaction', title: '📎 Transaction Slip / Voucher (Upload & Rename)' });
            UniversalDocUploader.reset('transDocUploader');
            UniversalDocUploader.loadExisting('transDocUploader', 'transaction', t.TransactionID);
        }

        openModal('transModal');
    } catch (err) {
        showToast('Error: ' + err.message, 'error');
    }
}

async function saveTransaction() {
    // Double submit rokne ke liye save button ko turant disable karte hain
    // (rapid double-click se transaction 2 baar post ho jata tha)
    const saveBtn = document.querySelector('#transModal button[onclick*="saveTransaction"]');
    if (saveBtn) {
        if (saveBtn.disabled) return;
        saveBtn.disabled = true;
    }
    try {
        const id = document.getElementById('transId').value;
        const transType = document.getElementById('transType').value;
        const data = {
            TransDate: document.getElementById('transDate').value,
            TransType: transType,
            Amount: document.getElementById('transAmount').value,
            AccountID: document.getElementById('transAccount').value,
            ToAccountID: transType === 'Transfer' ? (document.getElementById('transToAccount').value || null) : null,
            CategoryID: document.getElementById('transCategory').value || null,
            PartyID: document.getElementById('transParty').value || null,
            Description: document.getElementById('transDesc').value,
            Reference: document.getElementById('transRef').value,
            Tags: document.getElementById('transTags').value
        };

        if (!data.Amount || parseFloat(data.Amount) <= 0) { showToast('Amount sahi bharo!', 'error', 'Amount Chahiye'); return; }
        if (!data.AccountID) { showToast('Account select karo!', 'error', 'Account Chunein'); return; }
        if (data.TransType === 'Transfer') {
            if (!data.ToAccountID) {
                showToast('Transfer ke liye destination account chunein!', 'error', 'Destination Chahiye');
                return;
            }
            if (String(data.AccountID) === String(data.ToAccountID)) {
                showToast('Source aur destination account alag alag hone chahiye!', 'error', 'Same Account');
                return;
            }
        }

        showUniversalLoader(
            id ? 'Transaction Update Ho Raha Hai...' : 'Entry Save Ho Rahi Hai...',
            'Accounts balance aur ledger realtime update ho raha hai...'
        );

        try {
            const method = id ? 'PUT' : 'POST';
            const url = id ? `${API}/transactions/${id}` : `${API}/transactions`;
            const res = await fetch(url, { method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
            const result = await res.json();

            if (!result.success) throw new Error(result.error);

            const txnId = result.id || id || result.data?.TransactionID;
            // Upload any staged documents with rename
            if (txnId && window.UniversalDocUploader && UniversalDocUploader.hasPendingFiles('transDocUploader')) {
                try {
                    await UniversalDocUploader.uploadPending('transDocUploader', { entityType: 'transaction', entityId: txnId, customerId: data.PartyID || null });
                } catch (upErr) {
                    console.error('Transaction doc upload error:', upErr);
                }
            }

            closeModal('transModal');
            showToast(id ? 'Transaction update ho gaya!' : '✅ Entry safalta se add ho gayi!', 'success', 'Cashbook Entry');
            await refreshAllActiveViews('saveTransaction');
            triggerRealTimeSync('saveTransaction');

            // Har transaction ke baad voucher popup print button ke sath kholein
            if (typeof openTransVoucherFromData === 'function') {
                const accObj = allAccounts.find(a => a.AccountID == data.AccountID);
                const catObj = allCategories.find(c => c.CategoryID == data.CategoryID);
                const partyObj = allParties.find(p => p.PartyID == data.PartyID);
                const savedTxn = result.data || {};
                openTransVoucherFromData({
                    ...data,
                    ...savedTxn,
                    TransactionID: savedTxn.TransactionID || result.id || id || txnId,
                    AccountName: accObj ? accObj.AccountName : 'Account',
                    CategoryName: catObj ? catObj.CategoryName : '',
                    PartyName: partyObj ? partyObj.PartyName : '',
                    SNCode: savedTxn.SNCode || data.SNCode || '',
                    GlobalSerialNo: savedTxn.GlobalSerialNo || data.GlobalSerialNo || null,
                    ModuleCode: savedTxn.ModuleCode || data.ModuleCode || ''
                });
            }
        } catch (err) {
            showToast('Error: ' + err.message, 'error', 'Entry Truti');
        } finally {
            hideUniversalLoader();
        }
    } finally {
        if (saveBtn) saveBtn.disabled = false;
    }
}

async function deleteTransaction(id) {
    showConfirm('Kya aap is transaction ko delete karna chahte hain?', async () => {
        try {
            const res = await fetch(`${API}/transactions/${id}`, { method: 'DELETE' });
            const data = await res.json();
            if (!data.success) throw new Error(data.error);
            showToast('Transaction delete ho gaya!');
            await refreshAllActiveViews('deleteTransaction');
            triggerRealTimeSync('deleteTransaction');
        } catch (err) {
            showToast('Error: ' + err.message, 'error');
        }
    });
}

// ============ ACCOUNTS ============
let accCurrentTypeFilter = '';

async function loadAccounts() {
    const container = document.getElementById('accountsGrid');
    if (!container) return;
    renderTableSkeleton(container, 6, 5);

    try {
        const res = await fetch(`${API}/accounts`);
        const data = await res.json();
        allAccounts = data.data || [];

        // Update 4 KPI Summary Cards
        updateAccountsKpiCards(allAccounts);

        // Update badge in filter tabs
        const badgeAll = document.getElementById('aftBadgeAll');
        if (badgeAll) badgeAll.textContent = allAccounts.length;

        renderAccountsList();
        updateSidebarBalance();
    } catch (err) {
        container.innerHTML = `<div class="empty-state"><p style="color:var(--accent-red)">Error: ${err.message}</p></div>`;
    }
}

function updateAccountsKpiCards(accounts) {
    let totalNet = 0;
    let totalCash = 0;
    let totalWallets = 0;
    let totalBank = 0;

    accounts.forEach(a => {
        const bal = parseFloat(a.CurrentBalance || 0);
        totalNet += bal;

        const nameLower = (a.AccountName || '').toLowerCase();
        const typeLower = (a.AccountType || '').toLowerCase();

        if (typeLower === 'cash' || nameLower.includes('cash') || nameLower.includes('galla')) {
            totalCash += bal;
        } else if (nameLower.includes('digipay') || nameLower.includes('csc')) {
            totalWallets += bal;
        } else {
            totalBank += bal;
        }
    });

    const elTotal = document.getElementById('accKpiTotal');
    const elCash = document.getElementById('accKpiCash');
    const elWallets = document.getElementById('accKpiWallets');
    const elBank = document.getElementById('accKpiBank');

    if (elTotal) {
        elTotal.textContent = formatMoney(totalNet);
        elTotal.className = 'ak-val ' + (totalNet >= 0 ? 'text-income' : 'text-expense');
    }
    if (elCash) elCash.textContent = formatMoney(totalCash);
    if (elWallets) {
        elWallets.textContent = formatMoney(totalWallets);
        elWallets.className = 'ak-val ' + (totalWallets >= 0 ? 'text-income' : 'text-expense');
    }
    if (elBank) {
        elBank.textContent = formatMoney(totalBank);
        elBank.className = 'ak-val ' + (totalBank >= 0 ? 'text-income' : 'text-expense');
    }
}

function filterAccountsByType(type, btnEl) {
    accCurrentTypeFilter = type;
    document.querySelectorAll('.aft-tab').forEach(b => b.classList.remove('active'));
    if (btnEl) btnEl.classList.add('active');
    renderAccountsList();
}

function filterAccountsList() {
    renderAccountsList();
}

function renderAccountsList() {
    const container = document.getElementById('accountsGrid');
    if (!container) return;

    const searchTerm = (document.getElementById('searchAccountInput')?.value || '').toLowerCase().trim();

    let filtered = allAccounts.filter(a => {
        const name = (a.AccountName || '').toLowerCase();
        const type = (a.AccountType || '').toLowerCase();
        const bank = (a.BankName || '').toLowerCase();
        const accNo = (a.AccountNumber || '').toLowerCase();

        // Type filter check
        if (accCurrentTypeFilter === 'Cash') {
            if (!(type === 'cash' || name.includes('cash') || name.includes('galla'))) return false;
        } else if (accCurrentTypeFilter === 'CSC') {
            if (!(name.includes('digipay') || name.includes('csc') || type.includes('wallet'))) return false;
        } else if (accCurrentTypeFilter === 'Bank') {
            if (type !== 'bank' && !bank) return false;
        } else if (accCurrentTypeFilter === 'UPI') {
            if (type !== 'upi' && !name.includes('upi') && !name.includes('phonepe') && !name.includes('paytm')) return false;
        }

        // Search check
        if (searchTerm) {
            return name.includes(searchTerm) || bank.includes(searchTerm) || accNo.includes(searchTerm) || type.includes(searchTerm);
        }
        return true;
    });

    const countEl = document.getElementById('accFilteredCount');
    if (countEl) {
        countEl.textContent = `${filtered.length} of ${allAccounts.length} accounts dikh rahe hain`;
    }

    if (!filtered.length) {
        container.innerHTML = `
            <tr>
                <td colspan="6">
                    <div class="ptable-empty">
                        <i data-lucide="wallet" width="44" height="44" style="color: var(--text-muted);"></i>
                        <h3>Koi account nahi mila</h3>
                        <p>Filter badlein ya naya account add karein</p>
                        <button class="btn-primary" onclick="openAccountModal()"><i data-lucide="plus"></i> Naya Account</button>
                    </div>
                </td>
            </tr>`;
        lucide.createIcons();
        return;
    }

    const typeIcons = {
        Cash: { icon: 'banknote', emoji: '💵', label: 'Cash in Hand' },
        Bank: { icon: 'landmark', emoji: '🏦', label: 'Bank Account' },
        UPI: { icon: 'qr-code', emoji: '📱', label: 'UPI Wallet' },
        'Credit Card': { icon: 'credit-card', emoji: '💳', label: 'Credit Card' },
        Other: { icon: 'wallet', emoji: '💰', label: 'Account' }
    };

    container.innerHTML = filtered.map(a => {
        const bal = parseFloat(a.CurrentBalance || 0);
        const color = a.Color || '#10b981';
        const isCSC = (a.AccountName || '').toLowerCase().includes('digipay');
        const typeInfo = typeIcons[a.AccountType] || typeIcons['Other'];
        const displayLabel = isCSC ? 'CSC Wallet' : typeInfo.label;
        const balClass = bal >= 0 ? 'text-income' : 'text-expense';
        const bankLine = a.BankName ? escapeHtml(a.BankName) + (a.AccountNumber ? ' • ****' + escapeHtml(a.AccountNumber.slice(-4)) : '') : '<span class="cell-muted">—</span>';

        return `
            <tr class="trans-data-row">
                <td>
                    <div class="cell-flex">
                        <div class="pavatar" style="background:${color}1f; color:${color}; border: 1px solid ${color}35">
                            <i data-lucide="${typeInfo.icon}" width="18" height="18"></i>
                        </div>
                        <div>
                            <div class="cell-title">${escapeHtml(a.AccountName)}</div>
                        </div>
                    </div>
                </td>
                <td><span class="pbadge gray" style="border-left: 3px solid ${color}">${displayLabel}</span></td>
                <td class="cell-sub">${bankLine}</td>
                <td class="cell-right cell-muted cell-nowrap">${formatMoney(a.OpeningBalance)}</td>
                <td class="cell-right cell-amount ${balClass}">${formatMoney(bal)}</td>
                <td class="cell-center">
                    <div class="prow-actions" style="justify-content: center; gap: 6px;">
                        <button class="pbtn-sm blue" title="Bank Passbook Statement" onclick="openAccountPassbookModal(${a.AccountID})" style="padding: 4px 9px; display: inline-flex; align-items: center; gap: 4px; font-weight: 600; font-size: 12px;">
                            <i data-lucide="book-open" width="14" height="14"></i> Passbook
                        </button>
                        <button type="button" class="table-menu-trigger-btn acc-menu-trigger-btn" onclick="toggleAccountActionMenu(event, ${a.AccountID})" title="Sabhi Kriya (3 Dots Menu)">
                            <i data-lucide="more-vertical" width="16" height="16"></i>
                        </button>
                    </div>
                </td>
            </tr>`;
    }).join('');

    lucide.createIcons();
}

// --------------------------------------------------------------------------
// FLOATING 3-DOT ACTION MENU FOR ACCOUNTS
// --------------------------------------------------------------------------
let activeAccDropdownId = null;

function toggleAccountActionMenu(e, accountId) {
    if (e) {
        e.preventDefault();
        e.stopPropagation();
    }

    const existingMenu = document.getElementById('accFloatingActionMenu');
    if (existingMenu && activeAccDropdownId === accountId) {
        closeAccountActionMenu();
        return;
    }

    closeAllActionMenus();

    const acc = (allAccounts || []).find(a => Number(a.AccountID) === Number(accountId));
    if (!acc) return;

    const triggerBtn = (e && e.currentTarget) ? e.currentTarget : (e && e.target ? e.target.closest('.acc-menu-trigger-btn, .table-menu-trigger-btn') : null);
    if (!triggerBtn) return;

    triggerBtn.classList.add('active');
    activeAccDropdownId = accountId;

    const safeName = escapeHtml(acc.AccountName || 'Account');
    const bal = parseFloat(acc.CurrentBalance || 0);
    const balColor = bal >= 0 ? '#10b981' : '#f87171';
    const bankDetails = acc.BankName ? `${escapeHtml(acc.BankName)}${acc.AccountNumber ? ' • ****' + escapeHtml(acc.AccountNumber.slice(-4)) : ''}` : (acc.AccountType || 'Khata');

    const menu = document.createElement('div');
    menu.id = 'accFloatingActionMenu';
    menu.className = 'cust-action-dropdown-menu';

    menu.innerHTML = `
        <div class="cad-header">
            <div class="cad-title-row">
                <span class="cad-name" title="${safeName}">${safeName}</span>
                <span class="cad-id font-mono">#${acc.AccountID}</span>
            </div>
            <div style="display: flex; align-items: center; justify-content: space-between; gap: 6px; margin-top: 5px;">
                <span style="font-size: 11px; color: var(--text-muted);">${bankDetails}</span>
                <span style="font-size: 12px; font-weight: 800; color: ${balColor};">
                    ${formatMoney(bal)}
                </span>
            </div>
        </div>
        <div class="cad-items">
            <button type="button" class="cad-item" id="accOptPassbook">
                <span class="cad-icon purple"><i data-lucide="book-open"></i></span>
                <div class="cad-label">
                    <span class="cad-primary">Bank Passbook Statement</span>
                    <span class="cad-secondary">Is khate ka sampoorna ledger statement</span>
                </div>
            </button>
            <button type="button" class="cad-item" id="accOptTransfer">
                <span class="cad-icon indigo"><i data-lucide="arrow-left-right"></i></span>
                <div class="cad-label">
                    <span class="cad-primary">Paisa Transfer Karein</span>
                    <span class="cad-secondary">Is khate se doosre khate me transfer</span>
                </div>
            </button>
            <button type="button" class="cad-item" id="accOptIncome">
                <span class="cad-icon green"><i data-lucide="wallet"></i></span>
                <div class="cad-label">
                    <span class="cad-primary">+ Nayi Aamadani (Deposit)</span>
                    <span class="cad-secondary">Is khate me paisa jama karein (+Cr)</span>
                </div>
            </button>
            <button type="button" class="cad-item" id="accOptExpense">
                <span class="cad-icon orange"><i data-lucide="arrow-up-right"></i></span>
                <div class="cad-label">
                    <span class="cad-primary">- Naya Kharcha (Expense)</span>
                    <span class="cad-secondary">Is khate se kharcha darj karein (-Dr)</span>
                </div>
            </button>
            <button type="button" class="cad-item" id="accOptEdit">
                <span class="cad-icon cyan"><i data-lucide="edit-2"></i></span>
                <div class="cad-label">
                    <span class="cad-primary">Khata Details Edit</span>
                    <span class="cad-secondary">Naam, bank, A/C number badlein</span>
                </div>
            </button>
            <div class="cad-divider"></div>
            <button type="button" class="cad-item danger" id="accOptDelete">
                <span class="cad-icon red"><i data-lucide="trash-2"></i></span>
                <div class="cad-label">
                    <span class="cad-primary text-danger">Khata Delete Karein</span>
                    <span class="cad-secondary">Is khate ko system se hatayein</span>
                </div>
            </button>
        </div>
    `;

    menu.querySelector('#accOptPassbook')?.addEventListener('click', () => {
        closeAccountActionMenu();
        openAccountPassbookModal(acc.AccountID);
    });
    menu.querySelector('#accOptTransfer')?.addEventListener('click', () => {
        closeAccountActionMenu();
        openTransferFrom(acc.AccountID);
    });
    menu.querySelector('#accOptIncome')?.addEventListener('click', () => {
        closeAccountActionMenu();
        openAddTransaction('Income', { account: acc.AccountID });
    });
    menu.querySelector('#accOptExpense')?.addEventListener('click', () => {
        closeAccountActionMenu();
        openAddTransaction('Expense', { account: acc.AccountID });
    });
    menu.querySelector('#accOptEdit')?.addEventListener('click', () => {
        closeAccountActionMenu();
        openAccountModal(acc.AccountID);
    });
    menu.querySelector('#accOptDelete')?.addEventListener('click', () => {
        closeAccountActionMenu();
        deleteAccount(acc.AccountID);
    });

    positionFloatingMenu(menu, triggerBtn, 280);
}

function closeAccountActionMenu() {
    activeAccDropdownId = null;
    document.querySelectorAll('.acc-menu-trigger-btn.active').forEach(b => b.classList.remove('active'));
    const m = document.getElementById('accFloatingActionMenu');
    if (m) {
        m.classList.remove('active');
        m.remove();
    }
}
window.toggleAccountActionMenu = toggleAccountActionMenu;
window.closeAccountActionMenu = closeAccountActionMenu;

function openQuickTransferModal() {
    openAddTransaction('Transfer');
}

function openTransferFrom(accountId) {
    openAddTransaction('Transfer', { account: accountId });
}

function openAccountModal(id) {
    document.getElementById('accountId').value = id || '';
    document.getElementById('accountModalTitle').textContent = id ? 'Account Edit Karo' : 'Naya Account';

    if (!id) {
        document.getElementById('accountName').value = '';
        document.getElementById('accountType').value = 'Cash';
        document.getElementById('accountOpening').value = '';
        document.getElementById('accountBank').value = '';
        document.getElementById('accountNumber').value = '';
        document.getElementById('accountColor').value = '#6366f1';
    } else {
        const acc = allAccounts.find(a => a.AccountID == id);
        if (acc) {
            document.getElementById('accountName').value = acc.AccountName;
            document.getElementById('accountType').value = acc.AccountType;
            document.getElementById('accountOpening').value = acc.OpeningBalance;
            document.getElementById('accountBank').value = acc.BankName || '';
            document.getElementById('accountNumber').value = acc.AccountNumber || '';
            document.getElementById('accountColor').value = acc.Color || '#6366f1';
        }
    }
    openModal('accountModal');
}

async function saveAccount() {
    const id = document.getElementById('accountId').value;
    const data = {
        AccountName: document.getElementById('accountName').value,
        AccountType: document.getElementById('accountType').value,
        OpeningBalance: document.getElementById('accountOpening').value || 0,
        BankName: document.getElementById('accountBank').value,
        AccountNumber: document.getElementById('accountNumber').value,
        Color: document.getElementById('accountColor').value
    };
    if (!data.AccountName) { showToast('Account name bharo!', 'error'); return; }

    try {
        const method = id ? 'PUT' : 'POST';
        const url = id ? `${API}/accounts/${id}` : `${API}/accounts`;
        const res = await fetch(url, { method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
        const result = await res.json();
        if (!result.success) throw new Error(result.error);
        closeModal('accountModal');
        showToast(id ? 'Account update ho gaya!' : 'Account add ho gaya!');
        await loadMasterData();
        loadAccounts();
    } catch (err) {
        showToast('Error: ' + err.message, 'error');
    }
}

async function deleteAccount(id) {
    showConfirm('Account delete karna chahte hain? (Transactions safe rahenge)', async () => {
        try {
            const res = await fetch(`${API}/accounts/${id}`, { method: 'DELETE' });
            const json = await res.json();
            if (res.ok && json.success) {
                showToast('Account delete ho gaya!', 'success');
                await loadMasterData();
                loadAccounts();
            } else {
                showToast(json.error || 'Account delete nahi ho saka', 'error');
            }
        } catch (err) {
            showToast('Error: ' + err.message, 'error');
        }
    });
}

// ============ PARTIES & UDHAARI ============
let partyTabFilter = 'all'; // 'all', 'receivable', 'payable', 'settled'

async function loadParties() {
    const container = document.getElementById('partiesGrid');
    if (container) {
        renderTableSkeleton(container, 6, 5);
    }

    try {
        const res = await fetch(`${API}/parties`);
        const data = await res.json();
        allParties = data.data || [];

        // 1. Calculate and update 4 Top KPI Cards
        let totalReceivable = 0; // Hamara Lena (wo denge, bal > 0)
        let totalPayable = 0;    // Hamara Dena (hum denge, bal < 0)
        let countReceivable = 0;
        let countPayable = 0;
        let countSettled = 0;

        allParties.forEach(p => {
            const bal = parseFloat(p.CurrentBalance || 0);
            if (bal > 0) {
                totalReceivable += bal;
                countReceivable++;
            } else if (bal < 0) {
                totalPayable += Math.abs(bal);
                countPayable++;
            } else {
                countSettled++;
            }
        });

        const netBalance = totalReceivable - totalPayable;

        // Update KPI card elements
        const lenaEl = document.getElementById('partyKpiLena');
        if (lenaEl) lenaEl.textContent = formatMoney(totalReceivable);
        const lenaSubEl = document.getElementById('partyKpiLenaSub');
        if (lenaSubEl) lenaSubEl.textContent = `${countReceivable} parties se paise lene hain`;

        const denaEl = document.getElementById('partyKpiDena');
        if (denaEl) denaEl.textContent = formatMoney(totalPayable);
        const denaSubEl = document.getElementById('partyKpiDenaSub');
        if (denaSubEl) denaSubEl.textContent = `${countPayable} parties ko paise chukane hain`;

        const netEl = document.getElementById('partyKpiNet');
        if (netEl) {
            netEl.textContent = (netBalance >= 0 ? '+' : '-') + formatMoney(Math.abs(netBalance));
            netEl.className = 'pk-val ' + (netBalance > 0 ? 'text-income' : netBalance < 0 ? 'text-expense' : '');
        }

        const totalCountEl = document.getElementById('partyKpiTotalCount');
        if (totalCountEl) totalCountEl.textContent = allParties.length;

        // Update Tab Badges
        const bAll = document.getElementById('pftBadgeAll');
        if (bAll) bAll.textContent = allParties.length;
        const bLena = document.getElementById('pftBadgeLena');
        if (bLena) bLena.textContent = countReceivable;
        const bDena = document.getElementById('pftBadgeDena');
        if (bDena) bDena.textContent = countPayable;
        const bClear = document.getElementById('pftBadgeClear');
        if (bClear) bClear.textContent = countSettled;

        // Render parties list according to current filters
        renderPartiesList();
    } catch (err) {
        showToast('Parties load error: ' + err.message, 'error');
    }
}

function filterParties(tab, btn) {
    partyTabFilter = tab;
    document.querySelectorAll('.parties-filter-tabs .pft-tab').forEach(b => b.classList.remove('active'));
    if (btn) btn.classList.add('active');
    renderPartiesList();
}

function filterPartiesList() {
    renderPartiesList();
}

function renderPartiesList() {
    const container = document.getElementById('partiesGrid');
    if (!container) return;

    const searchInput = document.getElementById('searchPartyInput');
    const query = (searchInput ? searchInput.value : '').toLowerCase().trim();
    const typeSelect = document.getElementById('partyTypeSelect');
    const selectedType = typeSelect ? typeSelect.value : '';

    let filtered = allParties.filter(p => {
        const bal = parseFloat(p.CurrentBalance || 0);

        // Tab filter
        if (partyTabFilter === 'receivable' && bal <= 0) return false;
        if (partyTabFilter === 'payable' && bal >= 0) return false;
        if (partyTabFilter === 'settled' && bal !== 0) return false;

        // Type filter
        if (selectedType && (p.PartyType || 'Other') !== selectedType) return false;

        // Search query
        if (query) {
            const nameMatch = (p.PartyName || '').toLowerCase().includes(query);
            const phoneMatch = (p.Phone || '').toLowerCase().includes(query);
            const typeMatch = (p.PartyType || '').toLowerCase().includes(query);
            const notesMatch = (p.Notes || '').toLowerCase().includes(query);
            if (!nameMatch && !phoneMatch && !typeMatch && !notesMatch) return false;
        }

        return true;
    });

    const metaCount = document.getElementById('partiesFilteredCount');
    if (metaCount) {
        metaCount.textContent = `${filtered.length} of ${allParties.length} parties dikh rahi hain`;
    }

    if (!filtered.length) {
        container.innerHTML = `
            <tr>
                <td colspan="6">
                    <div class="ptable-empty">
                        <i data-lucide="users" width="52" height="52" style="opacity: 0.4;"></i>
                        <h3>Koi Party Nahi Mili</h3>
                        <p>Aapke filter ya search criteria ke mutabiq koi record nahi hai.</p>
                        <button class="btn-primary" onclick="openPartyModal()"><i data-lucide="plus"></i> Naya Party Add Karein</button>
                    </div>
                </td>
            </tr>`;
        lucide.createIcons();
        return;
    }

    const avatarColors = [
        'linear-gradient(135deg, #6366f1, #4f46e5)',
        'linear-gradient(135deg, #8b5cf6, #7c3aed)',
        'linear-gradient(135deg, #ec4899, #db2777)',
        'linear-gradient(135deg, #f97316, #ea580c)',
        'linear-gradient(135deg, #10b981, #059669)',
        'linear-gradient(135deg, #06b6d4, #0891b2)',
        'linear-gradient(135deg, #3b82f6, #2563eb)'
    ];

    container.innerHTML = filtered.map((p, i) => {
        const bal = parseFloat(p.CurrentBalance || 0);
        const bgGrad = avatarColors[i % avatarColors.length];

        let balClass, balBadge, balAmountText;
        if (bal > 0) {
            balClass = 'green';
            balBadge = 'Lena Hai';
            balAmountText = `+ ${formatMoney(bal)}`;
        } else if (bal < 0) {
            balClass = 'red';
            balBadge = 'Dena Hai';
            balAmountText = `− ${formatMoney(Math.abs(bal))}`;
        } else {
            balClass = 'gray';
            balBadge = 'Settled';
            balAmountText = formatMoney(0);
        }

        const safeName = escapeHtml(p.PartyName);
        const safeType = escapeHtml(p.PartyType || 'Other');
        const safePhone = escapeHtml(p.Phone || '');
        const inlineName = escapeInlineArg(p.PartyName);
        const transCount = p.TransactionCount || 0;
        const openingBal = parseFloat(p.OpeningBalance || 0);
        const initial = p.PartyName ? p.PartyName.charAt(0).toUpperCase() : 'P';

        return `
            <tr class="trans-data-row">
                <td>
                    <div class="cell-flex">
                        <div class="pavatar-circle" style="background:${bgGrad}">${initial}</div>
                        <div>
                            <div class="cell-title" title="${safeName}">${safeName}</div>
                            <div class="cell-sub">Opening: ${formatMoney(openingBal)}</div>
                        </div>
                    </div>
                </td>
                <td><span class="pbadge gray">${safeType}</span></td>
                <td class="cell-sub">
                    ${safePhone ? `<a href="tel:${safePhone}" style="color:#60a5fa; text-decoration:none;">📞 ${safePhone}</a>` : '<span class="cell-muted">Phone nahi hai</span>'}
                </td>
                <td class="cell-center cell-muted cell-nowrap">${transCount} entries</td>
                <td class="cell-right">
                    <div class="cell-amount ${bal > 0 ? 'amt-pos' : bal < 0 ? 'amt-neg' : 'amt-zero'}">${balAmountText}</div>
                    <span class="pbadge ${balClass}" style="margin-top:4px">${balBadge}</span>
                </td>
                <td class="cell-center cell-nowrap">
                    <div class="party-action-cell">
                        <button type="button" class="party-quick-btn" onclick="openPartyLedger(${p.PartyID}, '${inlineName}')" title="Khata Passbook Kholein">
                            <i data-lucide="book-open" width="14" height="14"></i>
                        </button>
                        <button type="button" class="party-menu-trigger-btn" onclick="togglePartyActionMenu(event, ${p.PartyID})" title="Sabhi Kriya (3 Dots Menu)">
                            <i data-lucide="more-vertical" width="16" height="16"></i>
                        </button>
                    </div>
                </td>
            </tr>`;
    }).join('');

    lucide.createIcons();
}

// --------------------------------------------------------------------------
// UNIVERSAL FLOATING 3-DOT ACTION MENU SYSTEM
// --------------------------------------------------------------------------
function positionFloatingMenu(menu, triggerBtn, preferredWidth = 275) {
    document.body.appendChild(menu);
    if (window.lucide) {
        lucide.createIcons({ root: menu });
    }

    const rect = triggerBtn.getBoundingClientRect();
    const menuWidth = preferredWidth;
    const menuHeight = menu.offsetHeight || 300;
    const viewportWidth = window.innerWidth;
    const viewportHeight = window.innerHeight;

    let left = rect.right - menuWidth;
    if (left < 10) left = 10;
    if (left + menuWidth > viewportWidth - 10) left = viewportWidth - menuWidth - 10;

    let top = rect.bottom + 6;
    if (top + menuHeight > viewportHeight - 10 && rect.top - menuHeight - 6 > 10) {
        top = rect.top - menuHeight - 6;
        menu.classList.add('opens-upward');
    }

    menu.style.top = `${top}px`;
    menu.style.left = `${left}px`;

    requestAnimationFrame(() => {
        menu.classList.add('active');
    });
}

function closeAllActionMenus() {
    if (typeof closeCustActionMenu === 'function') closeCustActionMenu();
    if (typeof closePartyActionMenu === 'function') closePartyActionMenu();
    if (typeof closeCSCActionMenu === 'function') closeCSCActionMenu();
    if (typeof closeInvoiceActionMenu === 'function') closeInvoiceActionMenu();
    if (typeof closeBCActionMenu === 'function') closeBCActionMenu();
    if (typeof closeAccountActionMenu === 'function') closeAccountActionMenu();
    if (typeof closeTransActionMenu === 'function') closeTransActionMenu();
    if (typeof closeDocActionMenu === 'function') closeDocActionMenu();
}
window.positionFloatingMenu = positionFloatingMenu;
window.closeAllActionMenus = closeAllActionMenus;

// --------------------------------------------------------------------------
// FLOATING 3-DOT ACTION MENU FOR PARTIES
// --------------------------------------------------------------------------
let activePartyDropdownId = null;

function togglePartyActionMenu(e, partyId) {
    if (e) {
        e.preventDefault();
        e.stopPropagation();
    }

    const existingMenu = document.getElementById('partyFloatingActionMenu');
    if (existingMenu && activePartyDropdownId === partyId) {
        closePartyActionMenu();
        return;
    }

    closeAllActionMenus();

    const party = (allParties || []).find(p => Number(p.PartyID) === Number(partyId));
    if (!party) return;

    const triggerBtn = (e && e.currentTarget) ? e.currentTarget : (e && e.target ? e.target.closest('.party-menu-trigger-btn') : null);
    if (!triggerBtn) return;

    triggerBtn.classList.add('active');
    activePartyDropdownId = partyId;

    const bal = parseFloat(party.CurrentBalance || 0);
    const inlineName = escapeInlineArg(party.PartyName);
    const safeName = escapeHtml(party.PartyName);

    let balBadgeHtml = '';
    if (bal > 0) {
        balBadgeHtml = `<span class="pbadge green font-mono" style="font-size: 11px;">+${formatMoney(bal)} (Lena Hai)</span>`;
    } else if (bal < 0) {
        balBadgeHtml = `<span class="pbadge red font-mono" style="font-size: 11px;">-${formatMoney(Math.abs(bal))} (Dena Hai)</span>`;
    } else {
        balBadgeHtml = `<span class="pbadge gray font-mono" style="font-size: 11px;">${formatMoney(0)} (Settled)</span>`;
    }

    const menu = document.createElement('div');
    menu.id = 'partyFloatingActionMenu';
    menu.className = 'cust-action-dropdown-menu';

    menu.innerHTML = `
        <div class="cad-header">
            <div class="cad-title-row">
                <span class="cad-name" title="${safeName}">${safeName}</span>
                <span class="cad-id font-mono">#${party.PartyID}</span>
            </div>
            <div style="display: flex; align-items: center; justify-content: space-between; gap: 6px; margin-top: 5px;">
                ${party.Phone ? `<span class="cad-phone font-mono" style="font-size: 11.5px;">📞 ${escapeHtml(party.Phone)}</span>` : `<span style="font-size: 11px; color: var(--text-muted);">${escapeHtml(party.PartyType || 'Party')}</span>`}
                ${balBadgeHtml}
            </div>
        </div>
        <div class="cad-items">
            <button type="button" class="cad-item" id="padOptLedger">
                <span class="cad-icon purple"><i data-lucide="book-open"></i></span>
                <div class="cad-label">
                    <span class="cad-primary">Khata Passbook (खाता खोलें)</span>
                    <span class="cad-secondary">Sampoorna len-den &amp; live baaki hisaab</span>
                </div>
            </button>
            <button type="button" class="cad-item" id="padOptLoanGiven">
                <span class="cad-icon red"><i data-lucide="hand-coins"></i></span>
                <div class="cad-label">
                    <span class="cad-primary">+ Udhaar Diya (Loan Given)</span>
                    <span class="cad-secondary">Khate se paisa nikaal kar udhaar dein</span>
                </div>
            </button>
            <button type="button" class="cad-item" id="padOptLoanRepay">
                <span class="cad-icon green"><i data-lucide="${(party.CurrentBalance || 0) > 0 ? 'arrow-down-left' : 'rotate-ccw'}"></i></span>
                <div class="cad-label">
                    <span class="cad-primary">${(party.CurrentBalance || 0) > 0 ? '↩ Wapas Mila (Loan Recovery)' : '📤 Karz Chukta (Loan Repay)'}</span>
                    <span class="cad-secondary">${(party.CurrentBalance || 0) > 0 ? 'Diye gaye udhaar ki wapsi jama karein' : 'Liye gaye karz ka bhugtan karein'}</span>
                </div>
            </button>
            <button type="button" class="cad-item" id="padOptEdit">
                <span class="cad-icon cyan"><i data-lucide="edit-3"></i></span>
                <div class="cad-label">
                    <span class="cad-primary">Party Edit Karein</span>
                    <span class="cad-secondary">Naam, prakar, phone, notes badlein</span>
                </div>
            </button>
            <div class="cad-divider"></div>
            <button type="button" class="cad-item danger" id="padOptDelete">
                <span class="cad-icon red"><i data-lucide="trash-2"></i></span>
                <div class="cad-label">
                    <span class="cad-primary text-danger">Party Delete Karein</span>
                    <span class="cad-secondary">Party ko system se hatayein</span>
                </div>
            </button>
        </div>
    `;

    menu.querySelector('#padOptLedger')?.addEventListener('click', () => {
        closePartyActionMenu();
        openPartyLedger(party.PartyID, party.PartyName);
    });
    menu.querySelector('#padOptLoanGiven')?.addEventListener('click', () => {
        closePartyActionMenu();
        addLoanFor(party.PartyID, party.PartyName);
    });
    menu.querySelector('#padOptLoanRepay')?.addEventListener('click', () => {
        closePartyActionMenu();
        if ((party.CurrentBalance || 0) > 0) {
            addRecoveryFor(party.PartyID, party.PartyName);
        } else {
            addRepayFor(party.PartyID, party.PartyName);
        }
    });
    menu.querySelector('#padOptEdit')?.addEventListener('click', () => {
        closePartyActionMenu();
        openPartyModal(party.PartyID);
    });
    menu.querySelector('#padOptDelete')?.addEventListener('click', () => {
        closePartyActionMenu();
        deleteParty(party.PartyID);
    });

    positionFloatingMenu(menu, triggerBtn, 280);
}

function closePartyActionMenu() {
    activePartyDropdownId = null;
    document.querySelectorAll('.party-menu-trigger-btn.active').forEach(b => b.classList.remove('active'));
    const m = document.getElementById('partyFloatingActionMenu');
    if (m) {
        m.classList.remove('active');
        m.remove();
    }
}
window.togglePartyActionMenu = togglePartyActionMenu;
window.closePartyActionMenu = closePartyActionMenu;

// Global Party Passbook Variables
let currentPartyLedgerId = null;
let currentPartyLedgerName = '';
let currentPartyLedgerTrans = [];

async function openPartyLedger(partyId, partyName) {
    currentPartyLedgerId = partyId;
    currentPartyLedgerName = partyName;
    currentPartyLedgerTrans = [];

    const party = (allParties || []).find(p => Number(p.PartyID) === Number(partyId)) || {};
    const titleEl = document.getElementById('partyLedgerTitle');
    const subEl = document.getElementById('partyLedgerSubtitle');
    const bodyEl = document.getElementById('partyLedgerBody');
    const headerIdEl = document.getElementById('plHeaderPartyId');
    const headerTypeEl = document.getElementById('plHeaderPartyType');
    const headerPhoneEl = document.getElementById('plHeaderPartyPhone');

    if (titleEl) titleEl.textContent = `${partyName} - Khata Passbook`;
    if (subEl) subEl.textContent = `Party ID #${partyId} ka sampoorna lene-dene ka hisaab, har entry ki full detail aur live running balance`;
    if (headerIdEl) headerIdEl.textContent = `Party ID #${partyId}`;
    if (headerTypeEl) headerTypeEl.textContent = party.PartyType || 'Party';
    if (headerPhoneEl) {
        if (party.Phone) {
            headerPhoneEl.textContent = `📞 ${party.Phone}`;
            headerPhoneEl.style.display = 'inline-flex';
        } else {
            headerPhoneEl.style.display = 'none';
        }
    }

    // Reset filters
    const searchInput = document.getElementById('plFilterSearch');
    if (searchInput) searchInput.value = '';
    const typeSelect = document.getElementById('plFilterType');
    if (typeSelect) typeSelect.value = '';

    // Quick action buttons setup
    const addLoanBtn = document.getElementById('plQuickAddLoanBtn');
    if (addLoanBtn) {
        addLoanBtn.onclick = () => addLoanFor(partyId, partyName);
    }
    const addRepayBtn = document.getElementById('plQuickAddRepayBtn');
    const addRepayLbl = document.getElementById('plQuickAddRepayLabel');
    const partyCurBal = parseFloat(party.CurrentBalance || 0);
    if (addRepayBtn) {
        if (partyCurBal > 0) {
            if (addRepayLbl) addRepayLbl.textContent = '↩ Wapas Mila';
            addRepayBtn.title = 'Diye gaye udhaar ki wapsi jama karein (Loan Recovery)';
            addRepayBtn.onclick = () => addRecoveryFor(partyId, partyName);
        } else {
            if (addRepayLbl) addRepayLbl.textContent = '📤 Karz Chukta';
            addRepayBtn.title = 'Liye gaye karz ka bhugtan karein (Loan Repay)';
            addRepayBtn.onclick = () => addRepayFor(partyId, partyName);
        }
    }
    const refreshBtn = document.getElementById('plQuickRefreshBtn');
    if (refreshBtn) {
        refreshBtn.onclick = () => openPartyLedger(partyId, partyName);
    }

    if (bodyEl) {
        bodyEl.innerHTML = `
            <tr>
                <td colspan="9" style="text-align:center; padding: 40px;">
                    <div class="spinner"></div>
                    <div style="margin-top: 12px; color: var(--text-muted); font-size: 13px; font-weight: 600;">
                        Khata passbook aur live len-den records fetch ho rahe hain...
                    </div>
                </td>
            </tr>`;
    }

    openModal('partyLedgerModal');
    if (window.lucide) lucide.createIcons();

    try {
        const res = await fetch(`${API}/parties/${partyId}/transactions`);
        const json = await res.json();
        const trans = json.data || [];

        const openBal = parseFloat(party.OpeningBalance || 0);
        let totalGiven = 0;
        let totalRepaid = 0;
        let givenCount = 0;
        let repaidCount = 0;

        // Sort chronologically (oldest to newest) to compute running balance accurately
        const chronoTrans = [...trans].sort((a, b) => {
            const da = new Date(a.TransDate).getTime() || 0;
            const db = new Date(b.TransDate).getTime() || 0;
            if (da !== db) return da - db;
            return (a.TransactionID || 0) - (b.TransactionID || 0);
        });

        let running = openBal;
        chronoTrans.forEach(t => {
            const amt = parseFloat(t.Amount || 0);
            const isDebit = t.TransType === 'Loan Given' || t.TransType === 'Expense' || t.TransType === 'Loan Repay';
            if (isDebit) {
                running += amt; // Dr increases Lena Hai / Reduces Dena Hai
                totalGiven += amt;
                givenCount++;
            } else {
                running -= amt; // Cr increases Dena Hai / Reduces Lena Hai
                totalRepaid += amt;
                repaidCount++;
            }
            t._runningBalance = running;
            t._isDebit = isDebit;
        });

        // Store for UI with newest first by default
        currentPartyLedgerTrans = [...chronoTrans].reverse();

        // Update Summary Cards
        const openEl = document.getElementById('plSummaryOpening');
        if (openEl) openEl.textContent = formatMoney(openBal);

        const givenEl = document.getElementById('plSummaryGiven');
        if (givenEl) givenEl.textContent = formatMoney(totalGiven);
        const givenCountEl = document.getElementById('plSummaryGivenCount');
        if (givenCountEl) givenCountEl.textContent = `${givenCount} debit records`;

        const repaidEl = document.getElementById('plSummaryRepaid');
        if (repaidEl) repaidEl.textContent = formatMoney(totalRepaid);
        const repaidCountEl = document.getElementById('plSummaryRepaidCount');
        if (repaidCountEl) repaidCountEl.textContent = `${repaidCount} credit records`;

        const curBal = running;
        const netEl = document.getElementById('plSummaryNet');
        const netCard = document.getElementById('plSummaryNetCard');
        const netStatus = document.getElementById('plSummaryNetStatus');

        if (netEl) {
            netEl.textContent = (curBal >= 0 ? '+' : '-') + formatMoney(Math.abs(curBal));
        }
        if (netCard) {
            netCard.classList.remove('income', 'expense');
            if (curBal > 0) {
                netCard.classList.add('income');
                if (netStatus) netStatus.textContent = 'Party se Lena Hai (Dr)';
            } else if (curBal < 0) {
                netCard.classList.add('expense');
                if (netStatus) netStatus.textContent = 'Party ko Dena Hai (Cr)';
            } else {
                if (netStatus) netStatus.textContent = 'Hisab Chukta (Settled)';
            }
        }

        const countEl = document.getElementById('plSummaryCount');
        if (countEl) countEl.textContent = `${trans.length} Entries`;

        if (addRepayBtn) {
            if (curBal > 0) {
                if (addRepayLbl) addRepayLbl.textContent = '↩ Wapas Mila';
                addRepayBtn.title = 'Diye gaye udhaar ki wapsi jama karein (Loan Recovery)';
                addRepayBtn.onclick = () => addRecoveryFor(partyId, partyName);
            } else {
                if (addRepayLbl) addRepayLbl.textContent = '📤 Karz Chukta';
                addRepayBtn.title = 'Liye gaye karz ka bhugtan karein (Loan Repay)';
                addRepayBtn.onclick = () => addRepayFor(partyId, partyName);
            }
        }

        // Render rows
        renderPartyLedgerRows(currentPartyLedgerTrans);

    } catch (err) {
        if (bodyEl) {
            bodyEl.innerHTML = `<tr><td colspan="9" style="color:var(--accent-red); text-align:center; padding: 30px;">Error: ${escapeHtml(err.message)}</td></tr>`;
        }
    }
}

function renderPartyLedgerRows(rows) {
    const bodyEl = document.getElementById('partyLedgerBody');
    if (!bodyEl) return;

    if (!rows || !rows.length) {
        bodyEl.innerHTML = `
            <tr>
                <td colspan="9" style="text-align: center; padding: 48px 20px; color: var(--text-muted);">
                    <i data-lucide="inbox" style="width: 44px; height: 44px; opacity: 0.35; margin-bottom: 8px;"></i>
                    <div style="font-size: 14px; font-weight: 700; color: var(--text-secondary);">Koi Entry Nahi Mili</div>
                    <div style="font-size: 12px; margin-top: 4px;">Is criteria ke sath koi transaction match nahi hui.</div>
                </td>
            </tr>`;
        if (window.lucide) lucide.createIcons();
        return;
    }

    bodyEl.innerHTML = rows.map(t => {
        const isDr = t._isDebit;
        const rBal = t._runningBalance;
        const safeDesc = escapeHtml(t.Description || 'Udhaari Hisaab');
        const safeCat = t.CategoryName ? escapeHtml(t.CategoryName) : '';
        const safeAcc = escapeHtml(t.AccountName || 'Counter Cash');
        const safeRef = t.Reference ? escapeHtml(t.Reference) : '';
        const safeTags = t.Tags ? escapeHtml(t.Tags) : '';

        // Type badge styling
        let typeBadgeHtml = '';
        if (t.TransType === 'Loan Given') {
            typeBadgeHtml = `<span class="pl-type-badge debit"><i data-lucide="hand-coins"></i> Udhaar Diya</span>`;
        } else if (t.TransType === 'Loan Repay') {
            typeBadgeHtml = `<span class="pl-type-badge debit"><i data-lucide="rotate-ccw"></i> Karz Chukta</span>`;
        } else if (t.TransType === 'Loan Recovery') {
            typeBadgeHtml = `<span class="pl-type-badge credit"><i data-lucide="arrow-down-left"></i> Udhaar Wapas Mila</span>`;
        } else if (t.TransType === 'Loan Received') {
            typeBadgeHtml = `<span class="pl-type-badge loan-received"><i data-lucide="hand-helping"></i> Udhaar Liya</span>`;
        } else if (t.TransType === 'Expense') {
            typeBadgeHtml = `<span class="pl-type-badge debit"><i data-lucide="trending-down"></i> Kharcha</span>`;
        } else if (t.TransType === 'Income') {
            typeBadgeHtml = `<span class="pl-type-badge credit"><i data-lucide="trending-up"></i> Aamadni</span>`;
        } else {
            typeBadgeHtml = `<span class="pl-type-badge"><i data-lucide="receipt"></i> ${escapeHtml(t.TransType)}</span>`;
        }

        // Running balance badge
        let balHtml = '';
        if (rBal > 0) {
            balHtml = `
                <div class="pl-bal-val debit">+${formatMoney(rBal)}</div>
                <span class="pl-bal-badge debit">Lena Hai (Dr)</span>`;
        } else if (rBal < 0) {
            balHtml = `
                <div class="pl-bal-val credit">-${formatMoney(Math.abs(rBal))}</div>
                <span class="pl-bal-badge credit">Dena Hai (Cr)</span>`;
        } else {
            balHtml = `
                <div class="pl-bal-val settled">${formatMoney(0)}</div>
                <span class="pl-bal-badge settled">Chukta</span>`;
        }

        return `
            <tr>
                <td>
                    <div style="font-weight: 700; font-size: 12.5px;">${formatDate(t.TransDate)}</div>
                    <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;" class="font-mono">#${t.TransactionID}</div>
                </td>
                <td>${typeBadgeHtml}</td>
                <td>
                    <div class="pl-desc-title">${safeDesc}</div>
                    <div style="display: flex; align-items: center; gap: 4px; flex-wrap: wrap;">
                        ${safeRef ? `<span class="pl-ref-pill font-mono" title="Reference Number"><i data-lucide="hash"></i> ${safeRef}</span>` : ''}
                        ${safeTags ? `<span class="pl-ref-pill" title="Tags">🏷️ ${safeTags}</span>` : ''}
                    </div>
                </td>
                <td>
                    ${safeCat ? `<span class="pl-cat-badge"><i data-lucide="tag"></i> ${safeCat}</span>` : '<span class="cell-muted">—</span>'}
                </td>
                <td>
                    <span class="pl-acc-badge"><i data-lucide="wallet"></i> ${safeAcc}</span>
                </td>
                <td style="text-align: right;">
                    ${isDr ? `<span class="pl-amount debit font-mono">-₹${formatMoney(t.Amount).replace('₹', '')}</span>` : '<span class="cell-muted">—</span>'}
                </td>
                <td style="text-align: right;">
                    ${!isDr ? `<span class="pl-amount credit font-mono">+₹${formatMoney(t.Amount).replace('₹', '')}</span>` : '<span class="cell-muted">—</span>'}
                </td>
                <td style="text-align: right;">
                    ${balHtml}
                </td>
                <td style="text-align: center;">
                    <button type="button" class="btn-pl-edit-row" onclick="editTransactionFromPassbook(${t.TransactionID})" title="Entry Edit Karein">
                        <i data-lucide="edit-2" width="12" height="12"></i>
                    </button>
                </td>
            </tr>
        `;
    }).join('');

    if (window.lucide) lucide.createIcons();
}

function filterPartyLedgerRows() {
    const query = (document.getElementById('plFilterSearch')?.value || '').toLowerCase().trim();
    const typeFilter = document.getElementById('plFilterType')?.value || '';

    let filtered = (currentPartyLedgerTrans || []).filter(t => {
        if (typeFilter && t.TransType !== typeFilter) return false;
        if (query) {
            const desc = (t.Description || '').toLowerCase();
            const cat = (t.CategoryName || '').toLowerCase();
            const acc = (t.AccountName || '').toLowerCase();
            const ref = (t.Reference || '').toLowerCase();
            const tags = (t.Tags || '').toLowerCase();
            const id = String(t.TransactionID || '');
            if (!desc.includes(query) && !cat.includes(query) && !acc.includes(query) && !ref.includes(query) && !tags.includes(query) && !id.includes(query)) {
                return false;
            }
        }
        return true;
    });

    renderPartyLedgerRows(filtered);
}

function editTransactionFromPassbook(txnId) {
    closeModal('partyLedgerModal');
    if (typeof editTransaction === 'function') {
        editTransaction(txnId);
    }
}

function exportPartyPassbookCSV() {
    if (!currentPartyLedgerTrans || !currentPartyLedgerTrans.length) {
        showToast('Download karne ke liye koi entry nahi hai.', 'warning');
        return;
    }
    const headers = ['TxnID', 'Date', 'Type', 'Description', 'Category', 'Account', 'Reference', 'Debit_Given', 'Credit_Repaid', 'Running_Balance'];
    const rows = currentPartyLedgerTrans.map(t => [
        t.TransactionID,
        formatDate(t.TransDate),
        `"${(t.TransType || '').replace(/"/g, '""')}"`,
        `"${(t.Description || '').replace(/"/g, '""')}"`,
        `"${(t.CategoryName || '').replace(/"/g, '""')}"`,
        `"${(t.AccountName || '').replace(/"/g, '""')}"`,
        `"${(t.Reference || '').replace(/"/g, '""')}"`,
        t._isDebit ? t.Amount : 0,
        !t._isDebit ? t.Amount : 0,
        t._runningBalance
    ]);
    const csvContent = 'data:text/csv;charset=utf-8,\uFEFF' + [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement('a');
    link.setAttribute('href', encodedUri);
    link.setAttribute('download', `Passbook_${(currentPartyLedgerName || 'Party').replace(/\s+/g, '_')}_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    showToast('Passbook CSV download ho gaya!', 'success');
}

function printPartyPassbook() {
    if (!currentPartyLedgerTrans || !currentPartyLedgerTrans.length) {
        showToast('Print karne ke liye koi record nahi hai.', 'warning');
        return;
    }

    const party = (allParties || []).find(p => Number(p.PartyID) === Number(currentPartyLedgerId)) || {};
    const openBal = parseFloat(party.OpeningBalance || 0);
    const curBal = parseFloat(party.CurrentBalance || 0);

    const rowsHtml = currentPartyLedgerTrans.map((t, idx) => {
        const isDr = t._isDebit;
        const drStr = isDr ? formatMoney(t.Amount) : '—';
        const crStr = !isDr ? formatMoney(t.Amount) : '—';
        const balStr = (t._runningBalance >= 0 ? '+' : '-') + formatMoney(Math.abs(t._runningBalance));
        const balLabel = t._runningBalance > 0 ? '(Lena)' : (t._runningBalance < 0 ? '(Dena)' : '(Nil)');
        return `
            <tr>
                <td style="padding: 6px 8px; font-size: 11px; text-align: center;">${idx + 1}</td>
                <td style="padding: 6px 8px; font-size: 11px; white-space: nowrap;">${formatDate(t.TransDate)}</td>
                <td style="padding: 6px 8px; font-size: 11px;">${escapeHtml(t.TransType)}</td>
                <td style="padding: 6px 8px; font-size: 11px;">
                    <b>${escapeHtml(t.Description || 'Len-Den')}</b>
                    ${t.Reference ? `<br><small style="color:#64748b;">Ref: ${escapeHtml(t.Reference)}</small>` : ''}
                </td>
                <td style="padding: 6px 8px; font-size: 11px;">${escapeHtml(t.AccountName || 'Cash')}</td>
                <td style="padding: 6px 8px; font-size: 11px; text-align: right; color: #dc2626; font-weight: 700;">${drStr}</td>
                <td style="padding: 6px 8px; font-size: 11px; text-align: right; color: #16a34a; font-weight: 700;">${crStr}</td>
                <td style="padding: 6px 8px; font-size: 11px; text-align: right; font-weight: 800;">${balStr} <span style="font-size: 9.5px; color: #64748b;">${balLabel}</span></td>
            </tr>
        `;
    }).join('');

    const sheetHtml = `
        <div class="sheet">
            <div class="header" style="text-align: center; border-bottom: 2px solid #0f172a; padding-bottom: 10px; margin-bottom: 12px;">
                <h1 style="margin: 0 0 4px 0; font-size: 18px; text-transform: uppercase;">Khata Passbook Statement</h1>
                <p style="margin: 2px 0; font-size: 12px; color: #334155;"><b>${escapeHtml(currentPartyLedgerName)}</b> (Party ID #${currentPartyLedgerId}) ${party.Phone ? `• 📞 ${escapeHtml(party.Phone)}` : ''}</p>
                <p style="margin: 2px 0; font-size: 11px; color: #64748b;">Tareekh: ${new Date().toLocaleDateString('en-IN')}</p>
            </div>
            <div class="meta-grid">
                <div class="meta-item"><span class="meta-lbl">Opening Baaki</span><span class="meta-val">${formatMoney(openBal)}</span></div>
                <div class="meta-item"><span class="meta-lbl">Kul Udhaar Diya</span><span class="meta-val" style="color: #dc2626;">${document.getElementById('plSummaryGiven')?.textContent || '₹0.00'}</span></div>
                <div class="meta-item"><span class="meta-lbl">Kul Wapas Mila / Chukta</span><span class="meta-val" style="color: #16a34a;">${document.getElementById('plSummaryRepaid')?.textContent || '₹0.00'}</span></div>
                <div class="meta-item"><span class="meta-lbl">Current Net Baaki</span><span class="meta-val">${(curBal >= 0 ? '+' : '-') + formatMoney(Math.abs(curBal))}</span></div>
            </div>
            <table>
                <thead>
                    <tr>
                        <th style="width: 30px; text-align: center;">#</th>
                        <th style="width: 80px;">Date</th>
                        <th style="width: 90px;">Kism</th>
                        <th>Vivran / Remark</th>
                        <th style="width: 90px;">Khata</th>
                        <th style="text-align: right; width: 85px;">Dr (Diya)</th>
                        <th style="text-align: right; width: 85px;">Cr (Liya)</th>
                        <th style="text-align: right; width: 110px;">Net Baaki</th>
                    </tr>
                </thead>
                <tbody>
                    ${rowsHtml}
                </tbody>
            </table>
            <div class="footer">
                Computer Generated Passbook • Cash Management System • Verified Records surakshit hisaab
            </div>
        </div>
    `;

    universalPrint(sheetHtml, {
        format: 'a4',
        title: `${currentPartyLedgerName || 'Party'} - Khata Passbook`
    });
}

function sharePartyPassbookWhatsApp() {
    if (!currentPartyLedgerTrans) return;
    const party = (allParties || []).find(p => Number(p.PartyID) === Number(currentPartyLedgerId)) || {};
    const partyName = currentPartyLedgerName || party.PartyName || 'Party';
    const sName = currentShopSettings.ShopName || '💰 AAPKI DUKAAN / HISAB BC';
    const sPhone = currentShopSettings.ShopPhone ? `*Helpline:* ${currentShopSettings.ShopPhone}\n` : '';
    const dateStr = new Date().toLocaleDateString('en-IN');

    const openBal = parseFloat(party.OpeningBalance || 0);
    const curBal = parseFloat(party.CurrentBalance || 0);
    const givenStr = document.getElementById('plSummaryGiven')?.textContent || '₹0.00';
    const repaidStr = document.getElementById('plSummaryRepaid')?.textContent || '₹0.00';
    const netStr = (curBal >= 0 ? '+' : '-') + formatMoney(Math.abs(curBal));
    const netLabel = curBal > 0 ? 'Party se Lena Hai (Dr)' : (curBal < 0 ? 'Party ko Dena Hai (Cr)' : 'Chukta');

    let recentRows = '';
    const sliceTrans = currentPartyLedgerTrans.slice(0, 5);
    if (sliceTrans.length > 0) {
        recentRows = sliceTrans.map((t, idx) => {
            const isDr = t._isDebit;
            const amtStr = formatMoney(t.Amount);
            const typeStr = isDr ? `Diya (Dr) -${amtStr}` : `Liya (Cr) +${amtStr}`;
            return `${idx + 1}. ${formatDate(t.TransDate)}: ${t.Description || 'Len-Den'} [${typeStr}]`;
        }).join('\n');
    }

    const text = `📖 *KHATA PASSBOOK STATEMENT*\n*${sName}*\n===============================\n*Party:* ${partyName} (ID #${currentPartyLedgerId})\n${party.Phone ? `*Mobile:* ${party.Phone}\n` : ''}*Tareekh:* ${dateStr}\n===============================\n*Opening Baaki:* ${formatMoney(openBal)}\n*Total Udhaar Diya (Dr 📤):* ${givenStr}\n*Total Wapas Liya (Cr 📥):* ${repaidStr}\n━━━━━━━━━━━━━━━━━━\n*CURRENT NET BAAKI:* ${netStr} (${netLabel})\n===============================\n*Recent Len-Den:*\n${recentRows || 'Koi lenden record nahi'}\n${sPhone}===============================\n${currentShopSettings.ShopFooterMsg || 'Dhanyawad! Surakshit digital hisaab.'}`;

    const clean = String(party.Phone || '').replace(/\D/g, '');
    openWhatsAppChat(clean, text);
}

