function openPartyModal(id) {
    document.getElementById('partyId').value = id || '';
    document.getElementById('partyModalTitle').textContent = id ? 'Party Edit Karo' : 'Naya Party';

    if (!id) {
        document.getElementById('partyName').value = '';
        document.getElementById('partyType').value = 'Friend';
        document.getElementById('partyPhone').value = '';
        document.getElementById('partyOpening').value = '';
        document.getElementById('partyNotes').value = '';
    } else {
        const p = allParties.find(x => x.PartyID == id);
        if (p) {
            document.getElementById('partyName').value = p.PartyName;
            document.getElementById('partyType').value = p.PartyType || 'Other';
            document.getElementById('partyPhone').value = p.Phone || '';
            document.getElementById('partyOpening').value = p.OpeningBalance || '';
            document.getElementById('partyNotes').value = p.Notes || '';
        }
    }
    openModal('partyModal');
}

async function saveParty() {
    const id = document.getElementById('partyId').value;
    const data = {
        PartyName: document.getElementById('partyName').value,
        PartyType: document.getElementById('partyType').value,
        Phone: document.getElementById('partyPhone').value,
        OpeningBalance: document.getElementById('partyOpening').value || 0,
        Notes: document.getElementById('partyNotes').value
    };
    if (!data.PartyName) { showToast('Naam bharo!', 'error'); return; }

    try {
        const method = id ? 'PUT' : 'POST';
        const url = id ? `${API}/parties/${id}` : `${API}/parties`;
        const res = await fetch(url, { method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
        const result = await res.json();
        if (!result.success) throw new Error(result.error);
        closeModal('partyModal');
        showToast(id ? 'Party update ho gayi!' : 'Party add ho gayi!');
        await refreshAllActiveViews('saveParty');
        triggerRealTimeSync('saveParty');
    } catch (err) {
        showToast('Error: ' + err.message, 'error');
    }
}

async function deleteParty(id) {
    showConfirm('Party delete karna chahte hain?', async () => {
        try {
            const res = await fetch(`${API}/parties/${id}`, { method: 'DELETE' });
            const json = await res.json();
            if (res.ok && json.success) {
                showToast('Party delete ho gayi!', 'success');
                await refreshAllActiveViews('saveParty');
                triggerRealTimeSync('saveParty');
            } else {
                showToast(json.error || 'Party delete nahi ho saki', 'error');
            }
        } catch (err) {
            showToast('Error: ' + err.message, 'error');
        }
    });
}

// ============ BUDGET PLANNER ============
let allCurrentBudgets = [];

function changeBudgetMonth(dir) {
    budgetMonth += dir;
    if (budgetMonth > 12) { budgetMonth = 1; budgetYear++; }
    if (budgetMonth < 1) { budgetMonth = 12; budgetYear--; }
    loadBudgets();
}

async function loadBudgets() {
    const labelEl = document.getElementById('budgetMonthLabel');
    if (labelEl) labelEl.textContent = `${MONTHS[budgetMonth - 1]} ${budgetYear}`;

    const container = document.getElementById('budgetsGrid');
    if (container) renderTableSkeleton(container, 6, 5);

    try {
        const res = await fetch(`${API}/budgets?month=${budgetMonth}&year=${budgetYear}`);
        const data = await res.json();
        allCurrentBudgets = data.data || [];

        // 1. Calculate Top 4 KPI Metrics
        let totalBudget = 0;
        let totalSpent = 0;

        allCurrentBudgets.forEach(b => {
            totalBudget += parseFloat(b.BudgetAmount || 0);
            totalSpent += parseFloat(b.SpentAmount || 0);
        });

        const remaining = totalBudget - totalSpent;
        const overallUsage = totalBudget > 0 ? (totalSpent / totalBudget) * 100 : 0;

        const kpiTotal = document.getElementById('budgetKpiTotal');
        if (kpiTotal) kpiTotal.textContent = formatMoney(totalBudget);
        const kpiTotalSub = document.getElementById('budgetKpiTotalSub');
        if (kpiTotalSub) kpiTotalSub.textContent = `${allCurrentBudgets.length} Category Budgets Nirdharit`;

        const kpiSpent = document.getElementById('budgetKpiSpent');
        if (kpiSpent) kpiSpent.textContent = formatMoney(totalSpent);
        const kpiSpentSub = document.getElementById('budgetKpiSpentSub');
        if (kpiSpentSub) kpiSpentSub.textContent = `${MONTHS[budgetMonth - 1]} me ab tak kharcha`;

        const kpiRem = document.getElementById('budgetKpiRemaining');
        if (kpiRem) {
            kpiRem.textContent = (remaining >= 0 ? '' : '-') + formatMoney(Math.abs(remaining));
            kpiRem.className = 'bk-val ' + (remaining >= 0 ? 'text-income' : 'text-expense');
        }

        const kpiUsage = document.getElementById('budgetKpiUsage');
        if (kpiUsage) {
            kpiUsage.textContent = `${overallUsage.toFixed(1)}%`;
            kpiUsage.style.color = overallUsage >= 100 ? 'var(--money-out)' : overallUsage >= 80 ? 'var(--money-warn)' : 'var(--money-in)';
        }

        // 2. Update Overall Month Progress Banner
        const sumText = document.getElementById('budgetSummaryText');
        if (sumText) sumText.textContent = `${allCurrentBudgets.length} budgets set hain • Kul Limit: ${formatMoney(totalBudget)} • Kharch: ${formatMoney(totalSpent)}`;

        const pill = document.getElementById('budgetOverallPill');
        if (pill) {
            pill.textContent = `${overallUsage.toFixed(1)}% KHARCH`;
            pill.className = 'bob-pill ' + (overallUsage >= 100 ? 'danger' : overallUsage >= 80 ? 'warning' : 'success');
            pill.style.background = '';
            pill.style.color = '';
        }

        const fill = document.getElementById('budgetOverallFill');
        if (fill) {
            const cappedPct = Math.min(overallUsage, 100);
            fill.style.width = `${cappedPct}%`;
            fill.className = 'progress-fill ' + (overallUsage >= 100 ? 'danger' : overallUsage >= 80 ? 'warning' : 'safe');
        }

        renderBudgetsList();
    } catch (err) {
        showToast('Budgets load error: ' + err.message, 'error');
    }
}

function filterBudgetsList() {
    renderBudgetsList();
}

function renderBudgetsList() {
    const container = document.getElementById('budgetsGrid');
    if (!container) return;

    const searchInput = document.getElementById('searchBudgetInput');
    const query = (searchInput ? searchInput.value : '').toLowerCase().trim();
    const statusFilter = document.getElementById('budgetFilterStatus');
    const selectedStatus = statusFilter ? statusFilter.value : '';

    let filtered = allCurrentBudgets.filter(b => {
        const spent = parseFloat(b.SpentAmount || 0);
        const total = parseFloat(b.BudgetAmount || 1);
        const pct = total > 0 ? (spent / total) * 100 : 0;
        const alertThreshold = b.AlertPercent || 80;

        if (selectedStatus === 'safe' && pct >= alertThreshold) return false;
        if (selectedStatus === 'warning' && (pct < alertThreshold || pct >= 100)) return false;
        if (selectedStatus === 'danger' && pct < 100) return false;

        if (query) {
            const nameMatch = (b.BudgetName || '').toLowerCase().includes(query);
            const catMatch = (b.CategoryName || '').toLowerCase().includes(query);
            if (!nameMatch && !catMatch) return false;
        }

        return true;
    });

    const metaCount = document.getElementById('budgetsFilteredCount');
    if (metaCount) {
        metaCount.textContent = `${filtered.length} of ${allCurrentBudgets.length} budgets dikh rahe hain`;
    }

    if (!filtered.length) {
        container.innerHTML = `
            <tr>
                <td colspan="6">
                    <div class="ptable-empty">
                        <i data-lucide="pie-chart" width="52" height="52" style="opacity: 0.4;"></i>
                        <h3>Is Mahine Koi Budget Nahi Hai</h3>
                        <p>Kharchon ko control karne ke liye categories par limit set karein.</p>
                        <button class="btn-primary" onclick="openBudgetModal()"><i data-lucide="plus"></i> Pehla Budget Banao</button>
                    </div>
                </td>
            </tr>`;
        lucide.createIcons();
        return;
    }

    container.innerHTML = filtered.map(b => {
        const spent = parseFloat(b.SpentAmount || 0);
        const total = parseFloat(b.BudgetAmount || 1);
        const pct = total > 0 ? (spent / total) * 100 : 0;
        const cappedPct = Math.min(pct, 100);
        const fillClass = pct >= 100 ? 'danger' : pct >= (b.AlertPercent || 80) ? 'warning' : 'safe';
        const remaining = total - spent;

        let statusText, badgeClass;
        if (pct >= 100) { statusText = 'Over-Budget'; badgeClass = 'red'; }
        else if (pct >= (b.AlertPercent || 80)) { statusText = 'Alert Warning'; badgeClass = 'yellow'; }
        else { statusText = 'Under Limit (Safe)'; badgeClass = 'green'; }

        const safeTitle = escapeHtml(b.BudgetName);
        const safeCat = escapeHtml(b.CategoryName || 'Overall Kharcha');

        return `
            <tr class="trans-data-row">
                <td>
                    <div class="cell-title" title="${safeTitle}">${safeTitle}</div>
                    <div class="cell-sub">Alert limit: ${b.AlertPercent || 80}%</div>
                </td>
                <td><span class="pbadge gray"><i data-lucide="tag" width="12" height="12"></i> ${safeCat}</span></td>
                <td class="cell-right cell-strong">${formatMoney(spent)}</td>
                <td class="cell-right cell-strong">${formatMoney(total)}</td>
                <td style="min-width: 150px;">
                    <div class="pprogress"><div class="pprogress-fill ${fillClass}" style="width: ${cappedPct}%;"></div></div>
                    <div style="display:flex; justify-content:space-between; margin-top:6px; align-items:center;">
                        <span class="pbadge ${badgeClass}">${pct.toFixed(1)}% • ${statusText}</span>
                        <span style="font-weight:700; color:${remaining >= 0 ? 'var(--accent-green)' : 'var(--accent-red)'}; font-size:12px; white-space:nowrap;">
                            ${remaining >= 0 ? formatMoney(remaining) + ' bacha' : formatMoney(Math.abs(remaining)) + ' exceed!'}
                        </span>
                    </div>
                </td>
                <td class="cell-center">
                    <div class="prow-actions">
                        <button class="pbtn-sm red" title="Delete Budget" onclick="deleteBudget(${b.BudgetID})">
                            <i data-lucide="trash-2" width="14" height="14"></i>
                        </button>
                    </div>
                </td>
            </tr>`;
    }).join('');

    lucide.createIcons();
}

function openBudgetModal() {
    document.getElementById('budgetName').value = '';
    document.getElementById('budgetCategory').value = '';
    document.getElementById('budgetAmount').value = '';
    document.getElementById('budgetMonth').value = budgetMonth;
    document.getElementById('budgetYear').value = budgetYear;
    document.getElementById('budgetAlert').value = 80;
    openModal('budgetModal');
}

async function saveBudget() {
    const data = {
        BudgetName: document.getElementById('budgetName').value,
        CategoryID: document.getElementById('budgetCategory').value || null,
        BudgetAmount: document.getElementById('budgetAmount').value,
        BudgetMonth: document.getElementById('budgetMonth').value,
        BudgetYear: document.getElementById('budgetYear').value,
        AlertPercent: document.getElementById('budgetAlert').value
    };
    if (!data.BudgetName || !data.BudgetAmount) { showToast('Naam aur amount bharo!', 'error'); return; }

    try {
        const res = await fetch(`${API}/budgets`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
        const result = await res.json();
        if (!result.success) throw new Error(result.error);
        closeModal('budgetModal');
        showToast('Budget set ho gaya!');
        await refreshAllActiveViews('budget');
        triggerRealTimeSync('budget');
    } catch (err) {
        showToast('Error: ' + err.message, 'error');
    }
}

async function deleteBudget(id) {
    showConfirm('Budget delete karna chahte hain?', async () => {
        try {
            const res = await fetch(`${API}/budgets/${id}`, { method: 'DELETE' });
            const json = await res.json();
            if (res.ok && json.success) {
                showToast('Budget delete ho gaya!', 'success');
                loadBudgets();
            } else {
                showToast(json.error || 'Budget delete nahi ho saka', 'error');
            }
        } catch (err) {
            showToast('Budget delete error: ' + err.message, 'error');
        }
    });
}

// ============ BILLS & REMINDERS (100% DIRECT LIVE SQL DATABASE) ============
let billStatusFilter = 'all';

async function loadBills() {
    const applyBillsData = (billsList) => {
        allBills = billsList || [];

        // 1. Calculate Top 4 KPI Metrics
        let totalPending = 0;
        let countPending = 0;
        let totalOverdue = 0;
        let countOverdue = 0;
        let totalPaid = 0;
        let countPaid = 0;
        let totalCommitments = 0;

        allBills.forEach(b => {
            const amt = parseFloat(b.Amount || 0);
            totalCommitments += amt;
            if (b.Status === 'Paid' || b.IsPaid) {
                totalPaid += amt;
                countPaid++;
            } else if (b.Status === 'Overdue') {
                totalOverdue += amt;
                countOverdue++;
            } else {
                totalPending += amt;
                countPending++;
            }
        });

        // Top nav badge
        const badge = document.getElementById('badge-bills');
        if (badge) {
            badge.textContent = countPending + countOverdue;
            badge.classList.remove('hidden');
            badge.style.display = 'inline-block';
        }

        // Update KPI card elements
        const kpiPend = document.getElementById('billKpiPending');
        if (kpiPend) kpiPend.textContent = formatMoney(totalPending);
        const kpiPendSub = document.getElementById('billKpiPendingSub');
        if (kpiPendSub) kpiPendSub.textContent = `${countPending} upcoming bills baqi`;

        const kpiOver = document.getElementById('billKpiOverdue');
        if (kpiOver) kpiOver.textContent = formatMoney(totalOverdue);
        const kpiOverSub = document.getElementById('billKpiOverdueSub');
        if (kpiOverSub) kpiOverSub.textContent = `${countOverdue} urgent bills ki taareekh nikli!`;

        const kpiPaid = document.getElementById('billKpiPaid');
        if (kpiPaid) kpiPaid.textContent = formatMoney(totalPaid);
        const kpiPaidSub = document.getElementById('billKpiPaidSub');
        if (kpiPaidSub) kpiPaidSub.textContent = `${countPaid} bills settle ho chuke`;

        const kpiTot = document.getElementById('billKpiTotal');
        if (kpiTot) kpiTot.textContent = formatMoney(totalCommitments);
        const kpiTotSub = document.getElementById('billKpiTotalSub');
        if (kpiTotSub) kpiTotSub.textContent = `Kul ${allBills.length} scheduled bills`;

        // Update Tab Badges
        const bAll = document.getElementById('bftBadgeAll');
        if (bAll) bAll.textContent = allBills.length;
        const bPend = document.getElementById('bftBadgePending');
        if (bPend) bPend.textContent = countPending;
        const bOver = document.getElementById('bftBadgeOverdue');
        if (bOver) bOver.textContent = countOverdue;
        const bPaid = document.getElementById('bftBadgePaid');
        if (bPaid) bPaid.textContent = countPaid;

        if (currentPage === 'bills') renderBills();
    };

    try {
        const res = await fetch(`${API}/bills`);
        const data = await res.json();
        const bills = data.data || [];
        applyBillsData(bills);
    } catch (err) {
        console.warn('[Bills] Live fetch error:', err.message);
        showToast('Bills load nahi ho sake: ' + err.message, 'error');
    }
}

function filterBills(status, btn) {
    billStatusFilter = status;
    document.querySelectorAll('.bills-filter-tabs .bft-tab').forEach(b => b.classList.remove('active'));
    if (btn) btn.classList.add('active');
    renderBills();
}

function filterBillsList() {
    renderBills();
}

function renderBills() {
    const container = document.getElementById('billsList');
    if (!container) return;

    const searchInput = document.getElementById('searchBillInput');
    const query = (searchInput ? searchInput.value : '').toLowerCase().trim();
    const typeSelect = document.getElementById('billTypeSelect');
    const selectedType = typeSelect ? typeSelect.value : '';

    let filtered = allBills.filter(b => {
        // Tab filter
        if (billStatusFilter !== 'all') {
            if (billStatusFilter === 'Paid' && !b.IsPaid && b.Status !== 'Paid') return false;
            if (billStatusFilter === 'Pending' && (b.IsPaid || b.Status !== 'Pending')) return false;
            if (billStatusFilter === 'Overdue' && (b.IsPaid || b.Status !== 'Overdue')) return false;
        }

        // Type filter
        if (selectedType && (b.BillType || 'Other') !== selectedType) return false;

        // Search query
        if (query) {
            const nameMatch = (b.BillName || '').toLowerCase().includes(query);
            const partyMatch = (b.PartyName || '').toLowerCase().includes(query);
            const catMatch = (b.CategoryName || '').toLowerCase().includes(query);
            const typeMatch = (b.BillType || '').toLowerCase().includes(query);
            const notesMatch = (b.Notes || '').toLowerCase().includes(query);
            if (!nameMatch && !partyMatch && !catMatch && !typeMatch && !notesMatch) return false;
        }

        return true;
    });

    const metaCount = document.getElementById('billsFilteredCount');
    if (metaCount) {
        metaCount.textContent = `${filtered.length} of ${allBills.length} bills dikh rahe hain`;
    }

    if (!filtered.length) {
        container.innerHTML = `
            <tr>
                <td colspan="6">
                    <div class="ptable-empty">
                        <i data-lucide="receipt" width="52" height="52" style="opacity: 0.4;"></i>
                        <h3>Koi Bill Nahi Mila</h3>
                        <p>Is category ya status me koi scheduled bill nahi hai.</p>
                        <button class="btn-primary" onclick="openBillModal()"><i data-lucide="plus"></i> Naya Bill Add Karein</button>
                    </div>
                </td>
            </tr>`;
        lucide.createIcons();
        return;
    }

    const billTypeIcons = {
        Electricity: '⚡',
        Rent: '🏠',
        EMI: '💳',
        Subscription: '📺',
        Insurance: '🛡️',
        Water: '💧',
        Internet: '🌐',
        Other: '📄'
    };

    container.innerHTML = filtered.map(b => {
        const status = b.IsPaid ? 'Paid' : b.Status;
        const statusClass = status.toLowerCase();
        const icon = billTypeIcons[b.BillType] || '📄';
        const isOverdue = status === 'Overdue';
        const isPaid = status === 'Paid';

        const safeName = escapeHtml(b.BillName);
        const safeParty = escapeHtml(b.PartyName || '');
        const safeCat = escapeHtml(b.CategoryName || '');
        const safeType = escapeHtml(b.BillType || 'Other');

        let statusBadge = '';
        if (isOverdue) statusBadge = '<span class="pbadge red">⚠️ OVERDUE</span>';
        else if (isPaid) statusBadge = '<span class="pbadge green">✓ PAID</span>';
        else statusBadge = '<span class="pbadge yellow">⏳ PENDING</span>';

        const metaParts = [];
        if (safeParty) metaParts.push(`👤 ${safeParty}`);
        if (safeCat) metaParts.push(`🏷️ ${safeCat}`);
        const metaLine = metaParts.length ? metaParts.join(' • ') : '';

        return `
            <tr class="trans-data-row">
                <td>
                    <div class="cell-flex">
                        <div class="pavatar" style="background:var(--bg-input); font-size:18px;">${icon}</div>
                        <div>
                            <div class="cell-title">${safeName}</div>
                            ${metaLine ? `<div class="cell-sub">${metaLine}</div>` : ''}
                        </div>
                    </div>
                </td>
                <td><span class="pbadge gray">${safeType}</span></td>
                <td class="cell-nowrap">
                    <span class="cell-strong">${formatDate(b.DueDate)}</span>
                </td>
                <td class="cell-right cell-amount ${isPaid ? 'cell-muted' : ''}">${formatMoney(b.Amount)}</td>
                <td class="cell-center">${statusBadge}</td>
                <td class="cell-center">
                    <div class="prow-actions">
                        ${!b.IsPaid ? `
                            <button class="pbtn-sm green" title="Pay Now" onclick="payBill(${b.BillID})">
                                <i data-lucide="check" width="14" height="14"></i>
                            </button>` : `
                            <span class="pbadge green">✓ Paid</span>
                        `}
                        <button class="pbtn-sm red" title="Delete Bill" onclick="deleteBill(${b.BillID})">
                            <i data-lucide="trash-2" width="14" height="14"></i>
                        </button>
                    </div>
                </td>
            </tr>`;
    }).join('');

    lucide.createIcons();
}

function openBillModal() {
    document.getElementById('billName').value = '';
    document.getElementById('billType').value = 'Electricity';
    document.getElementById('billAmount').value = '';
    document.getElementById('billDueDate').value = '';
    document.getElementById('billCategory').value = '';
    document.getElementById('billParty').value = '';
    document.getElementById('billNotes').value = '';

    if (window.UniversalDocUploader) {
        UniversalDocUploader.init('billDocUploader', { entityType: 'bill', title: '📎 Bill Invoice / Receipt (Upload & Rename)' });
        UniversalDocUploader.reset('billDocUploader');
    }

    openModal('billModal');
}

async function saveBill() {
    const data = {
        BillName: document.getElementById('billName').value,
        BillType: document.getElementById('billType').value,
        Amount: document.getElementById('billAmount').value,
        DueDate: document.getElementById('billDueDate').value,
        CategoryID: document.getElementById('billCategory').value || null,
        PartyID: document.getElementById('billParty').value || null,
        Notes: document.getElementById('billNotes').value
    };
    if (!data.BillName || !data.Amount || !data.DueDate) { showToast('Zaroori fields bharo!', 'error'); return; }

    try {
        const res = await fetch(`${API}/bills`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
        const result = await res.json();
        if (!result.success) throw new Error(result.error);

        const billId = result.id || result.data?.BillID;
        // Upload any staged documents with rename
        if (billId && window.UniversalDocUploader && UniversalDocUploader.hasPendingFiles('billDocUploader')) {
            try {
                await UniversalDocUploader.uploadPending('billDocUploader', { entityType: 'bill', entityId: billId });
            } catch (upErr) {
                console.error('Bill doc upload error:', upErr);
            }
        }

        closeModal('billModal');
        showToast('Bill add ho gaya!');
        await refreshAllActiveViews('bill');
        triggerRealTimeSync('bill');
    } catch (err) {
        showToast('Error: ' + err.message, 'error');
    }
}

async function payBill(id) {
    const bill = allBills.find(b => b.BillID == id);
    const accountId = allAccounts.length ? allAccounts[0].AccountID : null;

    showConfirm(`Kya aap "${bill ? bill.BillName : 'Bill'}" ka bhugtan karna chahte hain?`, async () => {
        try {
            const res = await fetch(`${API}/bills/${id}/pay`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ PaidDate: new Date().toISOString().split('T')[0], AccountID: accountId })
            });
            const result = await res.json();
            if (!result.success) throw new Error(result.error);
            showToast('Bill paid mark ho gaya!');
            await refreshAllActiveViews('payBill');
            triggerRealTimeSync('payBill');
        } catch (err) {
            showToast('Error: ' + err.message, 'error');
        }
    });
}

async function deleteBill(id) {
    showConfirm('Bill delete karna chahte hain?', async () => {
        try {
            const res = await fetch(`${API}/bills/${id}`, { method: 'DELETE' });
            const json = await res.json();
            if (res.ok && json.success) {
                showToast('Bill delete ho gaya!', 'success');
                await refreshAllActiveViews('bill');
                triggerRealTimeSync('bill');
            } else {
                showToast(json.error || 'Bill delete nahi ho saka', 'error');
            }
        } catch (err) {
            showToast('Error: ' + err.message, 'error');
        }
    });
}


