// ============ CATEGORIES ============
let catFilter = 'all';

async function loadCategories() {
    const container = document.getElementById('categoriesGrid');
    renderTableSkeleton(container, 4, 5);

    try {
        const res = await fetch(`${API}/categories`);
        const data = await res.json();
        allCategories = data.data || [];

        const filtered = catFilter === 'all' ? allCategories : allCategories.filter(c => c.CategoryType === catFilter);

        if (!filtered.length) {
            container.innerHTML = `
                <tr>
                    <td colspan="4">
                        <div class="ptable-empty">
                            <i data-lucide="tags" width="48" height="48" style="opacity: 0.4;"></i>
                            <h3>Koi Category Nahi Mili</h3>
                            <p>Is filter me koi category nahi hai. Nayi category banayein.</p>
                            <button class="btn-primary" onclick="openCategoryModal()"><i data-lucide="plus"></i> Nayi Category</button>
                        </div>
                    </td>
                </tr>`;
            lucide.createIcons();
            return;
        }

        container.innerHTML = filtered.map(c => {
            const color = c.Color || '#8b5cf6';
            const typeClass = c.CategoryType === 'Income' ? 'green' : 'red';
            return `
                <tr class="trans-data-row">
                    <td>
                        <div class="cell-flex">
                            <div class="pavatar" style="background:${color}22; color:${color}; font-size:18px;">💰</div>
                            <div class="cell-title">${escapeHtml(c.CategoryName)}</div>
                        </div>
                    </td>
                    <td><span class="pbadge ${typeClass}">${escapeHtml(c.CategoryType)}</span></td>
                    <td class="cell-center cell-muted cell-nowrap">${c.TransactionCount > 0 ? c.TransactionCount + ' transactions' : '—'}</td>
                    <td class="cell-center">
                        <div class="prow-actions">
                            <button class="pbtn-sm" title="Edit" onclick="openCategoryModal(${c.CategoryID})"><i data-lucide="edit-2" width="14" height="14"></i></button>
                            <button class="pbtn-sm red" title="Delete" onclick="deleteCategory(${c.CategoryID})"><i data-lucide="trash-2" width="14" height="14"></i></button>
                        </div>
                    </td>
                </tr>`;
        }).join('');

        lucide.createIcons();
    } catch (err) {
        showToast('Error: ' + err.message, 'error');
    }
}

function filterCategories(type, btn) {
    catFilter = type;
    document.querySelectorAll('.cat-tabs .tab-btn').forEach(b => b.classList.remove('active'));
    if (btn) btn.classList.add('active');
    loadCategories();
}

function openCategoryModal(id) {
    document.getElementById('categoryId').value = id || '';
    if (!id) {
        document.getElementById('categoryName').value = '';
        document.getElementById('categoryType').value = 'Expense';
        document.getElementById('categoryColor').value = '#8b5cf6';
    } else {
        const c = allCategories.find(x => x.CategoryID == id);
        if (c) {
            document.getElementById('categoryName').value = c.CategoryName;
            document.getElementById('categoryType').value = c.CategoryType;
            document.getElementById('categoryColor').value = c.Color || '#8b5cf6';
        }
    }
    openModal('categoryModal');
}

async function saveCategory() {
    const id = document.getElementById('categoryId').value;
    const data = {
        CategoryName: document.getElementById('categoryName').value,
        CategoryType: document.getElementById('categoryType').value,
        Color: document.getElementById('categoryColor').value
    };
    if (!data.CategoryName) { showToast('Category naam bharo!', 'error'); return; }

    try {
        const method = id ? 'PUT' : 'POST';
        const url = id ? `${API}/categories/${id}` : `${API}/categories`;
        const res = await fetch(url, { method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
        const result = await res.json();
        if (!result.success) throw new Error(result.error);
        closeModal('categoryModal');
        showToast(id ? 'Category update ho gayi!' : 'Category add ho gayi!');
        await loadMasterData();
        loadCategories();
    } catch (err) {
        showToast('Error: ' + err.message, 'error');
    }
}

async function deleteCategory(id) {
    showConfirm('Category delete karna chahte hain?', async () => {
        try {
            const res = await fetch(`${API}/categories/${id}`, { method: 'DELETE' });
            const json = await res.json();
            if (res.ok && json.success) {
                showToast('Category delete ho gayi!', 'success');
                await loadMasterData();
                loadCategories();
            } else {
                showToast(json.error || 'Category delete nahi ho saki', 'error');
            }
        } catch (err) {
            showToast('Error: ' + err.message, 'error');
        }
    });
}


/* ============================================================
   BC BANKING COUNTER / CSP JAVASCRIPT MODULE
   Cash Withdrawal, Cash Deposit, DMT, QR Pay & Galla Hisaab
   ============================================================ */

let currentBCPage = 1;
let bcSearchTimeout = null;
let currentReceiptData = null;

// Load BC Page (called when user clicks BC Counter nav)
async function loadBCPage() {
    populateBCAccountDropdowns();
    await loadBCDashboard();
    await loadBCTransactions(1);
}

// Populate account selectors in BC Modal
function populateBCAccountDropdowns() {
    const cashSelect = document.getElementById('bcCashAccount');
    const portalSelect = document.getElementById('bcPortalAccount');
    if (!cashSelect || !portalSelect) return;

    cashSelect.innerHTML = '';
    portalSelect.innerHTML = '';

    let defaultCashId = null;
    let defaultPortalId = null;

    allAccounts.forEach(acc => {
        const isCashType = acc.AccountType === 'Cash' || (acc.AccountName || '').toLowerCase().includes('cash') || (acc.AccountName || '').toLowerCase().includes('galla');
        if (isCashType && !defaultCashId) defaultCashId = acc.AccountID;
        if (!isCashType && !defaultPortalId) defaultPortalId = acc.AccountID;

        // Cash Account select (prefers Cash in Hand)
        const optCash = document.createElement('option');
        optCash.value = acc.AccountID;
        const cashBal = (isCashType && window.currentBCGallaCash != null) ? window.currentBCGallaCash : acc.CurrentBalance;
        optCash.textContent = `${acc.AccountName} (${acc.AccountType}) - ₹${Number(cashBal).toLocaleString('en-IN')}`;
        cashSelect.appendChild(optCash);

        // Portal Account select (prefers Digipay / Bank / UPI)
        const optPortal = document.createElement('option');
        optPortal.value = acc.AccountID;
        optPortal.textContent = `${acc.AccountName} (${acc.AccountType}) - ₹${Number(acc.CurrentBalance).toLocaleString('en-IN')}`;
        portalSelect.appendChild(optPortal);
    });

    if (defaultCashId) cashSelect.value = defaultCashId;
    if (defaultPortalId) portalSelect.value = defaultPortalId;

    // Mutually exclusive sync
    syncMutuallyExclusiveSelects(cashSelect, portalSelect, 'from', updateBCHisaabSummary);
}

function onBCCashAccountChanged() {
    const cashSelect = document.getElementById('bcCashAccount');
    const portalSelect = document.getElementById('bcPortalAccount');
    syncMutuallyExclusiveSelects(cashSelect, portalSelect, 'from', updateBCHisaabSummary);
}
window.onBCCashAccountChanged = onBCCashAccountChanged;

function onBCPortalAccountChanged() {
    const cashSelect = document.getElementById('bcCashAccount');
    const portalSelect = document.getElementById('bcPortalAccount');
    syncMutuallyExclusiveSelects(cashSelect, portalSelect, 'to', updateBCHisaabSummary);
}
window.onBCPortalAccountChanged = onBCPortalAccountChanged;

// Load BC Live Dashboard Stats
async function loadBCDashboard() {
    try {
        const res = await fetch(`${API}/bc/dashboard`);
        const json = await res.json();
        if (!json.success) return;
        const d = json.data;

        // Group today's service data
        let w = { TotalAmount: 0, TotalCount: 0 };
        let dep = { TotalAmount: 0, TotalCount: 0 };
        let tr = { TotalAmount: 0, TotalCount: 0 };
        let qr = { TotalAmount: 0, TotalCount: 0 };
        let totalProfit = 0;
        let totalComm = 0;
        let totalCharge = 0;

        (d.today || []).forEach(row => {
            if (row.ServiceType === 'Cash Withdrawal') w = row;
            else if (row.ServiceType === 'Cash Deposit') dep = row;
            else if (row.ServiceType === 'Money Transfer') tr = row;
            else if (row.ServiceType === 'QR Pay') qr = row;

            totalProfit += (row.TotalProfit || 0);
            totalComm += (row.TotalCommission || 0);
            totalCharge += (row.TotalCharge || 0);
        });

        // Update cards if on page
        const elW = document.getElementById('bcTodayWithdrawal');
        const elCW = document.getElementById('bcCountWithdrawal');
        if (elW) elW.textContent = '₹' + Number(w.TotalAmount || 0).toLocaleString('en-IN');
        if (elCW) elCW.textContent = (w.TotalCount || 0) + ' transactions';

        const elD = document.getElementById('bcTodayDeposit');
        const elCD = document.getElementById('bcCountDeposit');
        if (elD) elD.textContent = '₹' + Number(dep.TotalAmount || 0).toLocaleString('en-IN');
        if (elCD) elCD.textContent = (dep.TotalCount || 0) + ' transactions';

        const elT = document.getElementById('bcTodayTransfer');
        const elCT = document.getElementById('bcCountTransfer');
        if (elT) elT.textContent = '₹' + Number(tr.TotalAmount || 0).toLocaleString('en-IN');
        if (elCT) elCT.textContent = (tr.TotalCount || 0) + ' transactions';

        const elQ = document.getElementById('bcTodayQR');
        const elCQ = document.getElementById('bcCountQR');
        if (elQ) elQ.textContent = '₹' + Number(qr.TotalAmount || 0).toLocaleString('en-IN');
        if (elCQ) elCQ.textContent = (qr.TotalCount || 0) + ' transactions';

        const elP = document.getElementById('bcTodayProfit');
        const elPB = document.getElementById('bcProfitBreakdown');
        if (elP) elP.textContent = '₹' + Number(totalProfit).toLocaleString('en-IN');
        if (elPB) elPB.textContent = `Comm: ₹${Number(totalComm).toLocaleString('en-IN')} | Shulk: ₹${Number(totalCharge).toLocaleString('en-IN')}`;

        // Calculate expected galla cash
        const cashFlow = d.cashFlow || {};
        const session = d.session || {};
        const openingCash = session.OpeningCash || 0;
        const cashIn = (cashFlow.TotalCashIn || 0) + (cashFlow.TotalCashCharges || 0) + (cashFlow.TotalATMRefill || 0);
        const cashOut = (cashFlow.TotalCashOut || 0) + (cashFlow.TotalCashExpense || 0);
        const expectedCash = openingCash + cashIn - cashOut;

        // Update 3-Pillar Settlement Pipeline Balances
        let cashBal = 0, digipayBal = 0, liteBal = 0, bankBal = 0;
        (d.accounts || []).forEach(acc => {
            const name = (acc.AccountName || '').toLowerCase();
            if (acc.AccountType === 'Cash' || name.includes('cash')) cashBal += acc.CurrentBalance || 0;
            if (name === 'digipay') digipayBal = acc.CurrentBalance || 0;
            if (name.includes('lite')) liteBal = acc.CurrentBalance || 0;
            if (acc.AccountType === 'Bank' && !name.includes('digipay')) bankBal += acc.CurrentBalance || 0;
        });

        const displayGalla = (session.ActualClosingCash != null && Number(session.ActualClosingCash) > 0) ? Number(session.ActualClosingCash) : (cashBal > 0 ? cashBal : expectedCash);
        window.currentBCGallaCash = displayGalla;
        populateBCAccountDropdowns();

        const elGalla = document.getElementById('bcGallaCash');
        const elGallaSub = document.getElementById('bcGallaSub');
        if (elGalla) elGalla.textContent = '₹' + Number(displayGalla).toLocaleString('en-IN');

        const elPipeCash = document.getElementById('pipeCashBal');
        // Pillar 1 shows the accurate Cash in Hand (Galla) ledger balance matching Passbook
        if (elPipeCash) elPipeCash.textContent = '₹' + Number(cashBal).toLocaleString('en-IN', { minimumFractionDigits: 2 });

        const elPipeDigi = document.getElementById('pipeDigipayBal');
        if (elPipeDigi) elPipeDigi.textContent = '₹' + Number(digipayBal).toLocaleString('en-IN', { minimumFractionDigits: 2 });

        const elPipeLite = document.getElementById('pipeLiteBal');
        if (elPipeLite) elPipeLite.textContent = '₹' + Number(liteBal).toLocaleString('en-IN', { minimumFractionDigits: 2 });

        const elPipeBank = document.getElementById('pipeBankBal');
        if (elPipeBank) elPipeBank.textContent = '₹' + Number(bankBal).toLocaleString('en-IN', { minimumFractionDigits: 2 });

        if (elGallaSub) {
            if (session.ActualClosingCash != null && Number(session.ActualClosingCash) > 0) {
                elGallaSub.textContent = `Actual Galla: ₹${Number(session.ActualClosingCash).toLocaleString('en-IN')} (Milān Ho Chuka)`;
            } else {
                elGallaSub.textContent = `Subah: ₹${Number(openingCash).toLocaleString('en-IN')} | Aaya: +₹${Number(cashIn).toLocaleString('en-IN')} | Diya: -₹${Number(cashOut).toLocaleString('en-IN')}`;
            }
        }

        if (window.lucide && typeof lucide.createIcons === 'function') {
            lucide.createIcons();
        }

    } catch (err) {
        console.error('BC Dashboard error:', err);
    }
}

// Load BC Transactions Table
async function loadBCTransactions(page = 1) {
    currentBCPage = page;
    const tbody = document.getElementById('bcTableBody');
    if (!tbody) return;
    renderTableSkeleton(tbody, 10, 7);

    try {
        const search = document.getElementById('bcSearch')?.value || '';
        const serviceType = document.getElementById('bcServiceFilter')?.value || '';
        const startDate = document.getElementById('bcStartDate')?.value || '';
        const endDate = document.getElementById('bcEndDate')?.value || '';

        const bcLimit = 20;
        const params = new URLSearchParams({
            limit: bcLimit,
            offset: (page - 1) * bcLimit
        });
        if (search) params.append('search', search);
        if (serviceType) params.append('serviceType', serviceType);
        if (startDate) params.append('startDate', startDate);
        if (endDate) params.append('endDate', endDate);

        const res = await fetch(`${API}/bc?${params.toString()}`);
        const json = await res.json();
        if (!json.success) throw new Error(json.error);

        const list = json.data || [];
        window._currentBCTransactions = list;
        const total = json.total || 0;

        if (list.length === 0) {
            tbody.innerHTML = '<tr><td colspan="7" class="text-center" style="padding: 30px; color: var(--text-muted);">Koi BC entry nahi mili. Nayi entry karne ke liye upar button dabayein!</td></tr>';
            renderUniversalPaginationUI({
                containerId: 'bcPagination',
                infoId: 'bcPaginationInfo',
                currentPage: 1,
                pageSize: bcLimit,
                totalItems: 0,
                onPageChangeFnName: 'loadBCTransactions'
            });
            return;
        }

        const dayNames = ['Ravivar', 'Somvar', 'Mangalvar', 'Budhvar', 'Guruvar', 'Shukravar', 'Shanivar'];
        let html = '';
        list.forEach(item => {
            const bcDate = parseApiDate(item.TransDate);
            const dateStr = bcDate ? bcDate.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' }) : '-';
            const timeStr = item.TransTime ? item.TransTime.substring(0, 5) : '';
            const dayStr = bcDate ? dayNames[bcDate.getDay()] : '';

            // Service badge & styling
            let iconName = 'hand-coins';
            let serviceDisplay = item.ServiceType;
            let serviceColor = 'var(--chip-amber)';
            let serviceBg = 'rgba(245, 158, 11, 0.12)';
            let serviceBorder = 'rgba(245, 158, 11, 0.3)';

            if (item.ServiceType === 'Cash Withdrawal') {
                iconName = 'hand-coins';
                serviceDisplay = 'AEPS Nikasi';
                serviceColor = 'var(--chip-red)';
                serviceBg = 'rgba(220, 38, 38, 0.1)';
                serviceBorder = 'rgba(220, 38, 38, 0.25)';
            } else if (item.ServiceType === 'Cash Deposit') {
                iconName = 'arrow-down-to-dot';
                serviceDisplay = 'Cash Jama';
                serviceColor = 'var(--chip-green)';
                serviceBg = 'rgba(22, 163, 74, 0.1)';
                serviceBorder = 'rgba(22, 163, 74, 0.25)';
            } else if (item.ServiceType === 'Money Transfer') {
                iconName = 'send';
                serviceDisplay = 'Money Transfer';
                serviceColor = 'var(--chip-blue)';
                serviceBg = 'rgba(37, 99, 235, 0.1)';
                serviceBorder = 'rgba(37, 99, 235, 0.25)';
            } else if (item.ServiceType === 'QR Pay') {
                const isSend = (item.QROperation || '').toLowerCase().includes('send');
                iconName = isSend ? 'send' : 'qr-code';
                serviceDisplay = (isSend ? '📤 QR Send (' : '📥 QR Pay (') + (item.QRProvider || 'UPI') + ')';
                serviceColor = 'var(--chip-violet)';
                serviceBg = 'rgba(124, 58, 237, 0.1)';
                serviceBorder = 'rgba(124, 58, 237, 0.25)';
            }

            // Bank & Provider structured strings (no awkward broken lines)
            const bankTitle = item.BankName || (item.ServiceType === 'QR Pay' ? (item.QRProvider || 'UPI QR') : 'Direct Bank / Counter');
            const subDetailParts = [];
            if (item.AccountNumber) {
                subDetailParts.push(`<span class="bc-detail-tag" style="white-space: nowrap;">A/c: <b class="font-mono">${escapeHtml(item.AccountNumber)}</b></span>`);
            }
            if (item.BeneficiaryName) {
                subDetailParts.push(`<span class="bc-detail-tag" style="white-space: nowrap;">➡️ ${escapeHtml(item.BeneficiaryName)}</span>`);
            }
            if (item.ServiceType === 'QR Pay' && item.QROperation) {
                subDetailParts.push(`<span class="bc-detail-tag" style="white-space: nowrap;">${escapeHtml(item.QROperation)}</span>`);
            }

            // AEPS Portal — sirf Digipay / Digipay Lite (lamba CSC naam nahi)
            const portalRaw = (item.PortalName && String(item.PortalName).trim()) || item.PortalNameDisplay || (item.Notes ? String(item.Notes).split('|')[0].trim() : '');
            const portalDisplay = /Lite|Technology|Unified/i.test(portalRaw) ? 'Digipay Lite' : (/Digipay/i.test(portalRaw) ? 'Digipay' : 'Manual / Dashboard');
            const portalShort = portalDisplay;
            const portalBg = /Lite/i.test(portalDisplay) ? 'rgba(8,145,178,0.14)' : (/Digipay/i.test(portalDisplay) ? 'rgba(5,150,105,0.12)' : 'rgba(100,116,139,0.08)');
            const portalColor = /Lite/i.test(portalDisplay) ? 'var(--chip-cyan)' : (/Digipay/i.test(portalDisplay) ? 'var(--chip-green)' : 'var(--text-muted)');

            const itemJson = escapeHtml(encodeURIComponent(JSON.stringify(item)));

            // Universal Amount Polarity: Cash Withdrawal / QR Send / Transfer is Outflow (- Red), Deposit / QR Receive is Inflow (+ Green)
            const isOutBC = item.ServiceType === 'Cash Withdrawal' || item.ServiceType === 'Money Transfer' || ((item.QROperation || '').toLowerCase().includes('send'));
            const bcAmountHtml = formatUniversalAmount(item.Amount, isOutBC ? 'out' : 'in');

            // Account Balance formatted
            let balanceHtml = '<span style="color: var(--text-muted); opacity: 0.5;">-</span>';
            let rawBal = item.AccountBalance;
            if (Array.isArray(rawBal)) rawBal = rawBal[0];
            if (rawBal !== null && rawBal !== undefined && rawBal !== '') {
                const numBal = typeof rawBal === 'number' ? rawBal : parseFloat(String(rawBal).replace(/[^0-9.-]+/g, ''));
                if (!isNaN(numBal)) {
                    balanceHtml = `<b class="font-mono">₹${numBal.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</b>`;
                }
            }

            // Financial breakdown (Charge & Comm)
            const chargeVal = Number(item.CustomerCharge || 0);
            const commVal = Number(item.CommissionEarned || 0);

            // Settlement Account / Notes tag if present
            const settleTag = item.PortalAccountName ? `<span style="font-size: 11px; background: rgba(100, 116, 139, 0.08); border: 1px solid var(--border-row, #cbd5e1); color: var(--text-secondary); padding: 2px 6px; border-radius: 5px; white-space: nowrap; flex-shrink: 0; font-weight: 600;" title="Settlement Account: ${escapeHtml(item.PortalAccountName)}">🏦 ${escapeHtml(item.PortalAccountName)}</span>` : '';

            // RRN code
            const rrnCode = item.RRN_UTR || ('TXN-' + item.BCID);

            html += `
                <tr class="bc-table-row">
                    <!-- 1. Universal SN & Sewa (3 Lines) -->
                    <td class="cell-center bc-col-sn-service" style="vertical-align: middle; text-align: center;">
                        <div>
                            <button type="button" 
                                    class="csc-sn-pill uni-sn-pill" 
                                    onclick="openUniversalRecordDetail('BC', ${item.BCID}, '${escapeInlineArg(item.SNCode || '')}')" 
                                    title="Universal Serial No: ${escapeHtml(item.SNCode || ('SN-' + item.GlobalSerialNo))} (Click karke Poori Detail Dekhein)"
                                    style="font-size: 12.5px; font-weight: 800; padding: 3px 8px;">
                                <i data-lucide="file-text" width="13" height="13"></i>
                                <span>${escapeHtml(item.SNCode || (item.GlobalSerialNo ? 'SN-' + item.GlobalSerialNo : '-'))}</span>
                            </button>
                        </div>
                        <div style="margin-top: 5px;">
                            <span class="bc-badge" data-slip-json="${itemJson}" style="cursor: pointer; display: inline-flex; align-items: center; gap: 4px; padding: 3px 8px; border-radius: 5px; font-size: 11.5px; font-weight: 700; background: ${serviceBg}; color: ${serviceColor}; border: 1px solid ${serviceBorder}; white-space: nowrap;" title="Slip aur poori detail dekhein">
                                <i data-lucide="${iconName}" style="width: 12px; height: 12px;"></i>
                                ${serviceDisplay}
                            </span>
                        </div>
                        <div style="font-size: 11px; color: var(--text-muted); margin-top: 4px; font-family: monospace;">
                            BC-${item.BCID}
                        </div>
                    </td>

                    <!-- 2. Samay / Tarikh (3 Lines) -->
                    <td class="bc-col-datetime" style="white-space: nowrap; vertical-align: middle;">
                        <div style="font-weight: 800; font-size: 14px; color: var(--text-primary);">${timeStr}</div>
                        <div style="font-size: 11.5px; color: var(--text-secondary); margin-top: 3px; font-weight: 600;">${dateStr}</div>
                        <div style="font-size: 10.5px; color: var(--text-muted); margin-top: 2px;">${dayStr}</div>
                    </td>

                    <!-- 3. Grahak Vivran (Customer - 3 Lines) -->
                    <td class="bc-col-customer" style="vertical-align: middle;">
                        <!-- Line 1: Customer Name (Bada 15px) + ID + Docs -->
                        <div style="font-weight: 700; color: var(--text-primary); display: flex; align-items: center; gap: 6px; flex-wrap: nowrap;">
                            <span style="font-size: 15px; font-weight: 800; white-space: nowrap; color: var(--text-primary);">${escapeHtml(item.CustomerName || 'Grahak')}</span>
                            ${item.CustomerID ? `
                                <span class="badge" onclick="goToCustomerKhata(${item.CustomerID})" style="cursor: pointer; background: rgba(59, 130, 246, 0.15); color: var(--chip-blue); border: 1px solid rgba(59, 130, 246, 0.3); font-size: 11px; padding: 2px 6px; border-radius: 4px; font-weight: 700; white-space: nowrap;" title="Customer Khata Kholo (ID: #${item.CustomerID})">#${item.CustomerID} 🔗</span>
                                <button type="button" class="btn-copy-mini" tabindex="-1" onclick="event.stopPropagation(); openCustomerDocsModal(${item.CustomerID}, '${escapeInlineArg(item.CustomerName)}')" title="${escapeHtml(item.CustomerName)} ke dastavej (Documents) dekhein" style="color: var(--chip-cyan); padding: 2px 6px; display: inline-flex; align-items: center; gap: 2px; font-size: 11px; font-weight: 700; border-radius: 4px; background: rgba(2, 132, 199, 0.12); border: 1px solid rgba(2, 132, 199, 0.3); white-space: nowrap; cursor: pointer;"><i data-lucide="paperclip" width="11" height="11"></i> Docs</button>
                            ` : ''}
                        </div>
                        <!-- Line 2: Phone + Aadhaar -->
                        <div style="font-size: 12px; color: var(--text-secondary); display: flex; align-items: center; gap: 8px; flex-wrap: nowrap; margin-top: 5px;">
                            ${item.CustomerPhone ? `<span style="white-space: nowrap; font-weight: 600;">${renderPhoneWithCopy(item.CustomerPhone, { fontSize: '12px', showIcon: true, showWhatsApp: false })}</span>` : ''}
                            ${item.LinkedCustomerAadhaar ? `<span style="white-space: nowrap;">${renderAadhaarWithEye(item.LinkedCustomerAadhaar, { fontSize: '11.5px', color: 'var(--chip-green)' })}</span>` : (item.CustomerAadhaarLast4 ? `<span class="aadhaar-reveal-wrap font-mono" style="font-size: 11.5px; color: var(--text-muted); white-space: nowrap;">🪪 ****${escapeHtml(item.CustomerAadhaarLast4.slice(-4))}</span>` : '')}
                        </div>
                        <!-- Line 3: DOB Full Clear Tag -->
                        <div style="margin-top: 4px; display: flex; align-items: center; gap: 6px;">
                            ${item.DateOfBirth ? `
                                <span style="font-size: 11px; color: var(--chip-amber); background: rgba(245, 158, 11, 0.08); padding: 2px 7px; border-radius: 4px; border: 1px solid rgba(245, 158, 11, 0.25); white-space: nowrap; font-family: monospace; font-weight: 700;" title="Janm Tithi (DOB)">🎂 Janm Tithi: ${formatIndianDate(item.DateOfBirth)}</span>
                            ` : '<span style="font-size: 11px; color: var(--text-muted); opacity: 0.5;">Walk-in Grahak</span>'}
                        </div>
                    </td>

                    <!-- 4. Bank & Portal / RRN (3 Lines) -->
                    <td class="bc-col-bank-portal" style="vertical-align: middle;">
                        <!-- Line 1: Bank Name (Bada 14px) -->
                        <div style="font-weight: 800; color: var(--text-primary); font-size: 14px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;" title="${escapeHtml(bankTitle)}">${escapeHtml(bankTitle)}</div>
                        <!-- Line 2: Portal + Settlement Account -->
                        <div style="font-size: 11px; color: var(--text-muted); margin-top: 5px; display: flex; align-items: center; gap: 6px; flex-wrap: nowrap;">
                            <span title="${escapeHtml(portalDisplay)}" style="font-size: 11px; background: ${portalBg}; border: 1px solid ${portalBg}; color: ${portalColor}; padding: 2px 7px; border-radius: 5px; font-weight: 700; white-space: nowrap; flex-shrink: 0;">
                                ${escapeHtml(portalShort)}
                            </span>
                            ${settleTag}
                            ${subDetailParts.length > 0 ? `<span style="white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${subDetailParts.join(' ')}</span>` : ''}
                        </div>
                        <!-- Line 3: RRN Code -->
                        <div style="margin-top: 4px;">
                            <code data-slip-json="${itemJson}" style="font-size: 11.5px; color: var(--chip-violet); cursor: pointer; padding: 2px 7px; background: rgba(124, 58, 237, 0.08); border-radius: 4px; border: 1px solid rgba(124, 58, 237, 0.25); font-family: monospace; white-space: nowrap;" title="Transaction slip / RRN: ${escapeHtml(rrnCode)}">
                                RRN: ${escapeHtml(rrnCode)}
                            </code>
                        </div>
                    </td>

                    <!-- 5. Len-Den Rashi & Khata Balance (3 Lines) -->
                    <td class="text-right bc-col-amount-bal" data-slip-json="${itemJson}" style="cursor: pointer; vertical-align: middle; white-space: nowrap;" title="Slip aur poori detail dekhein">
                        <div style="font-size: 16px; font-weight: 800; white-space: nowrap;">
                            ${bcAmountHtml}
                        </div>
                        <div style="font-size: 11px; color: var(--text-muted); margin-top: 3px;">
                            Bank Balance:
                        </div>
                        <div style="font-size: 12.5px; color: var(--chip-green); font-weight: 800; font-family: monospace; margin-top: 1px;">
                            ${balanceHtml}
                        </div>
                    </td>

                    <!-- 6. Munafa & Shulk / Commission (3 Lines) -->
                    <td class="text-right bc-col-profit-fee" style="vertical-align: middle; white-space: nowrap;">
                        <div>
                            <span class="font-mono font-bold" style="background: rgba(16, 185, 129, 0.14); color: var(--chip-green); border: 1px solid rgba(16, 185, 129, 0.35); padding: 3px 8px; border-radius: 6px; font-size: 13.5px; white-space: nowrap;">
                                +₹${Number(item.NetProfit || 0).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                            </span>
                        </div>
                        <div style="font-size: 11px; color: var(--text-muted); margin-top: 4px;">
                            Shulk: ₹${chargeVal.toLocaleString('en-IN')}
                        </div>
                        <div style="font-size: 11px; color: var(--chip-cyan); margin-top: 1px; font-weight: 700;">
                            Comm: ₹${commVal.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                        </div>
                    </td>

                    <!-- 7. Kriya (Actions) -->
                    <td class="text-center bc-col-actions" style="vertical-align: middle; white-space: nowrap;">
                        <div style="display: flex; flex-direction: column; gap: 5px; justify-content: center; align-items: center; white-space: nowrap;">
                            <button class="btn-slip" data-slip-json="${itemJson}" title="Customer Slip Print / WhatsApp" style="padding: 5px 9px; font-size: 11.5px; background: rgba(16, 185, 129, 0.12); color: var(--chip-green); border: 1px solid rgba(16, 185, 129, 0.3); font-weight: 700; border-radius: 6px; cursor: pointer; display: inline-flex; align-items: center; gap: 4px; white-space: nowrap;">
                                <i data-lucide="printer" style="width: 12px; height: 12px;"></i> Slip
                            </button>
                            <button type="button" class="table-menu-trigger-btn bc-menu-trigger-btn" onclick="toggleBCActionMenu(event, ${item.BCID})" title="Sabhi Kriya (3 Dots Menu)">
                                <i data-lucide="more-vertical" width="15" height="15"></i>
                            </button>
                        </div>
                    </td>
                </tr>
            `;
        });

        tbody.innerHTML = html;
        lucide.createIcons();

        // Pagination (20 rows per page + universal buttons)
        renderUniversalPaginationUI({
            containerId: 'bcPagination',
            infoId: 'bcPaginationInfo',
            currentPage: page,
            pageSize: bcLimit,
            totalItems: total,
            onPageChangeFnName: 'loadBCTransactions'
        });

    } catch (err) {
        tbody.innerHTML = `<tr><td colspan="7" class="text-center text-danger" style="padding: 24px;">Error: ${err.message}</td></tr>`;
    }
}

// --------------------------------------------------------------------------
// FLOATING 3-DOT ACTION MENU FOR BC BANKING
// --------------------------------------------------------------------------
let activeBcDropdownId = null;

function toggleBCActionMenu(e, bcId) {
    if (e) {
        e.preventDefault();
        e.stopPropagation();
    }

    const existingMenu = document.getElementById('bcFloatingActionMenu');
    if (existingMenu && activeBcDropdownId === bcId) {
        closeBCActionMenu();
        return;
    }

    closeAllActionMenus();

    let item = (window._currentBCTransactions || []).find(b => Number(b.BCID) === Number(bcId));
    if (!item) {
        const trigger = (e && e.target) ? e.target.closest('tr') : null;
        const slipEl = trigger ? trigger.querySelector('[data-slip-json]') : null;
        if (slipEl && slipEl.dataset.slipJson) {
            try { item = JSON.parse(decodeURIComponent(slipEl.dataset.slipJson)); } catch (err) { }
        }
    }
    if (!item) return;

    const triggerBtn = (e && e.currentTarget) ? e.currentTarget : (e && e.target ? e.target.closest('.bc-menu-trigger-btn, .table-menu-trigger-btn') : null);
    if (!triggerBtn) return;

    triggerBtn.classList.add('active');
    activeBcDropdownId = bcId;

    const safeName = escapeHtml(item.CustomerName || 'Customer');
    const rrn = escapeHtml(item.RRN_UTR || 'TXN-' + item.BCID);
    const amount = Number(item.Amount || 0);
    const serviceType = escapeHtml(item.ServiceType || 'BC Transaction');
    const itemJson = escapeHtml(encodeURIComponent(JSON.stringify(item)));

    const menu = document.createElement('div');
    menu.id = 'bcFloatingActionMenu';
    menu.className = 'cust-action-dropdown-menu';

    menu.innerHTML = `
        <div class="cad-header">
            <div class="cad-title-row">
                <span class="cad-name" title="${safeName}">${safeName}</span>
                <span class="cad-id font-mono">#${rrn}</span>
            </div>
            <div style="display: flex; align-items: center; justify-content: space-between; gap: 6px; margin-top: 5px;">
                <span style="font-size: 11px; color: var(--text-muted);">${serviceType}</span>
                <span style="font-size: 12px; font-weight: 800; color: #10b981;">₹${amount.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</span>
            </div>
            ${item.CustomerPhone ? `<div class="cad-phone font-mono">📞 ${escapeHtml(item.CustomerPhone)}</div>` : ''}
        </div>
        <div class="cad-items">
            <button type="button" class="cad-item" id="bcOptSlip">
                <span class="cad-icon purple"><i data-lucide="receipt"></i></span>
                <div class="cad-label">
                    <span class="cad-primary">Customer Slip Dekhein / Print</span>
                    <span class="cad-secondary">Thermal &amp; A4 transaction slip</span>
                </div>
            </button>
            ${item.CustomerPhone ? `
                <button type="button" class="cad-item" id="bcOptWhatsApp">
                    <span class="cad-icon green"><i data-lucide="message-circle"></i></span>
                    <div class="cad-label">
                        <span class="cad-primary">WhatsApp Slip Bhejein</span>
                        <span class="cad-secondary">Len-den vivran direct WhatsApp</span>
                    </div>
                </button>
            ` : ''}
            ${item.CustomerID ? `
                <button type="button" class="cad-item" id="bcOptKhata">
                    <span class="cad-icon blue"><i data-lucide="book-open"></i></span>
                    <div class="cad-label">
                        <span class="cad-primary">Customer Khata Kholo</span>
                        <span class="cad-secondary">Linked khata hisaab dekhein</span>
                    </div>
                </button>
                <button type="button" class="cad-item" id="bcOptCust360">
                    <span class="cad-icon cyan"><i data-lucide="user-check"></i></span>
                    <div class="cad-label">
                        <span class="cad-primary">Customer 360° Profile</span>
                        <span class="cad-secondary">Sampoorna profile &amp; itihaas</span>
                    </div>
                </button>
                <button type="button" class="cad-item" id="bcOptDocs">
                    <span class="cad-icon orange"><i data-lucide="paperclip"></i></span>
                    <div class="cad-label">
                        <span class="cad-primary">Customer Dastavej (Docs)</span>
                        <span class="cad-secondary">Aadhaar, photo va upload files</span>
                    </div>
                </button>
            ` : ''}
            <div class="cad-divider"></div>
            <button type="button" class="cad-item danger" id="bcOptDelete">
                <span class="cad-icon red"><i data-lucide="trash-2"></i></span>
                <div class="cad-label">
                    <span class="cad-primary text-danger">BC Entry Delete Karein</span>
                    <span class="cad-secondary">Is len-den record ko hatayein</span>
                </div>
            </button>
        </div>
    `;

    menu.querySelector('#bcOptSlip')?.addEventListener('click', () => {
        closeBCActionMenu();
        if (item.BCID) {
            openBcSlipById(item.BCID);
        } else {
            openSlipFromData(itemJson);
        }
    });
    menu.querySelector('#bcOptWhatsApp')?.addEventListener('click', () => {
        closeBCActionMenu();
        const msg = `Namaste ${item.CustomerName || ''}, aapka ${item.ServiceType} ₹${amount} safaltapoorvak poora hua (RRN: ${item.RRN_UTR || item.BCID}). Shubh din!`;
        openWhatsAppChat(item.CustomerPhone, msg);
    });
    menu.querySelector('#bcOptKhata')?.addEventListener('click', () => {
        closeBCActionMenu();
        if (item.CustomerID) goToCustomerKhata(item.CustomerID);
    });
    menu.querySelector('#bcOptCust360')?.addEventListener('click', () => {
        closeBCActionMenu();
        if (item.CustomerID) openCustomer360Modal(item.CustomerID, true);
    });
    menu.querySelector('#bcOptDocs')?.addEventListener('click', () => {
        closeBCActionMenu();
        if (item.CustomerID) openCustomerDocsModal(item.CustomerID, item.CustomerName);
    });
    menu.querySelector('#bcOptDelete')?.addEventListener('click', () => {
        closeBCActionMenu();
        deleteBCTransaction(item.BCID);
    });

    positionFloatingMenu(menu, triggerBtn, 280);
}

function closeBCActionMenu() {
    activeBcDropdownId = null;
    document.querySelectorAll('.bc-menu-trigger-btn.active').forEach(b => b.classList.remove('active'));
    const m = document.getElementById('bcFloatingActionMenu');
    if (m) {
        m.classList.remove('active');
        m.remove();
    }
}
window.toggleBCActionMenu = toggleBCActionMenu;
window.closeBCActionMenu = closeBCActionMenu;

// Search debounce for BC table
function handleBCSearch() {
    clearTimeout(bcSearchTimeout);
    bcSearchTimeout = setTimeout(() => {
        loadBCTransactions(1);
    }, 300);
}

// Reset BC table filters
function resetBCFilters() {
    document.getElementById('bcSearch').value = '';
    document.getElementById('bcServiceFilter').value = '';
    document.getElementById('bcStartDate').value = '';
    document.getElementById('bcEndDate').value = '';
    loadBCTransactions(1);
}

// Open BC Modal with preselected service type
function openBCModal(serviceType = 'Cash Withdrawal') {
    populateBCAccountDropdowns();

    // Clear form
    document.getElementById('bcId').value = '';
    if (document.getElementById('bcCustomerId')) document.getElementById('bcCustomerId').value = '';
    if (document.getElementById('bcCustomerSelect')) document.getElementById('bcCustomerSelect').value = '';
    if (document.getElementById('bcAadhaarChip')) document.getElementById('bcAadhaarChip').innerHTML = '';
    if (document.getElementById('bcPhoneChip')) document.getElementById('bcPhoneChip').innerHTML = '';
    document.getElementById('bcCustomerName').value = '';
    document.getElementById('bcCustomerPhone').value = '';
    document.getElementById('bcAadhaar').value = '';
    if (document.getElementById('bcCustomerDob')) document.getElementById('bcCustomerDob').value = '';
    if (document.getElementById('bcDobChip')) document.getElementById('bcDobChip').innerHTML = '';
    if (document.getElementById('bcCustomerDocBadge')) document.getElementById('bcCustomerDocBadge').style.display = 'none';
    document.getElementById('bcBankName').value = '';
    document.getElementById('bcAccountNumber').value = '';
    if (document.getElementById('bcAccountBalance')) document.getElementById('bcAccountBalance').value = '';
    document.getElementById('bcBeneficiaryName').value = '';
    document.getElementById('bcIFSC').value = '';
    document.getElementById('bcAmount').value = '';
    document.getElementById('bcCustomerCharge').value = '0';
    const commEl = document.getElementById('bcCommission');
    if (commEl) {
        commEl.value = '0';
        commEl.removeAttribute('data-user-overridden');
        delete commEl.dataset.autoValue;
    }
    const commHint = document.getElementById('bcCommHint');
    if (commHint) {
        commHint.textContent = '';
        commHint.style.display = 'none';
    }
    const chargeKhataChk = document.getElementById('bcChargeOnKhata');
    if (chargeKhataChk) chargeKhataChk.checked = false;
    document.getElementById('bcProfitDisplay').value = '₹0.00';
    const breakupEl = document.getElementById('bcProfitBreakup');
    if (breakupEl) breakupEl.innerHTML = `Shulk: ₹0.00<br>Comm: ₹0.00`;
    document.getElementById('bcRRN').value = '';
    document.getElementById('bcNotes').value = '';
    document.getElementById('bcTransDate').value = new Date().toISOString().split('T')[0];

    // Find tab button and activate it
    const tabs = document.querySelectorAll('.bc-tabs .type-tab');
    let targetTab = null;
    tabs.forEach(t => {
        if (t.getAttribute('data-bctype') === serviceType) targetTab = t;
    });

    setBCServiceType(serviceType, targetTab);
    if (serviceType === 'QR Pay') {
        setBCQRAction('Send - Cash Taken from Customer');
    }
    updateBCHisaabSummary();
    openModal('bcModal');
}

// Switch BC Service Type & dynamically toggle visible fields
function setBCServiceType(serviceType, btnEl) {
    document.getElementById('bcServiceTypeVal').value = serviceType;

    const tabs = document.querySelectorAll('.bc-tabs .type-tab');
    tabs.forEach(t => {
        const type = t.getAttribute('data-bctype');
        const isMatch = (t === btnEl) || (type === serviceType);
        if (isMatch) {
            t.classList.add('active');
            if (type === 'Cash Withdrawal') {
                t.style.setProperty('background', 'linear-gradient(135deg, #2563eb, #1d4ed8)', 'important');
                t.style.setProperty('border-color', '#60a5fa', 'important');
                t.style.setProperty('color', '#ffffff', 'important');
                t.style.setProperty('box-shadow', '0 4px 14px rgba(37, 99, 235, 0.45)', 'important');
            } else if (type === 'Cash Deposit') {
                t.style.setProperty('background', 'linear-gradient(135deg, #059669, #047857)', 'important');
                t.style.setProperty('border-color', '#34d399', 'important');
                t.style.setProperty('color', '#ffffff', 'important');
                t.style.setProperty('box-shadow', '0 4px 14px rgba(16, 185, 129, 0.45)', 'important');
            } else if (type === 'Money Transfer') {
                t.style.setProperty('background', 'linear-gradient(135deg, #7c3aed, #6d28d9)', 'important');
                t.style.setProperty('border-color', '#a78bfa', 'important');
                t.style.setProperty('color', '#ffffff', 'important');
                t.style.setProperty('box-shadow', '0 4px 14px rgba(124, 58, 237, 0.45)', 'important');
            } else if (type === 'QR Pay') {
                t.style.setProperty('background', 'linear-gradient(135deg, #ea580c, #c2410c)', 'important');
                t.style.setProperty('border-color', '#fb923c', 'important');
                t.style.setProperty('color', '#ffffff', 'important');
                t.style.setProperty('box-shadow', '0 4px 14px rgba(234, 88, 12, 0.45)', 'important');
            }
            const icon = t.querySelector('i');
            if (icon) icon.style.setProperty('color', '#ffffff', 'important');
        } else {
            t.classList.remove('active');
            t.style.removeProperty('background');
            t.style.removeProperty('border-color');
            t.style.removeProperty('color');
            t.style.removeProperty('box-shadow');
            const icon = t.querySelector('i');
            if (icon) icon.style.removeProperty('color');
        }
    });

    // Field Groups
    const groupAadhaar = document.getElementById('bcGroupAadhaar');
    const groupBank = document.getElementById('bcGroupBank');
    const groupAccount = document.getElementById('bcGroupAccount');
    const groupAccountBalance = document.getElementById('bcGroupAccountBalance');
    const groupBeneficiary = document.getElementById('bcGroupBeneficiary');
    const groupIFSC = document.getElementById('bcGroupIFSC');
    const groupQR = document.getElementById('bcGroupQRProvider');
    const groupQROp = document.getElementById('bcGroupQROp');

    const cashLabel = document.getElementById('bcCashAccountLabel');
    const portalLabel = document.getElementById('bcPortalAccountLabel');

    if (serviceType === 'Cash Withdrawal') {
        document.getElementById('bcModalTitle').textContent = '💳 Cash Withdrawal (AEPS / Micro-ATM)';
        if (groupAadhaar) groupAadhaar.style.display = 'block';
        if (groupBank) groupBank.style.display = 'block';
        if (groupAccount) groupAccount.style.display = 'none';
        if (groupAccountBalance) groupAccountBalance.style.display = 'block';
        if (groupBeneficiary) groupBeneficiary.style.display = 'none';
        if (groupIFSC) groupIFSC.style.display = 'none';
        if (groupQR) groupQR.style.display = 'none';
        if (groupQROp) groupQROp.style.display = 'none';
        if (cashLabel) cashLabel.innerHTML = '<span>💵 Cash Galla (Customer ko Cash Diya 🔻)</span> <span class="pbadge green" style="font-size: 10px;">Auto-Selected</span>';
        if (portalLabel) portalLabel.innerHTML = '🏦 CSP / Portal Account (Bank se Paisa Aaya 🔺) <span class="req">*</span>';
    } else if (serviceType === 'Cash Deposit') {
        document.getElementById('bcModalTitle').textContent = '📥 Cash Deposit (Khate me Jama)';
        if (groupAadhaar) groupAadhaar.style.display = 'none';
        if (groupBank) groupBank.style.display = 'block';
        if (groupAccount) groupAccount.style.display = 'block';
        if (groupAccountBalance) groupAccountBalance.style.display = 'block';
        if (groupBeneficiary) groupBeneficiary.style.display = 'none';
        if (groupIFSC) groupIFSC.style.display = 'none';
        if (groupQR) groupQR.style.display = 'none';
        if (groupQROp) groupQROp.style.display = 'none';
        if (cashLabel) cashLabel.innerHTML = '<span>💵 Cash Galla (Customer se Cash Liya 🔺)</span> <span class="pbadge green" style="font-size: 10px;">Auto-Selected</span>';
        if (portalLabel) portalLabel.innerHTML = '🏦 CSP / Portal Account (Customer A/c me Gaya 🔻) <span class="req">*</span>';
    } else if (serviceType === 'Money Transfer') {
        document.getElementById('bcModalTitle').textContent = '💸 Money Transfer (DMT / IMPS)';
        if (groupAadhaar) groupAadhaar.style.display = 'none';
        if (groupBank) groupBank.style.display = 'block';
        if (groupAccount) groupAccount.style.display = 'block';
        if (groupAccountBalance) groupAccountBalance.style.display = 'none';
        if (groupBeneficiary) groupBeneficiary.style.display = 'block';
        if (groupIFSC) groupIFSC.style.display = 'block';
        if (groupQR) groupQR.style.display = 'none';
        if (groupQROp) groupQROp.style.display = 'none';
        if (cashLabel) cashLabel.innerHTML = '<span>💵 Cash Galla (Customer se Cash Liya 🔺)</span> <span class="pbadge green" style="font-size: 10px;">Auto-Selected</span>';
        if (portalLabel) portalLabel.innerHTML = '🏦 DMT Portal / Bank (Beneficiary ko Bheja 🔻) <span class="req">*</span>';
    } else if (serviceType === 'QR Pay') {
        if (groupAadhaar) groupAadhaar.style.display = 'none';
        if (groupBank) groupBank.style.display = 'none';
        if (groupAccount) groupAccount.style.display = 'none';
        if (groupAccountBalance) groupAccountBalance.style.display = 'none';
        if (groupBeneficiary) groupBeneficiary.style.display = 'none';
        if (groupIFSC) groupIFSC.style.display = 'none';
        if (groupQR) groupQR.style.display = 'block';
        if (groupQROp) groupQROp.style.display = 'block';
        onBCQROperationChanged();
    }

    if (serviceType !== 'QR Pay') {
        const helperEl = document.getElementById('bcQROpHelper');
        if (helperEl) helperEl.style.display = 'none';
    }

    // Auto-select portal account: Digipay for AEPS/DMT/Deposit, Bank Account for QR Pay
    const portalSelect = document.getElementById('bcPortalAccount');
    if (portalSelect) {
        for (let i = 0; i < portalSelect.options.length; i++) {
            const optText = (portalSelect.options[i].textContent || '').toLowerCase();
            if (serviceType === 'QR Pay' && optText.includes('bank')) {
                portalSelect.selectedIndex = i;
                break;
            } else if (serviceType !== 'QR Pay' && optText.includes('digipay')) {
                portalSelect.selectedIndex = i;
                break;
            }
        }
        if (portalSelect._ssInstance && typeof portalSelect._ssInstance.syncFromNative === 'function') {
            portalSelect._ssInstance.syncFromNative();
        }
    }

    calculateBCProfit();
    updateBCHisaabSummary();
}

// 1-Click QR Action toggle between Send (Cash In) and Receive (Cash Out)
function setBCQRAction(action) {
    const qrOpSel = document.getElementById('bcQROperation');
    if (qrOpSel) {
        qrOpSel.value = action;
        if (qrOpSel._ssInstance && typeof qrOpSel._ssInstance.syncFromNative === 'function') {
            qrOpSel._ssInstance.syncFromNative();
        }
    }
    onBCQROperationChanged();
}
window.setBCQRAction = setBCQRAction;

// Auto-sync Portal/Bank account when QR provider is changed
function onBCQRProviderChanged() {
    const prov = document.getElementById('bcQRProvider')?.value || '';
    const portalSelect = document.getElementById('bcPortalAccount');
    if (!portalSelect) return;

    for (let i = 0; i < portalSelect.options.length; i++) {
        const optText = (portalSelect.options[i].textContent || '').toLowerCase();
        if (prov === 'Digipay QR' && optText.includes('digipay')) {
            portalSelect.selectedIndex = i;
            break;
        } else if (optText.includes('bank')) {
            portalSelect.selectedIndex = i;
            break;
        }
    }
    if (portalSelect._ssInstance && typeof portalSelect._ssInstance.syncFromNative === 'function') {
        portalSelect._ssInstance.syncFromNative();
    }
    updateBCHisaabSummary();
}
window.onBCQRProviderChanged = onBCQRProviderChanged;

// Dynamically handle QR Send vs Receive title, helper descriptions, and account labels
function onBCQROperationChanged() {
    const qrOp = document.getElementById('bcQROperation')?.value || 'Send - Cash Taken from Customer';
    const titleEl = document.getElementById('bcModalTitle');
    const helperEl = document.getElementById('bcQROpHelper');
    const isQRActive = document.getElementById('bcServiceTypeVal')?.value === 'QR Pay';
    if (!isQRActive) return;

    const sendCard = document.getElementById('bcQrCardSendCash');
    const recvCard = document.getElementById('bcQrCardReceiveCash');
    const cashLabel = document.getElementById('bcCashAccountLabel');
    const portalLabel = document.getElementById('bcPortalAccountLabel');

    if (qrOp === 'Send - Cash Taken from Customer') {
        if (titleEl) titleEl.textContent = '📤 QR Code: Send (Customer ko Bheja — Mujhe Cash Mila)';
        if (sendCard) {
            sendCard.style.borderColor = '#2563eb';
            sendCard.style.background = 'rgba(37, 99, 235, 0.12)';
            sendCard.style.boxShadow = '0 0 0 2px rgba(37, 99, 235, 0.25)';
        }
        if (recvCard) {
            recvCard.style.borderColor = 'var(--border-color)';
            recvCard.style.background = 'var(--bg-card)';
            recvCard.style.boxShadow = 'none';
        }
        if (cashLabel) cashLabel.innerHTML = '<span>💵 Cash Galla (Customer se Cash Mila 🔺 +Amount)</span> <span class="pbadge green" style="font-size: 10px; background: #10b981; color: white;">Cash Judega</span>';
        if (portalLabel) portalLabel.innerHTML = '🏦 Dukaan Ka Bank / UPI (Jisse Customer ko Bheja 🔻 -Amount) <span class="req">*</span>';
        if (helperEl) {
            helperEl.style.display = 'block';
            helperEl.style.background = 'rgba(37, 99, 235, 0.08)';
            helperEl.style.borderColor = 'rgba(37, 99, 235, 0.3)';
            helperEl.style.color = '#1d4ed8';
            helperEl.innerHTML = '👉 <b>Customer ke QR/UPI par bheja:</b> Galle me CASH jama hoga (Cash 🔺), Dukaan ke Online Bank/UPI se katega (Online 🔻).';
        }
    } else if (qrOp === 'Cash Given to Customer') {
        if (titleEl) titleEl.textContent = '📲 QR Code: Receive (Customer se Liya — Maine Cash Diya)';
        if (recvCard) {
            recvCard.style.borderColor = '#ea580c';
            recvCard.style.background = 'rgba(234, 88, 12, 0.12)';
            recvCard.style.boxShadow = '0 0 0 2px rgba(234, 88, 12, 0.25)';
        }
        if (sendCard) {
            sendCard.style.borderColor = 'var(--border-color)';
            sendCard.style.background = 'var(--bg-card)';
            sendCard.style.boxShadow = 'none';
        }
        if (cashLabel) cashLabel.innerHTML = '<span>💵 Cash Galla (Customer ko Cash Diya 🔻 -Amount)</span> <span class="pbadge red" style="font-size: 10px; background: #ef4444; color: white;">Cash Nikasi</span>';
        if (portalLabel) portalLabel.innerHTML = '🏦 Dukaan Ka Bank / UPI QR (Jisme Online Paisa Aaya 🔺 +Amount) <span class="req">*</span>';
        if (helperEl) {
            helperEl.style.display = 'block';
            helperEl.style.background = 'rgba(234, 88, 12, 0.1)';
            helperEl.style.borderColor = 'rgba(234, 88, 12, 0.25)';
            helperEl.style.color = '#ea580c';
            helperEl.innerHTML = '👉 <b>Customer ne QR scan kiya:</b> Dukaan ke Online Bank/UPI me paisa aayega (Online 🔺), Galle se CASH niklega (Cash 🔻).';
        }
    } else if (qrOp === 'Deposit/Payment') {
        if (titleEl) titleEl.textContent = '📲 QR Code: Direct Receive (Payment Liya — No Cash)';
        if (sendCard) { sendCard.style.borderColor = 'var(--border-color)'; sendCard.style.background = 'var(--bg-card)'; sendCard.style.boxShadow = 'none'; }
        if (recvCard) { recvCard.style.borderColor = 'var(--border-color)'; recvCard.style.background = 'var(--bg-card)'; recvCard.style.boxShadow = 'none'; }
        if (cashLabel) cashLabel.innerHTML = '<span>💵 Cash Galla (Cash par koi asar nahi)</span>';
        if (portalLabel) portalLabel.innerHTML = '🏦 Dukaan Ka UPI QR (Jisme Payment Aaya 🔺) <span class="req">*</span>';
        if (helperEl) {
            helperEl.style.display = 'block';
            helperEl.style.background = 'rgba(16, 185, 129, 0.1)';
            helperEl.style.borderColor = 'rgba(16, 185, 129, 0.25)';
            helperEl.style.color = '#10b981';
            helperEl.innerHTML = '👉 <b>Direct QR Payment:</b> Dukaan ke UPI me jama hoga (+UPI), Galla cash par koi asar nahi hoga.';
        }
    } else if (qrOp === 'Send - Direct Transfer') {
        if (titleEl) titleEl.textContent = '📤 QR Code: Direct Send (Customer ko Bheja — No Cash)';
        if (sendCard) { sendCard.style.borderColor = 'var(--border-color)'; sendCard.style.background = 'var(--bg-card)'; sendCard.style.boxShadow = 'none'; }
        if (recvCard) { recvCard.style.borderColor = 'var(--border-color)'; recvCard.style.background = 'var(--bg-card)'; recvCard.style.boxShadow = 'none'; }
        if (cashLabel) cashLabel.innerHTML = '<span>💵 Cash Galla (Cash par koi asar nahi)</span>';
        if (portalLabel) portalLabel.innerHTML = '🏦 Dukaan Ka Bank / UPI (Jisse Transfer Hua 🔻) <span class="req">*</span>';
        if (helperEl) {
            helperEl.style.display = 'block';
            helperEl.style.background = 'rgba(124, 58, 237, 0.1)';
            helperEl.style.borderColor = 'rgba(124, 58, 237, 0.25)';
            helperEl.style.color = '#7c3aed';
            helperEl.innerHTML = '👉 <b>Direct Transfer:</b> Dukaan ke UPI/Bank account se katega (-UPI), Galla cash par koi asar nahi hoga.';
        }
    }

    updateBCHisaabSummary();
}

