// Populate From/To accounts in Settlement Modal
function populateSettlementAccounts() {
    const fromSel = document.getElementById('settleFromAccount');
    const toSel = document.getElementById('settleToAccount');
    if (!fromSel || !toSel) return;

    fromSel.innerHTML = '';
    toSel.innerHTML = '';

    (allAccounts || []).forEach(acc => {
        const optFrom = document.createElement('option');
        optFrom.value = acc.AccountID;
        optFrom.textContent = `${acc.AccountName} (${acc.AccountType})`;

        const optTo = document.createElement('option');
        optTo.value = acc.AccountID;
        optTo.textContent = `${acc.AccountName} (${acc.AccountType})`;

        fromSel.appendChild(optFrom);
        toSel.appendChild(optTo);
    });

    updateSettlementBadges();

    if (window.refreshAllSearchableSelects) {
        window.refreshAllSearchableSelects();
    }
}

// Set Settlement Type & smart pre-selections
function setSettlementType(type, btnEl) {
    document.getElementById('settlementTypeVal').value = type;

    const tabs = document.querySelectorAll('.settlement-tabs .type-tab');
    tabs.forEach(t => {
        const stype = t.getAttribute('data-stype');
        const isMatch = (t === btnEl) || (stype === type);
        if (isMatch) {
            t.classList.add('active');
            if (stype === 'Payout to Bank') {
                t.style.setProperty('background', 'linear-gradient(135deg, #0284c7, #0369a1)', 'important');
                t.style.setProperty('border-color', '#38bdf8', 'important');
                t.style.setProperty('color', '#ffffff', 'important');
                t.style.setProperty('box-shadow', '0 4px 14px rgba(2, 132, 199, 0.45)', 'important');
            } else if (stype === 'ATM Cash Refill') {
                t.style.setProperty('background', 'linear-gradient(135deg, #059669, #047857)', 'important');
                t.style.setProperty('border-color', '#34d399', 'important');
                t.style.setProperty('color', '#ffffff', 'important');
                t.style.setProperty('box-shadow', '0 4px 14px rgba(16, 185, 129, 0.45)', 'important');
            } else if (stype === 'Wallet Top-Up') {
                t.style.setProperty('background', 'linear-gradient(135deg, #7c3aed, #6d28d9)', 'important');
                t.style.setProperty('border-color', '#a78bfa', 'important');
                t.style.setProperty('color', '#ffffff', 'important');
                t.style.setProperty('box-shadow', '0 4px 14px rgba(124, 58, 237, 0.45)', 'important');
            } else if (stype === 'Wallet to Wallet') {
                t.style.setProperty('background', 'linear-gradient(135deg, #d97706, #b45309)', 'important');
                t.style.setProperty('border-color', '#fbbf24', 'important');
                t.style.setProperty('color', '#ffffff', 'important');
                t.style.setProperty('box-shadow', '0 4px 14px rgba(217, 119, 6, 0.45)', 'important');
            }
            const icon = t.querySelector('i');
            if (icon) icon.style.setProperty('color', '#ffffff', 'important');
        } else {
            t.classList.remove('active');
            t.style.removeProperty('background');
            t.style.removeProperty('border-color');
            t.style.removeProperty('color');
            t.style.removeProperty('box-shadow');
            const icon = t.querySelector('i');
            if (icon) icon.style.removeProperty('color');
        }
    });

    const fromSel = document.getElementById('settleFromAccount');
    const toSel = document.getElementById('settleToAccount');
    const infoBox = document.getElementById('settlementInfoBox');
    const title = document.getElementById('settlementModalTitle');
    const chargesGroup = document.getElementById('settleChargesGroup');

    let digipayId = null;
    let digiLiteId = null;
    let bankId = null;
    let cashId = null;

    allAccounts.forEach(acc => {
        const name = (acc.AccountName || '').toLowerCase();
        if (name.includes('digipay') && !name.includes('lite')) digipayId = acc.AccountID;
        if (name.includes('lite')) digiLiteId = acc.AccountID;
        if ((acc.AccountType === 'Bank' || name.includes('bank')) && !name.includes('digipay')) {
            if (!bankId) bankId = acc.AccountID;
        }
        if (acc.AccountType === 'Cash' || name.includes('cash') || name.includes('galla')) {
            if (!cashId) cashId = acc.AccountID;
        }
    });

    // Intelligent fallbacks
    if (!bankId) {
        const anyBank = allAccounts.find(a => a.AccountType === 'Bank');
        if (anyBank) bankId = anyBank.AccountID;
    }
    if (!cashId) {
        const anyCash = allAccounts.find(a => a.AccountType === 'Cash');
        if (anyCash) cashId = anyCash.AccountID;
    }
    if (!digipayId) {
        const anyPortal = allAccounts.find(a => a.AccountType === 'Portal' || a.AccountType === 'UPI');
        if (anyPortal) digipayId = anyPortal.AccountID;
    }

    if (type === 'Payout to Bank') {
        title.innerHTML = '🔄 Digipay se Bank Payout (Move to Bank)';
        infoBox.innerHTML = '<b>📱 Digipay / Digipay Lite</b> wallet se paisa nikal kar apne <b>🏦 Main Bank Account</b> mein transfer karein (Payout).';
        infoBox.style.color = '#38bdf8';
        infoBox.style.background = 'rgba(2, 132, 199, 0.1)';
        infoBox.style.borderColor = 'rgba(2, 132, 199, 0.3)';
        chargesGroup.style.display = 'block';

        const preferredFrom = digipayId || cashId || (allAccounts[0]?.AccountID);
        fromSel.value = preferredFrom;
        const preferredTo = bankId || (allAccounts.find(a => String(a.AccountID) !== String(preferredFrom))?.AccountID);
        toSel.value = preferredTo;
        document.getElementById('settleMode').value = 'IMPS';

    } else if (type === 'ATM Cash Refill') {
        title.innerHTML = '🏧 ATM / Bank se Cash Nikala (Galla Refill)';
        infoBox.innerHTML = 'Apne <b>🏦 Main Bank Account</b> se ATM ya Branch dwara physical Cash nikala aur <b>💵 Galla (Cash in Hand)</b> me laya.';
        infoBox.style.color = '#34d399';
        infoBox.style.background = 'rgba(16, 185, 129, 0.1)';
        infoBox.style.borderColor = 'rgba(16, 185, 129, 0.3)';
        chargesGroup.style.display = 'none';

        const preferredTo = cashId || (allAccounts[0]?.AccountID);
        toSel.value = preferredTo;
        const preferredFrom = bankId || (allAccounts.find(a => String(a.AccountID) !== String(preferredTo))?.AccountID);
        fromSel.value = preferredFrom;
        document.getElementById('settleMode').value = 'ATM';

    } else if (type === 'Wallet Top-Up') {
        title.innerHTML = '⚡ Wallet Load / Top-Up (Deposit/DMT ke liye)';
        infoBox.innerHTML = 'Apne <b>🏦 Bank ya UPI</b> se <b>📱 Digipay / Digipay Lite</b> wallet me paisa load kiya taaki customer ko Jama / Money Transfer kar sakein.';
        infoBox.style.color = '#a78bfa';
        infoBox.style.background = 'rgba(139, 92, 246, 0.1)';
        infoBox.style.borderColor = 'rgba(139, 92, 246, 0.3)';
        chargesGroup.style.display = 'none';

        const preferredTo = digipayId || (allAccounts.find(a => a.AccountType !== 'Cash' && a.AccountType !== 'Bank')?.AccountID) || (allAccounts[0]?.AccountID);
        toSel.value = preferredTo;
        const preferredFrom = bankId || cashId || (allAccounts.find(a => String(a.AccountID) !== String(preferredTo))?.AccountID);
        fromSel.value = preferredFrom;
        document.getElementById('settleMode').value = 'UPI';

    } else if (type === 'Wallet to Wallet') {
        title.innerHTML = '↔️ Digipay ⇄ Digipay Lite Wallet Transfer';
        infoBox.innerHTML = 'Ek CSC wallet se dusre CSC wallet mein balance shift karein.';
        infoBox.style.color = '#fbbf24';
        infoBox.style.background = 'rgba(245, 158, 11, 0.1)';
        infoBox.style.borderColor = 'rgba(245, 158, 11, 0.3)';
        chargesGroup.style.display = 'none';

        const preferredFrom = digipayId || (allAccounts[0]?.AccountID);
        fromSel.value = preferredFrom;
        const preferredTo = digiLiteId || (allAccounts.find(a => String(a.AccountID) !== String(preferredFrom))?.AccountID);
        toSel.value = preferredTo;
        document.getElementById('settleMode').value = 'IMPS';
    }

    // Mutually exclusive check & disable selected option on the opposite side
    syncMutuallyExclusiveSelects(fromSel, toSel, 'from', updateSettlementPreview);
    updateSettlementBadges();
}

function updateSettlementPreview() {
    const fromSel = document.getElementById('settleFromAccount');
    const toSel = document.getElementById('settleToAccount');
    if (!fromSel || !toSel) return;
    updateSettlementBadges();

    const amt = parseFloat(document.getElementById('settleAmount')?.value) || 0;
    const fee = parseFloat(document.getElementById('settleCharges')?.value) || 0;

    const fromAcc = (allAccounts || []).find(a => String(a.AccountID) === String(fromSel.value));
    const toAcc = (allAccounts || []).find(a => String(a.AccountID) === String(toSel.value));

    const fromText = fromAcc ? `${fromAcc.AccountName} (${fromAcc.AccountType})` : 'Source';
    const toText = toAcc ? `${toAcc.AccountName} (${toAcc.AccountType})` : 'Destination';

    const infoBox = document.getElementById('settlementInfoBox');
    const livePreview = document.getElementById('settlementLivePreview');

    if (fromSel.value && toSel.value && String(fromSel.value) === String(toSel.value)) {
        if (infoBox) {
            infoBox.innerHTML = `⚠️ <b style="color: #f87171;">Warning: Dono taraf ek hi account (${escapeHtml(fromText)}) chuna hai! Transfer ke liye do alag alag khate chunein.</b>`;
            infoBox.style.borderColor = 'rgba(239, 68, 68, 0.4)';
            infoBox.style.background = 'rgba(239, 68, 68, 0.1)';
        }
        if (livePreview) livePreview.style.display = 'none';
        return;
    }

    if (amt > 0 && fromAcc && toAcc) {
        const curFromBal = parseFloat(fromAcc.CurrentBalance || 0);
        const curToBal = parseFloat(toAcc.CurrentBalance || 0);
        const newFromBal = curFromBal - amt - fee;
        const newToBal = curToBal + amt;

        if (infoBox) {
            infoBox.innerHTML = `👉 <b>${escapeHtml(fromAcc.AccountName)}</b> se <b>₹${amt.toLocaleString('en-IN')}</b> ${fee > 0 ? `(+ ₹${fee} charge) ` : ''}ghatenge aur <b>${escapeHtml(toAcc.AccountName)}</b> me <b>₹${amt.toLocaleString('en-IN')}</b> add honge.`;
        }

        if (livePreview) {
            livePreview.style.display = 'block';
            livePreview.innerHTML = `
                <div class="settle-live-impact">
                    <div class="impact-box">
                        <span class="impact-label">📤 ${escapeHtml(fromAcc.AccountName)} (Deduct)</span>
                        <div class="impact-flow">
                            <span class="impact-old">₹${curFromBal.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</span>
                            <span class="impact-arrow">➔</span>
                            <span class="impact-new ${newFromBal < 0 ? 'negative' : 'deduct'}">
                                ₹${newFromBal.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                            </span>
                            ${newFromBal < 0 ? '<span style="font-size: 11px; color: #ef4444; font-weight: 800;">(Neg Bal Warning)</span>' : ''}
                        </div>
                    </div>
                    <div class="impact-box">
                        <span class="impact-label">📥 ${escapeHtml(toAcc.AccountName)} (Add)</span>
                        <div class="impact-flow">
                            <span class="impact-old">₹${curToBal.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</span>
                            <span class="impact-arrow">➔</span>
                            <span class="impact-new credit">
                                ₹${newToBal.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                            </span>
                        </div>
                    </div>
                </div>
            `;
        }
    } else {
        if (livePreview) livePreview.style.display = 'none';
    }
}

// Save Settlement
async function saveSettlement() {
    const type = document.getElementById('settlementTypeVal').value;
    const fromAcc = document.getElementById('settleFromAccount').value;
    const toAcc = document.getElementById('settleToAccount').value;
    const amt = parseFloat(document.getElementById('settleAmount').value);

    if (!fromAcc || !toAcc) {
        showToast('Source aur Destination account select karein!', 'error', 'Account Chunein');
        return;
    }
    if (String(fromAcc) === String(toAcc)) {
        showToast('Source aur Destination account alag alag hone chahiye! Ek hi khate me transfer nahi kiya ja sakta.', 'error', 'Same Account');
        return;
    }
    if (!amt || amt <= 0) {
        showToast('Valid amount daalein!', 'error', 'Rashi Bharein');
        document.getElementById('settleAmount').focus();
        return;
    }

    const oldFromAcc = (allAccounts || []).find(a => String(a.AccountID) === String(fromAcc));
    const oldToAcc = (allAccounts || []).find(a => String(a.AccountID) === String(toAcc));
    const oldFromBal = parseFloat(oldFromAcc?.CurrentBalance || 0);
    const oldToBal = parseFloat(oldToAcc?.CurrentBalance || 0);

    const payload = {
        TransferType: type,
        FromAccountID: fromAcc,
        ToAccountID: toAcc,
        Amount: amt,
        Charges: parseFloat(document.getElementById('settleCharges').value) || 0,
        TransferMode: document.getElementById('settleMode').value,
        Reference: document.getElementById('settleReference').value.trim(),
        TransDate: document.getElementById('settleDate').value,
        Notes: document.getElementById('settleNotes').value.trim()
    };

    showUniversalLoader(
        'Settlement Process Ho Raha Hai...',
        'Bank, Cash aur Wallet accounts synchronize ho rahe hain...'
    );

    try {
        const res = await fetch(`${API}/bc/settlement`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });
        const json = await res.json();
        if (!json.success) throw new Error(json.error);

        closeModal('bcSettlementModal');
        showToast(`✅ ${type} safaltapoorvak complete ho gaya!`, 'success', 'Settlement Safal');
        await refreshAllActiveViews('saveSettlement');
        triggerRealTimeSync('saveSettlement');

        const newFromBal = json.fromAccount?.CurrentBalance !== undefined
            ? parseFloat(json.fromAccount.CurrentBalance)
            : (oldFromBal - amt - (payload.Charges || 0));
        const newToBal = json.toAccount?.CurrentBalance !== undefined
            ? parseFloat(json.toAccount.CurrentBalance)
            : (oldToBal + amt);

        const fromName = oldFromAcc?.AccountName || json.fromAccount?.AccountName || 'Source Account';
        const toName = oldToAcc?.AccountName || json.toAccount?.AccountName || 'Destination Account';
        const fromType = oldFromAcc?.AccountType || json.fromAccount?.AccountType || 'Bank';
        const toType = oldToAcc?.AccountType || json.toAccount?.AccountType || 'Cash';

        showActionSuccessModal({
            title: `${type} Safalta Se Hua! 💸`,
            subtitle: `Dono accounts ke balance live database me update ho gaye hain`,
            icon: 'arrow-left-right',
            customHtml: `
                <div style="font-size: 26px; font-weight: 900; color: #10b981; margin: 4px 0 2px 0; font-variant-numeric: tabular-nums;">
                    ₹${amt.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                </div>
                <div style="font-size: 12px; font-weight: 700; color: var(--text-muted); margin-bottom: 14px;">
                    Transfer Rashi (${escapeHtml(type)})
                </div>

                <div class="settle-success-card">
                    <!-- Source Account: Deducted -->
                    <div class="settle-res-acc source">
                        <div class="res-acc-title">
                            <span class="res-pill red">📤 Kahan Se Deduct Hua</span>
                            <strong class="res-acc-name">${escapeHtml(fromName)} (${escapeHtml(fromType)})</strong>
                        </div>
                        <div class="res-bal-flow">
                            <div class="bal-box">
                                <span class="bal-lbl">Purana Balance</span>
                                <span class="bal-amt old">₹${oldFromBal.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</span>
                            </div>
                            <div class="flow-change-badge deduct">
                                <span>-₹${amt.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</span>
                                <i data-lucide="arrow-right" style="width: 14px; height: 14px;"></i>
                            </div>
                            <div class="bal-box right">
                                <span class="bal-lbl">Latest Naya Balance</span>
                                <span class="bal-amt new deduct">₹${newFromBal.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</span>
                            </div>
                        </div>
                    </div>

                    <!-- Destination Account: Credited -->
                    <div class="settle-res-acc dest">
                        <div class="res-acc-title">
                            <span class="res-pill green">📥 Kahan Ko Jama Hua</span>
                            <strong class="res-acc-name">${escapeHtml(toName)} (${escapeHtml(toType)})</strong>
                        </div>
                        <div class="res-bal-flow">
                            <div class="bal-box">
                                <span class="bal-lbl">Purana Balance</span>
                                <span class="bal-amt old">₹${oldToBal.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</span>
                            </div>
                            <div class="flow-change-badge credit">
                                <span>+₹${amt.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</span>
                                <i data-lucide="arrow-right" style="width: 14px; height: 14px;"></i>
                            </div>
                            <div class="bal-box right">
                                <span class="bal-lbl">Latest Naya Balance</span>
                                <span class="bal-amt new credit">₹${newToBal.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</span>
                            </div>
                        </div>
                    </div>
                </div>

                <div class="settle-meta-pills">
                    <span class="settle-meta-pill">⚡ Mode: <b>${escapeHtml(payload.TransferMode)}</b></span>
                    ${payload.Charges > 0 ? `<span class="settle-meta-pill">💸 Charges: <b>₹${Number(payload.Charges).toLocaleString('en-IN', { minimumFractionDigits: 2 })}</b></span>` : ''}
                    ${payload.Reference ? `<span class="settle-meta-pill">🔖 UTR/Ref: <b>${escapeHtml(payload.Reference)}</b></span>` : ''}
                    <span class="settle-meta-pill">📅 Tarikh: <b>${escapeHtml(payload.TransDate)}</b></span>
                </div>
            `,
            actions: [
                {
                    text: 'Naya Settlement',
                    icon: 'plus',
                    className: 'btn-primary',
                    onClick: () => openSettlementModal(type)
                },
                {
                    text: 'Theek Hai',
                    className: 'btn-secondary',
                    onClick: () => { }
                }
            ]
        });
    } catch (err) {
        showToast('Error: ' + err.message, 'error', 'Settlement Truti');
    } finally {
        hideUniversalLoader();
    }
}

