let allCustomersData = [];
let allInvoicesData = [];
let currentCustomerFilter = 'all';
let currentInvoiceFilter = 'all';
let currentActiveCustomerId = null;
let currentKbFilter = 'all';
let invoiceItemsList = [];

// Universal Live Sidebar Badges Updater — single fast query to live SQL Server
async function updateAllSidebarBadges() {
    try {
        const res = await fetch(`${API}/badges`);
        const json = await res.json();
        if (json.success && json.data) {
            const d = json.data;
            const setBadge = (id, val) => {
                const el = document.getElementById(id);
                if (el) {
                    el.textContent = val ?? 0;
                    el.classList.remove('hidden');
                    el.style.display = 'inline-block';
                }
            };

            setBadge('badge-transactions', d.transactions || 0);
            setBadge('badge-accounts', d.accounts || 0);
            setBadge('badge-parties', d.parties || 0);
            setBadge('badge-customers', d.customers || 0);
            setBadge('badge-billing', d.invoices || 0);
            setBadge('badge-khatabook', d.khatabook || 0);
            setBadge('badge-documents', d.documents || 0);
            setBadge('badge-csc', d.csc || 0);
            setBadge('badge-budgets', d.budgets || 0);
            setBadge('badge-bills', d.bills || 0);
            setBadge('badge-categories', d.categories || 0);
            setBadge('badge-recyclebin', d.recyclebin || 0);
            setBadge('badge-history', d.history || 0);
        }
    } catch (e) {
        console.warn('Sidebar badges update error:', e.message);
    }
}

// Backward compatible alias
async function updateVyaparBadges() {
    await updateAllSidebarBadges();
}

