// 1. CUSTOMERS MANAGEMENT (100% DIRECT LIVE SQL DATABASE)
// --------------------------------------------------------------------------

async function loadCustomersPage() {
    const applyCustomersData = (data, summary) => {
        allCustomersData = data || [];
        summary = summary || {};

        // KPIs
        const elTotal = document.getElementById('custKpiTotal');
        const elReceive = document.getElementById('custKpiToReceive');
        const elPay = document.getElementById('custKpiToPay');
        const elNet = document.getElementById('custKpiNet');

        if (elTotal) elTotal.textContent = summary.TotalCustomers || (allCustomersData.length || 0);
        if (elReceive) elReceive.textContent = formatMoney(summary.TotalToReceive || 0);
        if (elPay) elPay.textContent = formatMoney(summary.TotalToPay || 0);
        if (elNet) {
            const net = summary.NetBalance || 0;
            elNet.textContent = formatMoney(Math.abs(net));
            elNet.className = 'sc-amount ' + (net > 0 ? 'text-expense' : (net < 0 ? 'text-income' : 'cell-muted'));
            elNet.style.color = net > 0 ? '#f87171' : (net < 0 ? '#34d399' : '#94a3b8');
        }

        renderCustomersTable();
        populateCustomerDropdowns();
        updateVyaparBadges();
    };

    try {
        const tbody = document.getElementById('customersTableBody');
        if (tbody && (!allCustomersData || allCustomersData.length === 0)) {
            renderTableSkeleton(tbody, 7, 5);
        }
        const res = await fetch(`${API}/customers`);
        const json = await res.json();
        if (!json.success) throw new Error(json.error);

        const data = json.data || [];
        const summary = json.summary || {};

        applyCustomersData(data, summary);
    } catch (err) {
        console.warn('[Customers] Live fetch error:', err.message);
        showToast('Customers load nahi ho sake: ' + err.message, 'error');
    }
}

let phoneCheckDebounceTimer = null;
let activeFamilyData = null;
let custCurrentPage = 1;
let custPageSize = 20;

function changeCustPage(page) {
    custCurrentPage = page;
    renderCustomersTable();
    const tableEl = document.getElementById('customersTableBody');
    if (tableEl) {
        const wrap = tableEl.closest('.table-responsive') || tableEl.closest('.card');
        if (wrap) wrap.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
}
window.changeCustPage = changeCustPage;

function changeCustPageSize(val) {
    if (val === 'all') {
        custPageSize = 999999;
    } else {
        custPageSize = parseInt(val) || 20;
    }
    custCurrentPage = 1;
    renderCustomersTable();
}
window.changeCustPageSize = changeCustPageSize;

function setCustomerFilter(filter, btn) {
    currentCustomerFilter = filter;
    custCurrentPage = 1;
    document.querySelectorAll('.customer-toolbar .tab-btn').forEach(b => b.classList.remove('active'));
    if (btn) btn.classList.add('active');
    renderCustomersTable();
}

function filterCustomersList() {
    custCurrentPage = 1;
    renderCustomersTable();
}

function renderCustomersTable() {
    const tbody = document.getElementById('customersTableBody');
    if (!tbody) return;

    const queryStr = (document.getElementById('custSearchInput')?.value || '').toLowerCase().trim();

    let list = allCustomersData.filter(c => {
        // Search
        const nameMatch = (c.CustomerName || '').toLowerCase().includes(queryStr);
        const phoneMatch = (c.Phone || '').toLowerCase().includes(queryStr);
        const digitsOnly = queryStr.replace(/\D/g, '');
        const idMatch = (digitsOnly && String(c.CustomerID) === digitsOnly) ||
            (queryStr.startsWith('#') && String(c.CustomerID) === queryStr.replace(/^[#c]/i, '').trim());
        const aadhaarMatch = digitsOnly.length > 0 && (c.AadhaarNumber || '').replace(/\D/g, '').includes(digitsOnly);
        const addrMatch = (c.Address || '').toLowerCase().includes(queryStr);
        const famMatch = (c.FamilyName || '').toLowerCase().includes(queryStr);
        const relMatch = (c.Relationship || '').toLowerCase().includes(queryStr);
        const parentMatch = (c.ParentCustomerName || '').toLowerCase().includes(queryStr);
        if (queryStr && !idMatch && !nameMatch && !phoneMatch && !aadhaarMatch && !addrMatch && !famMatch && !relMatch && !parentMatch) return false;

        // Filter
        const bal = parseFloat(c.CurrentBalance) || 0;
        if (currentCustomerFilter === 'to_receive') return bal > 0;
        if (currentCustomerFilter === 'to_pay') return bal < 0;
        if (currentCustomerFilter === 'settled') return bal === 0;
        if (currentCustomerFilter === 'family') {
            return (c.FamilyMembersCount > 1) || (!c.IsFamilyHead) || (c.ParentCustomerID != null);
        }
        return true;
    });

    // Latest first sorting
    list.sort((a, b) => (b.CustomerID || 0) - (a.CustomerID || 0));

    const totalCust = list.length;

    if (totalCust === 0) {
        tbody.innerHTML = `
            <tr>
                <td colspan="8">
                    <div class="ptable-empty">
                        <i data-lucide="user-x" width="44" height="44" style="color: var(--text-muted);"></i>
                        <h3>Koi customer nahi mila</h3>
                        <p>Filter badlein ya naya customer jodein.</p>
                        <button class="btn-primary" onclick="openCustomerModal()"><i data-lucide="plus"></i> Naya Customer</button>
                    </div>
                </td>
            </tr>
        `;
        renderUniversalPaginationUI({
            containerId: 'custPagination',
            infoId: 'custPaginationInfo',
            currentPage: 1,
            pageSize: custPageSize,
            totalItems: 0,
            onPageChangeFnName: 'changeCustPage'
        });
        lucide.createIcons();
        return;
    }

    const totalCustPages = Math.ceil(totalCust / custPageSize) || 1;
    if (custCurrentPage > totalCustPages) custCurrentPage = totalCustPages;
    if (custCurrentPage < 1) custCurrentPage = 1;

    const startIdx = (custCurrentPage - 1) * custPageSize;
    const pagedList = list.slice(startIdx, startIdx + custPageSize);

    tbody.innerHTML = pagedList.map(c => {
        const bal = parseFloat(c.CurrentBalance) || 0;
        let balBadge = '<span class="pbadge gray" style="margin-top:4px;">Barabar (Chukta)</span>';
        let amtClass = 'cell-muted';
        if (bal > 0) {
            balBadge = '<span class="badge badge-due" style="margin-top:4px; font-size:11px;">⚠️ Lena Hai (Baaki)</span>';
            amtClass = 'amt-red';
        } else if (bal < 0) {
            balBadge = '<span class="badge badge-advance" style="margin-top:4px; font-size:11px;">🟢 Dena Hai (Advance)</span>';
            amtClass = 'amt-green';
        }

        const initials = (c.CustomerName || 'C').substring(0, 2).toUpperCase();
        const isHead = c.IsFamilyHead !== false && c.IsFamilyHead !== 0;
        const famCount = c.FamilyMembersCount || 1;
        const hasFamily = famCount > 1 || !isHead || c.ParentCustomerID != null;
        const khataCount = c.TotalKhataEntries || 0;
        const billCount = c.TotalBills || 0;

        return `
            <tr class="trans-data-row cust-row">
                <td class="cell-center cell-nowrap">
                    <span class="cust-id-chip" onclick="openCustomer360Modal(${c.CustomerID})" title="Customer #${c.CustomerID} (360° Profile Dekhein)">
                        #${c.CustomerID}
                    </span>
                </td>
                <td>
                    <div class="cell-flex">
                        <div class="pavatar cust-avatar ${isHead ? 'is-head' : 'is-member'}">
                            ${escapeHtml(initials)}
                        </div>
                        <div class="cust-meta-wrap">
                            <div class="cell-title cust-name-title">
                                <span class="cust-name-link" onclick="openCustomer360Modal(${c.CustomerID})" title="Customer 360° Profile Dekhein">${escapeHtml(c.CustomerName)}</span>
                                ${isHead && famCount > 1 ? `<span class="mukhiya-badge" onclick="openFamilyModal(${c.CustomerID})" title="Parivar Mukhiya (${famCount} Sadasya)">👑 Mukhiya (${famCount})</span>` : ''}
                            </div>
                            ${!isHead ? `
                                <div class="cell-sub">
                                     <span class="pbadge purple fam-sub-badge" onclick="openFamilyModal(${c.CustomerID})" style="cursor:pointer;" title="Parivar Tree Dekhein">👨‍👩‍👧 ${escapeHtml(c.Relationship || 'Member')} • ${escapeHtml(c.ParentCustomerName || 'Mukhiya')}</span>
                                    ${c.KhataMode === 'Joint' ? '<span class="joint-khata-tag">[Joint]</span>' : ''}
                                </div>
                            ` : (famCount > 1 ? `
                                <div class="cell-sub">
                                    <span class="fam-link" onclick="openFamilyModal(${c.CustomerID})" title="Parivar Tree Dekhein">👨‍👩‍👧‍👦 ${escapeHtml(c.FamilyName || c.CustomerName + ' Parivar')} (${famCount})</span>
                                </div>
                            ` : '')}
                            ${c.GSTIN ? `<div class="cell-sub font-mono">GST: ${escapeHtml(c.GSTIN)}</div>` : ''}
                            ${c.DateOfBirth ? `<div class="cell-sub" style="font-size: 11px; color: var(--text-muted); display: flex; align-items: center; gap: 3px;">🎂 ${formatIndianDate(c.DateOfBirth)}</div>` : ''}
                            ${c.Notes ? `<div class="cell-sub" style="font-size: 11px; color: #a78bfa; display: flex; align-items: center; gap: 3px;" title="${escapeHtml(c.Notes)}">📝 ${escapeHtml(c.Notes.substring(0, 26))}${c.Notes.length > 26 ? '...' : ''}</div>` : ''}
                            ${c.CreditLimit && Number(c.CreditLimit) > 0 ? `<div class="cell-sub font-mono" style="font-size: 10.5px; color: #38bdf8;">💳 Limit: ₹${Number(c.CreditLimit).toLocaleString('en-IN')}</div>` : ''}
                        </div>
                    </div>
                </td>
                <td>
                    ${c.Phone ? renderPhoneWithCopy(c.Phone, { showIcon: false, fontSize: '12.5px' }) : '<span class="cell-muted">—</span>'}
                </td>
                <td>
                    ${c.AadhaarNumber ? renderAadhaarWithEye(c.AadhaarNumber, { fontSize: '11.5px', color: '#10b981' }) : '<span class="cell-muted" style="font-size:11px;">—</span>'}
                </td>
                <td>
                    ${c.Address ? `
                        <span class="cust-pata-cell" title="${escapeHtml(c.Address)}">
                            <i data-lucide="map-pin" width="12" height="12"></i>
                            <span class="pata-text">${escapeHtml(c.Address)}</span>
                        </span>
                    ` : '<span class="cell-muted">—</span>'}
                </td>
                <td class="cell-center cell-nowrap">
                    <div class="cust-khata-stats">
                        <span class="khata-stat-pill ${khataCount > 0 ? 'active-khata' : ''}" onclick="goToCustomerKhata(${c.CustomerID})" title="${khataCount} Khata entries (Khata Book Kholein)">
                            <i data-lucide="book-open" width="11" height="11"></i>
                            <span>${khataCount} Entry</span>
                        </span>
                        <span class="khata-stat-pill ${billCount > 0 ? 'active-bill' : ''}" onclick="openCustomerBills(${c.CustomerID})" title="${billCount} Bills (Bills Dekhein)">
                            <i data-lucide="receipt" width="11" height="11"></i>
                            <span>${billCount} Bill</span>
                        </span>
                    </div>
                </td>
                <td class="cell-right">
                    <div class="cell-amount c360-num ${amtClass}">${bal > 0 ? '− ' : (bal < 0 ? '+ ' : '')}${formatMoney(Math.abs(bal))}</div>
                    ${balBadge}
                </td>
                <td class="cell-center cell-nowrap">
                    <div class="cust-action-cell">
                        <button type="button" class="cust-quick-btn" onclick="openCustomer360Modal(${c.CustomerID})" title="360° Profile Dekhein">
                            <i data-lucide="eye" width="14" height="14"></i>
                        </button>
                        <button type="button" class="cust-menu-trigger-btn" onclick="toggleCustActionMenu(event, ${c.CustomerID})" title="Sabhi Kriya (Actions Menu)">
                            <i data-lucide="more-vertical" width="16" height="16"></i>
                        </button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');

    renderUniversalPaginationUI({
        containerId: 'custPagination',
        infoId: 'custPaginationInfo',
        currentPage: custCurrentPage,
        pageSize: custPageSize,
        totalItems: totalCust,
        onPageChangeFnName: 'changeCustPage'
    });

    lucide.createIcons();
}

// --------------------------------------------------------------------------
// FLOATING 3-DOT ACTION MENU FOR CUSTOMERS (Modern Responsive Popover)
// --------------------------------------------------------------------------
let activeCustDropdownId = null;

function toggleCustActionMenu(e, customerId) {
    if (e) {
        e.preventDefault();
        e.stopPropagation();
    }

    const existingMenu = document.getElementById('custFloatingActionMenu');
    if (existingMenu && activeCustDropdownId === customerId) {
        closeCustActionMenu();
        return;
    }

    closeCustActionMenu();

    const cust = (allCustomersData || []).find(c => Number(c.CustomerID) === Number(customerId));
    if (!cust) return;

    const triggerBtn = (e && e.currentTarget) ? e.currentTarget : (e && e.target ? e.target.closest('.cust-menu-trigger-btn') : null);
    if (!triggerBtn) return;

    triggerBtn.classList.add('active');
    activeCustDropdownId = customerId;

    const isHead = cust.IsFamilyHead !== false && cust.IsFamilyHead !== 0;
    const famCount = cust.FamilyMembersCount || 1;
    const hasFamily = famCount > 1 || !isHead || cust.ParentCustomerID != null;

    const menu = document.createElement('div');
    menu.id = 'custFloatingActionMenu';
    menu.className = 'cust-action-dropdown-menu';

    menu.innerHTML = `
        <div class="cad-header">
            <div class="cad-title-row">
                <span class="cad-name" title="${escapeHtml(cust.CustomerName)}">${escapeHtml(cust.CustomerName)}</span>
                <span class="cad-id font-mono">#${cust.CustomerID}</span>
            </div>
            ${cust.Phone ? `<div class="cad-phone font-mono">📞 ${escapeHtml(cust.Phone)}</div>` : ''}
        </div>
        <div class="cad-items">
            <button type="button" class="cad-item" id="cadOptProfile">
                <span class="cad-icon blue"><i data-lucide="eye"></i></span>
                <div class="cad-label">
                    <span class="cad-primary">Customer 360° Profile</span>
                    <span class="cad-secondary">Poora hisaab, dastavej &amp; summary</span>
                </div>
            </button>
            <button type="button" class="cad-item" id="cadOptKhata">
                <span class="cad-icon green"><i data-lucide="book-open"></i></span>
                <div class="cad-label">
                    <span class="cad-primary">Khata Book (खाता खोलें)</span>
                    <span class="cad-secondary">Len-Den entries &amp; bakiya ledger</span>
                </div>
            </button>
            <button type="button" class="cad-item" id="cadOptBill">
                <span class="cad-icon indigo"><i data-lucide="receipt"></i></span>
                <div class="cad-label">
                    <span class="cad-primary">Naya Bill Banayein</span>
                    <span class="cad-secondary">Customer ke naam invoice banayein</span>
                </div>
            </button>
            <button type="button" class="cad-item" id="cadOptDocs">
                <span class="cad-icon orange"><i data-lucide="paperclip"></i></span>
                <div class="cad-label">
                    <span class="cad-primary">Dastavej (Documents / KYC)</span>
                    <span class="cad-secondary">Aadhaar, PAN &amp; files upload/dekhein</span>
                </div>
            </button>
            ${hasFamily ? `
            <button type="button" class="cad-item" id="cadOptFamily">
                <span class="cad-icon purple"><i data-lucide="users"></i></span>
                <div class="cad-label">
                    <span class="cad-primary">Parivar Tree (Family)</span>
                    <span class="cad-secondary">Parivar sadasya &amp; joint khata</span>
                </div>
            </button>` : ''}
            <button type="button" class="cad-item" id="cadOptEdit">
                <span class="cad-icon cyan"><i data-lucide="edit-3"></i></span>
                <div class="cad-label">
                    <span class="cad-primary">Edit Details</span>
                    <span class="cad-secondary">Naam, phone, pata update karein</span>
                </div>
            </button>
            <div class="cad-divider"></div>
            <button type="button" class="cad-item danger" id="cadOptDelete">
                <span class="cad-icon red"><i data-lucide="trash-2"></i></span>
                <div class="cad-label">
                    <span class="cad-primary text-danger">Grahak Delete Karein</span>
                    <span class="cad-secondary">Customer ko system se hatayein</span>
                </div>
            </button>
        </div>
    `;

    // Direct event bindings
    menu.querySelector('#cadOptProfile')?.addEventListener('click', () => {
        closeCustActionMenu();
        openCustomer360Modal(cust.CustomerID);
    });
    menu.querySelector('#cadOptKhata')?.addEventListener('click', () => {
        closeCustActionMenu();
        goToCustomerKhata(cust.CustomerID);
    });
    menu.querySelector('#cadOptBill')?.addEventListener('click', () => {
        closeCustActionMenu();
        createBillForCustomer(cust.CustomerID);
    });
    menu.querySelector('#cadOptDocs')?.addEventListener('click', () => {
        closeCustActionMenu();
        openCustomerDocsModal(cust.CustomerID, cust.CustomerName || '');
    });
    menu.querySelector('#cadOptFamily')?.addEventListener('click', () => {
        closeCustActionMenu();
        openFamilyModal(cust.CustomerID);
    });
    menu.querySelector('#cadOptEdit')?.addEventListener('click', () => {
        closeCustActionMenu();
        openCustomerModal(cust.CustomerID);
    });
    menu.querySelector('#cadOptDelete')?.addEventListener('click', () => {
        closeCustActionMenu();
        confirmDeleteCustomer(cust.CustomerID, cust.CustomerName || '');
    });

    positionFloatingMenu(menu, triggerBtn, 270);
}

function closeCustActionMenu() {
    activeCustDropdownId = null;
    document.querySelectorAll('.cust-menu-trigger-btn.active').forEach(b => b.classList.remove('active'));
    const m = document.getElementById('custFloatingActionMenu');
    if (m) {
        m.classList.remove('active');
        m.remove();
    }
}
window.toggleCustActionMenu = toggleCustActionMenu;
window.closeCustActionMenu = closeCustActionMenu;

// Global listeners for action menu dismissal across all modules
document.addEventListener('click', (e) => {
    if (!e.target.closest('.cust-action-dropdown-menu') &&
        !e.target.closest('.table-menu-trigger-btn') &&
        !e.target.closest('.cust-menu-trigger-btn') &&
        !e.target.closest('.party-menu-trigger-btn') &&
        !e.target.closest('.csc-menu-trigger-btn') &&
        !e.target.closest('.inv-menu-trigger-btn') &&
        !e.target.closest('.bc-menu-trigger-btn') &&
        !e.target.closest('.acc-menu-trigger-btn') &&
        !e.target.closest('.trans-menu-trigger-btn') &&
        !e.target.closest('.doc-menu-trigger-btn')) {
        closeAllActionMenus();
    }
});
window.addEventListener('scroll', () => {
    closeAllActionMenus();
}, true);
document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
        closeAllActionMenus();
    }
});

function populateCustomerDropdowns() {
    const selects = ['invCustomerSelect', 'khataCustomerSelect', 'bcCustomerSelect', 'docCustomerSelect', 'docCustomerFilter', 'cscCustomerSelect', 'bpCustomerSelect'];
    selects.forEach(id => {
        const el = document.getElementById(id);
        if (!el) return;
        const cur = el._ssInstance ? el.value : el.value;
        let defaultText = '-- Customer Select Karein --';
        if (id === 'bcCustomerSelect') defaultText = '-- Registered Customer select karein (Auto Fill Name, Phone, Aadhaar) --';
        if (id === 'bpCustomerSelect') defaultText = '-- Registered Customer select karein (Auto Fill Name, Phone) --';
        if (id === 'docCustomerSelect') defaultText = '🏪 Shop Document (koi customer nahi)';
        if (id === 'docCustomerFilter') defaultText = 'Sab Customers + Shop';
        if (id === 'cscCustomerSelect') defaultText = '-- Direct Naya / Walk-in Customer --';

        let html = `<option value="">${defaultText}</option>`;
        if (id === 'docCustomerFilter') {
            html += `<option value="shop">🏪 Sirf Shop Documents</option>`;
        }

        const isDocFilter = id === 'docCustomerFilter';
        const opts = (allCustomersData || []).map(c => {
            const bal = parseFloat(c.CurrentBalance) || 0;
            const balStr = bal > 0 ? ` [Baqi Lena: ${formatMoney(bal)}]` : (bal < 0 ? ` [Advance Jama: ${formatMoney(Math.abs(bal))}]` : '');
            const isHead = c.IsFamilyHead !== false && c.IsFamilyHead !== 0;
            const relStr = !isHead && c.ParentCustomerName ? ` (${escapeHtml(c.Relationship || 'Member')} of ${escapeHtml(c.ParentCustomerName)})` : '';
            const rawAadhaar = (c.AadhaarNumber || '').toString();
            const cleanAadhaar = rawAadhaar.replace(/\D/g, '');
            const cleanPhone = (c.Phone || '').toString().replace(/\D/g, '');
            const formattedAadhaar = cleanAadhaar ? formatAadhaarDisplay(cleanAadhaar) : '';
            const uidStr = cleanAadhaar ? ` [UID: ${escapeHtml(cleanAadhaar.slice(-4))}]` : '';
            const idBadge = `[#${c.CustomerID}] `;
            const label = isDocFilter
                ? `${idBadge}👤 ${escapeHtml(c.CustomerName)}${c.Phone ? ' (' + escapeHtml(c.Phone) + ')' : ''}${uidStr}`
                : `${idBadge}${escapeHtml(c.CustomerName)}${relStr}${c.Phone ? ' - ' + escapeHtml(c.Phone) : ''}${uidStr}${balStr}`;
            const searchData = `${escapeHtml(c.CustomerName)} ${c.Phone || ''} ${cleanAadhaar} ${formattedAadhaar} ${c.CustomerID} ${c.ParentCustomerName || ''}`;
            return `<option value="${c.CustomerID}" data-aadhaar="${cleanAadhaar}" data-phone="${cleanPhone}" data-search="${searchData}" ${cur == c.CustomerID ? 'selected' : ''}>${label}</option>`;
        }).join('');

        el.innerHTML = html + opts;

        if (el._ssInstance) {
            el._ssInstance.refresh();
        } else if (window.SearchableSelect && (el.classList.contains('searchable-select') || el.getAttribute('data-searchable') === 'true')) {
            new SearchableSelect(el);
        }
    });

    if (window.initAllSearchableSelects) {
        window.initAllSearchableSelects();
    }
}

function onBPCustomerSelectChange() {
    const sel = document.getElementById('bpCustomerSelect');
    if (!sel || !sel.value) {
        if (typeof renderUniversalDueAlert === 'function') renderUniversalDueAlert(null, 'bpDueAlertContainer', 'BP');
        return;
    }
    const custId = parseInt(sel.value);
    const cust = (typeof allCustomersData !== 'undefined' && Array.isArray(allCustomersData))
        ? allCustomersData.find(c => c.CustomerID === custId)
        : null;
    if (cust) {
        applyCustomerToForm(cust, {
            nameId: 'bpModalCustName',
            phoneId: 'bpModalCustPhone',
            chipId: 'bpPhoneChip'
        });
        if (typeof renderUniversalDueAlert === 'function') {
            renderUniversalDueAlert(cust, 'bpDueAlertContainer', 'BP');
        }
        calculateBPProfitInModal();
    } else {
        if (typeof renderUniversalDueAlert === 'function') renderUniversalDueAlert(null, 'bpDueAlertContainer', 'BP');
    }
}
window.onBPCustomerSelectChange = onBPCustomerSelectChange;

let aadhaarCheckDebounceTimer = null;

function formatAadhaarDisplay(val) {
    if (!val) return '';
    const digits = val.toString().replace(/\D/g, '').slice(0, 12);
    const parts = [];
    for (let i = 0; i < digits.length; i += 4) {
        parts.push(digits.substring(i, i + 4));
    }
    return parts.join(' ');
}

function formatAadhaarInput(el) {
    if (!el) return;
    const raw = el.value.replace(/\D/g, '').slice(0, 12);
    let formatted = '';
    for (let i = 0; i < raw.length; i += 4) {
        if (i > 0) formatted += ' ';
        formatted += raw.substring(i, i + 4);
    }
    el.value = formatted;
}

// ============ SHARED: APPLY A CUSTOMER OBJECT TO A FORM ============
// Kisi bhi customer record ke fields ko form me bhar deta hai (naam, phone, id,
// dropdown, aadhaar, dob, badge). Aadhaar aur Phone dono auto-fill isi ko use karte hain.
function applyCustomerToForm(cust, opts) {
    if (!cust) return;
    if (opts.nameId) {
        const el = document.getElementById(opts.nameId);
        if (el) el.value = cust.CustomerName || '';
    }
    if (opts.phoneId) {
        const el = document.getElementById(opts.phoneId);
        if (el) el.value = cust.Phone || '';
    }
    if (opts.customerIdId) {
        const el = document.getElementById(opts.customerIdId);
        if (el) el.value = cust.CustomerID || '';
    }
    // Aadhaar field (agar form me hai aur customer ke paas aadhaar hai)
    if (opts.aadhaarId) {
        const el = document.getElementById(opts.aadhaarId);
        if (el && cust.AadhaarNumber) el.value = formatAadhaarDisplay(cust.AadhaarNumber);
    }
    // Date of Birth (DOB) field (agar form me hai)
    const dobId = opts.dobId || (opts.nameId === 'bcCustomerName' ? 'bcCustomerDob' : (opts.nameId === 'cscCustName' ? 'cscCustDob' : null));
    const rawDob = cust.DateOfBirth || cust.DOB || cust.CustomerDateOfBirth;
    if (dobId) {
        const dobEl = document.getElementById(dobId);
        if (dobEl) {
            dobEl.value = rawDob ? String(rawDob).split('T')[0] : '';
        }
    }
    // DOB Chip
    const dobChipId = opts.dobChipId || (opts.nameId === 'bcCustomerName' ? 'bcDobChip' : null);
    if (dobChipId) {
        const dobChip = document.getElementById(dobChipId);
        if (dobChip) {
            if (rawDob) {
                const dobClean = String(rawDob).split('T')[0];
                dobChip.innerHTML = `<span class="badge" style="background: rgba(16, 185, 129, 0.15); color: #10b981; font-size: 10px; margin-left: 6px;">🎂 ${typeof formatDateDisplay === 'function' ? formatDateDisplay(dobClean) : dobClean}</span>`;
            } else {
                dobChip.innerHTML = '';
            }
        }
    }
    // Customer dropdown ko us customer pe set karo (agar maujood hai)
    if (opts.customerSelectId) {
        const sel = document.getElementById(opts.customerSelectId);
        if (sel) {
            let opt = sel.querySelector(`option[value="${cust.CustomerID}"]`);
            if (!opt && cust.CustomerID) {
                opt = document.createElement('option');
                opt.value = cust.CustomerID;
                const uStr = cust.AadhaarNumber ? (' [UID: ' + String(cust.AadhaarNumber).replace(/\D/g, '').slice(-4) + ']') : '';
                opt.textContent = `[#${cust.CustomerID}] ${cust.CustomerName}${cust.Phone ? ' - ' + cust.Phone : ''}${uStr}`;
                sel.appendChild(opt);
                if (sel._ssInstance && typeof sel._ssInstance.refresh === 'function') {
                    sel._ssInstance.refresh();
                }
            }
            sel.value = String(cust.CustomerID);
            if (sel._ssInstance && typeof sel._ssInstance.syncFromNative === 'function') {
                sel._ssInstance.syncFromNative();
            }
        }
    }
    // Success badge
    const chip = opts.chipId ? document.getElementById(opts.chipId) : null;
    if (chip) {
        chip.innerHTML = `<span class="badge" style="background: rgba(16, 185, 129, 0.15); color: #10b981; font-size: 10px; margin-left: 6px; white-space: nowrap;" title="Registered customer mila — details auto-fill ho gaye">✅ Auto-Fill: ${escapeHtml(cust.CustomerName)} (#${cust.CustomerID})</span>`;
        if (typeof lucide !== 'undefined' && lucide.createIcons) lucide.createIcons();
    }
    // Documents badge update for BC Entry
    if (opts.nameId === 'bcCustomerName' && typeof updateCustomerDocBadge === 'function') {
        updateCustomerDocBadge('bcCustomerDocBadge', cust.CustomerID, cust.CustomerName);
    }

    // Universal Due Alert auto-trigger
    if (typeof renderUniversalDueAlert === 'function') {
        if (opts.nameId === 'bpModalCustName') {
            renderUniversalDueAlert(cust, 'bpDueAlertContainer', 'BP');
        } else if (opts.nameId === 'cscCustName') {
            renderUniversalDueAlert(cust, 'cscDueAlertContainer', 'CSC');
        } else if (opts.nameId === 'bcCustomerName') {
            renderUniversalDueAlert(cust, 'bcDueAlertContainer', 'BC');
        }
    }
}

// ============ UNIVERSAL AADHAAR → CUSTOMER AUTO-FILL ============
// Jab kisi bhi nayi entry form (CSC / BC) me 12-digit Aadhaar bhala jaye jo pehle se
// kisi registered customer ke paas hai, to us customer ki details (Naam, Phone, DOB, ID)
// aur customer-dropdown khud-ba-khud bhar jayein. Aadhaar unique hota hai, isliye
// match milne par canonical customer ki info dikhana hi sabse sahi hai.
const _aadhaarAutoFillTimers = {};

function autoFillCustomerFromAadhaar(opts) {
    // opts: { inputId, nameId, phoneId, dobId, dobChipId, customerIdId, customerSelectId, chipId }
    const input = document.getElementById(opts.inputId);
    if (!input) return;

    // Purana debounce clear karo (per-field)
    if (_aadhaarAutoFillTimers[opts.inputId]) clearTimeout(_aadhaarAutoFillTimers[opts.inputId]);

    const digits = (input.value || '').replace(/\D/g, '');
    const chip = opts.chipId ? document.getElementById(opts.chipId) : null;

    // 12 digit poore hone tak wait karo; kam ho to chip saaf kar do
    if (digits.length !== 12) {
        if (chip) chip.innerHTML = '';
        input._matchedCustId = null;
        if (opts.phoneId) {
            const p = document.getElementById(opts.phoneId);
            if (p) p._matchedByAadhaar = null;
        }
        return;
    }

    // 1. INSTANT LOCAL LOOKUP: agar allCustomersData me customer hai to bina delay auto-fill ho jaye!
    if (typeof allCustomersData !== 'undefined' && Array.isArray(allCustomersData) && allCustomersData.length > 0) {
        const localCust = allCustomersData.find(c => {
            if (!c || !c.AadhaarNumber) return false;
            return String(c.AadhaarNumber).replace(/\D/g, '') === digits;
        });
        if (localCust) {
            applyCustomerToForm(localCust, opts);
            input._matchedCustId = localCust.CustomerID;
            if (opts.phoneId) {
                const p = document.getElementById(opts.phoneId);
                if (p) p._matchedByAadhaar = localCust.CustomerID;
            }
        }
    }

    // 2. SERVER VERIFY / FETCH: theek 12 digits par hi database se check karein
    _aadhaarAutoFillTimers[opts.inputId] = setTimeout(async () => {
        try {
            const res = await fetch(`${API}/customers/check-aadhaar?aadhaar=${encodeURIComponent(digits)}`);
            const data = await res.json();
            if (!data || !data.success) return;

            if (data.exists && data.customer) {
                // Pehle se darj customer mila — form auto-fill karein (Aadhaar has TOP priority)
                applyCustomerToForm(data.customer, opts);
                input._matchedCustId = data.customer.CustomerID;
                if (opts.phoneId) {
                    const p = document.getElementById(opts.phoneId);
                    if (p) p._matchedByAadhaar = data.customer.CustomerID;
                }
            } else {
                input._matchedCustId = null;
                if (opts.phoneId) {
                    const p = document.getElementById(opts.phoneId);
                    if (p) p._matchedByAadhaar = null;
                }
                if (chip) {
                    chip.innerHTML = `<span class="badge" title="Save karne par auto-register ho jayega" style="background: rgba(37, 99, 235, 0.12); color: #2563eb; font-weight: 700; font-size: 10px; padding: 1.5px 6px; border-radius: 4px; border: 1px solid rgba(37, 99, 235, 0.25); white-space: nowrap;">🆕 Naya Aadhaar</span>`;
                }
            }
        } catch (e) {
            console.error('Aadhaar auto-fill error:', e);
        }
    }, 200);
}

