// ============ UNIVERSAL CLIPBOARD COPY SYSTEM ============
function copyTextToClipboard(text, label = 'Content', triggerBtn = null) {
    if (!text) return;
    const onSuccess = () => {
        showToast(`${label} clipboard me copy ho gaya!`, 'success');
        if (triggerBtn) {
            const origHtml = triggerBtn.innerHTML;
            triggerBtn.classList.add('copied');
            triggerBtn.innerHTML = '<i data-lucide="check" width="11" height="11" style="color: #10b981;"></i>';
            if (typeof lucide !== 'undefined' && lucide.createIcons) {
                try { lucide.createIcons({ root: triggerBtn }); } catch (e) { }
            }
            setTimeout(() => {
                triggerBtn.classList.remove('copied');
                triggerBtn.innerHTML = origHtml;
                if (typeof lucide !== 'undefined' && lucide.createIcons) {
                    try { lucide.createIcons({ root: triggerBtn }); } catch (e) { }
                }
            }, 1500);
        }
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(onSuccess).catch(() => {
            legacyCopy(text, label, triggerBtn);
        });
    } else {
        legacyCopy(text, label, triggerBtn);
    }
}

function legacyCopy(text, label, triggerBtn = null) {
    try {
        const t = document.createElement('textarea');
        t.value = text;
        t.style.position = 'fixed';
        t.style.opacity = '0';
        document.body.appendChild(t);
        t.select();
        document.execCommand('copy');
        document.body.removeChild(t);
        showToast(`${label} copy ho gaya!`, 'success');
        if (triggerBtn) {
            const origHtml = triggerBtn.innerHTML;
            triggerBtn.classList.add('copied');
            triggerBtn.innerHTML = '<i data-lucide="check" width="11" height="11" style="color: #10b981;"></i>';
            if (typeof lucide !== 'undefined' && lucide.createIcons) {
                try { lucide.createIcons({ root: triggerBtn }); } catch (e) { }
            }
            setTimeout(() => {
                triggerBtn.classList.remove('copied');
                triggerBtn.innerHTML = origHtml;
                if (typeof lucide !== 'undefined' && lucide.createIcons) {
                    try { lucide.createIcons({ root: triggerBtn }); } catch (e) { }
                }
            }, 1500);
        }
    } catch (e) {
        showToast('Copy nahi ho paya: ' + e.message, 'error');
    }
}

// Universal Copy for Aadhaar — BINA SPACE KE (Strictly pure digits, no spaces)
function copyAadhaarToClipboard(aadhaar, evt) {
    if (evt) {
        if (typeof evt.stopPropagation === 'function') evt.stopPropagation();
        if (typeof evt.preventDefault === 'function') evt.preventDefault();
    }
    const triggerBtn = (evt && (evt.currentTarget || evt.target)) ? (evt.currentTarget || evt.target).closest('button') : null;
    if (!aadhaar) {
        showToast('Aadhaar number uplabdh nahi hai', 'warning');
        return;
    }
    // CRITICAL: Aadhaar copy bina space ke ho (Only pure digits, no spaces)
    const cleanDigits = String(aadhaar).replace(/\D/g, '');
    if (!cleanDigits) {
        showToast('Aadhaar number sahi nahi hai', 'error');
        return;
    }
    copyTextToClipboard(cleanDigits, 'Aadhaar number (bina space ke)', triggerBtn);
}

// Universal Copy for Customer Mobile
function copyPhoneToClipboard(phone, evt) {
    if (evt) {
        if (typeof evt.stopPropagation === 'function') evt.stopPropagation();
        if (typeof evt.preventDefault === 'function') evt.preventDefault();
    }
    const triggerBtn = (evt && (evt.currentTarget || evt.target)) ? (evt.currentTarget || evt.target).closest('button') : null;
    if (!phone) {
        showToast('Mobile number uplabdh nahi hai', 'warning');
        return;
    }
    let clean = String(phone).replace(/\D/g, '');
    if (clean.length === 12 && clean.startsWith('91')) {
        clean = clean.slice(-10);
    } else if (clean.length === 11 && clean.startsWith('0')) {
        clean = clean.slice(-10);
    }
    if (!clean) clean = String(phone).trim();
    copyTextToClipboard(clean, 'Mobile number', triggerBtn);
}

// Universal Copy for Customer Date of Birth (DOB)
function copyDOBToClipboard(dob, evt) {
    if (evt) {
        if (typeof evt.stopPropagation === 'function') evt.stopPropagation();
        if (typeof evt.preventDefault === 'function') evt.preventDefault();
    }
    const triggerBtn = (evt && (evt.currentTarget || evt.target)) ? (evt.currentTarget || evt.target).closest('button') : null;
    if (!dob) {
        showToast('Date of Birth uplabdh nahi hai', 'warning');
        return;
    }
    let raw = Array.isArray(dob) ? dob[0] : dob;
    let cleanDob = String(raw).trim();
    if (cleanDob.includes('T')) cleanDob = cleanDob.split('T')[0];
    if (/^\d{4}-\d{2}-\d{2}$/.test(cleanDob)) {
        const parts = cleanDob.split('-');
        cleanDob = `${parts[2]}/${parts[1]}/${parts[0]}`;
    }
    copyTextToClipboard(cleanDob, `Date of Birth (${cleanDob})`, triggerBtn);
}

// Reusable Phone Renderer with Copy Option
function renderPhoneWithCopy(phone, options = {}) {
    if (!phone) return options.fallback || '<span class="cell-muted">—</span>';
    const cleanDigits = String(phone).replace(/\D/g, '');
    let pure10 = cleanDigits;
    if (pure10.length === 12 && pure10.startsWith('91')) pure10 = pure10.slice(-10);
    else if (pure10.length === 11 && pure10.startsWith('0')) pure10 = pure10.slice(-10);

    const displayPhone = escapeHtml(phone);
    const fontSize = options.fontSize || 'inherit';
    const color = options.color || 'inherit';
    const showWhatsApp = options.showWhatsApp !== false;
    const showIcon = options.showIcon !== false;
    const showText = options.showText !== false;
    const extraClass = options.extraClass || '';
    const waPhone = pure10.length === 10 ? '91' + pure10 : cleanDigits;

    return `
        <span class="phone-copy-wrap ${extraClass}" style="display: inline-flex; align-items: center; gap: 4px; font-size: ${fontSize}; color: ${color}; vertical-align: middle;">
            ${showIcon ? '<span class="phone-icon" style="opacity: 0.85;">📞</span>' : ''}
            ${showText ? `<span class="phone-val-text font-mono">${displayPhone}</span>` : ''}
            <button type="button" class="phone-copy-btn" tabindex="-1" data-copy-phone="${escapeHtml(phone)}" title="Mobile number copy karein">
                <i data-lucide="copy" width="11" height="11"></i>
            </button>
            ${showWhatsApp && pure10 ? `
                <a href="https://wa.me/${waPhone}" target="_blank" tabindex="-1" onclick="event.stopPropagation();" title="WhatsApp Chat" class="phone-wa-link" style="color: #22c55e; display: inline-flex; align-items: center; margin-left: 2px;">
                    <i data-lucide="message-circle" width="12" height="12"></i>
                </a>
            ` : ''}
        </span>
    `;
}

