// ============ UNIVERSAL AADHAAR REVEAL / EYE TOGGLE SYSTEM ============
function renderAadhaarWithEye(aadhaarNumber, options = {}) {
    if (!aadhaarNumber) return options.fallback || '';
    const clean = String(aadhaarNumber).replace(/\D/g, '');
    if (clean.length < 4) return `<span class="font-mono">${escapeHtml(aadhaarNumber)}</span>`;

    const last4 = clean.slice(-4);
    const fullFormatted = formatAadhaarDisplay(clean);
    const maskedFormatted = clean.length >= 8 ? `**** **** ${last4}` : `****${last4}`;
    const id = 'aadh_' + Math.random().toString(36).substring(2, 9);
    const fontSize = options.fontSize || '12px';
    const color = options.color || 'inherit';
    const showLabel = options.showLabel !== false;
    const showCopy = options.showCopy !== false;

    return `
        <span class="aadhaar-reveal-wrap" id="${id}" style="font-size: ${fontSize}; color: ${color};">
            ${showLabel ? '<span class="aadhaar-icon" style="opacity: 0.85;">🪪</span>' : ''}
            <span class="aadhaar-val-text font-mono" data-masked="${maskedFormatted}" data-full="${fullFormatted}" data-raw="${clean}" data-state="masked">${maskedFormatted}</span>
            <button type="button" class="aadhaar-eye-btn" tabindex="-1" onclick="toggleAadhaarEye('${id}', event)" title="Poora Aadhaar number dekhein">
                <i data-lucide="eye" width="11" height="11"></i>
            </button>
            ${showCopy ? `
                <button type="button" class="aadhaar-copy-btn" tabindex="-1" data-copy-aadhaar="${clean}" title="Aadhaar number copy karein (bina space ke)">
                    <i data-lucide="copy" width="11" height="11"></i>
                </button>
            ` : ''}
        </span>
    `;
}

function toggleAadhaarEye(wrapId, evt) {
    if (evt) {
        if (typeof evt.stopPropagation === 'function') evt.stopPropagation();
        if (typeof evt.preventDefault === 'function') evt.preventDefault();
    }
    const wrap = document.getElementById(wrapId);
    if (!wrap) return;
    const textEl = wrap.querySelector('.aadhaar-val-text');
    const btn = wrap.querySelector('.aadhaar-eye-btn');
    if (!textEl) return;

    const isMasked = textEl.getAttribute('data-state') === 'masked';
    if (isMasked) {
        textEl.textContent = textEl.getAttribute('data-full');
        textEl.setAttribute('data-state', 'full');
        textEl.style.fontWeight = '800';
        textEl.style.letterSpacing = '0.5px';
        if (btn) {
            btn.classList.add('active');
            btn.innerHTML = '<i data-lucide="eye-off" width="11" height="11"></i>';
            btn.title = 'Aadhaar number chhipayein (Mask karein)';
        }
    } else {
        textEl.textContent = textEl.getAttribute('data-masked');
        textEl.setAttribute('data-state', 'masked');
        textEl.style.fontWeight = 'normal';
        textEl.style.letterSpacing = 'normal';
        if (btn) {
            btn.classList.remove('active');
            btn.innerHTML = '<i data-lucide="eye" width="11" height="11"></i>';
            btn.title = 'Poora Aadhaar number dekhein';
        }
    }
    if (typeof refreshIcons === 'function') {
        refreshIcons(wrap);
    } else if (typeof lucide !== 'undefined' && lucide.createIcons) {
        try { lucide.createIcons({ root: wrap }); } catch (e) { }
    }
}

// ============ UNIVERSAL DATE OF BIRTH (DOB) REVEAL / EYE TOGGLE SYSTEM ============
function renderDOBWithEye(dobStr, options = {}) {
    if (!dobStr) return options.fallback || '<span style="color:#64748b; font-size: 14px; font-weight: 500;">Darj nahi hai</span>';

    let raw = Array.isArray(dobStr) ? dobStr[0] : dobStr;
    if (!raw) return options.fallback || '<span style="color:#64748b; font-size: 14px; font-weight: 500;">Darj nahi hai</span>';

    raw = String(raw).trim();
    if (raw.includes('T')) raw = raw.split('T')[0];

    let yyyy = '', mm = '', dd = '';
    if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) {
        const parts = raw.split('-');
        yyyy = parts[0];
        mm = parts[1];
        dd = parts[2];
    } else if (/^\d{2}\/\d{2}\/\d{4}$/.test(raw)) {
        const parts = raw.split('/');
        dd = parts[0];
        mm = parts[1];
        yyyy = parts[2];
    } else if (/^\d{2}-\d{2}-\d{4}$/.test(raw)) {
        const parts = raw.split('-');
        dd = parts[0];
        mm = parts[1];
        yyyy = parts[2];
    } else {
        const parsed = (typeof parseApiDate === 'function') ? parseApiDate(raw) : new Date(raw);
        if (parsed && !isNaN(parsed.getTime())) {
            yyyy = String(parsed.getFullYear());
            mm = String(parsed.getMonth() + 1).padStart(2, '0');
            dd = String(parsed.getDate()).padStart(2, '0');
        } else {
            return `<span class="font-mono">${escapeHtml(raw)}</span>`;
        }
    }

    const fullFormatted = `${dd}/${mm}/${yyyy}`;
    // Masked format: ••/••/YYYY or **/**/YYYY
    const maskedFormatted = options.maskAll ? '••/••/••••' : `••/••/${yyyy}`;
    const cleanYMD = `${yyyy}-${mm}-${dd}`;
    const age = (typeof computeAgeFromDob === 'function') ? computeAgeFromDob(cleanYMD) : null;
    const ageTag = age !== null ? `${age} saal` : '';

    const id = 'dob_' + Math.random().toString(36).substring(2, 9);
    const fontSize = options.fontSize || '15px';
    const color = options.color || 'inherit';
    const showLabel = options.showLabel !== false;
    const showCopy = options.showCopy !== false;
    const showAge = options.showAge !== false;

    return `
        <span class="dob-reveal-wrap" id="${id}" style="font-size: ${fontSize}; color: ${color};">
            ${showLabel ? '<span class="dob-icon" style="opacity: 0.9; margin-right: 2px;">🎂</span>' : ''}
            <span class="dob-val-text font-mono" data-masked="${maskedFormatted}" data-full="${fullFormatted}" data-raw="${cleanYMD}" data-state="masked">${maskedFormatted}</span>
            ${showAge && ageTag ? `<span class="dob-age-pill" title="Umar: ${ageTag}">${ageTag}</span>` : ''}
            <button type="button" class="dob-eye-btn" tabindex="-1" onclick="toggleDOBEye('${id}', event)" title="Poora Date of Birth dekhein">
                <i data-lucide="eye" width="11" height="11"></i>
            </button>
            ${showCopy ? `
                <button type="button" class="dob-copy-btn btn-copy-mini" tabindex="-1" data-copy-dob="${fullFormatted}" title="Date of Birth copy karein (${fullFormatted})">
                    <i data-lucide="copy" width="11" height="11"></i>
                </button>
            ` : ''}
        </span>
    `;
}

function toggleDOBEye(wrapId, evt) {
    if (evt) {
        if (typeof evt.stopPropagation === 'function') evt.stopPropagation();
        if (typeof evt.preventDefault === 'function') evt.preventDefault();
    }
    const wrap = document.getElementById(wrapId);
    if (!wrap) return;
    const textEl = wrap.querySelector('.dob-val-text');
    const btn = wrap.querySelector('.dob-eye-btn');
    if (!textEl) return;

    const isMasked = textEl.getAttribute('data-state') === 'masked';
    if (isMasked) {
        textEl.textContent = textEl.getAttribute('data-full');
        textEl.setAttribute('data-state', 'full');
        textEl.style.fontWeight = '800';
        textEl.style.letterSpacing = '0.5px';
        if (btn) {
            btn.classList.add('active');
            btn.innerHTML = '<i data-lucide="eye-off" width="11" height="11"></i>';
            btn.title = 'Date of Birth chhipayein (Mask karein)';
        }
    } else {
        textEl.textContent = textEl.getAttribute('data-masked');
        textEl.setAttribute('data-state', 'masked');
        textEl.style.fontWeight = 'normal';
        textEl.style.letterSpacing = 'normal';
        if (btn) {
            btn.classList.remove('active');
            btn.innerHTML = '<i data-lucide="eye" width="11" height="11"></i>';
            btn.title = 'Poora Date of Birth dekhein';
        }
    }
    if (typeof refreshIcons === 'function') {
        refreshIcons(wrap);
    } else if (typeof lucide !== 'undefined' && lucide.createIcons) {
        try { lucide.createIcons({ root: wrap }); } catch (e) { }
    }
}

function handleCustomerAadhaarChange() {
    clearTimeout(aadhaarCheckDebounceTimer);
    const input = document.getElementById('custAadhaarInput');
    const feedback = document.getElementById('custAadhaarFeedback');
    const saveBtn = document.getElementById('btnSaveCustomer');
    const custId = document.getElementById('customerIdVal')?.value;

    if (!input) return;

    const rawVal = input.value;
    const cleanDigits = rawVal.replace(/\D/g, '').slice(0, 12);

    // Auto-format with spaces (1234 5678 9012)
    const formatted = formatAadhaarDisplay(cleanDigits);
    if (input.value !== formatted) {
        input.value = formatted;
    }

    if (cleanDigits.length === 0) {
        if (feedback) feedback.style.display = 'none';
        const phoneErr = document.getElementById('custPhoneFeedback')?.textContent?.includes('Duplicate Entry Roki Gayi');
        if (saveBtn && !phoneErr) {
            saveBtn.disabled = false;
            saveBtn.style.opacity = '1';
            saveBtn.style.cursor = 'pointer';
        }
        return;
    }

    if (cleanDigits.length < 12) {
        if (feedback) feedback.style.display = 'none';
        return;
    }

    // Exactly 12 digits!
    if (feedback) {
        feedback.style.display = 'block';
        feedback.style.background = '#eff6ff';
        feedback.style.border = '1.5px solid #3b82f6';
        feedback.style.color = '#1e40af';
        feedback.innerHTML = `
            <div style="display: flex; align-items: center; gap: 6px;">
                <span class="spinner" style="width: 12px; height: 12px; border-width: 2px;"></span>
                <span style="font-size: 12px; color: #1e40af; font-weight: 600;">Database me 12-digit Aadhaar verify ho raha hai...</span>
            </div>
        `;
    }

    aadhaarCheckDebounceTimer = setTimeout(async () => {
        try {
            const res = await fetch(`${API}/customers/check-aadhaar?aadhaar=${encodeURIComponent(cleanDigits)}&excludeId=${custId || ''}`);
            const data = await res.json();
            if (!data.success) return;

            if (data.exists) {
                // Duplicate found! Turant ek prominent toast popup bhi dikhao
                // taaki user ko foran pata chale ki yeh Aadhaar pehle se kisi aur ko allot hai.
                const dup = data.customer || {};
                showToast(
                    `🚫 Yeh Aadhaar (**** **** ${cleanDigits.slice(-4)}) pehle se "${dup.CustomerName || 'kisi customer'}" (ID: #${dup.CustomerID ?? '?'}, Mobile: ${dup.Phone || 'N/A'}) ke paas darj hai. Ek Aadhaar sirf ek grahak ke saath jud sakta hai.`,
                    'error',
                    'Duplicate Aadhaar — Roka Gaya'
                );
                if (feedback) {
                    feedback.style.display = 'block';
                    feedback.style.background = '#fef2f2';
                    feedback.style.border = '1.5px solid #ef4444';
                    feedback.style.color = '#7f1d1d';
                    feedback.innerHTML = `
                        <div style="display: flex; align-items: center; gap: 8px;">
                            <i data-lucide="shield-alert" style="width: 16px; height: 16px; color: #dc2626;"></i>
                            <b style="color: #b91c1c; font-size: 13px;">🚫 Duplicate Aadhaar Roka Gaya:</b>
                        </div>
                        <div style="margin-top: 4px; font-size: 12px; color: #7f1d1d; line-height: 1.45;">
                            Yeh 12-digit Aadhaar number pehle se customer <b style="color: #991b1b;">"${escapeHtml(data.customer.CustomerName)}"</b> (ID: #${data.customer.CustomerID}, Mobile: ${escapeHtml(data.customer.Phone || 'N/A')}) ke sath darj hai! Ek Aadhaar card kisi doosre grahak ke saath multiple add nahi kiya ja sakta.
                        </div>
                    `;
                    lucide.createIcons();
                }
                if (saveBtn) {
                    saveBtn.disabled = true;
                    saveBtn.style.opacity = '0.5';
                    saveBtn.style.cursor = 'not-allowed';
                }
            } else {
                // Valid & Unique!
                if (feedback) {
                    feedback.style.display = 'block';
                    feedback.style.background = '#f0fdf4';
                    feedback.style.border = '1.5px solid #10b981';
                    feedback.style.color = '#065f46';
                    feedback.innerHTML = `
                        <div style="display: flex; align-items: center; gap: 6px;">
                            <i data-lucide="check-circle-2" style="width: 15px; height: 15px; color: #059669;"></i>
                            <span style="font-size: 12px; color: #065f46;"><b style="color: #047857;">12-Digit Aadhaar Verified:</b> Yeh Aadhaar card number bilkul unique aur valid hai.</span>
                        </div>
                    `;
                    lucide.createIcons();
                }
                const phoneErr = document.getElementById('custPhoneFeedback')?.textContent?.includes('Duplicate Entry Roki Gayi');
                if (saveBtn && !phoneErr) {
                    saveBtn.disabled = false;
                    saveBtn.style.opacity = '1';
                    saveBtn.style.cursor = 'pointer';
                }
            }
        } catch (e) {
            console.error('Aadhaar check error:', e);
        }
    }, 250);
}

function onBCCustomerSelected() {
    const sel = document.getElementById('bcCustomerSelect');
    if (!sel) return;
    const custId = parseInt(sel.value);
    const chip = document.getElementById('bcAadhaarChip');
    const dobChip = document.getElementById('bcDobChip');
    const custIdInput = document.getElementById('bcCustomerId');

    if (!custId) {
        if (custIdInput) custIdInput.value = '';
        if (chip) chip.innerHTML = '';
        if (dobChip) dobChip.innerHTML = '';
        const dobInput = document.getElementById('bcCustomerDob');
        if (dobInput) dobInput.value = '';
        const docBadge = document.getElementById('bcCustomerDocBadge');
        if (docBadge) docBadge.style.display = 'none';
        if (typeof renderUniversalDueAlert === 'function') renderUniversalDueAlert(null, 'bcDueAlertContainer', 'BC');
        return;
    }

    const c = allCustomersData.find(x => x.CustomerID === custId);
    if (!c) {
        if (typeof renderUniversalDueAlert === 'function') renderUniversalDueAlert(null, 'bcDueAlertContainer', 'BC');
        return;
    }

    if (typeof renderUniversalDueAlert === 'function') {
        renderUniversalDueAlert(c, 'bcDueAlertContainer', 'BC');
    }

    if (custIdInput) custIdInput.value = c.CustomerID;
    document.getElementById('bcCustomerName').value = c.CustomerName || '';
    document.getElementById('bcCustomerPhone').value = c.Phone || '';
    const phoneChip = document.getElementById('bcPhoneChip');
    if (phoneChip && !c.Phone) phoneChip.innerHTML = '';
    if (c.AadhaarNumber) {
        document.getElementById('bcAadhaar').value = formatAadhaarDisplay(c.AadhaarNumber);
        if (chip) {
            chip.innerHTML = `<span class="badge" style="background: rgba(16, 185, 129, 0.15); color: #10b981; font-size: 10px; margin-left: 6px;" title="Full UID: ${formatAadhaarDisplay(c.AadhaarNumber)}">🪪 UID: ${formatAadhaarDisplay(c.AadhaarNumber)}</span>`;
        }
    } else {
        if (chip) chip.innerHTML = '';
    }

    const dobInput = document.getElementById('bcCustomerDob');
    if (dobInput) {
        const dStr = c.DateOfBirth ? String(c.DateOfBirth).split('T')[0] : '';
        dobInput.value = dStr;
        if (dobChip) {
            dobChip.innerHTML = dStr ? `<span class="badge" style="background: rgba(16, 185, 129, 0.15); color: #10b981; font-size: 10px; margin-left: 6px;">🎂 ${typeof formatDateDisplay === 'function' ? formatDateDisplay(dStr) : dStr}</span>` : '';
        }
    }

    // Auto update documents badge for this customer
    if (typeof updateCustomerDocBadge === 'function') {
        updateCustomerDocBadge('bcCustomerDocBadge', c.CustomerID, c.CustomerName);
    }
}

function handleCustomerPhoneOrNameChange() {
    clearTimeout(phoneCheckDebounceTimer);
    const phoneInput = document.getElementById('custPhoneInput');
    const nameInput = document.getElementById('custNameInput');
    const feedback = document.getElementById('custPhoneFeedback');
    const famSection = document.getElementById('custFamilySection');
    const saveBtn = document.getElementById('btnSaveCustomer');
    const custId = document.getElementById('customerIdVal')?.value;

    const phone = (phoneInput?.value || '').trim();
    const name = (nameInput?.value || '').trim();

    if (!phone || phone.length < 10) {
        if (feedback) feedback.style.display = 'none';
        if (famSection) famSection.style.display = 'none';
        if (saveBtn) {
            saveBtn.disabled = false;
            saveBtn.style.opacity = '1';
            saveBtn.style.cursor = 'pointer';
        }
        return;
    }

    phoneCheckDebounceTimer = setTimeout(async () => {
        try {
            const res = await fetch(`${API}/customers/check-phone?phone=${encodeURIComponent(phone)}&name=${encodeURIComponent(name)}&excludeId=${custId || ''}`);
            const data = await res.json();
            if (!data.success) return;

            if (data.isExactDuplicate) {
                // EXACT DUPLICATE BLOCK
                feedback.style.display = 'block';
                feedback.style.background = '#fef2f2';
                feedback.style.border = '1.5px solid #ef4444';
                feedback.style.color = '#7f1d1d';
                feedback.innerHTML = `
                    <div style="display: flex; align-items: center; gap: 8px;">
                        <i data-lucide="shield-alert" style="width: 16px; height: 16px; color: #dc2626;"></i>
                        <b style="color: #b91c1c; font-size: 13px;">🚫 Duplicate Entry Roki Gayi:</b>
                    </div>
                    <div style="margin-top: 4px; font-size: 12px; color: #7f1d1d; line-height: 1.45;">
                        <b style="color: #991b1b;">"${escapeHtml(data.duplicateMember.CustomerName)}"</b> is mobile number (${data.cleanPhone}) par pehle se registered hain! Duplicate customer add nahi ho sakta.
                    </div>
                `;
                if (saveBtn) {
                    saveBtn.disabled = true;
                    saveBtn.style.opacity = '0.5';
                    saveBtn.style.cursor = 'not-allowed';
                }
                if (famSection) famSection.style.display = 'none';
                lucide.createIcons();
            } else if (data.exists && data.members.length > 0) {
                // EXISTING PHONE (FAMILY MEMBER DETECTED!)
                feedback.style.display = 'block';
                feedback.style.background = '#eff6ff';
                feedback.style.border = '1.5px solid #3b82f6';
                feedback.style.color = '#1e3a8a';

                const head = data.familyHead || data.members[0];
                feedback.innerHTML = `
                    <div style="display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 6px;">
                        <div style="display: flex; align-items: center; gap: 6px;">
                            <span style="font-size: 16px;">👨‍👩‍👧‍👦</span>
                            <b style="color: #1d4ed8; font-size: 13px;">Parivar / Kutumb Detected:</b>
                        </div>
                        <span style="font-size: 11px; background: #dbeafe; color: #1e40af; font-weight: 700; border: 1px solid #bfdbfe; padding: 2px 8px; border-radius: 12px;">${data.count} Members Linked</span>
                    </div>
                    <div style="margin-top: 4px; font-size: 12px; color: #1e293b; line-height: 1.45;">
                        Yeh mobile number <b style="color: #0f172a;">${escapeHtml(head.CustomerName)}</b> (${head.Relationship || 'Mukhiya'}) ke parivar se linked hai. Naya sadasya is parivar me add hoga.
                    </div>
                `;

                // Open & prefill Family Section
                if (famSection) famSection.style.display = 'block';
                const noticeEl = document.getElementById('custFamilyNotice');
                if (noticeEl) noticeEl.textContent = `Yeh mobile number '${head.CustomerName}' ke parivar se linked hai.`;
                const badgeEl = document.getElementById('custFamilyCountBadge');
                if (badgeEl) badgeEl.textContent = `${data.count} Sadasya Mojood`;
                const headNameEl = document.getElementById('custFamilyHeadName');
                if (headNameEl) headNameEl.value = `${head.CustomerName} (Mukhiya)`;
                const parentIdEl = document.getElementById('custParentId');
                if (parentIdEl) parentIdEl.value = head.CustomerID;
                const famIdEl = document.getElementById('custFamilyId');
                if (famIdEl) famIdEl.value = head.FamilyID || head.CustomerID;
                const relSelectEl = document.getElementById('custRelationshipSelect');
                if (relSelectEl) relSelectEl.value = 'Anya (Other)';

                if (saveBtn) {
                    saveBtn.disabled = false;
                    saveBtn.style.opacity = '1';
                    saveBtn.style.cursor = 'pointer';
                }
                lucide.createIcons();
            } else {
                // NEW PHONE
                feedback.style.display = 'block';
                feedback.style.background = '#f0fdf4';
                feedback.style.border = '1.5px solid #10b981';
                feedback.style.color = '#065f46';
                feedback.innerHTML = `
                    <div style="display: flex; align-items: center; gap: 6px;">
                        <i data-lucide="check-circle-2" style="width: 14px; height: 14px; color: #059669;"></i>
                        <span style="font-size: 12px; color: #065f46;"><b style="color: #047857;">Naya Mobile Number:</b> Naya individual customer / Parivar Mukhiya banega.</span>
                    </div>
                `;
                if (famSection) famSection.style.display = 'none';
                const parentIdEl = document.getElementById('custParentId');
                if (parentIdEl) parentIdEl.value = '';
                const famIdEl = document.getElementById('custFamilyId');
                if (famIdEl) famIdEl.value = '';

                if (saveBtn) {
                    saveBtn.disabled = false;
                    saveBtn.style.opacity = '1';
                    saveBtn.style.cursor = 'pointer';
                }
                lucide.createIcons();
            }
        } catch (e) {
            console.error('Phone check error:', e);
        }
    }, 250);
}

function toggleKhataModeExplanation() {
    const isJoint = document.querySelector('input[name="custKhataModeRadio"]:checked')?.value === 'Joint';
    const el = document.getElementById('khataModeHelpText');
    if (el) {
        el.innerHTML = isJoint
            ? '🤝 <b>Joint Family Khata:</b> Is sadasya ka sara udhaar-jama hisaab sidhe Parivar Mukhiya ke ledger khate me judega.'
            : '👤 <b>Separate Khata:</b> Inka udhaar aur jama inke naam par darz hoga, par ye ek hi parivar aur mobile se jude rahenge.';
    }
}

function openCustomerModal(id = null) {
    document.getElementById('customerIdVal').value = id || '';
    const title = document.getElementById('customerModalTitle');
    const feedback = document.getElementById('custPhoneFeedback');
    const aadhaarFeedback = document.getElementById('custAadhaarFeedback');
    const famSection = document.getElementById('custFamilySection');
    const saveBtn = document.getElementById('btnSaveCustomer');

    if (feedback) feedback.style.display = 'none';
    if (aadhaarFeedback) aadhaarFeedback.style.display = 'none';
    if (famSection) famSection.style.display = 'none';
    if (saveBtn) {
        saveBtn.disabled = false;
        saveBtn.style.opacity = '1';
        saveBtn.style.cursor = 'pointer';
    }

    const idBadge = document.getElementById('custModalIdBadge');

    if (id) {
        const c = allCustomersData.find(x => x.CustomerID === id);
        if (!c) return;
        if (title) title.textContent = `Customer Edit Karein (ID: #${c.CustomerID})`;
        if (idBadge) {
            idBadge.textContent = `ID: #${c.CustomerID}`;
            idBadge.style.display = 'inline-flex';
            idBadge.style.background = '#eff6ff';
            idBadge.style.border = '1.5px solid #93c5fd';
            idBadge.style.color = '#1d4ed8';
        }
        document.getElementById('custNameInput').value = c.CustomerName || '';
        document.getElementById('custPhoneInput').value = c.Phone || '';
        document.getElementById('custAadhaarInput').value = formatAadhaarDisplay(c.AadhaarNumber || '');
        document.getElementById('custDobInput').value = c.DateOfBirth ? String(c.DateOfBirth).split('T')[0] : '';
        document.getElementById('custEmailInput').value = c.Email || '';
        document.getElementById('custAddressInput').value = c.Address || '';
        document.getElementById('custGstinInput').value = c.GSTIN || '';
        document.getElementById('custCreditLimitInput').value = c.CreditLimit || 0;
        document.getElementById('custNotesInput').value = c.Notes || '';

        const opGrp = document.getElementById('custOpeningBalanceGroup');
        const btGrp = document.getElementById('custBalanceTypeGroup');
        if (opGrp) opGrp.style.display = 'none';
        if (btGrp) btGrp.style.display = 'none';

        // Set family fields if present
        if (!c.IsFamilyHead && c.ParentCustomerID) {
            famSection.style.display = 'block';
            document.getElementById('custFamilyHeadName').value = c.ParentCustomerName || 'Mukhiya';
            document.getElementById('custParentId').value = c.ParentCustomerID;
            document.getElementById('custFamilyId').value = c.FamilyID || c.ParentCustomerID;
            document.getElementById('custRelationshipSelect').value = c.Relationship || 'Beta (Son)';
            const khataRadio = document.querySelector(`input[name="custKhataModeRadio"][value="${c.KhataMode || 'Separate'}"]`);
            if (khataRadio) khataRadio.checked = true;
        }
    } else {
        const nextId = (allCustomersData && allCustomersData.length > 0)
            ? Math.max(...allCustomersData.map(x => x.CustomerID || 0)) + 1
            : 1;
        if (title) title.textContent = 'Naya Customer Add Karein';
        if (idBadge) {
            idBadge.textContent = `✨ Nayi ID: #${nextId}`;
            idBadge.style.display = 'inline-flex';
            idBadge.style.background = '#eff6ff';
            idBadge.style.border = '1.5px solid #93c5fd';
            idBadge.style.color = '#1d4ed8';
        }
        document.getElementById('custNameInput').value = '';
        document.getElementById('custPhoneInput').value = '';
        document.getElementById('custAadhaarInput').value = '';
        document.getElementById('custDobInput').value = '';
        document.getElementById('custEmailInput').value = '';
        document.getElementById('custAddressInput').value = '';
        document.getElementById('custGstinInput').value = '';
        document.getElementById('custOpeningInput').value = '';
        document.getElementById('custBalTypeInput').value = 'ToReceive';
        document.getElementById('custCreditLimitInput').value = '';
        document.getElementById('custNotesInput').value = '';
        document.getElementById('custParentId').value = '';
        document.getElementById('custFamilyId').value = '';
        const relSelectEl = document.getElementById('custRelationshipSelect');
        if (relSelectEl) relSelectEl.value = 'Anya (Other)';

        const opGrp = document.getElementById('custOpeningBalanceGroup');
        const btGrp = document.getElementById('custBalanceTypeGroup');
        if (opGrp) opGrp.style.display = 'block';
        if (btGrp) btGrp.style.display = 'block';
    }

    if (window.UniversalDocUploader) {
        UniversalDocUploader.init('custDocUploader', { entityType: 'customer', title: '📎 Customer Dastavej (Aadhaar, Photo, etc.)' });
        UniversalDocUploader.reset('custDocUploader');
        if (id) {
            UniversalDocUploader.loadExisting('custDocUploader', 'customer', id, id);
        }
    }

    const docBtn = document.getElementById('custModalDocBtn');
    if (id) {
        if (docBtn) {
            docBtn.style.display = 'inline-flex';
            if (typeof updateCustomerDocBadge === 'function') {
                const cObj = (typeof allCustomersData !== 'undefined' && Array.isArray(allCustomersData)) ? allCustomersData.find(x => x.CustomerID === id) : null;
                updateCustomerDocBadge('custModalDocBtn', id, cObj?.CustomerName);
            }
        }
    } else {
        if (docBtn) docBtn.style.display = 'none';
    }

    openModal('customerModal');
    const custModalBody = document.querySelector('#customerModal .modal-body');
    if (custModalBody) custModalBody.scrollTop = 0;
    lucide.createIcons();
}

async function saveCustomer() {
    const id = document.getElementById('customerIdVal').value;
    const name = document.getElementById('custNameInput').value.trim();
    if (!name) {
        showToast('Kripya customer ka naam likhein!', 'error', 'Naam Zaroori Hai');
        return;
    }

    const rawAadhaar = document.getElementById('custAadhaarInput')?.value || '';
    const cleanAadhaar = rawAadhaar.replace(/\D/g, '');
    if (cleanAadhaar && cleanAadhaar.length !== 12) {
        showToast(`Aadhaar card theek 12 anko ka hona chahiye (abhi ${cleanAadhaar.length} ank hain)!`, 'error', 'Invalid Aadhaar');
        document.getElementById('custAadhaarInput')?.focus();
        return;
    }

    const famSection = document.getElementById('custFamilySection');
    const isFamSectionVisible = famSection && famSection.style.display !== 'none';

    const payload = {
        CustomerName: name,
        Phone: document.getElementById('custPhoneInput').value.trim(),
        AadhaarNumber: cleanAadhaar || null,
        DateOfBirth: document.getElementById('custDobInput').value || null,
        Email: document.getElementById('custEmailInput').value.trim(),
        Address: document.getElementById('custAddressInput').value.trim(),
        GSTIN: document.getElementById('custGstinInput').value.trim(),
        CreditLimit: parseFloat(document.getElementById('custCreditLimitInput').value) || 0,
        Notes: document.getElementById('custNotesInput').value.trim()
    };

    if (isFamSectionVisible) {
        payload.ParentCustomerID = document.getElementById('custParentId').value;
        payload.Relationship = document.getElementById('custRelationshipSelect').value;
        payload.KhataMode = document.querySelector('input[name="custKhataModeRadio"]:checked')?.value || 'Separate';
        payload.IsFamilyMember = true;
    }

    if (!id) {
        payload.OpeningBalance = parseFloat(document.getElementById('custOpeningInput').value) || 0;
        payload.BalanceType = document.getElementById('custBalTypeInput').value;
    }

    showUniversalLoader(
        id ? 'Customer Update Ho Raha Hai...' : 'Naya Customer Save Ho Raha Hai...',
        'Live database me grahak ka khata register ho raha hai...'
    );

    try {
        const url = id ? `${API}/customers/${id}` : `${API}/customers`;
        const method = id ? 'PUT' : 'POST';

        const res = await fetch(url, {
            method,
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });
        const json = await res.json();
        if (!json.success) throw new Error(json.error);

        const isNestedUnderInvoice = activeModalStack.includes('invoiceModal');
        const isNestedUnderFamily = activeModalStack.includes('familyTreeModal');
        const isNestedUnderCSC = activeModalStack.includes('cscNewAppModal');
        const isNestedUnderBC = activeModalStack.includes('bcModal');

        const savedCustId = id || json.customer?.CustomerID || json.data?.CustomerID;
        // Upload any staged documents with rename
        if (savedCustId && window.UniversalDocUploader && UniversalDocUploader.hasPendingFiles('custDocUploader')) {
            try {
                await UniversalDocUploader.uploadPending('custDocUploader', { entityType: 'customer', entityId: savedCustId, customerId: savedCustId });
            } catch (upErr) {
                console.error('Customer doc upload error:', upErr);
            }
        }

        closeModal('customerModal');
        showToast(json.message || (id ? 'Customer update ho gaya!' : '✅ Naya Customer jud gaya!'), 'success', 'Grahak Khata');
        await loadCustomersPage();
        triggerRealTimeSync('customer_saved');

        const newCustId = json.customer?.CustomerID || json.data?.CustomerID;

        // If cscNewAppModal was open underneath, auto-select this new customer!
        if (isNestedUnderCSC && newCustId) {
            populateCustomerDropdowns();
            const cscSel = document.getElementById('cscCustomerSelect');
            if (cscSel) {
                cscSel.value = newCustId;
                if (cscSel._ssInstance) cscSel._ssInstance.syncFromNative();
                if (typeof onCSCCustomerSelectChange === 'function') onCSCCustomerSelectChange();
            }
            showToast('✅ Naya Customer jud gaya aur CSC form me select ho gaya!', 'success');
        }

        // If invoiceModal was open underneath, auto-select this new customer!
        if (isNestedUnderInvoice && newCustId) {
            populateCustomerDropdowns();
            const invSel = document.getElementById('invCustomerSelect');
            if (invSel) {
                invSel.value = newCustId;
                if (invSel._ssInstance) invSel._ssInstance.syncFromNative();
                if (typeof onInvoiceCustomerChanged === 'function') onInvoiceCustomerChanged();
            }
        }

        // If bcNewTxnModal was open underneath, auto-select this new customer!
        if (isNestedUnderBC && newCustId) {
            populateCustomerDropdowns();
            const bcSel = document.getElementById('bcCustomerSelect');
            if (bcSel) {
                bcSel.value = newCustId;
                if (bcSel._ssInstance) bcSel._ssInstance.syncFromNative();
                if (typeof onBCCustomerSelected === 'function') onBCCustomerSelected();
            }
        }

        // If familyTreeModal was open underneath, refresh family tree!
        if (isNestedUnderFamily && activeFamilyData?.head?.CustomerID) {
            await openFamilyModal(activeFamilyData.head.CustomerID);
        }

        // Show milestone action modal if created directly (not nested in draft forms)
        if (!id && !isNestedUnderInvoice && !isNestedUnderFamily && !isNestedUnderCSC && !isNestedUnderBC) {
            showActionSuccessModal({
                title: 'Naya Grahak Jud Gaya! 👤',
                subtitle: `${name} ka khata database me safalta se open ho gaya`,
                icon: 'user-check',
                details: [
                    { label: 'Grahak ka Naam', val: name },
                    { label: 'Mobile Number', val: payload.Phone || 'Phone nahi hai' },
                    { label: 'Opening Balance', val: formatMoney(payload.OpeningBalance || 0), color: (payload.OpeningBalance > 0 ? '#f87171' : '#34d399') },
                    { label: 'Pata (Address)', val: payload.Address || 'Nahi likha' }
                ],
                actions: [
                    ...(newCustId ? [
                        {
                            text: '+ Naya Bill Banayein',
                            icon: 'file-text',
                            className: 'btn-primary',
                            onClick: () => openInvoiceModal(newCustId)
                        },
                        {
                            text: '+ Khata Entry Karein',
                            icon: 'book-open',
                            className: 'btn-success',
                            onClick: () => openKhataEntryModal('Got', newCustId)
                        }
                    ] : [])
                ]
            });
        }
    } catch (err) {
        showToast(err.message, 'error', 'Customer Truti');
    } finally {
        hideUniversalLoader();
    }
}

// --------------------------------------------------------------------------
// FAMILY TREE MODAL LOGIC (KUTUMB / PARIVAR VIEW)
// --------------------------------------------------------------------------
async function openFamilyModal(customerId) {
    try {
        const res = await fetch(`${API}/customers/family/${customerId}`);
        const json = await res.json();
        if (!json.success) throw new Error(json.error);

        activeFamilyData = json.data;
        const f = json.data;

        document.getElementById('ftFamilyTitle').textContent = `${f.familyName || 'Parivar'} (कुटुंब)`;
        document.getElementById('ftFamilyPhone').textContent = f.sharedPhone || 'Phone nahi hai';
        document.getElementById('ftMemberCount').textContent = `${f.membersCount} Sadasya`;

        document.getElementById('ftTotalToReceive').textContent = formatMoney(f.summary.totalToReceive);
        document.getElementById('ftTotalToPay').textContent = formatMoney(f.summary.totalToPay);
        const netEl = document.getElementById('ftNetBalance');
        netEl.textContent = formatMoney(Math.abs(f.summary.netFamilyBalance));
        netEl.style.color = f.summary.netFamilyBalance > 0 ? '#f87171' : (f.summary.netFamilyBalance < 0 ? '#34d399' : 'var(--text-primary, #0f172a)');

        const tbody = document.getElementById('ftMembersTableBody');
        tbody.innerHTML = f.members.map(m => {
            const bal = parseFloat(m.CurrentBalance) || 0;
            const isHead = m.IsFamilyHead !== false && m.IsFamilyHead !== 0;
            return `
                <tr>
                    <td>
                        <div class="ft-member-name-wrap">
                            <span class="ft-member-name">${escapeHtml(m.CustomerName)}</span>
                            ${isHead ? '<span class="fam-badge-mukhiya" style="font-size: 10px; padding: 1.5px 6px;">👑 MUKHIYA</span>' : ''}
                        </div>
                        <div class="ft-member-phone">📞 ${escapeHtml(m.Phone || '-')}</div>
                    </td>
                    <td>
                        <span class="ft-member-rel">
                            ${escapeHtml(m.Relationship || (isHead ? 'Mukhiya' : 'Member'))}
                        </span>
                    </td>
                    <td>
                        <span class="badge ${m.KhataMode === 'Joint' ? 'badge-primary' : 'badge-neutral'}" style="font-size: 11px;">
                            ${m.KhataMode === 'Joint' ? '🤝 Joint' : '👤 Separate'}
                        </span>
                    </td>
                    <td style="text-align: right; font-weight: 800; font-size: 13.5px; color: ${bal > 0 ? '#f87171' : (bal < 0 ? '#34d399' : 'var(--text-muted, #64748b)')};">
                        ${formatMoney(Math.abs(bal))}
                        <div style="font-size: 10.5px; font-weight: 600; color: var(--text-muted, #64748b);">${bal > 0 ? 'Lena Hai' : (bal < 0 ? 'Dena Hai' : 'Barabar')}</div>
                    </td>
                    <td style="text-align: center;">
                        <span class="badge badge-neutral">${m.TotalBills || 0}</span>
                    </td>
                    <td style="text-align: right;">
                        <div style="display: flex; gap: 6px; justify-content: flex-end;">
                            <button class="btn-success btn-sm" onclick="closeModal('familyTreeModal'); goToCustomerKhata(${m.CustomerID});" title="Khata Kholo" style="padding: 4px 8px; font-size: 11px;">
                                <i data-lucide="book-open"></i> Khata
                            </button>
                            <button class="btn-primary btn-sm" onclick="closeModal('familyTreeModal'); createBillForCustomer(${m.CustomerID});" title="Bill Banayein" style="padding: 4px 8px; font-size: 11px;">
                                <i data-lucide="receipt"></i> Bill
                            </button>
                            <button class="btn-ghost btn-sm" onclick="closeModal('familyTreeModal'); openCustomer360Modal(${m.CustomerID}, true);" title="Customer 360 Profile Dekhein" style="padding: 4px 8px; font-size: 11px; color: #2563eb; border-color: rgba(37, 99, 235, 0.3);">
                                <i data-lucide="eye"></i> 360
                            </button>
                        </div>
                    </td>
                </tr>
            `;
        }).join('');

        openModal('familyTreeModal');
        lucide.createIcons();
    } catch (err) {
        showToast('Parivar load nahi hua: ' + err.message, 'error');
    }
}

function addMemberToThisFamily() {
    if (!activeFamilyData) return;
    const head = activeFamilyData.head || activeFamilyData.members[0];
    const phone = activeFamilyData.sharedPhone || (head ? head.Phone : '');
    const address = head ? head.Address : '';

    openCustomerModal();

    setTimeout(() => {
        if (phone) document.getElementById('custPhoneInput').value = phone;
        if (address) document.getElementById('custAddressInput').value = address;
        handleCustomerPhoneOrNameChange();
    }, 150);
}

function sendFamilyWhatsAppReminder() {
    if (!activeFamilyData) return;
    const f = activeFamilyData;
    const cleanPhone = (f.sharedPhone || '').replace(/\D/g, '');
    if (!cleanPhone || cleanPhone.length < 10) {
        showToast('Parivar ka koi valid phone number nahi mila!', 'error');
        return;
    }

    let msg = `*नमस्ते! 🙏 ${f.familyName || 'परिवार'} का खाता हिसाब:*\n`;
    msg += `मुखिया: ${f.head ? f.head.CustomerName : 'Mukhiya'}\n`;
    msg += `सदास्य: ${f.membersCount} सदस्य\n`;
    msg += `---------------------------------\n`;
    f.members.forEach((m, idx) => {
        const bal = parseFloat(m.CurrentBalance) || 0;
        const balText = bal > 0 ? `₹${bal.toFixed(2)} (बाकी लेना है)` : (bal < 0 ? `₹${Math.abs(bal).toFixed(2)} (जमा / देना है)` : `₹0.00 (बराबर)`);
        msg += `${idx + 1}. ${m.CustomerName} (${m.Relationship || 'Member'}): ${balText}\n`;
    });
    msg += `---------------------------------\n`;
    const net = f.summary.netFamilyBalance;
    msg += `*कुल परिवार बकाया: ₹${Math.abs(net).toFixed(2)} ${net > 0 ? 'लेना है' : (net < 0 ? 'देना है' : 'हिसाब बराबर')}*\n\n`;
    msg += `धन्यवाद - Cash Management HisaabBC`;

    window.open(`https://wa.me/91${cleanPhone}?text=${encodeURIComponent(msg)}`, '_blank');
}

function confirmDeleteCustomer(id, name) {
    showConfirm(`Kya aap sach me customer "${name}" ko delete karna chahte hain?`, async () => {
        try {
            const res = await fetch(`${API}/customers/${id}`, { method: 'DELETE' });
            const json = await res.json();
            if (!json.success) throw new Error(json.error);

            showToast('Customer delete kar diya gaya!');
            await loadCustomersPage();
            triggerRealTimeSync('customer_deleted');
        } catch (err) {
            showToast('Error: ' + err.message, 'error');
        }
    });
}

function goToCustomerKhata(customerId) {
    showPage('khatabook', document.getElementById('nav-khatabook'));
    setTimeout(() => {
        selectKhataCustomer(customerId);
    }, 150);
}

function createBillForCustomer(customerId) {
    showPage('billing', document.getElementById('nav-billing'));
    setTimeout(() => {
        openInvoiceModal(customerId);
    }, 150);
}

function openCustomerBills(customerId) {
    showPage('billing', document.getElementById('nav-billing'));
    const sel = document.getElementById('invCustomerSelect');
    if (sel) sel.value = customerId;
    setTimeout(() => {
        const cust = allCustomersData.find(c => c.CustomerID === customerId);
        if (cust) {
            const inp = document.getElementById('invoiceSearchInput');
            if (inp) {
                inp.value = cust.CustomerName;
                filterInvoicesList();
            }
        }
    }, 150);
}

// --------------------------------------------------------------------------
// 2. BILLING & INVOICING SUITE
// --------------------------------------------------------------------------

async function loadBillingPage() {
    try {
        const res = await fetch(`${API}/invoices`);
        const json = await res.json();
        if (!json.success) throw new Error(json.error);

        allInvoicesData = json.data || [];
        const summary = json.summary || {};

        const elSales = document.getElementById('billKpiSales');
        const elRec = document.getElementById('billKpiReceived');
        const elDue = document.getElementById('billKpiDue');
        const elCount = document.getElementById('billKpiTotalCount');
        const elPaidCount = document.getElementById('billKpiPaidCount');
        const elDueCount = document.getElementById('billKpiDueCount');

        if (elSales) elSales.textContent = formatMoney(summary.TotalSales || 0);
        if (elRec) elRec.textContent = formatMoney(summary.TotalReceived || 0);
        if (elDue) elDue.textContent = formatMoney(summary.TotalDue || 0);
        if (elCount) elCount.textContent = `${summary.TotalInvoices || 0} Bills`;
        if (elPaidCount) elPaidCount.textContent = `${summary.PaidCount || 0} Chukaye gaye`;
        if (elDueCount) elDueCount.textContent = `${(summary.UnpaidCount || 0) + (summary.PartialCount || 0)} Baqi / Partial`;

        renderInvoicesTable();
        updateVyaparBadges();
    } catch (err) {
        console.error('Error loading invoices:', err);
    }
}

let invoiceCurrentPage = 1;
let invoicePageSize = 20;

function changeInvoicePage(page) {
    invoiceCurrentPage = page;
    renderInvoicesTable();
    const tableEl = document.getElementById('invoicesTableBody');
    if (tableEl) {
        const wrap = tableEl.closest('.table-responsive') || tableEl.closest('.card');
        if (wrap) wrap.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
}
window.changeInvoicePage = changeInvoicePage;

function changeInvoicePageSize(val) {
    if (val === 'all') {
        invoicePageSize = 999999;
    } else {
        invoicePageSize = parseInt(val) || 20;
    }
    invoiceCurrentPage = 1;
    renderInvoicesTable();
}
window.changeInvoicePageSize = changeInvoicePageSize;

function setInvoiceStatusFilter(status, btn) {
    currentInvoiceFilter = status;
    invoiceCurrentPage = 1;
    document.querySelectorAll('#page-billing .tab-btn').forEach(b => b.classList.remove('active'));
    if (btn) btn.classList.add('active');
    renderInvoicesTable();
}

function filterInvoicesList() {
    invoiceCurrentPage = 1;
    renderInvoicesTable();
}

function renderInvoicesTable() {
    const tbody = document.getElementById('invoicesTableBody');
    if (!tbody) return;

    const queryStr = (document.getElementById('invoiceSearchInput')?.value || '').toLowerCase().trim();

    let list = allInvoicesData.filter(i => {
        const numMatch = (i.InvoiceNumber || '').toLowerCase().includes(queryStr);
        const nameMatch = (i.CustomerName || '').toLowerCase().includes(queryStr);
        const phoneMatch = (i.CustomerPhone || '').toLowerCase().includes(queryStr);
        const digitsOnly = queryStr.replace(/\D/g, '');
        const idMatch = (digitsOnly && i.CustomerID && String(i.CustomerID) === digitsOnly) ||
            (queryStr.startsWith('#') && i.CustomerID && String(i.CustomerID) === queryStr.replace(/^[#c]/i, '').trim());
        const aadhaarMatch = digitsOnly.length >= 3 && (
            (i.CustomerAadhaar || '').replace(/\D/g, '').includes(digitsOnly) ||
            (i.AadhaarNumber || '').replace(/\D/g, '').includes(digitsOnly)
        );
        if (queryStr && !numMatch && !nameMatch && !phoneMatch && !idMatch && !aadhaarMatch) return false;

        if (currentInvoiceFilter !== 'all' && i.PaymentStatus !== currentInvoiceFilter) return false;
        return true;
    });

    // Latest first sorting
    list.sort((a, b) => {
        const dA = parseApiDate(a.InvoiceDate);
        const dB = parseApiDate(b.InvoiceDate);
        const da = dA ? dA.getTime() : 0;
        const db = dB ? dB.getTime() : 0;
        if (db !== da) return db - da;
        return (b.InvoiceID || 0) - (a.InvoiceID || 0);
    });

    const totalInvoices = list.length;

    if (totalInvoices === 0) {
        tbody.innerHTML = `
            <tr>
                <td colspan="11" style="text-align: center; padding: 40px; color: #94a3b8;">
                    <i data-lucide="receipt" style="width: 36px; height: 36px; opacity: 0.5; margin-bottom: 8px;"></i>
                    <div>Koi bill nahi mila. Naya bill banane ke liye upar button dabayein!</div>
                </td>
            </tr>
        `;
        renderUniversalPaginationUI({
            containerId: 'invoicePagination',
            infoId: 'invoicePaginationInfo',
            currentPage: 1,
            pageSize: invoicePageSize,
            totalItems: 0,
            onPageChangeFnName: 'changeInvoicePage'
        });
        lucide.createIcons();
        return;
    }

    const totalInvPages = Math.ceil(totalInvoices / invoicePageSize) || 1;
    if (invoiceCurrentPage > totalInvPages) invoiceCurrentPage = totalInvPages;
    if (invoiceCurrentPage < 1) invoiceCurrentPage = 1;

    const startIdx = (invoiceCurrentPage - 1) * invoicePageSize;
    const pagedList = list.slice(startIdx, startIdx + invoicePageSize);

    tbody.innerHTML = pagedList.map(i => {
        let statusBadge = '<span class="badge badge-danger">Unpaid</span>';
        if (i.PaymentStatus === 'Paid') {
            statusBadge = '<span class="badge badge-success">Paid</span>';
        } else if (i.PaymentStatus === 'Partial') {
            statusBadge = '<span class="badge badge-warning">Partial</span>';
        }

        return `
            <tr>
                <td class="cell-center" style="vertical-align: middle; text-align: center;">
                    <button type="button" 
                            class="csc-sn-pill uni-sn-pill" 
                            onclick="openUniversalRecordDetail('Invoices', ${i.InvoiceID}, '${escapeInlineArg(i.SNCode || '')}')" 
                            title="Universal Serial No: ${escapeHtml(i.SNCode || ('SN-' + i.GlobalSerialNo))} (Click karke Poori Detail Dekhein)">
                        <i data-lucide="file-text" width="12" height="12"></i>
                        <span>${escapeHtml(i.SNCode || (i.GlobalSerialNo ? 'SN-' + i.GlobalSerialNo : '-'))}</span>
                    </button>
                </td>
                <td>
                    <span class="ref-code font-mono" onclick="viewInvoiceDoc(${i.InvoiceID})" style="font-weight: 800; color: #38bdf8; cursor: pointer; padding: 3px 8px; border-radius: 6px; background: rgba(56, 189, 248, 0.12); border: 1px solid rgba(56, 189, 248, 0.3); display: inline-flex; align-items: center; gap: 5px; transition: all 0.2s;" onmouseover="this.style.background='rgba(56, 189, 248, 0.25)'" onmouseout="this.style.background='rgba(56, 189, 248, 0.12)'" title="Bill dekhein aur print karein">
                        <i data-lucide="file-text" width="12" height="12"></i> ${escapeHtml(i.InvoiceNumber)}
                    </span>
                </td>
                <td>
                    <div style="font-weight: 700; color: var(--text-primary); display: flex; align-items: center; gap: 6px;">
                        ${i.CustomerID ? `<span class="pbadge blue font-mono" style="font-size: 11px; font-weight: 800; padding: 1px 6px; border-radius: 4px;">#${i.CustomerID}</span>` : ''}
                        <span>${escapeHtml(i.CustomerName || 'Customer')}</span>
                    </div>
                    ${i.CustomerPhone ? `<div style="font-size: 11px; color: #94a3b8; margin-top: 2px;">${renderPhoneWithCopy(i.CustomerPhone, { fontSize: '11px', showIcon: true, showWhatsApp: false })}</div>` : ''}
                </td>
                <td>
                    <div style="font-weight: 600; font-size: 13px;">${formatIndianDate(i.InvoiceDate)}</div>
                    <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;"><i data-lucide="clock" style="width:10px;height:10px;display:inline-block;vertical-align:middle;"></i> ${formatTime(i.CreatedAt || i.InvoiceDate) || '12:00 AM'}</div>
                </td>
                <td style="text-align: center;">
                    <span class="badge badge-neutral">${i.TotalItemCount || 1}</span>
                </td>
                <td style="text-align: right; font-weight: 800; color: var(--text-primary);">${formatMoney(i.TotalAmount)}</td>
                <td style="text-align: right; font-weight: 700;" class="amt-pos">+${formatMoney(i.PaidAmount)}</td>
                <td style="text-align: right; font-weight: 800;" class="${i.BalanceAmount > 0 ? 'amt-neg' : 'amt-zero'}">
                    ${i.BalanceAmount > 0 ? '− ' : ''}${formatMoney(i.BalanceAmount)}
                </td>
                <td style="text-align: center;">${statusBadge}</td>
                <td><span class="trans-tag-pill">${escapeHtml(i.PaymentMode || 'Cash')}</span></td>
                <td style="text-align: right;">
                    <div style="display: flex; gap: 5px; justify-content: flex-end; align-items: center;">
                        <button class="btn-ghost btn-sm" onclick="viewInvoiceDoc(${i.InvoiceID})" title="Bill Dekhein & Print Karein" style="padding: 4px 9px; color: #38bdf8; background: rgba(56, 189, 248, 0.12); border: 1px solid rgba(56, 189, 248, 0.25); display: inline-flex; align-items: center; gap: 4px; font-size: 12px; font-weight: 600;">
                            <i data-lucide="file-text" width="13" height="13"></i> Bill
                        </button>
                        <button type="button" class="table-menu-trigger-btn inv-menu-trigger-btn" onclick="toggleInvoiceActionMenu(event, ${i.InvoiceID})" title="Sabhi Kriya (3 Dots Menu)">
                            <i data-lucide="more-vertical" width="16" height="16"></i>
                        </button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');

    renderUniversalPaginationUI({
        containerId: 'invoicePagination',
        infoId: 'invoicePaginationInfo',
        currentPage: invoiceCurrentPage,
        pageSize: invoicePageSize,
        totalItems: totalInvoices,
        onPageChangeFnName: 'changeInvoicePage'
    });

    lucide.createIcons();
}

// --------------------------------------------------------------------------
// FLOATING 3-DOT ACTION MENU FOR INVOICES / BILLING
