let activeInvDropdownId = null;

function toggleInvoiceActionMenu(e, invoiceId) {
    if (e) {
        e.preventDefault();
        e.stopPropagation();
    }

    const existingMenu = document.getElementById('invFloatingActionMenu');
    if (existingMenu && activeInvDropdownId === invoiceId) {
        closeInvoiceActionMenu();
        return;
    }

    closeAllActionMenus();

    const inv = (allInvoicesData || []).find(i => Number(i.InvoiceID) === Number(invoiceId));
    if (!inv) return;

    const triggerBtn = (e && e.currentTarget) ? e.currentTarget : (e && e.target ? e.target.closest('.inv-menu-trigger-btn, .table-menu-trigger-btn') : null);
    if (!triggerBtn) return;

    triggerBtn.classList.add('active');
    activeInvDropdownId = invoiceId;

    const safeName = escapeHtml(inv.CustomerName || 'Customer');
    const invNum = escapeHtml(inv.InvoiceNumber || '#' + inv.InvoiceID);
    const totalAmt = parseFloat(inv.TotalAmount) || 0;
    const balAmt = parseFloat(inv.BalanceAmount) || 0;
    const isPaid = inv.PaymentStatus === 'Paid';

    let balBadgeHtml = isPaid
        ? '<span class="pbadge green font-mono" style="font-size: 10.5px;">Paid Full</span>'
        : `<span class="pbadge red font-mono" style="font-size: 10.5px;">Due: ₹${balAmt.toLocaleString('en-IN')}</span>`;

    const menu = document.createElement('div');
    menu.id = 'invFloatingActionMenu';
    menu.className = 'cust-action-dropdown-menu';

    menu.innerHTML = `
        <div class="cad-header">
            <div class="cad-title-row">
                <span class="cad-name" title="${safeName}">${safeName}</span>
                <span class="cad-id font-mono">${invNum}</span>
            </div>
            <div style="display: flex; align-items: center; justify-content: space-between; gap: 6px; margin-top: 5px;">
                <span style="font-size: 11.5px; font-weight: 700; color: var(--text-primary);">
                    ₹${totalAmt.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                </span>
                ${balBadgeHtml}
            </div>
            ${inv.CustomerPhone ? `<div class="cad-phone font-mono">📞 ${escapeHtml(inv.CustomerPhone)}</div>` : ''}
        </div>
        <div class="cad-items">
            <button type="button" class="cad-item" id="invOptView">
                <span class="cad-icon blue"><i data-lucide="printer"></i></span>
                <div class="cad-label">
                    <span class="cad-primary">Bill Dekhein &amp; Print</span>
                    <span class="cad-secondary">A4 ya Thermal print / PDF download</span>
                </div>
            </button>
            ${!isPaid ? `
                <button type="button" class="cad-item" id="invOptPay">
                    <span class="cad-icon green"><i data-lucide="hand-coins"></i></span>
                    <div class="cad-label">
                        <span class="cad-primary">Baqi Paisa Jama Karein</span>
                        <span class="cad-secondary">Payment receive karein &amp; khata update</span>
                    </div>
                </button>
            ` : ''}
            ${inv.CustomerPhone ? `
                <button type="button" class="cad-item" id="invOptWhatsApp">
                    <span class="cad-icon green"><i data-lucide="message-circle"></i></span>
                    <div class="cad-label">
                        <span class="cad-primary">WhatsApp Par Bill Bhejein</span>
                        <span class="cad-secondary">Bill details direct WhatsApp share</span>
                    </div>
                </button>
            ` : ''}
            ${inv.CustomerID ? `
                <button type="button" class="cad-item" id="invOptKhata">
                    <span class="cad-icon purple"><i data-lucide="book-open"></i></span>
                    <div class="cad-label">
                        <span class="cad-primary">Customer Khata Kholo</span>
                        <span class="cad-secondary">Grahak ka khatabook len-den hisaab</span>
                    </div>
                </button>
                <button type="button" class="cad-item" id="invOptCust360">
                    <span class="cad-icon cyan"><i data-lucide="user-check"></i></span>
                    <div class="cad-label">
                        <span class="cad-primary">Customer 360° Profile</span>
                        <span class="cad-secondary">Sampurna customer profile &amp; history</span>
                    </div>
                </button>
                <button type="button" class="cad-item" id="invOptDocs">
                    <span class="cad-icon orange"><i data-lucide="paperclip"></i></span>
                    <div class="cad-label">
                        <span class="cad-primary">Customer Dastavej (Docs)</span>
                        <span class="cad-secondary">Attached documents &amp; files</span>
                    </div>
                </button>
            ` : ''}
            <div class="cad-divider"></div>
            <button type="button" class="cad-item danger" id="invOptDelete">
                <span class="cad-icon red"><i data-lucide="trash-2"></i></span>
                <div class="cad-label">
                    <span class="cad-primary text-danger">Bill Delete Karein</span>
                    <span class="cad-secondary">Bill aur iska hisaab hatayein</span>
                </div>
            </button>
        </div>
    `;

    menu.querySelector('#invOptView')?.addEventListener('click', () => {
        closeInvoiceActionMenu();
        viewInvoiceDoc(inv.InvoiceID);
    });
    menu.querySelector('#invOptPay')?.addEventListener('click', () => {
        closeInvoiceActionMenu();
        openInvoicePayModal(inv.InvoiceID);
    });
    menu.querySelector('#invOptWhatsApp')?.addEventListener('click', () => {
        closeInvoiceActionMenu();
        const msg = `Namaste ${inv.CustomerName || ''}, aapke Bill #${inv.InvoiceNumber} ki kul rakam ₹${totalAmt} hai. ${balAmt > 0 ? `Baqi rakam: ₹${balAmt}` : 'Bhugtan prapt ho chuka hai (Paid).'}`;
        openWhatsAppChat(inv.CustomerPhone, msg);
    });
    menu.querySelector('#invOptKhata')?.addEventListener('click', () => {
        closeInvoiceActionMenu();
        if (inv.CustomerID) goToCustomerKhata(inv.CustomerID);
    });
    menu.querySelector('#invOptCust360')?.addEventListener('click', () => {
        closeInvoiceActionMenu();
        if (inv.CustomerID) openCustomer360Modal(inv.CustomerID, true);
    });
    menu.querySelector('#invOptDocs')?.addEventListener('click', () => {
        closeInvoiceActionMenu();
        if (inv.CustomerID) openCustomerDocsModal(inv.CustomerID, inv.CustomerName);
    });
    menu.querySelector('#invOptDelete')?.addEventListener('click', () => {
        closeInvoiceActionMenu();
        confirmDeleteInvoice(inv.InvoiceID, inv.InvoiceNumber);
    });

    positionFloatingMenu(menu, triggerBtn, 280);
}

function closeInvoiceActionMenu() {
    activeInvDropdownId = null;
    document.querySelectorAll('.inv-menu-trigger-btn.active').forEach(b => b.classList.remove('active'));
    const m = document.getElementById('invFloatingActionMenu');
    if (m) {
        m.classList.remove('active');
        m.remove();
    }
}
window.toggleInvoiceActionMenu = toggleInvoiceActionMenu;
window.closeInvoiceActionMenu = closeInvoiceActionMenu;

async function openInvoiceModal(prefillCustomerId = null) {
    if (!allCustomersData || allCustomersData.length === 0) {
        try {
            const cres = await fetch(`${API}/customers`).then(r => r.json());
            allCustomersData = cres.data || [];
        } catch (e) { }
    }
    populateCustomerDropdowns();
    populateSelects();

    try {
        const nextRes = await fetch(`${API}/invoices/next-number`).then(r => r.json());
        if (nextRes.success) {
            document.getElementById('invNumberInput').value = nextRes.nextInvoiceNumber;
        }
    } catch (e) { }

    document.getElementById('invDateInput').value = new Date().toISOString().split('T')[0];
    document.getElementById('invPaidInput').value = '';
    document.getElementById('invDiscountInput').value = '0';
    document.getElementById('invTaxInput').value = '0';
    document.getElementById('invModeSelect').value = 'Cash';
    document.getElementById('invNotesInput').value = '';

    const custSel = document.getElementById('invCustomerSelect');
    if (custSel && prefillCustomerId) {
        custSel.value = prefillCustomerId;
    }
    const invDobEl = document.getElementById('invCustomerDob');
    if (invDobEl) invDobEl.value = '';
    const invDocBadge = document.getElementById('invCustomerDocBadge');
    if (invDocBadge) invDocBadge.style.display = 'none';

    invoiceItemsList = [
        { ItemName: 'Item 1', Quantity: 1, Unit: 'Pcs', UnitPrice: 0, TotalPrice: 0 }
    ];
    renderInvoiceItemRows();
    calculateInvoiceTotals();
    toggleInvoiceAccountField();
    if (prefillCustomerId) onInvoiceCustomerChanged();

    if (window.UniversalDocUploader) {
        UniversalDocUploader.init('invoiceDocUploader', { entityType: 'invoice', title: '📎 Bill / Invoice Documents (Parchi, Slip, etc.)' });
        UniversalDocUploader.reset('invoiceDocUploader');
    }

    openModal('invoiceModal');
}

function onInvoiceCustomerChanged() {
    const sel = document.getElementById('invCustomerSelect');
    const dobIn = document.getElementById('invCustomerDob');
    const docBadge = document.getElementById('invCustomerDocBadge');

    if (sel && dobIn) {
        const custId = parseInt(sel.value);
        const cust = (typeof allCustomersData !== 'undefined' && Array.isArray(allCustomersData))
            ? allCustomersData.find(c => c.CustomerID === custId)
            : null;
        dobIn.value = cust?.DateOfBirth ? String(cust.DateOfBirth).split('T')[0] : '';

        if (custId && cust) {
            if (typeof updateCustomerDocBadge === 'function') {
                updateCustomerDocBadge('invCustomerDocBadge', cust.CustomerID, cust.CustomerName);
            }
            if (typeof renderUniversalDueAlert === 'function') {
                renderUniversalDueAlert(cust, 'invDueAlertContainer', 'INV');
            }
        } else {
            if (docBadge) docBadge.style.display = 'none';
            if (typeof renderUniversalDueAlert === 'function') {
                renderUniversalDueAlert(null, 'invDueAlertContainer', 'INV');
            }
        }
    } else {
        if (docBadge) docBadge.style.display = 'none';
        if (typeof renderUniversalDueAlert === 'function') {
            renderUniversalDueAlert(null, 'invDueAlertContainer', 'INV');
        }
    }
    calculateInvoiceTotals();
}

function addInvoiceItemRow(name = '', qty = 1, unit = 'Pcs', price = 0) {
    invoiceItemsList.push({
        ItemName: name || `Item ${invoiceItemsList.length + 1}`,
        Quantity: qty,
        Unit: unit,
        UnitPrice: price,
        TotalPrice: qty * price
    });
    renderInvoiceItemRows();
    calculateInvoiceTotals();
}

function removeInvoiceItemRow(index) {
    if (invoiceItemsList.length <= 1) {
        showToast('Kam se kam ek item hona zaroori hai', 'error');
        return;
    }
    invoiceItemsList.splice(index, 1);
    renderInvoiceItemRows();
    calculateInvoiceTotals();
}

const INVOICE_ITEM_UNITS = ['Pcs', 'Kg', 'Ltr', 'Mtr', 'Box', 'Packet', 'Service'];

function renderInvoiceItemRows() {
    const tbody = document.getElementById('invItemsBody');
    if (!tbody) return;

    tbody.innerHTML = '';

    invoiceItemsList.forEach((item, idx) => {
        const tr = document.createElement('tr');

        const nameTd = document.createElement('td');
        const nameInput = document.createElement('input');
        nameInput.type = 'text';
        nameInput.className = 'form-control form-control-sm';
        nameInput.placeholder = 'Saaman ka naam';
        nameInput.value = item.ItemName || '';
        nameInput.addEventListener('change', () => {
            invoiceItemsList[idx].ItemName = nameInput.value;
        });
        nameTd.appendChild(nameInput);
        tr.appendChild(nameTd);

        const qtyTd = document.createElement('td');
        const qtyInput = document.createElement('input');
        qtyInput.type = 'number';
        qtyInput.className = 'form-control form-control-sm';
        qtyInput.min = '0.01';
        qtyInput.step = '0.01';
        qtyInput.value = item.Quantity;
        qtyInput.addEventListener('input', () => {
            invoiceItemsList[idx].Quantity = parseFloat(qtyInput.value) || 0;
            calculateInvoiceTotals();
        });
        qtyTd.appendChild(qtyInput);
        tr.appendChild(qtyTd);

        const unitTd = document.createElement('td');
        const unitSelect = document.createElement('select');
        unitSelect.className = 'form-control form-control-sm';
        INVOICE_ITEM_UNITS.forEach(u => {
            const opt = document.createElement('option');
            opt.value = u;
            opt.textContent = u;
            if (item.Unit === u) opt.selected = true;
            unitSelect.appendChild(opt);
        });
        unitSelect.addEventListener('change', () => {
            invoiceItemsList[idx].Unit = unitSelect.value;
        });
        unitTd.appendChild(unitSelect);
        tr.appendChild(unitTd);

        const priceTd = document.createElement('td');
        const priceInput = document.createElement('input');
        priceInput.type = 'number';
        priceInput.className = 'form-control form-control-sm';
        priceInput.min = '0';
        priceInput.step = '0.01';
        priceInput.value = item.UnitPrice;
        priceInput.addEventListener('input', () => {
            invoiceItemsList[idx].UnitPrice = parseFloat(priceInput.value) || 0;
            calculateInvoiceTotals();
        });
        priceTd.appendChild(priceInput);
        tr.appendChild(priceTd);

        const totalTd = document.createElement('td');
        totalTd.style.textAlign = 'right';
        totalTd.style.fontWeight = '700';
        totalTd.style.color = '#38bdf8';
        const totalSpan = document.createElement('span');
        totalSpan.id = `itemRowTotal_${idx}`;
        totalSpan.textContent = '₹' + ((item.Quantity || 0) * (item.UnitPrice || 0)).toFixed(2);
        totalTd.appendChild(totalSpan);
        tr.appendChild(totalTd);

        const actionTd = document.createElement('td');
        actionTd.style.textAlign = 'center';
        const removeBtn = document.createElement('button');
        removeBtn.type = 'button';
        removeBtn.className = 'btn-ghost btn-sm';
        removeBtn.style.padding = '3px 6px';
        removeBtn.style.color = '#f87171';
        removeBtn.addEventListener('click', () => removeInvoiceItemRow(idx));
        removeBtn.innerHTML = '<i data-lucide="x"></i>';
        actionTd.appendChild(removeBtn);
        tr.appendChild(actionTd);

        tbody.appendChild(tr);
    });

    lucide.createIcons();
}

function calculateInvoiceTotals() {
    let subTotal = 0;
    invoiceItemsList.forEach((it, idx) => {
        const qty = parseFloat(it.Quantity) || 0;
        const rate = parseFloat(it.UnitPrice) || 0;
        const total = parseFloat((qty * rate).toFixed(2));
        it.TotalPrice = total;
        subTotal += total;

        const cell = document.getElementById(`itemRowTotal_${idx}`);
        if (cell) cell.textContent = formatMoney(total);
    });

    const discount = Math.max(0, parseFloat(document.getElementById('invDiscountInput')?.value) || 0);
    const taxable = Math.max(0, subTotal - discount);
    const taxPct = Math.max(0, parseFloat(document.getElementById('invTaxInput')?.value) || 0);
    const taxAmt = parseFloat(((taxable * taxPct) / 100).toFixed(2));
    const grandTotal = parseFloat((taxable + taxAmt).toFixed(2));

    const paidInput = document.getElementById('invPaidInput');
    let paid = parseFloat(paidInput?.value);
    if (isNaN(paid)) paid = 0;

    const balanceDue = Math.max(0, parseFloat((grandTotal - paid).toFixed(2)));

    const elSub = document.getElementById('invCalcSubTotal');
    const elTaxAmt = document.getElementById('invCalcTaxAmt');
    const elGrand = document.getElementById('invCalcGrandTotal');
    const elDue = document.getElementById('invCalcBalanceDue');

    if (elSub) elSub.textContent = formatMoney(subTotal);
    if (elTaxAmt) elTaxAmt.textContent = formatMoney(taxAmt);
    if (elGrand) elGrand.textContent = formatMoney(grandTotal);
    if (elDue) elDue.textContent = formatMoney(balanceDue);
}

function toggleInvoiceAccountField() {
    const mode = document.getElementById('invModeSelect')?.value;
    const grp = document.getElementById('invAccountGroup');
    if (!grp) return;
    if (mode === 'Udhar') {
        grp.style.display = 'none';
    } else {
        grp.style.display = 'block';
    }
}

async function saveInvoice() {
    const custId = document.getElementById('invCustomerSelect').value;
    if (!custId) {
        showToast('Kripya Customer select karein!', 'error', 'Customer Chunein');
        return;
    }

    if (invoiceItemsList.length === 0) {
        showToast('Kam se kam ek item add karein!', 'error', 'Item Zaroori Hai');
        return;
    }

    const invNum = document.getElementById('invNumberInput')?.value?.trim();
    if (!invNum) {
        showToast('Kripya Invoice Number bharein!', 'error', 'Invoice Number Zaroori');
        return;
    }
    const invDate = document.getElementById('invDateInput')?.value;
    if (!invDate) {
        showToast('Kripya Invoice Date chunein!', 'error', 'Date Zaroori');
        return;
    }
    const discount = parseFloat(document.getElementById('invDiscountInput').value) || 0;
    const taxPct = parseFloat(document.getElementById('invTaxInput').value) || 0;
    const paid = parseFloat(document.getElementById('invPaidInput').value) || 0;
    const mode = document.getElementById('invModeSelect').value;
    const accId = document.getElementById('invAccountSelect')?.value || null;
    const notes = document.getElementById('invNotesInput').value.trim();

    const subTotal = invoiceItemsList.reduce((sum, item) => sum + ((parseFloat(item.Quantity) || 0) * (parseFloat(item.UnitPrice) || 0)), 0);
    const taxable = Math.max(0, subTotal - discount);
    const taxAmt = parseFloat(((taxable * taxPct) / 100).toFixed(2));
    const grandTotal = parseFloat((taxable + taxAmt).toFixed(2));
    const dueAmt = Math.max(0, grandTotal - paid);

    const payload = {
        CustomerID: parseInt(custId),
        InvoiceNumber: invNum,
        InvoiceDate: invDate,
        Items: invoiceItemsList,
        DiscountAmount: discount,
        TaxPercent: taxPct,
        PaidAmount: paid,
        PaymentMode: mode,
        AccountID: accId ? parseInt(accId) : null,
        Notes: notes
    };

    showUniversalLoader('Naya Bill Generate Ho Raha Hai...', 'Database me bill aur khatabook sync ho raha hai...');

    try {
        const res = await fetch(`${API}/invoices`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });
        const json = await res.json();
        if (!json.success) throw new Error(json.error);

        const createdInvId = json.data?.InvoiceID || json.invoiceId;
        // Upload any staged documents with rename
        if (createdInvId && window.UniversalDocUploader && UniversalDocUploader.hasPendingFiles('invoiceDocUploader')) {
            try {
                await UniversalDocUploader.uploadPending('invoiceDocUploader', { entityType: 'invoice', entityId: createdInvId, customerId: parseInt(custId) });
            } catch (upErr) {
                console.error('Invoice doc upload error:', upErr);
            }
        }

        closeModal('invoiceModal');
        showToast(json.message || `✅ Bill #${invNum} ban gaya aur Khatabook update ho gaya!`, 'success', 'Bill Ban Gaya');
        await loadBillingPage();
        triggerRealTimeSync('invoice_saved');

        const cust = allCustomersData.find(c => c.CustomerID == custId);
        const custName = cust ? cust.CustomerName : 'Customer';

        // Auto open print / bill view modal with full details
        if (createdInvId) {
            setTimeout(() => {
                viewInvoiceDoc(createdInvId);
            }, 150);
        }
    } catch (err) {
        showToast('Error: ' + err.message, 'error', 'Bill Fail');
    } finally {
        hideUniversalLoader();
    }
}

