/* ==========================================================================
   17. RECEIPT SLIP POPUPS & PRINTING (PRINT BUTTON ON EVERY TRANSACTION)
   ========================================================================== */
let currentKhataReceiptData = null;
let currentTransVoucherData = null;

function openKhataSlipFromData(entryData, fromC360 = false) {
    currentKhataReceiptData = entryData;

    // Clean reset of optional rows before populating
    ['khataSlipSNRow', 'khataSlipIdRow', 'khataSlipPhoneRow', 'khataSlipAadhaarRow', 'khataSlipRefRow', 'khataSlipNoteRow'].forEach(id => {
        const el = document.getElementById(id);
        if (el) {
            el.style.setProperty('display', 'none', 'important');
            el.classList.add('is-hidden');
        }
    });
    ['khataSlipSN', 'khataSlipCustId', 'khataSlipPhone', 'khataSlipAadhaar', 'khataSlipRef', 'khataSlipNote'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.textContent = '-';
    });

    const isGave = entryData.EntryType === 'Gave';
    const isSettlement = entryData.EntryType === 'Settlement';
    const isBCFlow = entryData.EntryType === 'BC-Flow';
    const isCashOut = entryData.PaymentMode === 'Cash Out';

    const dateStr = entryData.EntryDate ? formatIndianDateTime(entryData.EntryDate) : formatIndianDateTime(new Date());
    const snCode = entryData.SNCode || (entryData.GlobalSerialNo ? `SN-${entryData.GlobalSerialNo}` : '');
    const receiptNo = 'KB-' + new Date().getFullYear() + '-' + String(entryData.KhataID || 'NEW').padStart(4, '0');
    const workLabel = isBCFlow
        ? (isCashOut ? 'BC Cash Out' : 'BC Cash In')
        : (isSettlement ? 'Advance Settlement' : (isGave ? 'Maine Diya (Udhaar)' : 'Mujhe Mila (Jama)'));
    const fullWork = `${workLabel}${entryData.Description ? ' — ' + entryData.Description : ''}`;

    const headerSnEl = document.getElementById('khataHeaderSN');
    const headerRcptEl = document.getElementById('khataHeaderReceiptNo');
    const headerWorkEl = document.getElementById('khataHeaderWork');
    if (headerSnEl) headerSnEl.textContent = snCode || '-';
    if (headerRcptEl) headerRcptEl.textContent = receiptNo;
    if (headerWorkEl) headerWorkEl.textContent = fullWork;

    const snRow = document.getElementById('khataSlipSNRow');
    const snEl = document.getElementById('khataSlipSN');
    if (snRow && snEl) {
        if (snCode) {
            snRow.style.display = 'flex';
            snEl.textContent = snCode;
        } else {
            snRow.style.display = 'none';
        }
    }

    document.getElementById('khataSlipDateTime').textContent = dateStr;
    document.getElementById('khataSlipReceiptNo').textContent = receiptNo;

    const typeEl = document.getElementById('khataSlipType');
    typeEl.textContent = isBCFlow
        ? (isCashOut ? 'BC CASH FLOW — CASH OUT' : 'BC CASH FLOW — CASH IN')
        : (isSettlement ? 'ADVANCE SE AUTO-SETTLE' : (isGave ? 'MAINE DIYA (UDHAAR / DEBIT)' : 'MUJHE MILA (JAMA / PAYMENT IN)'));
    typeEl.style.color = (isBCFlow || isSettlement) ? (isBCFlow ? '#0284c7' : '#2563eb') : '';
    typeEl.className = (isBCFlow || isSettlement) ? '' : (isGave ? 'text-danger' : 'text-success');

    document.getElementById('khataSlipCustomer').textContent = entryData.CustomerName || '-';

    const idRow = document.getElementById('khataSlipIdRow');
    if (idRow) {
        if (entryData.CustomerID) {
            idRow.style.display = 'flex';
            document.getElementById('khataSlipCustId').textContent = '#' + entryData.CustomerID;
        } else {
            idRow.style.display = 'none';
        }
    }

    const phoneRow = document.getElementById('khataSlipPhoneRow');
    if (entryData.CustomerPhone) {
        phoneRow.style.display = 'flex';
        document.getElementById('khataSlipPhone').innerHTML = `<span>${escapeHtml(entryData.CustomerPhone)}</span> <button type="button" class="btn-copy-mini" data-copy-phone="${escapeHtml(entryData.CustomerPhone)}" title="Mobile number copy karein"><i data-lucide="copy" width="11" height="11"></i></button>`;
    } else {
        phoneRow.style.display = 'none';
    }

    const aadhaarRow = document.getElementById('khataSlipAadhaarRow');
    if (entryData.CustomerAadhaar) {
        aadhaarRow.style.display = 'flex';
        document.getElementById('khataSlipAadhaar').innerHTML = renderAadhaarWithEye(entryData.CustomerAadhaar, { color: 'inherit', fontSize: '12px' });
    } else {
        aadhaarRow.style.display = 'none';
    }

    document.getElementById('khataSlipMode').textContent = entryData.PaymentMode || 'Cash';

    const refRow = document.getElementById('khataSlipRefRow');
    if (entryData.ReferenceNo) {
        refRow.style.display = 'flex';
        document.getElementById('khataSlipRef').textContent = entryData.ReferenceNo;
    } else {
        refRow.style.display = 'none';
    }

    document.getElementById('khataSlipAmount').textContent = '₹' + Number(entryData.Amount || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 });
    document.getElementById('khataSlipWords').textContent = numberToWordsINR(entryData.Amount || 0);

    const noteRow = document.getElementById('khataSlipNoteRow');
    if (entryData.Description) {
        noteRow.style.display = 'flex';
        document.getElementById('khataSlipNote').textContent = entryData.Description;
    } else {
        noteRow.style.display = 'none';
    }

    const balRow = document.getElementById('khataSlipBalance');
    if (entryData.RunningBalance !== undefined) {
        const rb = parseFloat(entryData.RunningBalance) || 0;
        const rbColor = rb > 0 ? '#ef4444' : (rb < 0 ? '#10b981' : '#64748b');
        const rbTag = rb > 0 ? ' (Baki Lena Hai)' : (rb < 0 ? ' (Advance Jama)' : ' (Hisaab Barabar)');
        balRow.textContent = '₹' + Number(Math.abs(rb)).toLocaleString('en-IN', { minimumFractionDigits: 2 }) + rbTag;
        balRow.style.color = rbColor;
    } else {
        balRow.textContent = 'Recorded in Live DB';
        balRow.style.color = '';
    }

    // Handle back button if opened on top of Customer 360
    const backBtn = document.getElementById('khataReceiptBackBtn');
    if (backBtn) {
        backBtn.style.display = (fromC360 || activeModalStack.includes('customer360Modal')) ? 'inline-flex' : 'none';
    }

    applyShopBrandingToDOM();
    setPrintFormat('a4', 'khata');
    if (typeof lucide !== 'undefined' && lucide.createIcons) {
        lucide.createIcons({ root: document.getElementById('khataReceiptModal') });
    }
    openModal('khataReceiptModal');
}

async function openKhataSlipFromRow(khataId, customerId) {
    try {
        if (khataId) {
            try {
                const singleRes = await fetch(`${API}/khatabook/entry/${khataId}`);
                const singleJson = await singleRes.json();
                if (singleJson && singleJson.success && singleJson.data) {
                    openKhataSlipFromData(singleJson.data, activeModalStack.includes('customer360Modal'));
                    return;
                }
            } catch (ignore) { }
        }

        const targetCustId = customerId || currentActiveCustomerId;
        if (!targetCustId) return;

        const res = await fetch(`${API}/khatabook/statement/${targetCustId}`);
        const json = await res.json();
        const entries = json.entries || [];
        const entry = entries.find(x => x.KhataID == khataId) || entries[0];
        if (entry) {
            openKhataSlipFromData({
                ...entry,
                CustomerID: json.customer?.CustomerID || targetCustId,
                CustomerName: json.customer?.CustomerName,
                CustomerPhone: json.customer?.Phone,
                CustomerAadhaar: json.customer?.AadhaarNumber
            }, activeModalStack.includes('customer360Modal'));
        }
    } catch (e) {
        showToast('Khata slip generate karne me dikkat: ' + e.message, 'error');
    }
}

function printKhataReceipt(format = null) {
    executeUnifiedPrint('khata', format || 'a4');
}

function shareKhataReceiptWhatsApp() {
    if (!currentKhataReceiptData) return;
    const k = currentKhataReceiptData;
    const isGave = k.EntryType === 'Gave';
    const isSettlement = k.EntryType === 'Settlement';
    const custIdStr = k.CustomerID ? `*Customer ID:* #${k.CustomerID}\n` : '';
    const sName = currentShopSettings.ShopName || 'AAPKI DUKAAN / HISAB BC';
    const sPhone = currentShopSettings.ShopPhone ? `*Helpline:* ${currentShopSettings.ShopPhone}\n` : '';
    const snLine = (k.SNCode || k.GlobalSerialNo) ? `*Universal SN:* ${k.SNCode || ('SN-' + k.GlobalSerialNo)}\n` : '';
    const text = `*KHATABOOK TRANSACTION SLIP*\n*${sName}*\n===============================\n${snLine}*Date:* ${document.getElementById('khataSlipDateTime').textContent}\n*Receipt No:* ${document.getElementById('khataSlipReceiptNo').textContent}\n${custIdStr}*Customer:* ${k.CustomerName}\n${k.CustomerPhone ? `*Mobile:* ${k.CustomerPhone}\n` : ''}${k.CustomerAadhaar ? `*Aadhaar:* 🪪 ${formatAadhaarDisplay(k.CustomerAadhaar)}\n` : ''}*Type:* ${k.EntryType === 'BC-Flow' ? (k.PaymentMode === 'Cash Out' ? 'BC Cash Flow - Cash Out' : 'BC Cash Flow - Cash In') : (isSettlement ? 'Advance se Auto-Settle' : (isGave ? 'Maine Diya (Udhaar)' : 'Mujhe Mila (Jama)'))}\n*Amount:* ₹${Number(k.Amount).toLocaleString('en-IN', { minimumFractionDigits: 2 })}\n*Mode:* ${k.PaymentMode || 'Cash'}\n${k.Description ? `*Notes:* ${fixMojibake(k.Description)}\n` : ''}${sPhone}===============================\n${currentShopSettings.ShopFooterMsg || 'Dhanyawad! - ' + sName}`;
    const phone = k.CustomerPhone ? '91' + k.CustomerPhone.replace(/\D/g, '') : '';
    const url = phone.length >= 12
        ? `https://api.whatsapp.com/send?phone=${phone}&text=${encodeURIComponent(text)}`
        : `https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`;
    window.open(url, '_blank');
}

