/* ==========================================================================
   17. RECYCLE BIN (Deleted items — restore / permanent delete)
   ========================================================================== */
let rbFilter = 'all';
let rbData = [];

async function loadRecycleBinPage() {
    try {
        const res = await fetch(`${API}/recyclebin`).then(r => r.json());
        if (!res.success) throw new Error(res.error || 'Load fail');
        rbData = res.data || [];
        const counts = res.counts || {};

        const badge = document.getElementById('badge-recyclebin');
        if (badge) badge.textContent = counts.total || 0;

        const set = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v || 0; };
        set('rbCountTotal', counts.total);
        set('rbCountCustomer', counts.customer);
        set('rbCountAccount', counts.account);
        set('rbCountOthers', (counts.party || 0) + (counts.category || 0) + (counts.budget || 0));

        renderRbPills(counts);
        renderRbTable();
        refreshIcons();
    } catch (err) {
        showToast('Recycle Bin load karne me error: ' + err.message, 'error');
    }
}

function renderRbPills(counts) {
    const el = document.getElementById('rbPills');
    if (!el) return;
    let defs = [
        ['all', 'Sab', counts.total || 0],
        ['customer', 'ग्राहक (Customers)', counts.customer || 0],
        ['account', 'खाते (Accounts)', counts.account || 0],
        ['party', 'व्यापारी (Parties)', counts.party || 0],
        ['category', 'श्रेणी (Categories)', counts.category || 0],
        ['budget', 'बजट (Budgets)', counts.budget || 0]
    ].filter(d => d[0] === 'all' || d[2] > 0);
    if (!defs.some(d => d[0] === rbFilter)) rbFilter = 'all';
    el.innerHTML = defs.map(([key, label, count]) => `
        <button class="pill-btn ${rbFilter === key ? 'active' : ''}" onclick="setRbFilter('${key}', this)">${label} (${count})</button>
    `).join('');
}

function setRbFilter(f, btn) {
    rbFilter = f;
    document.querySelectorAll('#rbPills .pill-btn').forEach(b => b.classList.remove('active'));
    if (btn) btn.classList.add('active');
    renderRbTable();
}

function renderRbTable() {
    const tbody = document.getElementById('rbTableBody');
    if (!tbody) return;
    const rows = rbData.filter(i => rbFilter === 'all' || i.type === rbFilter);
    if (!rows.length) {
        tbody.innerHTML = `<tr><td colspan="5" style="text-align: center; padding: 36px; color: var(--text-muted);">
            <div style="font-size: 34px; margin-bottom: 8px;">🗑️</div>
            <b>Recycle Bin khali hai</b><br>
            <span style="font-size: 12px;">Yahan delete ki gayi cheezein aati hain — aap unhe wapas la sakte hain.</span>
        </td></tr>`;
        return;
    }
    tbody.innerHTML = rows.map(i => {
        const amt = (i.amount !== null && i.amount !== undefined) ? formatMoney(i.amount) : '—';
        const del = i.deletedAt ? formatIndianDateTime(i.deletedAt) : '';
        return `
            <tr>
                <td><span class="rb-type-badge" style="background: ${escapeHtml(i.color)}1f; color: ${escapeHtml(i.color)}; border-color: ${escapeHtml(i.color)}55;"><i data-lucide="${escapeHtml(i.icon)}" width="12" height="12"></i> ${escapeHtml(i.typeLabel)}</span></td>
                <td><b>${escapeHtml(i.name)}</b>${i.type === 'customer' ? ` <span class="pbadge blue font-mono" style="font-size: 10.5px; font-weight: 800; padding: 1px 6px; border-radius: 4px; margin-left: 4px;">#${i.id}</span>` : ''}</td>
                <td style="color: var(--text-muted); font-size: 12.5px;">${escapeHtml(i.detail)}${del ? `<br><span style="font-size: 11px; opacity: 0.75;">Delete hua: ${del}</span>` : ''}</td>
                <td class="cell-right">${i.amount !== null && i.amount !== undefined ? `<b>${amt}</b>` : '—'}</td>
                <td class="cell-center">
                    <div class="prow-actions" style="justify-content: center;">
                        <button class="pbtn-sm green" onclick="restoreRecycleItem('${escapeInlineArg(i.type)}', ${i.id})" title="Wapas Layein (Restore)"><i data-lucide="rotate-ccw" width="14" height="14"></i></button>
                        <button class="pbtn-sm red" onclick="purgeRecycleItem('${escapeInlineArg(i.type)}', ${i.id})" title="Hamesha Ke Liye Delete"><i data-lucide="trash-2" width="14" height="14"></i></button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');
}

async function restoreRecycleItem(type, id) {
    showConfirm('Kya aap ise wapas laana chahte hain? Ye dobara active ho jayega.', async () => {
        try {
            const res = await fetch(`${API}/recyclebin/restore`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ type, id })
            });
            const j = await res.json();
            if (!j.success) throw new Error(j.error || 'Restore fail');
            showToast(j.message || 'Wapas aa gaya!', 'success', 'Recycle Bin');
            await loadRecycleBinPage();
            if (typeof loadMasterData === 'function') loadMasterData();
        } catch (e) {
            showToast('Restore error: ' + e.message, 'error');
        }
    });
}

function purgeRecycleItem(type, id) {
    const item = rbData.find(x => x.type === type && x.id === id);
    const name = item ? item.name : 'ye item';
    showConfirm(`⚠️ Kya aap "${name}" ko HAMESHA ke liye delete karna chahte hain? Ye wapas nahi aayega.`, async () => {
        try {
            const res = await fetch(`${API}/recyclebin/${type}/${id}`, { method: 'DELETE' });
            const j = await res.json();
            if (!j.success) throw new Error(j.error || 'Delete fail');
            showToast(j.message || 'Hamesha ke liye delete ho gaya', 'success', 'Recycle Bin');
            await loadRecycleBinPage();
            if (typeof loadMasterData === 'function') loadMasterData();
        } catch (e) {
            showToast('Delete error: ' + e.message, 'error');
        }
    });
}

// ==========================================================================
// DUKAAN PROFILE & PRINT BRANDING SETTINGS
// ==========================================================================
let currentShopSettings = {
    ShopName: '💰 AAPKI DUKAAN / HISAB BC',
    ShopSubtitle: 'Main Market, Cash Management Counter',
    ShopPhone: '+91 98765 43210',
    ShopAddress: 'Main Market, Cash Management Counter',
    ShopEmail: '',
    ShopGSTIN: '',
    ShopCSPCode: 'BC-001 / CSP-KENDRA',
    ShopFooterMsg: 'Thank you for visiting! Phir Padhaarein.'
};

function initCachedShopSettings() {
    try {
        const cached = localStorage.getItem('app_shop_settings');
        if (cached) {
            const parsed = JSON.parse(cached);
            currentShopSettings = { ...currentShopSettings, ...parsed };
        }
    } catch (e) { }
}

async function loadShopSettings() {
    try {
        const res = await fetch(`${API}/settings`);
        const json = await res.json();
        if (json.success && json.settings) {
            currentShopSettings = { ...currentShopSettings, ...json.settings };
            try { localStorage.setItem('app_shop_settings', JSON.stringify(currentShopSettings)); } catch (e) { }
        }
    } catch (err) {
        console.warn('Shop settings load fallback to local cache:', err.message);
    }
    populateShopSettingsUI();
    applyShopBrandingToDOM();
}

function populateShopSettingsUI() {
    const s = currentShopSettings;
    const nameInput = document.getElementById('setShopName');
    const subInput = document.getElementById('setShopSubtitle');
    const phoneInput = document.getElementById('setShopPhone');
    const addrInput = document.getElementById('setShopAddress');
    const cspInput = document.getElementById('setShopCSPCode');
    const gstinInput = document.getElementById('setShopGSTIN');
    const emailInput = document.getElementById('setShopEmail');
    const footerInput = document.getElementById('setShopFooterMsg');

    if (nameInput) nameInput.value = s.ShopName || '';
    if (subInput) subInput.value = s.ShopSubtitle || '';
    if (phoneInput) phoneInput.value = s.ShopPhone || '';
    if (addrInput) addrInput.value = s.ShopAddress || '';
    if (cspInput) cspInput.value = s.ShopCSPCode || '';
    if (gstinInput) gstinInput.value = s.ShopGSTIN || '';
    if (emailInput) emailInput.value = s.ShopEmail || '';
    if (footerInput) footerInput.value = s.ShopFooterMsg || '';

    const tabBadge = document.getElementById('tabBadgeShopName');
    if (tabBadge) {
        const cleanName = (s.ShopName || 'Dukaan Profile').replace(/[^\w\s\u0900-\u097F]/g, '').trim();
        tabBadge.textContent = cleanName.length > 15 ? cleanName.slice(0, 15) + '…' : (cleanName || 'Dukaan Profile');
    }

    updateLiveSlipPreview();
}

function updateLiveSlipPreview() {
    const nameVal = (document.getElementById('setShopName')?.value || currentShopSettings.ShopName || '💰 AAPKI DUKAAN / HISAB BC').trim();
    const subVal = (document.getElementById('setShopSubtitle')?.value || currentShopSettings.ShopSubtitle || 'Main Market, Cash Management Counter').trim();
    const phoneVal = (document.getElementById('setShopPhone')?.value || currentShopSettings.ShopPhone || '+91 98765 43210').trim();
    const addrVal = (document.getElementById('setShopAddress')?.value || currentShopSettings.ShopAddress || '').trim();
    const cspVal = (document.getElementById('setShopCSPCode')?.value || currentShopSettings.ShopCSPCode || '').trim();
    const footerVal = (document.getElementById('setShopFooterMsg')?.value || currentShopSettings.ShopFooterMsg || 'Thank you for visiting! Phir Padhaarein.').trim();

    const prevTitle = document.getElementById('prevShopTitle');
    const prevSub = document.getElementById('prevShopSub');
    const prevContact = document.getElementById('prevShopContact');
    const prevCSP = document.getElementById('prevShopCSPBadge');
    const prevFooter = document.getElementById('prevShopFooter');

    if (prevTitle) prevTitle.textContent = nameVal;
    if (prevSub) prevSub.textContent = subVal;
    if (prevContact) {
        const contacts = [];
        if (phoneVal) contacts.push(`Phone: ${phoneVal}`);
        if (addrVal) contacts.push(addrVal);
        prevContact.textContent = contacts.join(' • ');
        prevContact.style.display = contacts.length > 0 ? 'block' : 'none';
    }
    if (prevCSP) {
        if (cspVal) {
            prevCSP.textContent = `CSP: ${cspVal}`;
            prevCSP.style.display = 'inline-block';
        } else {
            prevCSP.style.display = 'none';
        }
    }
    if (prevFooter) prevFooter.textContent = footerVal;
}

async function saveShopSettingsFromUI(e) {
    if (e && e.preventDefault) e.preventDefault();

    const nameVal = (document.getElementById('setShopName')?.value || '').trim();
    if (!nameVal) {
        showToast('Dukaan ka naam khali nahi ho sakta!', 'warning', 'Dukaan Settings');
        return;
    }

    const payload = {
        ShopName: nameVal,
        ShopSubtitle: (document.getElementById('setShopSubtitle')?.value || '').trim(),
        ShopPhone: (document.getElementById('setShopPhone')?.value || '').trim(),
        ShopAddress: (document.getElementById('setShopAddress')?.value || '').trim(),
        ShopCSPCode: (document.getElementById('setShopCSPCode')?.value || '').trim(),
        ShopGSTIN: (document.getElementById('setShopGSTIN')?.value || '').trim(),
        ShopEmail: (document.getElementById('setShopEmail')?.value || '').trim(),
        ShopFooterMsg: (document.getElementById('setShopFooterMsg')?.value || '').trim()
    };

    try {
        const res = await fetch(`${API}/settings`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });
        const json = await res.json();
        if (!json.success) throw new Error(json.error || 'Settings save failed');

        currentShopSettings = { ...currentShopSettings, ...payload };
        try { localStorage.setItem('app_shop_settings', JSON.stringify(currentShopSettings)); } catch (err) { }

        populateShopSettingsUI();
        applyShopBrandingToDOM();
        showToast('Dukaan profile aur print settings kamyabi se save ho gayi!', 'success', 'Dukaan Settings');
        triggerRealTimeSync('settings_shop_update');
    } catch (err) {
        console.error('Save shop settings error:', err.message);
        showToast('Settings save karne me error: ' + err.message, 'error', 'Dukaan Settings');
    }
}

async function resetShopSettingsToDefault() {
    showConfirm('Kya aap dukaan profile aur print branding ko default par reset karna chahte hain?', async () => {
        const defaults = {
            ShopName: '💰 AAPKI DUKAAN / HISAB BC',
            ShopSubtitle: 'Main Market, Cash Management Counter',
            ShopPhone: '+91 98765 43210',
            ShopAddress: 'Main Market, Cash Management Counter',
            ShopEmail: '',
            ShopGSTIN: '',
            ShopCSPCode: 'BC-001 / CSP-KENDRA',
            ShopFooterMsg: 'Thank you for visiting! Phir Padhaarein.'
        };
        try {
            await fetch(`${API}/settings`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(defaults)
            });
            currentShopSettings = { ...defaults };
            try { localStorage.setItem('app_shop_settings', JSON.stringify(currentShopSettings)); } catch (e) { }
            populateShopSettingsUI();
            applyShopBrandingToDOM();
            showToast('Default Dukaan Profile reset ho gaya!', 'success', 'Dukaan Settings');
            triggerRealTimeSync('settings_shop_reset');
        } catch (e) {
            showToast('Reset error: ' + e.message, 'error');
        }
    });
}

function applyShopBrandingToDOM() {
    const s = currentShopSettings;
    const sName = s.ShopName || '💰 AAPKI DUKAAN / HISAB BC';
    const sSub = s.ShopSubtitle || 'Main Market, Cash Management Counter';
    const sContact = [s.ShopPhone ? `Phone: ${s.ShopPhone}` : '', s.ShopAddress].filter(Boolean).join(' • ');
    const sFooter = s.ShopFooterMsg || 'Thank you for visiting! Phir Padhaarein.';

    // 1. BC Counter Slip
    const slipTitle = document.getElementById('slipShopTitle');
    const slipSub = document.getElementById('slipShopSub');
    const slipContact = document.getElementById('slipShopContact');
    const slipFoot = document.getElementById('slipFooterNote');
    if (slipTitle) slipTitle.textContent = sName;
    if (slipSub) slipSub.textContent = sSub;
    if (slipContact) {
        slipContact.textContent = sContact;
        slipContact.style.display = sContact ? 'block' : 'none';
    }
    if (slipFoot) slipFoot.textContent = sFooter;

    // 2. Khatabook Slip
    const khataTitle = document.getElementById('khataSlipShopTitle');
    const khataSub = document.getElementById('khataSlipShopSub');
    const khataContact = document.getElementById('khataSlipShopContact');
    const khataFoot = document.getElementById('khataSlipFooterNote');
    if (khataTitle) khataTitle.textContent = sName;
    if (khataSub) khataSub.textContent = sSub;
    if (khataContact) {
        khataContact.textContent = sContact;
        khataContact.style.display = sContact ? 'block' : 'none';
    }
    if (khataFoot) khataFoot.textContent = sFooter;

    // 3. Transaction Voucher
    const tvTitle = document.getElementById('tvShopTitle');
    const tvSub = document.getElementById('tvShopSub');
    const tvContact = document.getElementById('tvShopContact');
    const tvFoot = document.getElementById('tvFooterNote');
    if (tvTitle) tvTitle.textContent = sName;
    if (tvSub) tvSub.textContent = sSub;
    if (tvContact) {
        tvContact.textContent = sContact;
        tvContact.style.display = sContact ? 'block' : 'none';
    }
    if (tvFoot) tvFoot.textContent = sFooter;

    // Live preview sync
    updateLiveSlipPreview();
}

/* ==========================================================================
   18. SETTINGS PAGE (Modular Tabbed Control Center & Dedicated Sub-Pages)
   ========================================================================== */
function switchSettingsTab(tabKey) {
    if (!tabKey) tabKey = 'shop';
    try { localStorage.setItem('activeSettingsTab', tabKey); } catch (e) { }

    // 1. Toggle active state on all horizontal tab buttons
    document.querySelectorAll('.settings-tab-btn').forEach(btn => {
        btn.classList.remove('active');
    });
    const targetBtn = document.getElementById(`btn-tab-${tabKey}`);
    if (targetBtn) {
        targetBtn.classList.add('active');
        try {
            targetBtn.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'nearest' });
        } catch (e) { }
    }

    // 2. Strict Tab Isolation: Hide all panes and only display the target pane
    document.querySelectorAll('.settings-tab-pane').forEach(pane => {
        pane.classList.remove('active');
        pane.style.display = 'none';
    });
    const targetPane = document.getElementById(`pane-settings-${tabKey}`);
    if (targetPane) {
        targetPane.classList.add('active');
        targetPane.style.display = 'block';
    }

    // 3. Tab-specific data initializations
    if (tabKey === 'shop') {
        populateShopSettingsUI();
    } else if (tabKey === 'csc-services') {
        loadCSCServicesSettingsUI();
    } else if (tabKey === 'appearance') {
        const theme = document.documentElement.getAttribute('data-theme') || 'dark';
        updateThemeChooserCardsUI(theme);
    } else if (tabKey === 'loading') {
        initLoaderSettingsUI();
    } else if (tabKey === 'excel-data') {
        try { if (typeof lucide !== 'undefined') lucide.createIcons(); } catch (e) { }
    } else if (tabKey === 'database') {
        if (typeof loadDatabasePage === 'function') {
            loadDatabasePage();
        }
    } else if (tabKey === 'extension') {
        try { if (typeof lucide !== 'undefined') lucide.createIcons(); } catch (e) { }
    } else if (tabKey === 'tenants') {
        if (typeof loadTenantShops === 'function') loadTenantShops();
    } else if (tabKey === 'errors') {
        if (typeof loadClientErrorLogs === 'function') loadClientErrorLogs();
    } else if (tabKey === 'safety') {
        try {
            const lastBk = localStorage.getItem('last_manual_backup_time');
            const bkEl = document.getElementById('lastBackupTimeDisplay');
            if (bkEl && lastBk) bkEl.textContent = lastBk;
        } catch (e) { }
    } else if (tabKey === 'license') {
        if (typeof loadLicenseSettingsUI === 'function') loadLicenseSettingsUI();
    }

    try {
        if (typeof lucide !== 'undefined' && lucide.createIcons) {
            lucide.createIcons({ root: targetPane || document });
        }
    } catch (e) { }
}

function navigateToSettingsTab(tabKey) {
    if (typeof showPage === 'function') {
        showPage('settings');
    }
    setTimeout(() => {
        switchSettingsTab(tabKey);
        const mc = document.getElementById('mainContent');
        if (mc) mc.scrollTop = 0;
    }, 60);
}

// Global window exposure for inline onclicks & modules
window.switchSettingsTab = switchSettingsTab;
window.navigateToSettingsTab = navigateToSettingsTab;


function selectThemeFromSettings(targetTheme) {
    localStorage.setItem('cash_mgmt_theme', targetTheme);
    applyTheme(targetTheme, true);
    updateThemeChooserCardsUI(targetTheme);
}

function updateThemeChooserCardsUI(theme) {
    const isDark = theme === 'dark';
    const cardDark = document.getElementById('themeCardDark');
    const cardLight = document.getElementById('themeCardLight');
    const badge = document.getElementById('appearanceCurrentBadge');
    const tabBadge = document.getElementById('tabBadgeTheme');

    if (cardDark) cardDark.classList.toggle('active', isDark);
    if (cardLight) cardLight.classList.toggle('active', !isDark);
    if (badge) {
        badge.textContent = isDark ? '● Dark Mode Active' : '● Light Mode Active';
        badge.className = isDark ? 'rb-pill-status' : 'rb-pill-status live';
    }
    if (tabBadge) tabBadge.textContent = isDark ? 'Dark' : 'Light';
}

async function loadSettingsPage() {
    // 1. Theme state sync
    const theme = document.documentElement.getAttribute('data-theme') || 'dark';
    const stl = document.getElementById('settingsThemeLabel');
    if (stl) stl.textContent = theme === 'light' ? 'Light Mode' : 'Dark Mode';
    updateThemeChooserCardsUI(theme);

    // 2. Static and environment metadata
    const svS = document.getElementById('settingsServerStatus');
    if (svS) svS.textContent = 'LIVE (' + location.host + ')';
    const t = document.getElementById('settingsToday');
    if (t) t.textContent = new Date().toLocaleDateString('en-IN', { weekday: 'long', day: '2-digit', month: 'long', year: 'numeric' });

    // 3. Live SQL Server Telemetry
    const dbS = document.getElementById('settingsDbStatus');
    const dbI = document.getElementById('settingsDbInfo');
    const telemConn = document.getElementById('telemConnState');
    const tabBadgeDb = document.getElementById('tabBadgeDb');
    const telemHost = document.getElementById('telemServerHost');
    if (telemHost) telemHost.textContent = location.host || 'localhost:3000';

    try {
        const h = await fetch(`${API}/health`).then(r => r.json());
        const ok = Boolean(h && h.success && h.status === 'CONNECTED');
        isDatabaseConnected = ok;
        if (dbS) { dbS.textContent = ok ? '● LIVE DB' : '● DB OFFLINE'; dbS.classList.toggle('live', ok); }
        if (dbI) dbI.textContent = ok ? 'SQLite 3 — cash_management.db (Connected)' : 'SQLite 3 — Not connected';
        if (telemConn) {
            telemConn.textContent = ok ? '● CONNECTED' : '● DISCONNECTED';
            telemConn.className = ok ? 'dtc-val connected' : 'dtc-val';
        }
        if (tabBadgeDb) {
            tabBadgeDb.textContent = ok ? 'Live' : 'Offline';
            tabBadgeDb.classList.toggle('live', ok);
        }
    } catch (e) {
        isDatabaseConnected = false;
        if (dbS) { dbS.textContent = '● STATUS UNKNOWN'; dbS.classList.remove('live'); }
        if (dbI) dbI.textContent = 'SQLite 3 — Status could not be confirmed';
        if (svS) svS.textContent = 'STATUS UNKNOWN — server could not be reached';
        if (telemConn) {
            telemConn.textContent = '● OFFLINE';
            telemConn.className = 'dtc-val';
        }
        if (tabBadgeDb) {
            tabBadgeDb.textContent = 'Offline';
            tabBadgeDb.classList.remove('live');
        }
    }

    // 4. Load shop settings & initialize active settings tab from storage (defaults to 'shop')
    await loadShopSettings();
    const activeTab = localStorage.getItem('activeSettingsTab') || 'shop';
    switchSettingsTab(activeTab);

    // 5. Initialize loading animation engine UI
    initLoaderSettingsUI();
    refreshIcons();
}

function settingsSyncNow() {
    triggerRealTimeSync('settings_manual');
    showToast('Sync broadcast trigger ho gaya — sab screens refresh ho rahi hain!', 'success', 'Real-Time Sync');
}

/* DOCS VAULT P4: rename + description + delete + c360 tab */
async function renameDocument(docId) {
    const doc = findDocAnywhere(docId);
    const oldName = doc ? doc.OriginalName : '';
    const base = oldName.replace(/\.[^.]+$/, '');
    const input = prompt('Naya naam likhein (extension apne aap lag jayegi):', base);
    if (input === null) return;
    const newName = (input || '').trim();
    if (!newName) { showToast('Naam khali nahi ho sakta', 'warning'); return; }
    try {
        const res = await fetch(API + '/documents/' + docId + '/rename', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ newName }) });
        const j = await res.json();
        if (!j.success) throw new Error(j.error || 'Rename fail');
        showToast(j.message || 'Rename ho gaya!', 'success', 'Documents');
        await loadDocumentsPage(true);
        if (typeof c360ActiveCustomerId !== 'undefined' && c360ActiveCustomerId) loadC360Documents(c360ActiveCustomerId);
        triggerRealTimeSync('documents_rename');
    } catch (err) { showToast('Rename error: ' + err.message, 'error'); }
}
async function editDocumentDescription(docId) {
    const doc = findDocAnywhere(docId);
    const input = prompt('Description / note likhein:', doc ? (doc.Description || '') : '');
    if (input === null) return;
    try {
        const res = await fetch(API + '/documents/' + docId + '/description', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ description: (input || '').trim() }) });
        const j = await res.json();
        if (!j.success) throw new Error(j.error || 'Update fail');
        showToast(j.message || 'Update ho gaya', 'success', 'Documents');
        await loadDocumentsPage(true);
        if (typeof c360ActiveCustomerId !== 'undefined' && c360ActiveCustomerId) loadC360Documents(c360ActiveCustomerId);
    } catch (err) { showToast('Error: ' + err.message, 'error'); }
}
function deleteDocument(docId) {
    const doc = findDocAnywhere(docId);
    const name = doc ? doc.OriginalName : ('Document #' + docId);
    showConfirm('Kya aap "' + escapeHtml(name) + '" delete karna chahte hain?<br><span style="font-size:12px;">File recycle me surakshit rahegi.</span>', async () => {
        try {
            const res = await fetch(API + '/documents/' + docId, { method: 'DELETE' });
            const j = await res.json();
            if (!j.success) throw new Error(j.error || 'Delete fail');
            showToast(j.message || 'Delete ho gaya', 'success', 'Documents');
            if (currentViewDocId == docId) closeModal('docViewModal');
            await loadDocumentsPage(true);
            if (typeof c360ActiveCustomerId !== 'undefined' && c360ActiveCustomerId) loadC360Documents(c360ActiveCustomerId);
            triggerRealTimeSync('documents_delete');
        } catch (err) { showToast('Delete error: ' + err.message, 'error'); }
    });
}
async function loadC360Documents(customerId) {
    const listEl = document.getElementById('c360DocsList');
    const countEl = document.getElementById('c360TabCountDocs');
    try {
        if (listEl) listEl.innerHTML = '<div style="padding:16px;color:var(--text-muted);font-size:13px;">📁 Documents load ho rahe hain...</div>';
        const res = await fetch(API + '/documents/customer/' + customerId).then(r => r.json());
        const docs = (res && res.success ? res.data : []) || [];
        c360DocsCache = docs;
        if (countEl) countEl.textContent = docs.length;
        if (!listEl) return;
        if (!docs.length) {
            listEl.innerHTML = '<div style="text-align:center;padding:22px;color:var(--text-muted);"><div style="font-size:36px;">📂</div><b>Is customer ka koi document nahi hai</b><br><span style="font-size:12px;">Aadhaar, PAN, Photo, Agreement — yahin se upload karein.</span><br><button class="btn-primary btn-sm" style="margin-top:10px;" onclick="openCustomerDocsModal(' + customerId + ')">Pehla Document Upload Karein</button></div>';
        } else {
            listEl.innerHTML = docs.map(d => {
                const ic = docIconFor(d);
                return '<div class="c360-doc-row"><div class="c360-doc-ic ' + ic.cls + '" onclick="openCustomerDocsModal(' + customerId + ')">' + ic.icon + '</div>'
                    + '<div class="c360-doc-info" onclick="openCustomerDocsModal(' + customerId + ')"><b>' + escapeHtml(d.OriginalName) + '</b><span>' + escapeHtml(d.Description || '') + ' • ' + formatFileSize(d.FileSize) + '</span></div>'
                    + '<div class="c360-doc-btns"><button class="btn-icon" title="Universal Viewer" onclick="openCustomerDocsModal(' + customerId + ')">👁️</button>'
                    + '<button class="btn-icon" title="Download" onclick="downloadDocument(' + d.DocumentID + ')">⬇️</button>'
                    + '<button class="btn-icon" title="Rename" onclick="renameDocument(' + d.DocumentID + ')">✏️</button>'
                    + '<button class="btn-icon" title="Delete" style="color:var(--accent-red);" onclick="deleteDocument(' + d.DocumentID + ')">🗑️</button></div></div>';
            }).join('');
        }
        refreshIcons();
    } catch (err) {
        if (listEl) listEl.innerHTML = '<div style="padding:16px;color:var(--accent-red);">Error: ' + escapeHtml(err.message) + '</div>';
    }
}
function c360UploadDoc() {
    let name = '';
    try { if (typeof c360ActiveCustomerData !== 'undefined' && c360ActiveCustomerData && c360ActiveCustomerData.customer) name = c360ActiveCustomerData.customer.CustomerName || ''; } catch (e) { }
    openDocUploadModal(typeof c360ActiveCustomerId !== 'undefined' ? c360ActiveCustomerId : null, name || '');
}
// File input par chuni hui files ka preview (naam + size)
document.addEventListener('change', (e) => {
    if (e.target && e.target.id === 'docFileInput') {
        const pv = document.getElementById('docFilePreview');
        const files = Array.from(e.target.files || []);
        if (!pv) return;
        pv.innerHTML = files.length
            ? files.map(f => `<span class="doc-file-tag">📄 <b>${escapeHtml(f.name)}</b> (${formatFileSize(f.size)})</span>`).join('')
            : '';
    }
});

// Drag and drop for doc upload dropzone
document.addEventListener('dragover', (e) => {
    const dz = e.target.closest('#docUploadDropzone');
    if (dz) {
        e.preventDefault();
        dz.classList.add('dragover');
    }
});
document.addEventListener('dragleave', (e) => {
    const dz = e.target.closest('#docUploadDropzone');
    if (dz) {
        dz.classList.remove('dragover');
    }
});
document.addEventListener('drop', (e) => {
    const dz = e.target.closest('#docUploadDropzone');
    if (dz && e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files.length) {
        e.preventDefault();
        dz.classList.remove('dragover');
        const fi = document.getElementById('docFileInput');
        if (fi) {
            fi.files = e.dataTransfer.files;
            fi.dispatchEvent(new Event('change', { bubbles: true }));
        }
    }
});
/* DOCS VAULT P3: upload + view + download + print */
function openDocUploadModal(presetCustomerId, presetCustomerName) {
    buildDocCustomerFilter();
    const sel = document.getElementById('docCustomerSelect');
    if (presetCustomerId && sel) {
        let found = false;
        for (const o of sel.options) { if (o.value == String(presetCustomerId)) { found = true; break; } }
        if (!found) {
            const opt = document.createElement('option');
            opt.value = presetCustomerId;
            opt.textContent = '👤 ' + (presetCustomerName || ('Customer #' + presetCustomerId));
            sel.appendChild(opt);
        }
        sel.value = String(presetCustomerId);
        if (sel._ssInstance) sel._ssInstance.syncFromNative();
    } else if (sel) {
        sel.value = '';
        if (sel._ssInstance) sel._ssInstance.syncFromNative();
    }
    const fi = document.getElementById('docFileInput');
    if (fi) fi.value = '';
    const pv = document.getElementById('docFilePreview');
    if (pv) pv.innerHTML = '';
    const prog = document.getElementById('docUploadProgress');
    if (prog) prog.style.display = 'none';
    openModal('docUploadModal');
    refreshIcons();
}
async function uploadDocuments() {
    const fi = document.getElementById('docFileInput');
    const files = fi ? Array.from(fi.files || []) : [];
    if (!files.length) { showToast('Pehle file(s) chunein!', 'warning', 'Upload'); return; }
    const custSel = document.getElementById('docCustomerSelect');
    const catSel = document.getElementById('docCategorySelect');
    const descInp = document.getElementById('docDescriptionInput');
    const category = catSel ? catSel.value : '';
    let desc = descInp ? descInp.value.trim() : '';
    if (category && category !== 'shop' && category !== 'Other') desc = desc ? ('[' + category + '] ' + desc) : ('[' + category + ']');
    if (category === 'shop' && !desc) desc = '[Shop Document]';
    const fd = new FormData();
    files.forEach(f => fd.append('files', f));
    if (custSel && custSel.value) fd.append('CustomerID', custSel.value);
    fd.append('UploadedBy', 'shop');
    fd.append('Description', desc || '');
    const btn = document.getElementById('docUploadBtn');
    const prog = document.getElementById('docUploadProgress');
    const bar = document.getElementById('docUploadBar');
    if (btn) { btn.disabled = true; btn.textContent = '⏳ Uploading...'; }
    if (prog) prog.style.display = 'block';
    if (bar) bar.style.width = '55%';
    try {
        const res = await fetch(API + '/documents/upload', { method: 'POST', body: fd });
        const j = await res.json().catch(() => ({ success: false }));
        if (!j.success) throw new Error(j.error || 'Upload fail');
        if (bar) bar.style.width = '100%';
        showToast(j.message || 'Upload ho gaya!', 'success', 'Documents');
        closeModal('docUploadModal');
        if (fi) fi.value = '';
        if (descInp) descInp.value = '';
        await loadDocumentsPage(true);
        if (typeof c360ActiveCustomerId !== 'undefined' && c360ActiveCustomerId) loadC360Documents(c360ActiveCustomerId);
        triggerRealTimeSync('documents_upload');
    } catch (err) {
        showToast('Upload error: ' + err.message, 'error');
    } finally {
        if (btn) { btn.disabled = false; btn.innerHTML = 'Upload Karo'; }
        if (prog) prog.style.display = 'none';
        hideUniversalLoader(true);
        refreshIcons();
    }
}
function findDocAnywhere(docId) {
    const a = (allDocumentsData || []).find(d => d.DocumentID == docId);
    if (a) return a;
    return (c360DocsCache || []).find(d => d.DocumentID == docId) || null;
}
function viewDocument(docId) {
    const doc = findDocAnywhere(docId);
    if (doc && doc.CustomerID && typeof window.openCustomerDocsModal === 'function') {
        openCustomerDocsModal(doc.CustomerID, doc.CustomerName || '', docId);
        return;
    }

    currentViewDocId = docId;
    const title = document.getElementById('docViewTitle');
    const body = document.getElementById('docViewBody');
    const meta = document.getElementById('docViewMeta');
    if (title) title.textContent = doc ? (doc.OriginalName || doc.FileName) : ('Document #' + docId);
    if (meta && doc) meta.textContent = (typeof docLinkedLabel === 'function' ? docLinkedLabel(doc) : '') + ' • ' + formatFileSize(doc.FileSize) + (doc.Description ? ' • ' + doc.Description : '');
    if (body) {
        const ext = ((doc && doc.FileType) || '').toLowerCase();
        const url = API + '/documents/' + docId + '/view';
        if (doc && (doc.IsExternal === true || doc.IsExternal === 1 || /^(https?):\/\//i.test(doc.FilePath || ''))) {
            body.innerHTML = '<div style="padding:40px 20px;text-align:center;">'
                + '<div style="font-size:54px;">📄</div>'
                + '<h3 style="color:#f8fafc;margin:8px 0;">' + escapeHtml(doc.OriginalName || '') + '</h3>'
                + '<p style="color:#94a3b8;font-size:13px;">Ye document online (Google Drive) par store hai. Preview ke liye link kholein.</p>'
                + '<div style="display:flex;gap:8px;justify-content:center;margin-top:14px;">'
                + '<a class="btn-success btn-sm" href="' + escapeHtml(doc.FilePath) + '" target="_blank" rel="noopener noreferrer">Open Link</a> '
                + '<button class="btn-secondary btn-sm" onclick="downloadDocument(' + docId + ')">Download</button></div></div>';
        } else if (['.jpg', '.jpeg', '.png', '.gif', '.webp', '.bmp', '.svg'].includes(ext)) {
            body.innerHTML = '<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;overflow:hidden;padding:16px;">'
                + '<img src="' + url + '" style="max-width:100%;max-height:100%;object-fit:contain;border-radius:8px;box-shadow:0 4px 20px rgba(0,0,0,0.5);" alt="preview">'
                + '</div>';
        } else if (ext === '.pdf' || ext === '.txt') {
            body.innerHTML = '<iframe src="' + url + '" style="width:100%;height:100%;border:none;background:#fff;" title="Document Preview"></iframe>';
        } else {
            body.innerHTML = '<div style="padding:40px 20px;text-align:center;"><div style="font-size:54px;">📄</div><h3 style="color:#f8fafc;margin:8px 0;">' + escapeHtml(doc ? (doc.OriginalName || doc.FileName) : '') + '</h3><p style="color:#94a3b8;font-size:13px;">Preview uplabdh nahi hai (Word/Excel). Download ya Print karein.</p><div style="display:flex;gap:8px;justify-content:center;margin-top:14px;"><button class="btn-success btn-sm" onclick="downloadDocument(' + docId + ')">Download</button> <button class="btn-secondary btn-sm" onclick="printDocument(' + docId + ')">Print</button></div></div>';
        }
    }
    openModal('docViewModal');
    refreshIcons();
}
function downloadCurrentDoc() { if (currentViewDocId) downloadDocument(currentViewDocId); }
function printCurrentDoc() { if (currentViewDocId) printDocument(currentViewDocId); }
function downloadDocument(docId) {
    window.open(API + '/documents/' + docId + '/download', '_blank');
    showToast('Download shuru ho gaya!', 'success', 'Documents');
}
function printDocument(docId) {
    window.open(API + '/documents/' + docId + '/view', '_blank');
    showToast('Naye tab me khul gaya — wahan Ctrl+P dabayein', 'info', 'Print');
}
/* DOCS VAULT P2: grid + table render */
let docCurrentPage = 1;
let docPageSize = 20;

function changeDocPage(page) {
    docCurrentPage = page;
    renderDocumentsVault();
    const docWrap = document.getElementById('docGrid') || document.getElementById('docTableBody');
    if (docWrap) {
        const wrap = docWrap.closest('.table-responsive') || docWrap.closest('.card') || docWrap;
        if (wrap) wrap.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
}
window.changeDocPage = changeDocPage;

function changeDocPageSize(val) {
    if (val === 'all') {
        docPageSize = 999999;
    } else {
        docPageSize = parseInt(val) || 20;
    }
    docCurrentPage = 1;
    renderDocumentsVault();
}
window.changeDocPageSize = changeDocPageSize;

function renderDocumentsVault() {
    const rows = getFilteredDocuments();

    // Latest first sorting: CreatedAt DESC, DocumentID DESC
    rows.sort((a, b) => {
        const dA = parseApiDate(a.CreatedAt);
        const dB = parseApiDate(b.CreatedAt);
        const da = dA ? dA.getTime() : 0;
        const db = dB ? dB.getTime() : 0;
        if (db !== da) return db - da;
        return (b.DocumentID || 0) - (a.DocumentID || 0);
    });

    const totalDocs = rows.length;
    const totalDocPages = Math.ceil(totalDocs / docPageSize) || 1;
    if (docCurrentPage > totalDocPages) docCurrentPage = totalDocPages;
    if (docCurrentPage < 1) docCurrentPage = 1;

    const startIdx = (docCurrentPage - 1) * docPageSize;
    const pagedRows = rows.slice(startIdx, startIdx + docPageSize);

    const grid = document.getElementById('docGrid');
    const tbody = document.getElementById('docTableBody');
    if (grid) {
        if (!rows.length) {
            grid.innerHTML = '<div class="doc-empty"><div style="font-size:44px;">📂</div><b>Koi document nahi mila</b><br><span style="font-size:12px;color:var(--text-muted);">Nayi file upload karein ya filter badlein.</span><br><button class="btn-primary btn-sm" onclick="openDocUploadModal()" style="margin-top:10px;">Upload Karein</button></div>';
        } else {
            grid.innerHTML = pagedRows.map(d => {
                const ic = docIconFor(d);
                const docDate = parseApiDate(d.CreatedAt);
                const dt = docDate ? docDate.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' }) : '';
                return '<div class="doc-card"><div class="doc-thumb ' + ic.cls + '" onclick="viewDocument(' + d.DocumentID + ')" title="Preview kholein">' + ic.icon + '</div>'
                    + '<div class="doc-card-body" onclick="viewDocument(' + d.DocumentID + ')"><div class="doc-name" title="' + escapeHtml(d.OriginalName) + '">' + escapeHtml(d.OriginalName) + '</div>'
                    + '<div class="doc-sub">' + escapeHtml(docLinkedLabel(d)) + '</div>'
                    + '<div class="doc-meta"><span>' + formatFileSize(d.FileSize) + '</span><span>•</span><span>' + dt + '</span></div></div>'
                    + '<div class="doc-actions" onclick="event.stopPropagation()">'
                    + '<button class="btn-icon" title="View" onclick="viewDocument(' + d.DocumentID + ')">👁️</button>'
                    + '<button class="btn-icon" title="Print" onclick="printDocument(' + d.DocumentID + ')">🖨️</button>'
                    + '<button class="btn-icon" title="Download" onclick="downloadDocument(' + d.DocumentID + ')">⬇️</button>'
                    + '<button class="btn-icon" title="Rename" onclick="renameDocument(' + d.DocumentID + ')">✏️</button>'
                    + '<button class="btn-icon" title="Delete" style="color:var(--accent-red);" onclick="deleteDocument(' + d.DocumentID + ')">🗑️</button>'
                    + '</div></div>';
            }).join('');
        }
    }
    if (tbody) {
        if (!rows.length) {
            tbody.innerHTML = '<tr><td colspan="5" style="text-align:center;padding:28px;color:var(--text-muted);">📂 Koi document nahi mila</td></tr>';
        } else {
            tbody.innerHTML = pagedRows.map(d => {
                const ic = docIconFor(d);
                const docDate = parseApiDate(d.CreatedAt);
                const dt = docDate ? docDate.toLocaleString('en-IN', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : '—';
                return '<tr><td><b>' + ic.icon + ' ' + escapeHtml(d.OriginalName) + '</b><br><span style="font-size:11px;color:var(--text-muted);">' + escapeHtml(d.Description || (d.FileType || '').toUpperCase()) + '</span></td>'
                    + '<td style="font-size:12.5px;">' + escapeHtml(docLinkedLabel(d)) + '</td>'
                    + '<td style="white-space:nowrap;">' + formatFileSize(d.FileSize) + '</td>'
                    + '<td style="white-space:nowrap;font-size:12px;">' + dt + '</td>'
                    + '<td class="cell-right"><div class="table-actions" style="justify-content:flex-end; gap:5px;" onclick="event.stopPropagation()">'
                    + '<button class="btn-ghost btn-sm" title="View" onclick="viewDocument(' + d.DocumentID + ')" style="padding:4px 8px; color:#38bdf8; display:inline-flex; align-items:center; gap:4px; font-size:12px; font-weight:600;"><i data-lucide="eye" width="13" height="13"></i> Dekhein</button>'
                    + '<button type="button" class="table-menu-trigger-btn doc-menu-trigger-btn" onclick="toggleDocActionMenu(event, ' + d.DocumentID + ')" title="Sabhi Kriya (3 Dots Menu)"><i data-lucide="more-vertical" width="15" height="15"></i></button>'
                    + '</div></td></tr>';
            }).join('');
        }
    }

    renderUniversalPaginationUI({
        containerId: 'docPagination',
        infoId: 'docPaginationInfo',
        currentPage: docCurrentPage,
        pageSize: docPageSize,
        totalItems: totalDocs,
        onPageChangeFnName: 'changeDocPage'
    });

    refreshIcons();
}

// --------------------------------------------------------------------------
// FLOATING 3-DOT ACTION MENU FOR DOCUMENTS VAULT
// --------------------------------------------------------------------------
let activeDocDropdownId = null;

function toggleDocActionMenu(e, docId) {
    if (e) {
        e.preventDefault();
        e.stopPropagation();
    }

    const existingMenu = document.getElementById('docFloatingActionMenu');
    if (existingMenu && activeDocDropdownId === docId) {
        closeDocActionMenu();
        return;
    }

    closeAllActionMenus();

    const d = (allDocumentsData || []).find(item => Number(item.DocumentID) === Number(docId));
    if (!d) return;

    const triggerBtn = (e && e.currentTarget) ? e.currentTarget : (e && e.target ? e.target.closest('.doc-menu-trigger-btn, .table-menu-trigger-btn') : null);
    if (!triggerBtn) return;

    triggerBtn.classList.add('active');
    activeDocDropdownId = docId;

    const safeName = escapeHtml(d.OriginalName || 'Document');
    const sizeStr = formatFileSize(d.FileSize);
    const safeType = escapeHtml((d.Category || d.FileType || 'File').toUpperCase());

    const menu = document.createElement('div');
    menu.id = 'docFloatingActionMenu';
    menu.className = 'cust-action-dropdown-menu';

    menu.innerHTML = `
        <div class="cad-header">
            <div class="cad-title-row">
                <span class="cad-name" title="${safeName}">${safeName}</span>
                <span class="cad-id font-mono">#${d.DocumentID}</span>
            </div>
            <div style="display: flex; align-items: center; justify-content: space-between; gap: 6px; margin-top: 5px;">
                <span style="font-size: 11px; color: var(--text-muted);">${safeType}</span>
                <span style="font-size: 11.5px; font-weight: 600; color: var(--text-secondary);">${sizeStr}</span>
            </div>
        </div>
        <div class="cad-items">
            <button type="button" class="cad-item" id="docOptView">
                <span class="cad-icon blue"><i data-lucide="eye"></i></span>
                <div class="cad-label">
                    <span class="cad-primary">Dastavej Dekhein (View)</span>
                    <span class="cad-secondary">Full size viewer / preview</span>
                </div>
            </button>
            <button type="button" class="cad-item" id="docOptPrint">
                <span class="cad-icon purple"><i data-lucide="printer"></i></span>
                <div class="cad-label">
                    <span class="cad-primary">Print Karein</span>
                    <span class="cad-secondary">Direct print preview bhejein</span>
                </div>
            </button>
            <button type="button" class="cad-item" id="docOptDownload">
                <span class="cad-icon green"><i data-lucide="download"></i></span>
                <div class="cad-label">
                    <span class="cad-primary">Download Karein</span>
                    <span class="cad-secondary">Original file download karein</span>
                </div>
            </button>
            <button type="button" class="cad-item" id="docOptRename">
                <span class="cad-icon cyan"><i data-lucide="edit-2"></i></span>
                <div class="cad-label">
                    <span class="cad-primary">Naam Badlein (Rename)</span>
                    <span class="cad-secondary">File ka title ya description badlein</span>
                </div>
            </button>
            <div class="cad-divider"></div>
            <button type="button" class="cad-item danger" id="docOptDelete">
                <span class="cad-icon red"><i data-lucide="trash-2"></i></span>
                <div class="cad-label">
                    <span class="cad-primary text-danger">Dastavej Delete Karein</span>
                    <span class="cad-secondary">Is file ko hamesha ke liye hatayein</span>
                </div>
            </button>
        </div>
    `;

    menu.querySelector('#docOptView')?.addEventListener('click', () => {
        closeDocActionMenu();
        viewDocument(d.DocumentID);
    });
    menu.querySelector('#docOptPrint')?.addEventListener('click', () => {
        closeDocActionMenu();
        printDocument(d.DocumentID);
    });
    menu.querySelector('#docOptDownload')?.addEventListener('click', () => {
        closeDocActionMenu();
        downloadDocument(d.DocumentID);
    });
    menu.querySelector('#docOptRename')?.addEventListener('click', () => {
        closeDocActionMenu();
        renameDocument(d.DocumentID);
    });
    menu.querySelector('#docOptDelete')?.addEventListener('click', () => {
        closeDocActionMenu();
        deleteDocument(d.DocumentID);
    });

    positionFloatingMenu(menu, triggerBtn, 270);
}

function closeDocActionMenu() {
    activeDocDropdownId = null;
    document.querySelectorAll('.doc-menu-trigger-btn.active').forEach(b => b.classList.remove('active'));
    const m = document.getElementById('docFloatingActionMenu');
    if (m) {
        m.classList.remove('active');
        m.remove();
    }
}
window.toggleDocActionMenu = toggleDocActionMenu;
window.closeDocActionMenu = closeDocActionMenu;
/* DOCS VAULT P1: state + list + filters */
let allDocumentsData = [];
let docTypeFilter = 'all';
let currentViewDocId = null;
let c360DocsCache = [];
function formatFileSize(bytes) {
    if (bytes === null || bytes === undefined) return '—';
    const b = parseFloat(bytes) || 0;
    if (b === 0) return '0 KB';
    if (b < 1024) return b + ' B';
    if (b < 1048576) return (b / 1024).toFixed(1) + ' KB';
    return (b / 1048576).toFixed(2) + ' MB';
}
function docIconFor(doc) {
    const cat = (doc.Category || '').toLowerCase();
    const ext = (doc.FileType || '').toLowerCase();
    if (cat === 'image') return { icon: '🖼️', cls: 'doc-ic-img' };
    if (cat === 'pdf' || ext === '.pdf') return { icon: '📕', cls: 'doc-ic-pdf' };
    if (cat === 'excel') return { icon: '📊', cls: 'doc-ic-xls' };
    if (cat === 'document') return { icon: '📄', cls: 'doc-ic-doc' };
    if (['.jpg', '.jpeg', '.png', '.gif', '.webp', '.bmp', '.svg'].includes(ext)) return { icon: '🖼️', cls: 'doc-ic-img' };
    if (['.xls', '.xlsx', '.csv'].includes(ext)) return { icon: '📊', cls: 'doc-ic-xls' };
    if (['.doc', '.docx', '.txt', '.rtf'].includes(ext)) return { icon: '📄', cls: 'doc-ic-doc' };
    if (['.ppt', '.pptx'].includes(ext)) return { icon: '📽️', cls: 'doc-ic-ppt' };
    return { icon: '📦', cls: 'doc-ic-other' };
}
function docLinkedLabel(doc) {
    if (doc.CustomerID && doc.CustomerName) return '👤 ' + doc.CustomerName + ' (#' + doc.CustomerID + ')';
    if (doc.CustomerID) return '👤 Customer #' + doc.CustomerID;
    return '🏪 Shop Document';
}
async function loadDocumentsPage(silent) {
    try {
        if (!silent) showUniversalLoader('Documents Load Ho Rahe Hain...', 'Vault se files aa rahi hain...');
        const listRes = await fetch(API + '/documents').then(r => r.json()).catch(() => ({ success: false }));
        const statsRes = await fetch(API + '/documents/stats').then(r => r.json()).catch(() => ({ success: false }));
        allDocumentsData = (listRes && listRes.success) ? (listRes.data || []) : [];
        if (statsRes && statsRes.success && statsRes.data) {
            const s = statsRes.data;
            const set = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };
            set('docCountTotal', s.TotalDocs || 0);
            set('docCountCustomer', s.CustomerDocs || 0);
            set('docCountShop', s.ShopDocs || 0);
            set('docCountSize', formatFileSize(s.TotalSize || 0));
            const badge = document.getElementById('badge-documents');
            if (badge) badge.textContent = s.TotalDocs || 0;
        }
        buildDocCustomerFilter();
        renderDocumentsVault();
        refreshIcons();
    } catch (err) {
        showToast('Documents load error: ' + err.message, 'error');
    } finally {
        if (!silent) hideUniversalLoader();
    }
}
function buildDocCustomerFilter() {
    const sel = document.getElementById('docCustomerFilter');
    if (sel) {
        const cur = sel.value || 'all';
        const custs = (typeof allCustomersData !== 'undefined' ? allCustomersData : []) || [];
        let html = '<option value="all">Sab Customers + Shop</option><option value="shop">🏪 Sirf Shop Documents</option>';
        const known = { all: 1, shop: 1 };
        custs.forEach(c => {
            html += '<option value="' + c.CustomerID + '">👤 ' + escapeHtml(c.CustomerName) + (c.Phone ? ' (' + escapeHtml(c.Phone) + ')' : '') + '</option>';
            known[String(c.CustomerID)] = 1;
        });
        (allDocumentsData || []).forEach(d => {
            if (d.CustomerID && !known[String(d.CustomerID)]) {
                html += '<option value="' + d.CustomerID + '">👤 ' + escapeHtml(d.CustomerName || ('Customer #' + d.CustomerID)) + '</option>';
                known[String(d.CustomerID)] = 1;
            }
        });
        sel.innerHTML = html;
        sel.value = known[cur] ? cur : 'all';
        if (sel._ssInstance) {
            sel._ssInstance.refresh();
        } else if (window.SearchableSelect) {
            new SearchableSelect(sel);
        }
    }
    const upSel = document.getElementById('docCustomerSelect');
    if (upSel) {
        const upCur = upSel.value || '';
        const custs = (typeof allCustomersData !== 'undefined' ? allCustomersData : []) || [];
        upSel.innerHTML = '<option value="">🏪 Shop Document (koi customer nahi)</option>' + custs.map(c =>
            '<option value="' + c.CustomerID + '">👤 ' + escapeHtml(c.CustomerName) + (c.Phone ? ' (' + escapeHtml(c.Phone) + ')' : '') + '</option>'
        ).join('');
        upSel.value = upCur;
        if (upSel._ssInstance) {
            upSel._ssInstance.refresh();
        } else if (window.SearchableSelect) {
            new SearchableSelect(upSel);
        }
    }
}
function setDocTypeFilter(type, btn) {
    docTypeFilter = type || 'all';
    docCurrentPage = 1;
    document.querySelectorAll('#docTypePills .pill-btn').forEach(b => b.classList.remove('active'));
    if (btn) btn.classList.add('active');
    renderDocumentsVault();
}
function filterDocumentsList() {
    docCurrentPage = 1;
    renderDocumentsVault();
}
function getFilteredDocuments() {
    const q = (document.getElementById('docSearchInput')?.value || '').toLowerCase().trim();
    const custF = document.getElementById('docCustomerFilter')?.value || 'all';
    return (allDocumentsData || []).filter(d => {
        if (docTypeFilter !== 'all' && (d.Category || 'other') !== docTypeFilter) return false;
        if (custF === 'shop' && d.CustomerID) return false;
        if (custF !== 'all' && custF !== 'shop' && String(d.CustomerID) !== String(custF)) return false;
        if (q) {
            const hay = ((d.OriginalName || '') + ' ' + (d.Description || '') + ' ' + (d.CustomerName || '')).toLowerCase();
            if (!hay.includes(q)) return false;
        }
        return true;
    });
}

