function getCSCServiceTheme(sType) {
    if (!sType) return CSC_SERVICE_THEMES['Other'];
    if (CSC_SERVICE_THEMES[sType]) return CSC_SERVICE_THEMES[sType];
    const low = sType.toLowerCase();
    if (low.includes('pan')) return CSC_SERVICE_THEMES['PAN Card'];
    if (low.includes('aay') || low.includes('income')) return CSC_SERVICE_THEMES['Aay Praman Patra'];
    if (low.includes('niwas') || low.includes('domicile')) return CSC_SERVICE_THEMES['Niwas Praman Patra'];
    if (low.includes('jati') || low.includes('caste')) return CSC_SERVICE_THEMES['Jati Praman Patra'];
    if (low.includes('ration') || low.includes('rashan')) return CSC_SERVICE_THEMES['Ration Card'];
    if (low.includes('voter')) return CSC_SERVICE_THEMES['Voter ID'];
    if (low.includes('pvc')) return CSC_SERVICE_THEMES['Aadhaar PVC Card'];
    if (low.includes('complaint')) return CSC_SERVICE_THEMES['Aadhaar Complaint'];
    if (low.includes('aadhaar')) return CSC_SERVICE_THEMES['Aadhaar Seva'];
    if (low.includes('aeps')) return CSC_SERVICE_THEMES['AEPS'];
    if (low.includes('upi')) return CSC_SERVICE_THEMES['UPI Payment'];
    if (low.includes('bill') || low.includes('bijli')) return CSC_SERVICE_THEMES['Bijli Bill'];
    if (low.includes('ayushman')) return CSC_SERVICE_THEMES['Ayushman Card'];
    if (low.includes('kisan')) return CSC_SERVICE_THEMES['PM Kisan'];
    if (low.includes('shram')) return CSC_SERVICE_THEMES['E-Shram / Labour'];
    if (low.includes('driving')) return CSC_SERVICE_THEMES['Driving License'];
    if (low.includes('passport')) return CSC_SERVICE_THEMES['Passport Seva'];
    return CSC_SERVICE_THEMES['Other'];
}

