// 1. Load Main CSC Work Tracker Page (100% Live Database Mode)
async function loadCSCPage() {
    const applyCSCData = (apps, stats) => {
        allCSCApplications = apps || [];
        stats = stats || {};

        // Update KPI Cards & Stats
        const elTotal = document.getElementById('cscKpiTotal');
        const elPending = document.getElementById('cscKpiPending');
        const elOverdue = document.getElementById('cscKpiOverdueSub');
        const elApproved = document.getElementById('cscKpiApproved');
        const elDelivered = document.getElementById('cscKpiDelivered');
        const elRejected = document.getElementById('cscKpiRejected');
        const elFee = document.getElementById('cscKpiTotalFee');
        const elDue = document.getElementById('cscKpiDueSub');

        if (elTotal) elTotal.textContent = stats.totalCount || allCSCApplications.length || 0;
        if (elPending) elPending.textContent = stats.pendingCount || allCSCApplications.filter(a => a.Status === 'Pending').length;
        if (elOverdue) {
            const ov = stats.overdueCount || 0;
            elOverdue.innerHTML = ov > 0 ? `<span class="amt-red" style="font-weight: 800;">${ov} Overdue</span>` : `0 Overdue`;
        }
        if (elApproved) elApproved.textContent = stats.approvedCount || allCSCApplications.filter(a => a.Status === 'Approved').length;
        if (elDelivered) elDelivered.textContent = stats.deliveredCount || allCSCApplications.filter(a => a.Status === 'Delivered').length;
        if (elRejected) elRejected.textContent = stats.rejectedCount || allCSCApplications.filter(a => a.Status === 'Rejected').length;
        if (elFee) elFee.textContent = `₹${Number(stats.totalBilled || 0).toLocaleString('en-IN')}`;
        if (elDue) {
            const dueVal = Number(stats.totalDue || 0);
            elDue.innerHTML = dueVal > 0
                ? `<span class="amt-red" style="font-weight: 800;">Bakiya: ₹${dueVal.toLocaleString('en-IN')}</span>`
                : `<span class="amt-green" style="font-weight: 700;">Bakiya: ₹0 (Chukta)</span>`;
        }

        // Sidebar Pending Badge
        const badge = document.getElementById('badge-csc');
        if (badge) {
            badge.textContent = stats.totalCount || allCSCApplications.length || 0;
            badge.classList.remove('hidden');
            badge.style.display = 'inline-block';
        }

        // Status Tabs Counts
        const tAll = document.getElementById('cscTabCountAll');
        const tPending = document.getElementById('cscTabCountPending');
        const tProcess = document.getElementById('cscTabCountProcess');
        const tApproved = document.getElementById('cscTabCountApproved');
        const tDelivered = document.getElementById('cscTabCountDelivered');
        const tRejected = document.getElementById('cscTabCountRejected');

        if (tAll) tAll.textContent = stats.totalCount || allCSCApplications.length || 0;
        if (tPending) tPending.textContent = allCSCApplications.filter(a => a.Status === 'Pending').length;
        if (tProcess) tProcess.textContent = allCSCApplications.filter(a => a.Status === 'Under Process').length;
        if (tApproved) tApproved.textContent = stats.approvedCount || allCSCApplications.filter(a => a.Status === 'Approved').length;
        if (tDelivered) tDelivered.textContent = stats.deliveredCount || allCSCApplications.filter(a => a.Status === 'Delivered').length;
        if (tRejected) tRejected.textContent = stats.rejectedCount || allCSCApplications.filter(a => a.Status === 'Rejected').length;

        // Sync active card in UI
        document.querySelectorAll('#cscStatsGrid .csc-stat-card').forEach(c => c.classList.remove('active-card'));
        const currentCardId = (cscCurrentFilterStatus === 'pending_and_process' || cscCurrentFilterStatus === 'Pending') ? 'cscCardPending' :
            (cscCurrentFilterStatus === 'Approved') ? 'cscCardApproved' :
                (cscCurrentFilterStatus === 'Delivered') ? 'cscCardDelivered' :
                    (cscCurrentFilterStatus === 'Rejected') ? 'cscCardRejected' :
                        (cscCurrentFilterPayment === 'due') ? 'cscCardFinance' : 'cscCardTotal';
        const activeCardEl = document.getElementById(currentCardId);
        if (activeCardEl) activeCardEl.classList.add('active-card');

        filterCSCTable();
    };

    try {
        const [appsRes, statsRes] = await Promise.all([
            fetch(`${API}/csc?_t=${Date.now()}`).then(r => r.json()),
            fetch(`${API}/csc/stats?_t=${Date.now()}`).then(r => r.json())
        ]);

        if (!appsRes || !appsRes.success) throw new Error(appsRes?.error || 'Live CSC fetch failed');

        const apps = Array.isArray(appsRes.data) ? appsRes.data : [];
        const stats = statsRes.data || {};

        applyCSCData(apps, stats);
    } catch (err) {
        console.error('[Live CSC Error]:', err.message);
        showToast('CSC aavedan load nahi ho paye: ' + err.message, 'error');
    }
}

let cscCurrentPage = 1;
let cscPageSize = 20;

function changeCSCPage(page) {
    cscCurrentPage = page;
    filterCSCTable(false);
    const tableEl = document.getElementById('cscTableBody');
    if (tableEl) {
        const wrap = tableEl.closest('.table-responsive') || tableEl.closest('.card');
        if (wrap) wrap.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
}
window.changeCSCPage = changeCSCPage;

function changeCSCPageSize(val) {
    if (val === 'all') {
        cscPageSize = 999999;
    } else {
        cscPageSize = parseInt(val) || 20;
    }
    cscCurrentPage = 1;
    filterCSCTable(true);
}
window.changeCSCPageSize = changeCSCPageSize;

// 2. Filter & Render CSC Applications Table
function filterCSCTable(resetPage = true) {
    if (resetPage) cscCurrentPage = 1;
    let filtered = [...allCSCApplications];

    // Status Tab filter
    if (cscCurrentFilterStatus !== 'all') {
        if (cscCurrentFilterStatus === 'pending_and_process') {
            // Pending card: Pending + Applied + Under Process sab dikhao (stats se match)
            filtered = filtered.filter(a => ['Pending', 'Applied', 'Under Process'].includes(a.Status || 'Pending'));
        } else {
            filtered = filtered.filter(a => (a.Status || 'Pending') === cscCurrentFilterStatus);
        }
    }

    // Service Chip filter
    if (cscCurrentFilterService !== 'all') {
        const filterLower = cscCurrentFilterService.toLowerCase();
        filtered = filtered.filter(a => {
            if (!a.ServiceType) return false;
            const stLower = a.ServiceType.toLowerCase();
            return stLower === filterLower || stLower.includes(filterLower) || filterLower.includes(stLower);
        });
    }

    // Payment Filter
    const paySelect = document.getElementById('cscPaymentFilter');
    const payVal = paySelect ? paySelect.value : cscCurrentFilterPayment;
    if (payVal === 'due') {
        filtered = filtered.filter(a => (parseFloat(a.DueAmount) || 0) > 0);
    } else if (payVal === 'paid') {
        filtered = filtered.filter(a => (parseFloat(a.DueAmount) || 0) <= 0);
    }

    // Date Filter
    const dateSelect = document.getElementById('cscDateFilter');
    const dateVal = dateSelect ? dateSelect.value : cscCurrentFilterDate;
    if (dateVal !== 'all') {
        const todayStr = new Date().toISOString().split('T')[0];
        const now = new Date();
        if (dateVal === 'today') {
            filtered = filtered.filter(a => (a.ApplyDate || '').startsWith(todayStr));
        } else if (dateVal === 'week') {
            const oneWeekAgo = new Date();
            oneWeekAgo.setDate(now.getDate() - 7);
            filtered = filtered.filter(a => {
                if (!a.ApplyDate) return false;
                const d = parseApiDate(a.ApplyDate);
                return d ? d >= oneWeekAgo : false;
            });
        } else if (dateVal === 'month') {
            const yearMonth = todayStr.substring(0, 7);
            filtered = filtered.filter(a => (a.ApplyDate || '').startsWith(yearMonth));
        }
    }

    // Text Search Filter
    if (cscCurrentSearchQuery) {
        const q = cscCurrentSearchQuery.toLowerCase().trim();
        const queryDigits = q.replace(/\D/g, '');
        filtered = filtered.filter(a => {
            const aadhaarDigits = (a.CustomerAadhaar || '').replace(/\D/g, '');
            const aadhaarMatch = queryDigits.length >= 3 && (aadhaarDigits.includes(queryDigits) || (a.LinkedCustomerAadhaar || '').replace(/\D/g, '').includes(queryDigits));
            const text = [
                a.AckNumber || '',
                a.CustomerName || '',
                a.CustomerPhone || '',
                a.CustomerAadhaar || '',
                a.ServiceType || '',
                a.PortalName || '',
                a.CertificateDocNo || '',
                a.StatusRemarks || ''
            ].join(' ').toLowerCase();
            return text.includes(q) || aadhaarMatch;
        });
    }

    renderCSCTable(filtered);
}

function renderCSCTable(list) {
    const tbody = document.getElementById('cscTableBody');
    const summaryEl = document.getElementById('cscTableSummary');
    if (!tbody) return;

    if (!list) list = [];

    // Latest first sorting: ApplyDate DESC, AppID DESC
    list.sort((a, b) => {
        const dA = parseApiDate(a.ApplyDate);
        const dB = parseApiDate(b.ApplyDate);
        const da = dA ? dA.getTime() : 0;
        const db = dB ? dB.getTime() : 0;
        if (db !== da) return db - da;
        return (b.AppID || 0) - (a.AppID || 0);
    });

    const totalCSC = list.length;

    if (summaryEl) {
        summaryEl.innerHTML = `Kul <b>${totalCSC}</b> Aavedan (Forms) dikh rahe hain (Total: ${allCSCApplications.length})`;
    }

    if (totalCSC === 0) {
        let emptyTitle = "Koi CSC Aavedan Nahi Mila";
        let emptySubtitle = "Diye gaye filter ke hisaab se koi record maujood nahi hai.";
        let icon = "📋";

        const paySelect = document.getElementById('cscPaymentFilter');
        const payVal = paySelect ? paySelect.value : cscCurrentFilterPayment;

        if (cscCurrentFilterStatus === 'Delivered') {
            emptyTitle = "Koi Delivered Aavedan Nahi Hai";
            emptySubtitle = "Abhi tak kisi bhi aavedan ka status 'Delivered' nahi hua hai.";
            icon = "📦";
        } else if (cscCurrentFilterStatus === 'Rejected') {
            emptyTitle = "Koi Rejected / Objection Aavedan Nahi Hai";
            emptySubtitle = "Sabhi forms surakshit hain! Koi aavedan reject ya aapatti me nahi hai.";
            icon = "🎉";
        } else if (payVal === 'due') {
            emptyTitle = "Koi Bakiya (Due) Fees Nahi Hai";
            emptySubtitle = "Sabhi aavedano ki fees poori tarah chukayi ja chuki hai (Zero Due Balance).";
            icon = "💳";
        } else if (cscCurrentFilterStatus === 'Pending' || cscCurrentFilterStatus === 'pending_and_process') {
            emptyTitle = "Koi Pending Aavedan Nahi Hai";
            emptySubtitle = "Sabhi forms process ho chuke hain ya ban kar taiyar hain.";
            icon = "✅";
        } else if (cscCurrentFilterStatus === 'Under Process') {
            emptyTitle = "Koi Under Process Aavedan Nahi Hai";
            emptySubtitle = "Filhal koi form karyavahi ke antargat nahi hai.";
            icon = "⚙️";
        } else if (cscCurrentFilterStatus === 'Approved') {
            emptyTitle = "Koi Ready / Approved Aavedan Nahi Hai";
            emptySubtitle = "Abhi koi naya form ban kar taiyar nahi hua hai.";
            icon = "⏳";
        } else if (cscCurrentFilterService !== 'all') {
            emptyTitle = `"${escapeHtml(cscCurrentFilterService)}" me Koi Aavedan Nahi`;
            emptySubtitle = "Is seva category me abhi tak koi form darz nahi kiya gaya.";
            icon = "📂";
        } else if (cscCurrentSearchQuery) {
            emptyTitle = `"${escapeHtml(cscCurrentSearchQuery)}" Se Milta Koi Form Nahi Mila`;
            emptySubtitle = "Customer naam, mobile number, ya token number dobara jaanchiye.";
            icon = "🔍";
        }

        tbody.innerHTML = `
            <tr>
                <td colspan="9" style="text-align: center; padding: 48px 20px; color: var(--text-muted);">
                    <div style="font-size: 42px; margin-bottom: 12px; filter: drop-shadow(0 2px 8px rgba(0,0,0,0.3));">${icon}</div>
                    <b style="font-size: 16px; color: #ffffff; display: block; margin-bottom: 6px;">${emptyTitle}</b>
                    <div style="font-size: 13px; color: var(--text-muted); max-width: 440px; margin: 0 auto 18px auto; line-height: 1.5;">
                        ${emptySubtitle}
                    </div>
                    <div style="display: flex; gap: 10px; justify-content: center; align-items: center; flex-wrap: wrap;">
                        <button class="btn-primary btn-sm" onclick="resetCSCFilters()" style="padding: 7px 16px; font-weight: 600;">
                            🔄 Sabhi Aavedan Dekhein (Reset Filter)
                        </button>
                        <button class="btn-ghost btn-sm" onclick="openNewCSCModal()" style="padding: 7px 16px;">
                            ➕ Naya Aavedan Banayein
                        </button>
                    </div>
                </td>
            </tr>
        `;
        renderUniversalPaginationUI({
            containerId: 'cscPagination',
            infoId: 'cscPaginationInfo',
            currentPage: 1,
            pageSize: cscPageSize,
            totalItems: 0,
            onPageChangeFnName: 'changeCSCPage'
        });
        return;
    }

    const totalCSCPages = Math.ceil(totalCSC / cscPageSize) || 1;
    if (cscCurrentPage > totalCSCPages) cscCurrentPage = totalCSCPages;
    if (cscCurrentPage < 1) cscCurrentPage = 1;

    const startIdx = (cscCurrentPage - 1) * cscPageSize;
    const pagedList = list.slice(startIdx, startIdx + cscPageSize);

    const todayStr = new Date().toISOString().split('T')[0];

    tbody.innerHTML = pagedList.map(app => {
        const theme = getCSCServiceTheme(app.ServiceType);
        const totalFee = parseFloat(app.TotalFee) || 0;
        const paidFee = parseFloat(app.PaidAmount) || 0;
        const dueFee = parseFloat(app.DueAmount) || 0;

        let elecInfo = null;
        try {
            if (app.StatusRemarks && app.StatusRemarks.startsWith('{')) {
                elecInfo = JSON.parse(app.StatusRemarks);
            }
        } catch (_) { }

        // Status pill classes
        let statusCls = 'status-pending';
        let statusLabel = app.Status || 'Pending';
        if (statusLabel === 'Under Process') statusCls = 'status-process';
        else if (statusLabel === 'Approved') statusCls = 'status-approved';
        else if (statusLabel === 'Delivered') statusCls = 'status-delivered';
        else if (statusLabel === 'Rejected') statusCls = 'status-rejected';

        // Target Date Overdue calculation
        let dateDisplay = '-';
        let isOverdue = false;
        if (app.ExpectedDate) {
            const expStr = app.ExpectedDate.split('T')[0];
            dateDisplay = formatIndianDate(app.ExpectedDate);
            if (expStr < todayStr && app.Status !== 'Delivered' && app.Status !== 'Approved' && app.Status !== 'Rejected') {
                isOverdue = true;
            }
        }

        // Masked Aadhaar with eye reveal
        let aadhaarText = '';
        if (app.CustomerAadhaar) {
            aadhaarText = renderAadhaarWithEye(app.CustomerAadhaar, { fontSize: '11px', color: '#94a3b8' });
        }

        const phoneVal = app.CustomerPhone ? escapeHtml(app.CustomerPhone) : '';

        return `
            <tr>
                <!-- Universal Serial Number (Dedicated Separate Column) -->
                <td class="cell-center" style="vertical-align: middle;">
                    <button type="button" 
                            class="csc-sn-pill" 
                            onclick="openCSCDetailModal(${app.AppID})" 
                            title="Universal Serial No: ${escapeHtml(app.SNCode || ('SN-' + app.GlobalSerialNo))} (Click karke Poori Detail Dekhein)">
                        <i data-lucide="file-text" width="12" height="12"></i>
                        <span>${escapeHtml(app.SNCode || (app.GlobalSerialNo ? 'SN-' + app.GlobalSerialNo : '-'))}</span>
                    </button>
                </td>

                <!-- Ack Number & Date (Original Unaltered Column) -->
                <td>
                    <div onclick="openCSCDetailModal(${app.AppID})" 
                         class="csc-ack-pill"
                         title="Poori detail dekhne ke liye click karein">
                        <i data-lucide="eye" width="12" height="12"></i>
                        <span>${escapeHtml(app.AckNumber || 'PENDING')}</span>
                    </div>
                    <div style="font-size: 11px; color: var(--text-muted); margin-top: 3px; display: flex; align-items: center; gap: 4px; flex-wrap: wrap;">
                        <span>📅 ${formatIndianDate(app.ApplyDate)}</span>
                        <span style="display: inline-flex; align-items: center; gap: 2px;">${formatTime(app.CreatedAt) ? `<i data-lucide="clock" width="10" height="10"></i> ${formatTime(app.CreatedAt)}` : ''}</span>
                    </div>
                </td>

                <!-- Customer Details -->
                <td>
                    <div style="display: flex; align-items: center; gap: 6px;">
                        <span class="csc-cust-name" onclick="filterCSCByCustomerName('${escapeInlineArg(app.CustomerName)}')" title="Is customer ke sabhi aavedan khojein">${escapeHtml(app.CustomerName)}</span>
                        ${app.CustomerID ? `
                            <button class="btn-icon-mini" onclick="openCustomer360Modal(${app.CustomerID}, true)" title="Customer 360 Profile"><i data-lucide="external-link" width="12" height="12"></i></button>
                            <button class="btn-icon-mini" onclick="openCustomerDocsModal(${app.CustomerID}, '${escapeInlineArg(app.CustomerName)}')" title="${escapeHtml(app.CustomerName)} ke dastavej (Documents) dekhein" style="color: #0284c7;"><i data-lucide="paperclip" width="12" height="12"></i></button>
                        ` : ''}
                    </div>
                    <div style="display: flex; gap: 8px; align-items: center; margin-top: 2px; flex-wrap: wrap;">
                        ${phoneVal ? `
                            <span style="display: inline-flex; align-items: center; gap: 4px; font-size: 11.5px; color: var(--text-muted);">
                                <span>📞 ${phoneVal}</span>
                                <button type="button" class="btn-copy-mini" data-copy-phone="${phoneVal}" title="Mobile number copy karein">
                                    <i data-lucide="copy" width="11" height="11"></i>
                                </button>
                                <button class="btn-icon-mini" onclick="openWhatsAppChat('${escapeInlineArg(app.CustomerPhone || '')}', 'Namaste ${escapeInlineArg(app.CustomerName)}, aapke ${escapeInlineArg(app.ServiceType)} (Ack: ${escapeInlineArg(app.AckNumber)}) ka status: ${escapeInlineArg(app.Status)} hai.')" title="WhatsApp Chat">
                                    <i data-lucide="message-circle" width="12" height="12" style="color: #22c55e;"></i>
                                </button>
                            </span>
                        ` : ''}
                        ${aadhaarText}
                        ${app.DateOfBirth ? `<span style="font-size: 11px; color: var(--text-muted); display: inline-flex; align-items: center; gap: 2px;">🎂 ${formatIndianDate(app.DateOfBirth)}</span>` : ''}
                    </div>
                </td>

                <!-- Service -->
                <td>
                    <span class="csc-service-badge ${theme.cls}">
                        ${theme.label}
                    </span>
                    ${elecInfo && elecInfo.consumerNo ? `
                        <div style="font-size: 11px; color: #38bdf8; font-weight: 700; margin-top: 3px;">
                            ⚡ Khata: ${escapeHtml(elecInfo.consumerNo)}
                        </div>
                    ` : ''}
                </td>

                <!-- Target Date -->
                <td>
                    <div class="${isOverdue ? 'csc-date-overdue' : ''}" style="font-size: 12.5px;">
                        ${isOverdue ? '<i data-lucide="alert-circle" width="14" height="14"></i>' : ''}
                        <span>${dateDisplay}</span>
                    </div>
                    ${app.CompletionDate ? `<div style="font-size: 11px; color: var(--universal-amt-pos); font-weight: 600; margin-top: 2px;" title="Kam Poora Hua">🏁 Done: ${formatIndianDate(app.CompletionDate)}</div>` : ''}
                    ${isOverdue ? '<span class="badge" style="font-size: 10px; background: rgba(239, 68, 68, 0.2); color: #f87171; margin-top: 2px;">Late / Overdue</span>' : ''}
                </td>

                <!-- Fees & Due -->
                <td>
                    <div class="csc-fee-stack">
                        <span class="csc-total-fee c360-num">₹${totalFee.toLocaleString('en-IN')}</span>
                        <div style="display: flex; gap: 6px; align-items: center; flex-wrap: wrap; margin-top: 2px;">
                            ${elecInfo && elecInfo.remainingBill !== undefined ? `
                                <span class="badge" style="background: rgba(245, 158, 11, 0.15); color: #f59e0b; font-size: 10.5px; font-weight: 800; border: 1px dashed rgba(245, 158, 11, 0.4);" title="Bacha Hua Bill (Arrear)">
                                    Bacha: ₹${Number(elecInfo.remainingBill).toLocaleString('en-IN')}
                                </span>
                            ` : ''}
                            ${paidFee > 0 ? `<span class="amt-pos" style="font-size: 11px; font-weight: 700;">+₹${paidFee.toLocaleString('en-IN')}</span>` : ''}
                            ${dueFee > 0 ? `
                                <span class="badge badge-due amt-neg" style="font-size: 11px; font-weight: 700;">−₹${dueFee.toLocaleString('en-IN')} Due</span>
                            ` : `
                                <span class="badge badge-paid amt-pos" style="font-size: 11px;">✅ Paid</span>
                            `}
                        </div>
                    </div>
                </td>

                <!-- Status Pill -->
                <td>
                    <span class="csc-status-pill ${statusCls}" onclick="openCSCStatusModal(${app.AppID})" title="Status badalne ke liye click karein">
                        <span class="dot"></span>
                        <span>${statusLabel}</span>
                        <i data-lucide="chevron-down" width="11" height="11"></i>
                    </span>
                </td>

                <!-- Certificate / Doc Number -->
                <td>
                    ${elecInfo ? `
                        <div style="font-weight: 700; font-size: 12px; color: #34d399;">
                            ⚡ ${escapeHtml(elecInfo.consumerNo || app.CertificateDocNo || '-')}
                        </div>
                        <div style="font-size: 10.5px; color: var(--text-muted); margin-top: 1px;">
                            Bill: ${escapeHtml(elecInfo.billNo || '-')}
                        </div>
                    ` : (app.CertificateDocNo ? `
                        <div style="font-weight: 700; font-size: 12px; color: #34d399;">
                            ${escapeHtml(app.CertificateDocNo)}
                        </div>
                    ` : `
                        <span style="font-size: 11.5px; color: var(--text-muted); font-style: italic;">Taiyar hone par aayega</span>
                    `)}
                </td>

                <!-- Actions -->
                <td style="text-align: center; width: 65px;">
                    <button type="button" class="table-menu-trigger-btn csc-menu-trigger-btn" onclick="toggleCSCActionMenu(event, ${app.AppID})" title="Kriya (3 Dots Menu)" style="display: inline-flex; align-items: center; justify-content: center; width: 34px; height: 34px; border-radius: 8px; border: 1.5px solid var(--border-row, #cbd5e1); background: var(--bg-card); color: var(--text-primary); cursor: pointer; transition: all 0.15s ease;">
                        <i data-lucide="more-vertical" width="16" height="16"></i>
                    </button>
                </td>
            </tr>
        `;
    }).join('');

    renderUniversalPaginationUI({
        containerId: 'cscPagination',
        infoId: 'cscPaginationInfo',
        currentPage: cscCurrentPage,
        pageSize: cscPageSize,
        totalItems: totalCSC,
        onPageChangeFnName: 'changeCSCPage'
    });

    refreshIcons(tbody);
}

// --------------------------------------------------------------------------
// FLOATING 3-DOT ACTION MENU FOR CSC WORK TRACKER
// --------------------------------------------------------------------------
let activeCscDropdownId = null;

function toggleCSCActionMenu(e, appId) {
    if (e) {
        e.preventDefault();
        e.stopPropagation();
    }

    const existingMenu = document.getElementById('cscFloatingActionMenu');
    if (existingMenu && activeCscDropdownId === appId) {
        closeCSCActionMenu();
        return;
    }

    closeAllActionMenus();

    const app = (allCSCApplications || []).find(a => Number(a.AppID) === Number(appId))
        || (window._c360CscApps || []).find(a => Number(a.AppID) === Number(appId));
    if (!app) return;

    const triggerBtn = (e && e.currentTarget) ? e.currentTarget : (e && e.target ? e.target.closest('.csc-menu-trigger-btn, .table-menu-trigger-btn') : null);
    if (!triggerBtn) return;

    triggerBtn.classList.add('active');
    activeCscDropdownId = appId;

    const safeName = escapeHtml(app.CustomerName || 'Grahak');
    const safeService = escapeHtml(app.ServiceType || 'CSC Seva');
    const totalFee = parseFloat(app.TotalFee) || 0;
    const dueFee = parseFloat(app.DueAmount) || 0;
    const statusLabel = escapeHtml(app.Status || 'Pending');

    let statusPillClass = 'status-pending';
    if (app.Status === 'Under Process') statusPillClass = 'status-process';
    else if (app.Status === 'Approved') statusPillClass = 'status-approved';
    else if (app.Status === 'Delivered') statusPillClass = 'status-delivered';
    else if (app.Status === 'Rejected') statusPillClass = 'status-rejected';

    const menu = document.createElement('div');
    menu.id = 'cscFloatingActionMenu';
    menu.className = 'cust-action-dropdown-menu';

    menu.innerHTML = `
        <div class="cad-header">
            <div class="cad-title-row">
                <span class="cad-name" title="${safeName}">${safeName}</span>
                <span class="cad-id font-mono">#${escapeHtml(app.AckNumber || 'ID-' + app.AppID)}</span>
            </div>
            <div style="display: flex; align-items: center; justify-content: space-between; gap: 6px; margin-top: 5px;">
                <span style="font-size: 11px; color: var(--text-muted); max-width: 150px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">
                    📂 ${safeService}
                </span>
                <span class="csc-status-pill ${statusPillClass}" style="padding: 2px 7px; font-size: 10px; cursor: default;">
                    <span class="dot"></span>
                    <span>${statusLabel}</span>
                </span>
            </div>
            ${dueFee > 0 ? `
                <div style="font-size: 10.5px; color: #f87171; font-weight: 700; margin-top: 4px;">
                    ⚠️ Baaki (Due): ₹${dueFee.toLocaleString('en-IN')} (Kul: ₹${totalFee.toLocaleString('en-IN')})
                </div>
            ` : `
                <div style="font-size: 10.5px; color: #34d399; font-weight: 600; margin-top: 4px;">
                    ✅ Fees Paid Full: ₹${totalFee.toLocaleString('en-IN')}
                </div>
            `}
        </div>
        <div class="cad-items">
            <button type="button" class="cad-item" id="cscOptDetail">
                <span class="cad-icon blue"><i data-lucide="eye"></i></span>
                <div class="cad-label">
                    <span class="cad-primary">Aavedan Poori Detail</span>
                    <span class="cad-secondary">Form vivran, timeline &amp; documents</span>
                </div>
            </button>
            <button type="button" class="cad-item" id="cscOptStatus">
                <span class="cad-icon indigo"><i data-lucide="rotate-ccw"></i></span>
                <div class="cad-label">
                    <span class="cad-primary">Status Update Karein</span>
                    <span class="cad-secondary">Process, Approved, Delivered mark karein</span>
                </div>
            </button>
            <button type="button" class="cad-item" id="cscOptReceipt">
                <span class="cad-icon purple"><i data-lucide="printer"></i></span>
                <div class="cad-label">
                    <span class="cad-primary">Customer Slip (पावती)</span>
                    <span class="cad-secondary">Print karein ya customer ko receipt dein</span>
                </div>
            </button>
            <button type="button" class="cad-item" id="cscOptWhatsApp">
                <span class="cad-icon green"><i data-lucide="message-circle"></i></span>
                <div class="cad-label">
                    <span class="cad-primary">WhatsApp Alert Bhejein</span>
                    <span class="cad-secondary">Status update grahak ko direct message</span>
                </div>
            </button>
            ${app.CustomerID ? `
                <button type="button" class="cad-item" id="cscOptCustProfile">
                    <span class="cad-icon cyan"><i data-lucide="user-check"></i></span>
                    <div class="cad-label">
                        <span class="cad-primary">Customer 360° Profile</span>
                        <span class="cad-secondary">Khata, billing &amp; profile hisaab</span>
                    </div>
                </button>
                <button type="button" class="cad-item" id="cscOptCustDocs">
                    <span class="cad-icon orange"><i data-lucide="paperclip"></i></span>
                    <div class="cad-label">
                        <span class="cad-primary">Customer Dastavej (Docs)</span>
                        <span class="cad-secondary">Aadhaar, photo va upload files</span>
                    </div>
                </button>
            ` : ''}
            <button type="button" class="cad-item" id="cscOptEdit">
                <span class="cad-icon cyan"><i data-lucide="edit-2"></i></span>
                <div class="cad-label">
                    <span class="cad-primary">Aavedan Edit Karein</span>
                    <span class="cad-secondary">Fees, date, token no badlein</span>
                </div>
            </button>
            <div class="cad-divider"></div>
            <button type="button" class="cad-item danger" id="cscOptDelete">
                <span class="cad-icon red"><i data-lucide="trash-2"></i></span>
                <div class="cad-label">
                    <span class="cad-primary text-danger">Aavedan Delete Karein</span>
                    <span class="cad-secondary">Is form record ko system se hatayein</span>
                </div>
            </button>
        </div>
    `;

    menu.querySelector('#cscOptDetail')?.addEventListener('click', () => {
        closeCSCActionMenu();
        openCSCDetailModal(app.AppID);
    });
    menu.querySelector('#cscOptStatus')?.addEventListener('click', () => {
        closeCSCActionMenu();
        openCSCStatusModal(app.AppID);
    });
    menu.querySelector('#cscOptReceipt')?.addEventListener('click', () => {
        closeCSCActionMenu();
        openCSCReceiptModal(app.AppID);
    });
    menu.querySelector('#cscOptWhatsApp')?.addEventListener('click', () => {
        closeCSCActionMenu();
        sendCSCWhatsApp(app.AppID);
    });
    menu.querySelector('#cscOptCustProfile')?.addEventListener('click', () => {
        closeCSCActionMenu();
        if (app.CustomerID) openCustomer360Modal(app.CustomerID, true);
    });
    menu.querySelector('#cscOptCustDocs')?.addEventListener('click', () => {
        closeCSCActionMenu();
        if (app.CustomerID) openCustomerDocsModal(app.CustomerID, app.CustomerName);
    });
    menu.querySelector('#cscOptEdit')?.addEventListener('click', () => {
        closeCSCActionMenu();
        openEditCSCModal(app.AppID);
    });
    menu.querySelector('#cscOptDelete')?.addEventListener('click', () => {
        closeCSCActionMenu();
        deleteCSCApplication(app.AppID);
    });

    positionFloatingMenu(menu, triggerBtn, 280);
}

function closeCSCActionMenu() {
    activeCscDropdownId = null;
    document.querySelectorAll('.csc-menu-trigger-btn.active').forEach(b => b.classList.remove('active'));
    const m = document.getElementById('cscFloatingActionMenu');
    if (m) {
        m.classList.remove('active');
        m.remove();
    }
}
window.toggleCSCActionMenu = toggleCSCActionMenu;
window.closeCSCActionMenu = closeCSCActionMenu;

// 3. Filter Actions (Status tabs, Service chips & KPI Cards)
function filterCSCByCard(type, cardEl) {
    // 1. Highlight active card visually
    document.querySelectorAll('#cscStatsGrid .csc-stat-card').forEach(c => c.classList.remove('active-card'));
    if (cardEl) {
        cardEl.classList.add('active-card');
    } else {
        const idMap = {
            'all': 'cscCardTotal',
            'pending_and_process': 'cscCardPending',
            'Approved': 'cscCardApproved',
            'Delivered': 'cscCardDelivered',
            'Rejected': 'cscCardRejected',
            'finance': 'cscCardFinance'
        };
        const target = document.getElementById(idMap[type]);
        if (target) target.classList.add('active-card');
    }

    // 2. Clear search, date, and service to match the stat card count
    cscCurrentSearchQuery = '';
    const sInp = document.getElementById('cscSearchInput');
    if (sInp) sInp.value = '';

    cscCurrentFilterDate = 'all';
    const dSel = document.getElementById('cscDateFilter');
    if (dSel) dSel.value = 'all';

    cscCurrentFilterService = 'all';
    document.querySelectorAll('#cscServiceChips .csc-chip').forEach(b => {
        b.classList.toggle('active', b.dataset.service === 'all');
    });

    const pSel = document.getElementById('cscPaymentFilter');

    // 3. Handle finance vs status types
    if (type === 'finance') {
        cscCurrentFilterStatus = 'all';
        document.querySelectorAll('#cscStatusTabs .csc-status-tab').forEach(b => {
            b.classList.toggle('active', b.dataset.status === 'all');
        });

        const dueCount = allCSCApplications.filter(a => (parseFloat(a.DueAmount) || 0) > 0).length;
        if (dueCount > 0) {
            cscCurrentFilterPayment = 'due';
            if (pSel) pSel.value = 'due';
            showToast(`⚠️ Bakiya Fees wale ${dueCount} aavedan filter kiye gaye.`, 'info');
        } else {
            cscCurrentFilterPayment = 'all';
            if (pSel) pSel.value = 'all';
            showToast(`✅ Koi fees bakiya nahi hai! Sabhi chukaye gaye aavedan dikh rahe hain.`, 'success');
        }
    } else {
        // Reset payment filter so zero-due applications are NOT excluded!
        cscCurrentFilterPayment = 'all';
        if (pSel) pSel.value = 'all';

        cscCurrentFilterStatus = type;

        // Synchronize tabs
        document.querySelectorAll('#cscStatusTabs .csc-status-tab').forEach(b => {
            if (type === 'pending_and_process') {
                b.classList.toggle('active', b.dataset.status === 'Pending');
            } else {
                b.classList.toggle('active', b.dataset.status === type);
            }
        });
    }

    filterCSCTable();
}

function setCSCStatusTab(status, btn) {
    cscCurrentFilterStatus = status;
    document.querySelectorAll('#cscStatusTabs .csc-status-tab').forEach(b => b.classList.remove('active'));
    if (btn) btn.classList.add('active');

    // Sync card active state
    document.querySelectorAll('#cscStatsGrid .csc-stat-card').forEach(c => c.classList.remove('active-card'));
    const idMap = {
        'all': 'cscCardTotal',
        'Pending': 'cscCardPending',
        'Under Process': 'cscCardPending',
        'Approved': 'cscCardApproved',
        'Delivered': 'cscCardDelivered',
        'Rejected': 'cscCardRejected'
    };
    const card = document.getElementById(idMap[status]);
    if (card) card.classList.add('active-card');

    // If payment dropdown was stuck on 'due' and no due records exist, reset to 'all'
    const pSel = document.getElementById('cscPaymentFilter');
    const dueCount = allCSCApplications.filter(a => (parseFloat(a.DueAmount) || 0) > 0).length;
    if (pSel && pSel.value === 'due' && dueCount === 0) {
        pSel.value = 'all';
        cscCurrentFilterPayment = 'all';
    }

    filterCSCTable();
}

function setCSCServiceChip(service, btn) {
    cscCurrentFilterService = service;
    document.querySelectorAll('#cscServiceChips .csc-chip').forEach(b => b.classList.remove('active'));
    if (btn) btn.classList.add('active');
    filterCSCTable();
}

function filterCSCByStatus(status) {
    filterCSCByCard(status);
}

function filterCSCByPayment(pay) {
    const sel = document.getElementById('cscPaymentFilter');
    if (sel) sel.value = pay;
    cscCurrentFilterPayment = pay;

    // Sync cards
    document.querySelectorAll('#cscStatsGrid .csc-stat-card').forEach(c => c.classList.remove('active-card'));
    if (pay === 'due') {
        const fc = document.getElementById('cscCardFinance');
        if (fc) fc.classList.add('active-card');
    }
    filterCSCTable();
}

function filterCSCByCustomerName(name) {
    if (!name) return;
    const sInp = document.getElementById('cscSearchInput');
    if (sInp) sInp.value = name;
    cscCurrentSearchQuery = name;
    filterCSCTable();
    showToast(`Customer "${name}" ke aavedan filter kiye gaye.`, 'info');
}

function onCSCSearchInput() {
    const inp = document.getElementById('cscSearchInput');
    cscCurrentSearchQuery = inp ? inp.value : '';
    filterCSCTable();
}

function resetCSCFilters() {
    cscCurrentFilterStatus = 'all';
    cscCurrentFilterService = 'all';
    cscCurrentFilterPayment = 'all';
    cscCurrentFilterDate = 'all';
    cscCurrentSearchQuery = '';

    const sInp = document.getElementById('cscSearchInput');
    if (sInp) sInp.value = '';

    const pSel = document.getElementById('cscPaymentFilter');
    if (pSel) pSel.value = 'all';

    const dSel = document.getElementById('cscDateFilter');
    if (dSel) dSel.value = 'all';

    document.querySelectorAll('#cscStatusTabs .csc-status-tab').forEach(b => {
        b.classList.toggle('active', b.dataset.status === 'all');
    });

    document.querySelectorAll('#cscServiceChips .csc-chip').forEach(b => {
        b.classList.toggle('active', b.dataset.service === 'all');
    });

    document.querySelectorAll('#cscStatsGrid .csc-stat-card').forEach(c => {
        c.classList.toggle('active-card', c.id === 'cscCardTotal');
    });

    filterCSCTable();
    showToast('Sabhi filters reset kar diye gaye.', 'info');
}

// ============ CSC DYNAMIC MULTI-NOTES SYSTEM ============
function addCSCNoteRow(initialValue = '') {
    const container = document.getElementById('cscNotesContainer');
    if (!container) return;

    const rowId = 'csc_note_' + Math.random().toString(36).substring(2, 9);
    const count = container.querySelectorAll('.csc-note-row').length + 1;

    const row = document.createElement('div');
    row.className = 'csc-note-row';
    row.id = rowId;
    row.style.cssText = 'display: flex; align-items: center; gap: 8px; margin-bottom: 6px;';

    row.innerHTML = `
        <span class="csc-note-num-badge" title="Tippani / Note #${count}">#${count}</span>
        <input type="text" class="form-control csc-note-input" placeholder="Vivran / Note #${count} likhein (Enter daba kar naya note jodein)..." value="${escapeHtml(initialValue)}" onkeydown="handleCSCNoteKeydown(event, '${rowId}')" style="flex: 1;">
        <button type="button" class="btn-ghost btn-sm csc-remove-note-btn" onclick="removeCSCNoteRow('${rowId}')" title="Yeh note hatayein">
            <i data-lucide="trash-2" width="13" height="13"></i>
        </button>
    `;

    container.appendChild(row);
    if (typeof refreshIcons === 'function') {
        refreshIcons(row);
    } else if (typeof lucide !== 'undefined' && lucide.createIcons) {
        try { lucide.createIcons({ root: row }); } catch (e) { }
    }
    renumberCSCNotes();

    // Auto focus new input if user triggered it
    if (!initialValue) {
        const inp = row.querySelector('.csc-note-input');
        if (inp) inp.focus();
    }
}

function removeCSCNoteRow(rowId) {
    const row = document.getElementById(rowId);
    if (!row) return;
    const container = document.getElementById('cscNotesContainer');
    if (!container) return;

    const rows = container.querySelectorAll('.csc-note-row');
    if (rows.length <= 1) {
        const inp = row.querySelector('.csc-note-input');
        if (inp) inp.value = '';
        return;
    }

    row.remove();
    renumberCSCNotes();
}

function renumberCSCNotes() {
    const container = document.getElementById('cscNotesContainer');
    if (!container) return;
    const rows = container.querySelectorAll('.csc-note-row');
    rows.forEach((r, idx) => {
        const num = idx + 1;
        const badge = r.querySelector('.csc-note-num-badge');
        if (badge) {
            badge.textContent = `#${num}`;
            badge.title = `Tippani / Note #${num}`;
        }
        const inp = r.querySelector('.csc-note-input');
        if (inp && !inp.value) {
            inp.placeholder = `Vivran / Note #${num} likhein (Enter daba kar naya note jodein)...`;
        }
        const delBtn = r.querySelector('.csc-remove-note-btn');
        if (delBtn) {
            if (rows.length === 1) {
                delBtn.style.opacity = '0.35';
                delBtn.title = 'Aakhiri note clear karein';
            } else {
                delBtn.style.opacity = '1';
                delBtn.title = `Note #${num} hatayein`;
            }
        }
    });
}

function handleCSCNoteKeydown(evt, rowId) {
    if (evt.key === 'Enter') {
        evt.preventDefault();
        addCSCNoteRow('');
    } else if (evt.key === 'Backspace' && evt.target.value === '') {
        const container = document.getElementById('cscNotesContainer');
        if (!container) return;
        const rows = Array.from(container.querySelectorAll('.csc-note-row'));
        if (rows.length > 1) {
            evt.preventDefault();
            const currIdx = rows.findIndex(r => r.id === rowId);
            const prevRow = currIdx > 0 ? rows[currIdx - 1] : rows[1];
            removeCSCNoteRow(rowId);
            if (prevRow) {
                const prevInp = prevRow.querySelector('.csc-note-input');
                if (prevInp) {
                    prevInp.focus();
                    try { prevInp.setSelectionRange(prevInp.value.length, prevInp.value.length); } catch (e) { }
                }
            }
        }
    }
}

function setCSCNotesInUI(notes) {
    const container = document.getElementById('cscNotesContainer');
    if (!container) return;
    container.innerHTML = '';

    let list = [];
    if (Array.isArray(notes)) {
        list = notes;
    } else if (typeof notes === 'string' && notes.trim()) {
        list = notes.split(/\r?\n/).map(s => s.replace(/^[•\-\*]\s*/, '').trim()).filter(Boolean);
    }

    if (list.length === 0) {
        addCSCNoteRow('');
    } else {
        list.forEach(n => addCSCNoteRow(n));
    }
}

function getCSCNotesJoined() {
    const container = document.getElementById('cscNotesContainer');
    if (!container) {
        return document.getElementById('cscStatusRemarks')?.value?.trim() || '';
    }
    const inputs = container.querySelectorAll('.csc-note-input');
    const notes = [];
    inputs.forEach(inp => {
        const val = inp.value.trim();
        if (val) notes.push(val);
    });
    const joined = notes.join('\n');
    const hiddenRemarks = document.getElementById('cscStatusRemarks');
    if (hiddenRemarks) hiddenRemarks.value = joined;
    return joined;
}

// Global Customer Document Badge & Viewer Helpers
window.updateCustomerDocBadge = async function (badgeId, customerId, customerName = '') {
    const el = document.getElementById(badgeId);
    if (!el) return;
    if (!customerId) {
        el.style.display = 'none';
        return;
    }
    el.dataset.customerId = customerId;
    el.dataset.customerName = customerName || '';
    el.style.display = 'inline-flex';
    try {
        const res = await fetch(`/api/documents/customer/${encodeURIComponent(customerId)}`);
        const json = await res.json();
        const docs = Array.isArray(json.data) ? json.data : (json.data?.documents || (Array.isArray(json) ? json : []));
        const count = docs.length;
        const countEl = el.querySelector('#cscCustomerDocCount') || el.querySelector('.doc-count');
        if (countEl) {
            countEl.textContent = count;
        } else {
            el.innerHTML = `📎 Docs (${count})`;
        }
        el.title = `${customerName || 'Grahak'} ke ${count} dastavej dekhein / upload karein`;
    } catch (e) {
        el.title = 'Customer Dastavej dekhein';
    }
    el.onclick = function (e) {
        if (e) e.stopPropagation();
        if (typeof openCustomerDocsModal === 'function') {
            openCustomerDocsModal(customerId, customerName || '');
        }
    };
};

window.openCSCCustomerDocs = function () {
    const custSel = document.getElementById('cscCustomerSelect');
    const custId = (custSel && custSel.value) ? parseInt(custSel.value) : null;
    const custName = (document.getElementById('cscCustName')?.value || '').trim();
    if (!custId) {
        showToast('Pehle grahak chunein ya dastavej upload section use karein', 'info');
        return;
    }
    if (typeof openCustomerDocsModal === 'function') {
        openCustomerDocsModal(custId, custName);
    }
};

// 4. New / Edit CSC Modal Logic
function openNewCSCModal(preselectCustomerId = null) {
    const modal = document.getElementById('cscNewAppModal');
    if (!modal) return;

    document.getElementById('cscModalTitle').innerHTML = '<i data-lucide="clipboard-check" style="color: #10b981;"></i> <span>Naya CSC Aavedan (Application Entry)</span>';
    document.getElementById('cscSaveBtnText').textContent = 'Aavedan Save Karein';
    document.getElementById('cscAppId').value = '';

    // Reset Form
    document.getElementById('cscAppForm').reset();
    if (document.getElementById('cscCustDob')) document.getElementById('cscCustDob').value = '';
    const cscDocBadge = document.getElementById('cscCustomerDocBadge');
    if (cscDocBadge) cscDocBadge.style.display = 'none';

    // Multi-notes container fresh reset
    setCSCNotesInUI('');

    // Aadhaar auto-fill chip bhi saaf karo (form.reset() sirf inputs clear karta hai)
    if (document.getElementById('cscAadhaarChip')) document.getElementById('cscAadhaarChip').innerHTML = '';
    if (document.getElementById('cscPhoneChip')) document.getElementById('cscPhoneChip').innerHTML = '';
    if (typeof hideFamilyPicker === 'function') hideFamilyPicker();

    // Default Dates
    const today = new Date();
    const todayStr = today.toISOString().split('T')[0];
    document.getElementById('cscApplyDate').value = todayStr;

    // Ensure allCSCServices fallback if not yet fetched
    if (!allCSCServices || allCSCServices.length === 0) {
        allCSCServices = DEFAULT_FALLBACK_CSC_SERVICES;
    }

    populateCustomerDropdowns();
    populateCSCServiceSelects();

    // Select first service by default and apply fees
    const sTypeSel = document.getElementById('cscServiceType');
    if (sTypeSel && sTypeSel.options.length > 1) {
        sTypeSel.selectedIndex = 1;
        onCSCServiceTypeChange();
    } else {
        document.getElementById('cscGovtFee').value = 0;
        document.getElementById('cscOperatorFee').value = 50;
        document.getElementById('cscTotalFee').value = 50;
        document.getElementById('cscPaidAmount').value = 50;
        calculateCSCFees();
    }

    if (window.UniversalDocUploader) {
        UniversalDocUploader.init('cscDocUploader', { entityType: 'csc', title: '📎 CSC Aavedan Dastavej (Upload & Rename)' });
        UniversalDocUploader.reset('cscDocUploader');
    }

    // If preselecting customer
    if (preselectCustomerId) {
        const custSel = document.getElementById('cscCustomerSelect');
        if (custSel) {
            custSel.value = preselectCustomerId;
            onCSCCustomerSelectChange();
        }
    }

    openModal('cscNewAppModal');
    refreshIcons(modal);
}

function openEditCSCModal(appId) {
    const app = allCSCApplications.find(a => a.AppID === appId);
    if (!app) {
        showToast('Application nahi mila', 'error');
        return;
    }

    const modal = document.getElementById('cscNewAppModal');
    if (!modal) return;

    document.getElementById('cscModalTitle').innerHTML = '<i data-lucide="edit-2" style="color: #3b82f6;"></i> <span>CSC Aavedan Edit Karein</span>';
    document.getElementById('cscSaveBtnText').textContent = 'Badlav Save Karein';
    document.getElementById('cscAppId').value = app.AppID;

    // Populate Fields
    const custSel = document.getElementById('cscCustomerSelect');
    if (custSel) custSel.value = app.CustomerID || '';

    document.getElementById('cscCustName').value = app.CustomerName || '';
    document.getElementById('cscCustPhone').value = app.CustomerPhone || '';
    document.getElementById('cscCustAadhaar').value = app.CustomerAadhaar || '';
    const linkedCust = (typeof allCustomersData !== 'undefined' && Array.isArray(allCustomersData))
        ? allCustomersData.find(c => c.CustomerID === app.CustomerID)
        : null;
    const dobInp = document.getElementById('cscCustDob');
    if (dobInp) {
        dobInp.value = app.DateOfBirth ? String(app.DateOfBirth).split('T')[0] : (linkedCust?.DateOfBirth ? String(linkedCust.DateOfBirth).split('T')[0] : '');
    }
    const pInp = document.getElementById('cscPortalName');
    if (pInp) pInp.value = app.PortalName || '';

    // Customer doc badge in edit mode
    if (app.CustomerID && typeof updateCustomerDocBadge === 'function') {
        updateCustomerDocBadge('cscCustomerDocBadge', app.CustomerID, app.CustomerName);
    } else {
        const cBadge = document.getElementById('cscCustomerDocBadge');
        if (cBadge) cBadge.style.display = 'none';
    }

    populateCSCServiceSelects();
    document.getElementById('cscServiceType').value = app.ServiceType || '';
    document.getElementById('cscAckNumber').value = app.AckNumber || '';

    if (app.ApplyDate) document.getElementById('cscApplyDate').value = app.ApplyDate.split('T')[0];
    if (app.ExpectedDate) document.getElementById('cscExpectedDate').value = app.ExpectedDate.split('T')[0];

    document.getElementById('cscGovtFee').value = app.GovtFee || 0;
    document.getElementById('cscOperatorFee').value = app.OperatorFee || 0;
    document.getElementById('cscTotalFee').value = app.TotalFee || 0;
    document.getElementById('cscPaidAmount').value = app.PaidAmount || 0;
    document.getElementById('cscPaymentMode').value = app.PaymentMode || 'Cash';
    document.getElementById('cscStatus').value = app.Status || 'Pending';
    const remHidden = document.getElementById('cscStatusRemarks');
    if (remHidden) remHidden.value = app.StatusRemarks || '';
    setCSCNotesInUI(app.StatusRemarks || '');

    calculateCSCFees();

    if (window.UniversalDocUploader) {
        UniversalDocUploader.init('cscDocUploader', { entityType: 'csc', title: '📎 CSC Aavedan Dastavej (Upload & Rename)' });
        UniversalDocUploader.reset('cscDocUploader');
        UniversalDocUploader.loadExisting('cscDocUploader', 'csc', app.AppID, app.CustomerID);
    }

    openModal('cscNewAppModal');
    refreshIcons(modal);
}

