function onCSCCustomerSelectChange() {
    const custSel = document.getElementById('cscCustomerSelect');
    const docBadge = document.getElementById('cscCustomerDocBadge');
    if (!custSel || !custSel.value) {
        if (docBadge) docBadge.style.display = 'none';
        if (window.UniversalDocUploader) {
            UniversalDocUploader.reset('cscDocUploader');
        }
        if (typeof renderUniversalDueAlert === 'function') renderUniversalDueAlert(null, 'cscDueAlertContainer', 'CSC');
        return;
    }

    const cId = parseInt(custSel.value);
    const cust = allCustomersData.find(c => c.CustomerID === cId);
    if (cust) {
        if (typeof renderUniversalDueAlert === 'function') {
            renderUniversalDueAlert(cust, 'cscDueAlertContainer', 'CSC');
        }
        const nameEl = document.getElementById('cscCustName');
        const phoneEl = document.getElementById('cscCustPhone');
        const aadhaarEl = document.getElementById('cscCustAadhaar');
        const dobEl = document.getElementById('cscCustDob');
        if (nameEl) nameEl.value = cust.CustomerName || '';
        if (phoneEl) {
            phoneEl.value = cust.Phone || '';
            if (typeof handleCSCPhoneInput === 'function') handleCSCPhoneInput(phoneEl);
        }
        if (aadhaarEl) {
            aadhaarEl.value = typeof formatAadhaarDisplay === 'function' ? formatAadhaarDisplay(cust.AadhaarNumber || '') : (cust.AadhaarNumber || '');
            if (typeof handleCSCAadhaarInput === 'function') handleCSCAadhaarInput(aadhaarEl);
        }
        if (dobEl) {
            dobEl.value = cust.DateOfBirth ? String(cust.DateOfBirth).split('T')[0] : '';
        }
        if (typeof updateCustomerDocBadge === 'function') {
            updateCustomerDocBadge('cscCustomerDocBadge', cust.CustomerID, cust.CustomerName);
        }
        // Load customer's past documents into uploader automatically
        if (window.UniversalDocUploader) {
            UniversalDocUploader.loadExisting('cscDocUploader', 'csc', null, cust.CustomerID);
        }
    }
}

function onCSCServiceTypeChange() {
    const sType = document.getElementById('cscServiceType').value;
    const govtInp = document.getElementById('cscGovtFee');
    const opInp = document.getElementById('cscOperatorFee');
    const totalInp = document.getElementById('cscTotalFee');
    const paidInp = document.getElementById('cscPaidAmount');
    const applyInp = document.getElementById('cscApplyDate');
    const expInp = document.getElementById('cscExpectedDate');

    if (!sType) return;

    // Find service in allCSCServices
    const sObj = allCSCServices.find(s => s.ServiceName === sType) ||
        allCSCServices.find(s => s.ServiceName.toLowerCase().startsWith(sType.toLowerCase())) ||
        allCSCServices.find(s => sType.toLowerCase().startsWith(s.ServiceName.toLowerCase()));

    if (sObj) {
        govtInp.value = sObj.GovtFee ?? 0;
        opInp.value = sObj.OperatorFee ?? 50;
        const total = (parseFloat(sObj.GovtFee) || 0) + (parseFloat(sObj.OperatorFee) || 0);
        totalInp.value = total;
        paidInp.value = total;

        // Auto-calculate expected delivery date
        const baseDate = (applyInp && applyInp.value) ? parseApiDate(applyInp.value) : new Date();
        if (baseDate) {
            const exp = new Date(baseDate.getTime());
            exp.setDate(exp.getDate() + (sObj.DefaultDays || 10));
            if (expInp) expInp.value = toLocalYMD(exp);
        }
    }
    calculateCSCFees();
}

function calculateCSCFees(fromTotal = false) {
    const gFee = parseFloat(document.getElementById('cscGovtFee').value) || 0;
    const opFee = parseFloat(document.getElementById('cscOperatorFee').value) || 0;
    const totalEl = document.getElementById('cscTotalFee');
    const paidEl = document.getElementById('cscPaidAmount');
    const dueEl = document.getElementById('cscDueAmountDisplay');

    let total = parseFloat(totalEl.value) || 0;
    if (!fromTotal) {
        total = gFee + opFee;
        totalEl.value = total;
    }

    const paid = parseFloat(paidEl.value) || 0;
    const due = Math.max(0, total - paid);

    if (dueEl) {
        dueEl.textContent = `₹${due.toLocaleString('en-IN')}`;
        dueEl.style.color = due > 0 ? '#f87171' : '#34d399';
        dueEl.style.background = due > 0 ? 'rgba(239, 68, 68, 0.15)' : 'rgba(16, 185, 129, 0.15)';
    }
}

function cleanCustomerName(name) {
    if (!name) return '';
    let s = String(name).trim();
    // 1. Remove prefixes like M/s., Shri, Smt, Sri, Mr., Mrs., Ms., Late, Doctor, Dr.
    s = s.replace(/^(?:M\/s\.?|M\/S\.?|Shri\.?|Smt\.?|Sri\.?|Mr\.?|Mrs\.?|Ms\.?|Late\.?|Doctor\.?|Dr\.?)\s*/i, '');
    s = s.replace(/^[:\-–—#=\s]+/, '').trim();
    s = s.replace(/\s+/g, ' ');
    // 2. Auto-correct ALL CAPS / uppercase to Title Case (e.g. "RAMESH KUMAR" -> "Ramesh Kumar")
    s = s.toLowerCase().replace(/(?:^|[\s\(\[\{\.\-\/])\p{L}/gu, m => m.toUpperCase());
    return s;
}

async function handleCSCFormSubmit(e) {
    e.preventDefault();
    const btn = document.getElementById('cscSaveBtn');

    const custName = cleanCustomerName(document.getElementById('cscCustName')?.value || '');
    if (!custName) {
        showToast('Kripya Grahak ka naam bharein!', 'error', 'Naam Zaroori');
        return;
    }
    const sType = document.getElementById('cscServiceType')?.value;
    if (!sType || !sType.trim()) {
        showToast('Kripya Service Type select karein!', 'error', 'Service Chunein');
        return;
    }

    btn.disabled = true;

    try {
        const appId = document.getElementById('cscAppId').value;
        const custSel = document.getElementById('cscCustomerSelect');
        const custId = custSel && custSel.value ? parseInt(custSel.value) : null;
        const portalInp = document.getElementById('cscPortalName');

        const payload = {
            CustomerID: custId,
            CustomerName: custName,
            CustomerPhone: document.getElementById('cscCustPhone').value.trim(),
            CustomerAadhaar: document.getElementById('cscCustAadhaar').value.trim(),
            CustomerDateOfBirth: document.getElementById('cscCustDob')?.value || null,
            DateOfBirth: document.getElementById('cscCustDob')?.value || null,
            PortalName: portalInp ? portalInp.value.trim() : '',
            ServiceType: sType,
            AckNumber: document.getElementById('cscAckNumber').value.trim(),
            ApplyDate: document.getElementById('cscApplyDate').value,
            ExpectedDate: document.getElementById('cscExpectedDate').value,
            GovtFee: parseFloat(document.getElementById('cscGovtFee').value) || 0,
            OperatorFee: parseFloat(document.getElementById('cscOperatorFee').value) || 0,
            TotalFee: parseFloat(document.getElementById('cscTotalFee').value) || 0,
            PaidAmount: parseFloat(document.getElementById('cscPaidAmount').value) || 0,
            PaymentMode: document.getElementById('cscPaymentMode').value,
            Status: document.getElementById('cscStatus').value,
            StatusRemarks: (typeof getCSCNotesJoined === 'function')
                ? getCSCNotesJoined()
                : (document.getElementById('cscStatusRemarks')?.value?.trim() || ''),
            SkipFamilyLink: document.getElementById('cscCustPhone')?._skipFamilyLink === true
        };

        if (window._pendingCSCElectricityData && (payload.ServiceType.includes('Electricity') || payload.ServiceType.includes('Bijli'))) {
            Object.assign(payload, window._pendingCSCElectricityData);
            window._pendingCSCElectricityData = null;
        }

        const url = appId ? `${API}/csc/${appId}` : `${API}/csc`;
        const method = appId ? 'PUT' : 'POST';

        const res = await fetch(url, {
            method,
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });
        const json = await res.json();

        if (!json.success) throw new Error(json.error || 'Failed to save application');

        showToast(appId ? 'CSC aavedan update ho gaya! ✅' : 'Naya CSC aavedan save ho gaya! ✅', 'success');
        if (json.autoRegisteredCustomer) {
            showToast(`🎉 Naya grahak '${json.autoRegisteredCustomer.CustomerName}' auto-register ho gaya! (ID: #${json.autoRegisteredCustomer.CustomerID})`, 'success');
            if (typeof loadMasterData === 'function') loadMasterData();
        }

        const createdId = appId || json.appId || json.data?.AppID;
        // Upload any staged documents with rename
        if (createdId && window.UniversalDocUploader && UniversalDocUploader.hasPendingFiles('cscDocUploader')) {
            try {
                await UniversalDocUploader.uploadPending('cscDocUploader', { entityType: 'csc', entityId: createdId, customerId: custId });
            } catch (upErr) {
                console.error('CSC doc upload error:', upErr);
            }
        }

        closeModal('cscNewAppModal');
        await loadCSCPage();
        await refreshAllActiveViews('csc_saved');
        triggerRealTimeSync('csc_saved');

        // Always show customer print slip / receipt modal with full application details
        if (createdId) {
            setTimeout(() => {
                openCSCReceiptModal(createdId);
            }, 120);
        }
    } catch (err) {
        showToast(err.message, 'error');
    } finally {
        btn.disabled = false;
    }
}

// ==========================================================================
// 4.1 CSC SERVICES & FEES CONFIGURATION MANAGEMENT ENGINE (100% LIVE DB)
// ==========================================================================
async function loadCSCServices() {
    const applyCSCServices = (services) => {
        allCSCServices = (services && services.length > 0) ? services : DEFAULT_FALLBACK_CSC_SERVICES;
        populateCSCServiceSelects();
        updateCSCServicesBadge();
        if (typeof currentPage !== 'undefined' && currentPage === 'reports' && typeof updateReportTypeFilterOptions === 'function') {
            updateReportTypeFilterOptions();
        }
        if (document.getElementById('pane-settings-csc-services')?.classList.contains('active')) {
            renderCSCServicesSettingsTable();
        }
    };

    try {
        const res = await fetch(`${API}/csc/services?all=1&_t=${Date.now()}`);
        const json = await res.json();
        if (json.success && Array.isArray(json.data)) {
            applyCSCServices(json.data);
        } else {
            applyCSCServices(DEFAULT_FALLBACK_CSC_SERVICES);
        }
    } catch (err) {
        console.error('[Live CSC Services Error]:', err.message);
        applyCSCServices(DEFAULT_FALLBACK_CSC_SERVICES);
    }
}

const CSC_TYPEAHEAD_ALIASES = [
    { keys: ['income', 'aay'], service: 'Aay' },
    { keys: ['caste', 'jati'], service: 'Jati' },
    { keys: ['domicile', 'niwas', 'residence', 'nivas'], service: 'Niwas' },
    { keys: ['birth', 'death', 'janm', 'mrityu'], service: 'Janma' },
    { keys: ['electric', 'electricity', 'bijli', 'power', 'light'], service: 'Bijli' },
    { keys: ['ration', 'rashan', 'khadya'], service: 'Ration' },
    { keys: ['kisan', 'pmkisan', 'farmer', 'kheti'], service: 'Kisan' },
    { keys: ['ayushman', 'pmjay', 'golden', 'health'], service: 'Ayushman' },
    { keys: ['voter', 'election', 'pehchan', 'matdata'], service: 'Voter' },
    { keys: ['dl', 'driving', 'licence', 'license'], service: 'Driving' },
    { keys: ['pan', 'nsdl', 'uti', 'incometax'], service: 'PAN' },
    { keys: ['aadhaar', 'uid', 'uidai', 'ekyc', 'aadhar'], service: 'Aadhaar' },
    { keys: ['passport', 'pass'], service: 'Passport' },
    { keys: ['shram', 'labour', 'majdoor', 'eshram'], service: 'Shram' }
];

function getCSCEmoji(serviceName) {
    if (!serviceName) return '📦';
    const s = String(serviceName);
    if (s.includes('PAN')) return '💳';
    if (s.includes('Aay')) return '📜';
    if (s.includes('Niwas')) return '🏠';
    if (s.includes('Jati')) return '🏛️';
    if (s.includes('Ration')) return '🌾';
    if (s.includes('Voter')) return '🗳️';
    if (s.includes('Ayushman')) return '🪪';
    if (s.includes('Kisan')) return '🚜';
    if (s.includes('Shram') || s.includes('Labour')) return '📦';
    if (s.includes('Janma') || s.includes('Birth') || s.includes('Death') || s.includes('Mrityu')) return '👶';
    if (s.includes('Driving')) return '🚗';
    if (s.includes('Passport')) return '✈️';
    if (s.includes('Bijli')) return '⚡';
    if (s.includes('Aadhaar')) return '🪪';
    if (s.includes('AEPS')) return '💵';
    if (s.includes('UPI')) return '📱';
    return '📦';
}

function buildCSCServiceOptions(services, defaultText = '-- Sewa Chunein --', defaultValue = '') {
    const list = (services && services.length > 0)
        ? services
        : (typeof DEFAULT_FALLBACK_CSC_SERVICES !== 'undefined' ? DEFAULT_FALLBACK_CSC_SERVICES : []);
    const activeServices = list.filter(s => s.IsActive !== false && s.IsActive !== 0);

    let html = `<option value="${defaultValue}">${escapeHtml(defaultText)}</option>`;
    activeServices.forEach(s => {
        const total = (parseFloat(s.GovtFee) || 0) + (parseFloat(s.OperatorFee) || 0);
        const iconEmoji = getCSCEmoji(s.ServiceName);
        html += `<option value="${escapeHtml(s.ServiceName)}" data-id="${s.ServiceID || ''}" data-govt="${s.GovtFee || 0}" data-op="${s.OperatorFee || 0}" data-total="${total}" data-days="${s.DefaultDays || 10}">
            ${escapeHtml(s.ServiceName)} ${iconEmoji} (Kul: ₹${total})
        </option>`;
    });
    return html;
}

function attachCSCTypeaheadToSelect(sel, onChangeCallback) {
    if (!sel || sel._typeaheadAttached) return;
    sel._typeaheadAttached = true;

    let buffer = '';
    let timer = null;

    sel.addEventListener('keydown', (e) => {
        if (['Tab', 'Escape', 'Enter', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.key)) {
            return;
        }
        if (e.ctrlKey || e.altKey || e.metaKey) return;
        if (e.key.length !== 1) return;

        e.preventDefault();

        buffer += e.key.toLowerCase();
        clearTimeout(timer);
        timer = setTimeout(() => {
            buffer = '';
        }, 1200);

        const options = Array.from(sel.options).filter(o => o.value && o.value !== 'all');
        if (options.length === 0) return;

        // 1. Starts with query on service name / option text
        let matched = options.find(o =>
            o.value.toLowerCase().startsWith(buffer) ||
            o.text.trim().toLowerCase().startsWith(buffer)
        );

        // 2. Alias exact key match
        if (!matched && typeof CSC_TYPEAHEAD_ALIASES !== 'undefined') {
            for (const alias of CSC_TYPEAHEAD_ALIASES) {
                if (alias.keys.some(k => k === buffer)) {
                    matched = options.find(o =>
                        o.value.toLowerCase().includes(alias.service.toLowerCase()) ||
                        o.text.toLowerCase().includes(alias.service.toLowerCase())
                    );
                    if (matched) break;
                }
            }
        }

        // 3. Includes / Substring query in service name or text
        if (!matched) {
            matched = options.find(o =>
                o.value.toLowerCase().includes(buffer) ||
                o.text.toLowerCase().includes(buffer)
            );
        }

        // 4. Alias prefix match
        if (!matched && typeof CSC_TYPEAHEAD_ALIASES !== 'undefined') {
            for (const alias of CSC_TYPEAHEAD_ALIASES) {
                if (alias.keys.some(k => k.startsWith(buffer))) {
                    matched = options.find(o =>
                        o.value.toLowerCase().includes(alias.service.toLowerCase()) ||
                        o.text.toLowerCase().includes(alias.service.toLowerCase())
                    );
                    if (matched) break;
                }
            }
        }

        if (matched && sel.value !== matched.value) {
            sel.value = matched.value;
            if (typeof onChangeCallback === 'function') {
                onChangeCallback();
            }
        }
    });
}

function initCSCServiceTypeahead() {
    const sel = document.getElementById('cscServiceType');
    if (sel) {
        attachCSCTypeaheadToSelect(sel, () => {
            if (typeof onCSCServiceTypeChange === 'function') onCSCServiceTypeChange();
        });
    }
}

function populateCSCServiceSelects() {
    const appSel = document.getElementById('cscServiceType');
    if (appSel) {
        const currentVal = appSel.value;
        appSel.innerHTML = buildCSCServiceOptions(allCSCServices, '-- Sewa Chunein --', '');
        if (currentVal) appSel.value = currentVal;
        initCSCServiceTypeahead();
    }
}

function updateCSCServicesBadge() {
    const activeCount = allCSCServices.filter(s => s.IsActive !== false && s.IsActive !== 0).length;
    const badge = document.getElementById('tabBadgeCscServices');
    if (badge) badge.textContent = `${activeCount} Sewayein`;

    const totalEl = document.getElementById('cscServTotalCount');
    if (totalEl) totalEl.textContent = allCSCServices.length;
    const activeEl = document.getElementById('cscServActiveCount');
    if (activeEl) activeEl.textContent = activeCount;

    const avgEl = document.getElementById('cscServAvgOpFee');
    if (avgEl && activeCount > 0) {
        const sumOp = allCSCServices.filter(s => s.IsActive !== false && s.IsActive !== 0).reduce((acc, s) => acc + (parseFloat(s.OperatorFee) || 0), 0);
        avgEl.textContent = `₹${Math.round(sumOp / activeCount)}`;
    }
}

function loadCSCServicesSettingsUI() {
    loadCSCServices().then(() => {
        renderCSCServicesSettingsTable();
    });
}

