function printCSCReceipt(format = 'a4') {
    const chosen = (format === 'a4_half') ? 'a4_half' : (format === 'current' || format === 'thermal' ? 'current' : 'a4');
    executeUnifiedPrint('csc', chosen);
}

function shareCSCReceiptWhatsApp() {
    if (!currentActiveCSCReceipt) return;
    const app = currentActiveCSCReceipt;
    if (!app.CustomerPhone) {
        showToast('Customer ka phone number darz nahi hai!', 'warning');
        return;
    }

    const sName = currentShopSettings.ShopName || 'APNA CSC SEVA KENDRA';
    const sPhone = currentShopSettings.ShopPhone ? `📞 *Helpline:* ${currentShopSettings.ShopPhone}\n` : '';

    const msg = [
        `🏛️ *${sName} - AAVEDAN PAWATI*`,
        `━━━━━━━━━━━━━━━━━━━━`,
        `🔢 *Universal SN:* ${app.SNCode || ('SN-' + (app.GlobalSerialNo || ''))}${app.ModuleCode ? ` (${app.ModuleCode})` : ''}`,
        `👤 *Grahak:* ${app.CustomerName}`,
        `📋 *Sewa:* ${app.ServiceType}`,
        `🎫 *Ack / Token No:* ${app.AckNumber || 'Pending'}`,
        `📅 *Apply Tarikh:* ${formatIndianDate(app.ApplyDate)}`,
        `⏳ *Target Date:* ${app.ExpectedDate ? formatIndianDate(app.ExpectedDate) : '7 Days'}`,
        `⚡ *Status:* ${app.Status}`,
        `━━━━━━━━━━━━━━━━━━━━`,
        `💰 *Kul Fee:* ₹${app.TotalFee}`,
        `✅ *Jama Kiya:* ₹${app.PaidAmount}`,
        `⚠️ *Bakiya:* ₹${app.DueAmount}`,
        `━━━━━━━━━━━━━━━━━━━━`,
        sPhone ? sPhone.trim() : '',
        `_${currentShopSettings.ShopFooterMsg || 'Aapka form apply ho gaya hai. Taiyar hone par suchna di jayegi.'}_`
    ].filter(Boolean).join('\n');

    openWhatsAppChat(app.CustomerPhone, msg);
}

function sendCSCWhatsApp(appId) {
    const app = allCSCApplications.find(a => a.AppID === appId);
    if (!app) return;
    if (!app.CustomerPhone) {
        showToast('Customer phone number nahi hai!', 'warning');
        return;
    }

    let statusMsg = '';
    if (app.Status === 'Approved') {
        statusMsg = `✅ *Aapka ${app.ServiceType} ban kar taiyar ho gaya hai!* Kripya center se apna document prapt karein.${app.CertificateDocNo ? ' Kramank: ' + app.CertificateDocNo : ''}`;
    } else if (app.Status === 'Delivered') {
        statusMsg = `📦 *Aapka ${app.ServiceType} safaltapoorvak deliver ho gaya hai.* Center par aane ke liye dhanyawad!`;
    } else if (app.Status === 'Rejected') {
        statusMsg = `❌ *Aapke ${app.ServiceType} par aapatti (objection) aayi hai.* Kripya documents ke sath center par sampark karein.`;
    } else {
        statusMsg = `⏳ *Aapka ${app.ServiceType} under process hai.* Target tarikh: ${formatIndianDate(app.ExpectedDate)}.`;
    }

    const msg = [
        `Namaste *${app.CustomerName}* ji,`,
        statusMsg,
        `Token / Ack No: *${app.AckNumber}*`,
        (parseFloat(app.DueAmount) || 0) > 0 ? `⚠️ Bakiya Rashi: ₹${app.DueAmount}` : '',
        `_Apna CSC & Grahak Seva Kendra_`
    ].filter(Boolean).join('\n');

    openWhatsAppChat(app.CustomerPhone, msg);
}

function sendCSCStatusWhatsAppFromModal() {
    const appId = parseInt(document.getElementById('cscStatusUpdateAppId').value);
    if (appId) sendCSCWhatsApp(appId);
}

// 8. Export CSC List to CSV
function exportCSCToCSV() {
    if (!allCSCApplications || allCSCApplications.length === 0) {
        showToast('Export karne ke liye koi data nahi hai', 'warning');
        return;
    }

    const headers = [
        'AppID', 'CustomerName', 'CustomerPhone', 'CustomerAadhaar',
        'ServiceType', 'AckNumber', 'PortalName',
        'ApplyDate', 'ExpectedDate', 'GovtFee', 'OperatorFee',
        'TotalFee', 'PaidAmount', 'DueAmount', 'Status', 'CertificateDocNo', 'Remarks'
    ];

    const rows = allCSCApplications.map(a => [
        a.AppID,
        `"${(a.CustomerName || '').replace(/"/g, '""')}"`,
        `"${a.CustomerPhone || ''}"`,
        `"${a.CustomerAadhaar || ''}"`,
        `"${a.ServiceType || ''}"`,
        `"${a.AckNumber || ''}"`,
        `"${a.PortalName || ''}"`,
        a.ApplyDate ? a.ApplyDate.split('T')[0] : '',
        a.ExpectedDate ? a.ExpectedDate.split('T')[0] : '',
        a.GovtFee || 0,
        a.OperatorFee || 0,
        a.TotalFee || 0,
        a.PaidAmount || 0,
        a.DueAmount || 0,
        `"${a.Status || ''}"`,
        `"${a.CertificateDocNo || ''}"`,
        `"${(a.StatusRemarks || '').replace(/"/g, '""')}"`
    ]);

    const csvContent = '\uFEFF' + [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `CSC_Work_Tracker_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    showToast('CSC Applications Excel/CSV export complete! 📊', 'success');
}

// 9. Customer 360 Profile Integration
async function loadC360CSC(customerId) {
    const tbody = document.getElementById('c360CSCTableBody');
    const badge = document.getElementById('c360TabCountCSC');
    if (!tbody) return;

    try {
        const res = await fetch(`${API}/csc?customerId=${customerId}`);
        const json = await res.json();
        const apps = (json.success && Array.isArray(json.data)) ? json.data : [];
        window._c360CscApps = apps;

        if (badge) badge.textContent = apps.length;

        if (apps.length === 0) {
            tbody.innerHTML = `<tr><td colspan="9" style="text-align: center; padding: 24px; color: var(--text-muted);">Is customer ka koi CSC aavedan abhi darz nahi hai.</td></tr>`;
            return;
        }

        tbody.innerHTML = apps.map(a => {
            const due = parseFloat(a.DueAmount) || 0;
            return `
                <tr>
                    <td class="cell-center" style="vertical-align: middle; text-align: center;">
                        <button type="button" 
                                class="csc-sn-pill uni-sn-pill" 
                                onclick="openCSCDetailModal(${a.AppID})" 
                                title="Universal Serial No: ${escapeHtml(a.SNCode || ('SN-' + a.GlobalSerialNo))} (Click karke Poori Detail Dekhein)">
                            <i data-lucide="file-text" width="12" height="12"></i>
                            <span>${escapeHtml(a.SNCode || (a.GlobalSerialNo ? 'SN-' + a.GlobalSerialNo : '-'))}</span>
                        </button>
                    </td>
                    <td>
                        <div>${formatIndianDate(a.ApplyDate)}</div>
                        <div style="font-size: 11px; color: var(--text-muted); display: inline-flex; align-items: center; gap: 3px; margin-top: 1px;">
                            ${formatTime(a.CreatedAt) ? `<i data-lucide="clock" width="10" height="10"></i> ${formatTime(a.CreatedAt)}` : ''}
                        </div>
                    </td>
                    <td>
                        <b>${escapeHtml(a.ServiceType)}</b>
                    </td>
                    <td class="font-mono" style="color: #38bdf8; font-weight: 700; cursor: pointer;" onclick="openCSCDetailModal(${a.AppID})" title="Poori detail dekhne ke liye click karein">
                        <span style="display: inline-flex; align-items: center; gap: 4px; padding: 2px 6px; border-radius: 4px; background: rgba(56, 189, 248, 0.12); border: 1px solid rgba(56, 189, 248, 0.25);">
                            <i data-lucide="eye" width="11" height="11"></i> ${escapeHtml(a.AckNumber || '-')}
                        </span>
                    </td>
                    <td><span class="badge" style="font-size: 11px;">${escapeHtml(a.Status || 'Pending')}</span></td>
                    <td>${a.ExpectedDate ? formatIndianDate(a.ExpectedDate) : '-'}</td>
                    <td>
                        ₹${Number(a.TotalFee || 0).toLocaleString('en-IN')}
                        ${due > 0 ? `<div style="color: #f87171; font-weight:700; font-size:11px;">Due: ₹${due.toLocaleString('en-IN')}</div>` : ''}
                    </td>
                    <td class="font-mono" style="color: #34d399;">${escapeHtml(a.CertificateDocNo || '-')}</td>
                    <td style="text-align: right;">
                        <div style="display: flex; gap: 5px; justify-content: flex-end; align-items: center;">
                            <button class="btn-ghost btn-sm" onclick="openCSCDetailModal(${a.AppID})" title="Poori Detail Dekhein" style="color: #38bdf8; padding: 4px 8px;">
                                <i data-lucide="eye" width="13" height="13"></i>
                            </button>
                            <button type="button" class="table-menu-trigger-btn csc-menu-trigger-btn" onclick="toggleCSCActionMenu(event, ${a.AppID})" title="Sabhi Kriya (3 Dots Menu)">
                                <i data-lucide="more-vertical" width="14" height="14"></i>
                            </button>
                        </div>
                    </td>
                </tr>
            `;
        }).join('');

        refreshIcons(tbody);
    } catch (e) {
        tbody.innerHTML = `<tr><td colspan="8" style="text-align: center; padding: 16px; color: #ef4444;">Error loading CSC records: ${escapeHtml(e.message)}</td></tr>`;
    }
}

function openNewCSCModalForCurrentCustomer() {
    if (typeof current360CustomerId !== 'undefined' && current360CustomerId) {
        openNewCSCModal(current360CustomerId);
    } else {
        openNewCSCModal();
    }
}

// 10. Update Badge in Sidebar
async function updateCSCPendingBadge() {
    try {
        const res = await fetch(`${API}/csc/stats`);
        const json = await res.json();
        if (json.success && json.data) {
            const badge = document.getElementById('badge-csc');
            if (badge) {
                const count = json.data.totalCount || json.data.pendingCount || 0;
                badge.textContent = count;
                badge.classList.remove('hidden');
                badge.style.display = 'inline-block';
            }
        }
    } catch (e) { }
}

// ============================================================================
// ⚡ BILL & EMI PAYMENT COUNTER (ELECTRICITY, LOANS, PHONES, UTILITIES)
// ============================================================================

let allBillPayments = [];
let currentBPCategory = 'all';
let currentBPPage = 1;
let currentBPPageSize = 25;
let bpSearchQuery = '';
let bpDateRange = '';
let bpSearchDebounceTimer = null;

async function loadBillPaymentsPage(page = 1) {
    currentBPPage = page;
    const tbody = document.getElementById('billPaymentsTableBody');
    if (tbody && (!allBillPayments || allBillPayments.length === 0)) {
        if (typeof renderTableSkeleton === 'function') renderTableSkeleton(tbody, 8, 6);
    }

    try {
        const queryParams = new URLSearchParams({
            page: currentBPPage,
            limit: currentBPPageSize
        });
        if (currentBPCategory && currentBPCategory !== 'all') {
            queryParams.append('category', currentBPCategory);
        }
        if (bpSearchQuery) {
            queryParams.append('search', bpSearchQuery);
        }
        if (bpDateRange) {
            queryParams.append('dateRange', bpDateRange);
        }

        const res = await nativeFetch(`/api/bill-payments?${queryParams.toString()}`);
        const json = await res.json();

        if (json.success) {
            allBillPayments = json.records || (Array.isArray(json.data) ? json.data : (json.data && json.data.records)) || [];
            const stats = json.stats || (json.data && json.data.stats) || {};
            const pagination = json.pagination || (json.data && json.data.pagination) || { total: allBillPayments.length, page: 1, totalPages: 1 };

            // Update KPI summary cards
            const elColl = document.getElementById('bpKpiTodayColl');
            const elProfit = document.getElementById('bpKpiTodayProfit');
            const elCount = document.getElementById('bpKpiTodayCount');
            const elWallet = document.getElementById('bpKpiWalletBal');

            if (elColl) elColl.textContent = '₹' + Number(stats.todayCollected || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 });
            if (elProfit) elProfit.textContent = '₹' + Number(stats.todayProfit || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 });
            if (elCount) elCount.textContent = (stats.todayCount || 0) + ' Bills';

            // Also fetch bank account balance for online bills if available
            if (elWallet && typeof allAccounts !== 'undefined' && Array.isArray(allAccounts)) {
                const wAcc = allAccounts.find(a => a.AccountID === 2 || /bank|online/i.test(a.AccountName));
                if (wAcc) {
                    const bBal = wAcc.CurrentBalance !== undefined ? wAcc.CurrentBalance : (wAcc.Balance || 0);
                    elWallet.textContent = '₹' + Number(bBal).toLocaleString('en-IN', { minimumFractionDigits: 2 });
                }
            }

            // Update sidebar badge
            const badge = document.getElementById('badge-billpayments');
            if (badge) {
                const count = stats.todayCount || pagination.total || 0;
                badge.textContent = count;
                badge.style.display = count > 0 ? 'inline-block' : 'none';
            }

            // Render table
            renderBillPaymentsTable(allBillPayments, pagination);
        } else {
            if (tbody) tbody.innerHTML = `<tr><td colspan="8" style="text-align:center; padding: 24px; color: #ef4444;">❌ Data load karne me samasya: ${json.error || 'Server error'}</td></tr>`;
        }
    } catch (err) {
        console.error('Error loading bill payments:', err);
        if (tbody) tbody.innerHTML = `<tr><td colspan="8" style="text-align:center; padding: 24px; color: #ef4444;">❌ Connection Error: ${err.message}</td></tr>`;
    } finally {
        if (typeof stopTopLoading === 'function') stopTopLoading();
        if (typeof lucide !== 'undefined' && lucide.createIcons) lucide.createIcons();
    }
}

function renderBillPaymentsTable(records, pagination) {
    const tbody = document.getElementById('billPaymentsTableBody');
    const pageInfo = document.getElementById('bpPageInfo');
    const prevBtn = document.getElementById('bpPrevBtn');
    const nextBtn = document.getElementById('bpNextBtn');

    if (!tbody) return;

    if (!records || records.length === 0) {
        tbody.innerHTML = `
            <tr>
                <td colspan="8" style="text-align: center; padding: 48px 16px;">
                    <div style="font-size: 38px; margin-bottom: 10px;">⚡</div>
                    <div style="font-size: 15px; font-weight: 700; color: var(--text-primary); margin-bottom: 4px;">Koi Bill / EMI Bhugtan Record Nahi Mila</div>
                    <div style="font-size: 12.5px; color: var(--text-muted); margin-bottom: 16px;">Naya bill ya EMI jama karne ke liye neeche button dabayein</div>
                    <button class="btn-primary" onclick="openNewBillPaymentModal()" style="background: linear-gradient(135deg, #059669, #047857); padding: 7px 18px;">
                        + Naya Bill / EMI Jama Karein
                    </button>
                </td>
            </tr>
        `;
        renderUniversalPaginationUI({
            containerId: 'bpPaginationBtns',
            infoId: 'bpPaginationInfo',
            currentPage: 1,
            pageSize: currentBPPageSize,
            totalItems: 0,
            onPageChangeFnName: 'loadBillPaymentsPage'
        });
        return;
    }

    const catBadge = (cat) => {
        if (cat === 'Electricity') return `<span class="bp-badge bp-badge-electricity">⚡ Electricity</span>`;
        if (cat === 'Loan_EMI') return `<span class="bp-badge bp-badge-loan">💳 Loan EMI</span>`;
        if (cat === 'Mobile_Kist') return `<span class="bp-badge bp-badge-mobile">📱 Phone Kist</span>`;
        return `<span class="bp-badge bp-badge-other">📦 ${cat || 'Other'}</span>`;
    };

    tbody.innerHTML = records.map(r => {
        const pDate = r.PaymentDate ? new Date(r.PaymentDate).toLocaleDateString('en-GB') : '-';
        const pTime = r.PaymentTime ? r.PaymentTime.substring(0, 5) : '';
        const billAmt = Number(r.BillAmount || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 });
        const feeAmt = Number(r.CustomerCharge || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 });
        const totalColl = Number(r.TotalCollected || (r.BillAmount + r.CustomerCharge) || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 });
        const profitAmt = Number(r.NetProfit || (r.CustomerCharge + (r.CommissionEarned || 0)) || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 });
        const serialTag = r.GlobalSerialNo ? `<span style="font-size: 10.5px; font-family: monospace; color: var(--text-muted); background: var(--bg-secondary); padding: 1px 5px; border-radius: 4px;">#${r.GlobalSerialNo}</span>` : '';
        const vibhagArrear = parseFloat(r.RemainingArrear || 0);
        const dukanUdhaar = parseFloat(r.CustomerDue || 0);

        return `
            <tr>
                <td style="font-size: 12px; white-space: nowrap;">
                    <div style="font-weight: 700; color: var(--text-primary);">${pDate}</div>
                    <div style="font-size: 11px; color: var(--text-muted);">${pTime} ${serialTag}</div>
                </td>
                <td>
                    ${catBadge(r.BillCategory)}
                    <div style="font-size: 11px; font-weight: 600; color: var(--text-secondary); margin-top: 3px;">${r.ProviderName || '-'}</div>
                </td>
                <td>
                    <div style="font-weight: 700; font-family: monospace; font-size: 13.5px; color: var(--text-primary);">${r.ConsumerNumber || '-'}</div>
                    ${r.BillNumber ? `<div style="font-size: 11px; color: var(--text-muted);">Bill No: ${r.BillNumber}</div>` : ''}
                </td>
                <td>
                    <div style="font-weight: 700; color: var(--text-primary);">${cleanCustomerName(r.CustomerName || 'Walk-in Customer')}</div>
                    ${r.CustomerPhone ? `<div style="font-size: 11.5px; color: var(--text-muted);"><i data-lucide="phone" style="width: 11px; height: 11px; display: inline;"></i> ${r.CustomerPhone}</div>` : ''}
                </td>
                <td style="font-size: 12.5px; font-weight: 600; text-align: right;">
                    <div style="font-weight: 700; color: #0f172a;">₹${billAmt}</div>
                    ${vibhagArrear > 0 ? `<div style="font-size: 10.5px; color: #b45309; font-weight: 700;">Vibhag Baaki: ₹${vibhagArrear.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</div>` : ''}
                </td>
                <td style="font-size: 12px; color: #059669; font-weight: 700; text-align: right;">
                    +₹${feeAmt}
                </td>
                <td style="font-size: 13.5px; font-weight: 800; color: #047857; text-align: right; background: rgba(5, 150, 105, 0.04);">
                    <div>₹${totalColl}</div>
                    ${dukanUdhaar > 0 ? `
                        <div style="font-size: 10.5px; font-weight: 800; color: #dc2626; background: #fee2e2; padding: 2px 5px; border-radius: 4px; margin-top: 2px; display: inline-block;">
                            🔴 Dukan Udhaar: ₹${dukanUdhaar.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                        </div>
                    ` : `
                        <div style="font-size: 10.5px; font-weight: 700; color: #10b981;">(Profit: ₹${profitAmt})</div>
                    `}
                </td>
                <td style="white-space: nowrap; text-align: center; padding: 6px 8px;">
                    <div style="display: inline-flex; align-items: center; gap: 4px;">
                        <button class="btn-ghost" onclick="openBillReceiptModal('${r.PaymentID}')" title="Grahak Parchi Kholein" style="padding: 3px 7px; color: #059669; font-weight: 700; font-size: 11.5px; border: 1px solid rgba(5,150,105,0.25); border-radius: 6px; background: rgba(5,150,105,0.06);">
                            🧾 Parchi
                        </button>
                        <button class="btn-ghost" onclick="openEditBillPaymentModal('${r.PaymentID}')" title="Bill Edit Karein" style="padding: 3px 7px; color: #d97706; font-weight: 700; font-size: 11.5px; border: 1px solid rgba(217,119,6,0.3); border-radius: 6px; background: rgba(217,119,6,0.08);">
                            ✏️ Edit
                        </button>
                        <button class="btn-ghost" onclick="deleteBillPayment('${r.PaymentID}')" title="Delete Karein" style="padding: 3px 6px; color: #ef4444; font-size: 11.5px; border: 1px solid rgba(239,68,68,0.25); border-radius: 6px; background: rgba(239,68,68,0.06);">
                            <i data-lucide="trash-2" style="width: 13px; height: 13px;"></i>
                        </button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');

    renderUniversalPaginationUI({
        containerId: 'bpPaginationBtns',
        infoId: 'bpPaginationInfo',
        currentPage: pagination?.page || currentBPPage || 1,
        pageSize: pagination?.limit || currentBPPageSize || 25,
        totalItems: pagination?.total !== undefined ? pagination.total : (records ? records.length : 0),
        onPageChangeFnName: 'loadBillPaymentsPage'
    });

    if (typeof lucide !== 'undefined' && lucide.createIcons) lucide.createIcons();
}

