function applyBPReceiptParsedData(data) {
    if (!data) return;

    const catSel = document.getElementById('bpModalCategory');
    const provInp = document.getElementById('bpModalProvider');
    const consInp = document.getElementById('bpModalConsumerNo');
    const billNoInp = document.getElementById('bpModalBillNo');
    const nameInp = document.getElementById('bpModalCustName');
    const billAmtInp = document.getElementById('bpModalBillAmount');
    const dateInp = document.getElementById('bpModalPaymentDate');
    const notesInp = document.getElementById('bpModalNotes');
    const refInp = document.getElementById('bpModalTxnRef');

    if (catSel && data.billCategory) catSel.value = data.billCategory;
    if (provInp && data.providerName) provInp.value = data.providerName;
    if (consInp && data.consumerNumber) consInp.value = data.consumerNumber;
    if (billNoInp && data.billNumber) billNoInp.value = data.billNumber;
    if (nameInp && data.customerName) nameInp.value = data.customerName;
    if (billAmtInp && data.billAmount > 0) billAmtInp.value = data.billAmount;
    if (dateInp && data.paymentDate) dateInp.value = data.paymentDate;
    if (refInp && data.txnRef) refInp.value = data.txnRef;
    if (notesInp && data.notes) notesInp.value = data.notes;

    const chargeInp = document.getElementById('bpModalCustomerCharge');
    if (chargeInp) {
        delete chargeInp.dataset.userEdited;
        if (data.customerCharge !== undefined) chargeInp.value = data.customerCharge;
    }

    // Auto-generate Dynamic Custom Columns from extra fields detected by AI!
    clearBPCustomFields();
    if (data.extraFields && typeof data.extraFields === 'object') {
        for (const [key, val] of Object.entries(data.extraFields)) {
            addBPCustomFieldRow(key, val);
        }
    }

    if (typeof calculateBPProfitInModal === 'function') {
        calculateBPProfitInModal();
    }
}

async function pasteBPReceiptFromClipboard() {
    try {
        if (!navigator.clipboard || !navigator.clipboard.read) {
            if (typeof showToast === 'function') showToast('Clipboard access nahi mila. Raseed select karein ya Ctrl+V dabayein.', 'info');
            return;
        }
        const items = await navigator.clipboard.read();
        for (const item of items) {
            for (const type of item.types) {
                if (type.startsWith('image/')) {
                    const blob = await item.getType(type);
                    const file = new File([blob], `pasted_receipt_${Date.now()}.png`, { type });
                    uploadAndScanBPReceipt(file);
                    return;
                }
            }
        }
        if (typeof showToast === 'function') showToast('Clipboard me koi raseed image nahi mili. Screenshot lekar Paste karein.', 'warning');
    } catch (e) {
        console.warn('Clipboard read error:', e.message);
        if (typeof showToast === 'function') showToast('Kripya modal me click karke keyboard se Ctrl+V dabayein', 'info');
    }
}

function clearBPReceiptUpload() {
    const fileInp = document.getElementById('bpReceiptFileInput');
    if (fileInp) fileInp.value = '';
    const statusBox = document.getElementById('bpScanStatusBox');
    if (statusBox) {
        statusBox.style.display = 'none';
        statusBox.innerHTML = '';
    }
    const previewWrap = document.getElementById('bpReceiptPreviewWrap');
    if (previewWrap) previewWrap.style.display = 'none';
    const thumbEl = document.getElementById('bpReceiptThumb');
    if (thumbEl) thumbEl.src = '';
    const docIdInp = document.getElementById('bpModalAttachedDocId');
    if (docIdInp) docIdInp.value = '';
}

