function printBillReceiptSlip(chosenFormat = 'current') {
    const area = document.getElementById('billReceiptPrintArea');
    if (!area) {
        if (typeof showToast === 'function') showToast('Print karne ke liye koi content nahi mila', 'warning');
        return;
    }

    const fmt = (chosenFormat === 'a4_half') ? 'a4_half' : (chosenFormat === 'a4' ? 'a4' : 'thermal');
    if (typeof universalPrint === 'function') {
        universalPrint('billReceiptPrintArea', {
            format: fmt,
            title: `Bill & EMI Receipt - ${activeBillReceiptData?.ConsumerNumber || 'Receipt'}`
        });
    } else {
        window.print();
    }
}

function shareBillReceiptWhatsApp() {
    if (!activeBillReceiptData) {
        if (typeof showToast === 'function') showToast('⚠️ Pehle receipt kholein', 'warning');
        return;
    }
    const r = activeBillReceiptData;
    const phone = (r.CustomerPhone || '').replace(/\D/g, '').slice(-10);
    const billAmt = Number(r.BillAmount || 0).toLocaleString('en-IN');
    const feeAmt = Number(r.CustomerCharge || 0).toLocaleString('en-IN');
    const totalAmt = Number(r.TotalCollected || (r.BillAmount + r.CustomerCharge) || 0).toLocaleString('en-IN');
    const pDate = r.PaymentDate ? new Date(r.PaymentDate).toLocaleDateString('en-GB') : '';

    const s = window.currentShopSettings || {};
    const u = window.currentUser || {};
    let userSettings = {};
    try { if (u.SettingsJson) userSettings = typeof u.SettingsJson === 'string' ? JSON.parse(u.SettingsJson) : u.SettingsJson; } catch (_) { }
    const shopName = s.ShopName || userSettings.ShopName || u.ShopName || 'CSC & BC Kendra';
    const shopSubtitle = s.ShopSubtitle || userSettings.ShopSubtitle || 'Grahak Seva Kendra, CSC Center , AADHAAR Sewa Kendra';
    const shopPhone = s.ShopPhone || userSettings.ShopPhone || u.MobileNumber || '';
    const shopAddress = s.ShopAddress || userSettings.ShopAddress || '';

    const shopContactLine = [shopPhone ? `Phone: ${shopPhone}` : '', shopAddress].filter(Boolean).join(' • ');
    const text = `*⚡ BILL & EMI PAYMENT RECEIPT*\n` +
        `*${shopName}*\n` +
        `_${shopSubtitle}_\n` +
        (shopContactLine ? `${shopContactLine}\n` : '') +
        `--------------------------------\n` +
        `*Grahak:* ${cleanCustomerName(r.CustomerName || '')}\n` +
        `*Sewa/Provider:* ${r.ProviderName || r.BillCategory}\n` +
        `*Khata No:* ${r.ConsumerNumber}\n` +
        `*Tarikh:* ${pDate}\n` +
        `*Bill Rashi:* ₹${billAmt}\n` +
        `*Suvidha Shulk:* ₹${feeAmt}\n` +
        `*Kul Cash Jama:* ₹${totalAmt}\n` +
        `*Status:* SUCCESS\n` +
        `*Ref No:* ${r.TxnReference || r.PaymentID}\n` +
        `--------------------------------\n` +
        `Dhanyawad! Hamare Kendra Par Aane Ke Liye Shukriya.`;

    const url = phone ? `https://wa.me/91${phone}?text=${encodeURIComponent(text)}` : `https://wa.me/?text=${encodeURIComponent(text)}`;
    window.open(url, '_blank');
}

async function deleteBillPayment(paymentId) {
    if (!confirm('Kya aap sach me yeh bill payment record delete karna chahte hain?')) return;

    try {
        const res = await nativeFetch(`/api/bill-payments/${paymentId}`, { method: 'DELETE' });
        const json = await res.json();
        if (json.success) {
            if (typeof showToast === 'function') showToast('🗑️ Bill payment record delete ho gaya!', 'success');
            loadBillPaymentsPage(currentBPPage);
        } else {
            if (typeof showToast === 'function') showToast(`❌ Error: ${json.error || 'Delete failed'}`, 'error');
        }
    } catch (e) {
        if (typeof showToast === 'function') showToast(`❌ Delete error: ${e.message}`, 'error');
    }
}

function exportBillPaymentsExcel() {
    if (!allBillPayments || allBillPayments.length === 0) {
        if (typeof showToast === 'function') showToast('⚠️ Export karne ke liye koi data nahi hai', 'warning');
        return;
    }

    const headers = ['SN', 'PaymentDate', 'Category', 'Provider', 'ConsumerNo', 'CustomerName', 'Phone', 'BillAmount', 'CustomerCharge', 'TotalCollected', 'Commission', 'NetProfit', 'RefNo'];
    const rows = allBillPayments.map(r => [
        r.GlobalSerialNo || r.PaymentID,
        r.PaymentDate ? String(r.PaymentDate).split('T')[0] : '',
        `"${r.BillCategory || ''}"`,
        `"${r.ProviderName || ''}"`,
        `"${r.ConsumerNumber || ''}"`,
        `"${cleanCustomerName(r.CustomerName || '')}"`,
        `"${r.CustomerPhone || ''}"`,
        r.BillAmount || 0,
        r.CustomerCharge || 0,
        r.TotalCollected || (r.BillAmount + r.CustomerCharge) || 0,
        r.CommissionEarned || 0,
        r.NetProfit || 0,
        `"${r.TxnReference || ''}"`
    ]);

    const csvContent = 'data:text/csv;charset=utf-8,' + [headers.join(','), ...rows.map(e => e.join(','))].join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement('a');
    link.setAttribute('href', encodedUri);
    link.setAttribute('download', `Bill_Payments_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    if (typeof showToast === 'function') showToast('📥 Bill Payments CSV export ho gaya!', 'success');
}

