// UCL Modal & Auto Customer Logic
// --------------------------------------------------------------------------
async function openNewUCLModal() {
    const form = document.getElementById('uclForm');
    if (form) form.reset();

    const editIdEl = document.getElementById('uclEditId');
    if (editIdEl) editIdEl.value = '';
    const titleEl = document.getElementById('uclModalTitle');
    if (titleEl) titleEl.textContent = 'Naya UCL Update (आधार संशोधन एंट्री)';
    const chip = document.getElementById('uclAadhaarChip');
    if (chip) chip.innerHTML = '';
    const phoneChip = document.getElementById('uclPhoneChip');
    if (phoneChip) phoneChip.innerHTML = '';
    const phoneInp = document.getElementById('uclCustPhone');
    if (phoneInp) {
        phoneInp._skipFamilyLink = false;
        phoneInp._matchedByAadhaar = null;
    }
    const aadhaarInp = document.getElementById('uclCustAadhaar');
    if (aadhaarInp) {
        aadhaarInp._matchedCustId = null;
    }
    const pacEl = document.getElementById('uclPACSelect');
    if (pacEl) pacEl.value = '';

    clearUCLReceiptUpload();
    setupUCLModalListeners();

    // Populate customer dropdown from allCustomersData
    const custSel = document.getElementById('uclCustomerSelect');
    if (custSel) {
        let optHtml = '<option value="">-- Direct Naya / Walk-in Customer --</option>';
        if (Array.isArray(allCustomersData)) {
            allCustomersData.forEach(c => {
                const p = c.Phone ? ` (${c.Phone})` : '';
                optHtml += `<option value="${c.CustomerID}" data-name="${escapeHtml(c.CustomerName)}" data-phone="${c.Phone || ''}" data-aadhaar="${c.AadhaarNumber || ''}">
                    ${escapeHtml(c.CustomerName)}${p}
                </option>`;
            });
        }
        custSel.innerHTML = optHtml;
    }

    // Populate active accounts
    const accSel = document.getElementById('uclAccountSelect');
    if (accSel) {
        let accHtml = '';
        if (Array.isArray(allAccounts)) {
            allAccounts.filter(a => a.IsActive).forEach(a => {
                accHtml += `<option value="${a.AccountID}">${escapeHtml(a.AccountName)} (Bal: ₹${formatNumber(a.CurrentBalance || 0)})</option>`;
            });
        }
        accSel.innerHTML = accHtml;
    }

    // Default fee values
    document.getElementById('uclFee').value = 50;
    document.getElementById('uclOpFee').value = 0;
    document.getElementById('uclTotalAmt').value = 50;
    document.getElementById('uclPaidAmt').value = 50;
    calculateUCLFees();

    openModal('uclModal');
    if (window.lucide && typeof lucide.createIcons === 'function') lucide.createIcons();
}
window._realOpenNewUCLModal = openNewUCLModal;
window.openNewUCLModal = openNewUCLModal;
if (window._queuedOpenUCLModal) {
    window._queuedOpenUCLModal = false;
    openNewUCLModal();
}

async function openEditUCLModal(id) {
    try {
        const res = await fetch(`${API}/ucl/${id}`);
        const json = await res.json();
        if (!json.success || !json.data) {
            alert('UCL record nahi mila: ' + (json.error || ''));
            return;
        }
        const row = json.data;
        await openNewUCLModal();

        const editInput = document.getElementById('uclEditId');
        if (editInput) editInput.value = row.UCLID;

        const titleEl = document.getElementById('uclModalTitle');
        if (titleEl) titleEl.textContent = `UCL Update Badlein (${row.SerialNo || 'UCL-' + row.UCLID})`;

        const nameInput = document.getElementById('uclCustName');
        if (nameInput) nameInput.value = row.CustomerName || '';

        const phoneInput = document.getElementById('uclCustPhone');
        if (phoneInput) phoneInput.value = row.CustomerPhone || '';

        const aadhaarInput = document.getElementById('uclCustAadhaar');
        if (aadhaarInput) {
            aadhaarInput.value = row.AadhaarMasked || row.AadhaarLast4 || '';
            handleUCLAadhaarInput(aadhaarInput);
        }

        const sidInput = document.getElementById('uclSID');
        if (sidInput) sidInput.value = row.SID || '';

        const typeSelect = document.getElementById('uclUpdateType');
        if (typeSelect) typeSelect.value = row.UpdateType || 'Demographics (Name)';

        const bioSelect = document.getElementById('uclBiometrics');
        if (bioSelect) bioSelect.value = row.BiometricsUpdate || 'No';

        const feeInput = document.getElementById('uclFee');
        if (feeInput) feeInput.value = row.TotalFee ?? 50;

        const opFeeInput = document.getElementById('uclOpFee');
        if (opFeeInput) opFeeInput.value = row.OperatorFee ?? 0;

        const paidInput = document.getElementById('uclPaidAmt');
        if (paidInput) paidInput.value = row.PaidAmount ?? 50;

        const payModeSelect = document.getElementById('uclPayMode');
        if (payModeSelect) payModeSelect.value = row.PaymentMode || 'Cash';

        const statusSelect = document.getElementById('uclStatus');
        if (statusSelect) statusSelect.value = row.Status || 'Generated';

        const notesInput = document.getElementById('uclNotes');
        if (notesInput) notesInput.value = row.Notes || '';

        if (row.CustomerID) {
            const custSelect = document.getElementById('uclCustomerSelect');
            if (custSelect) custSelect.value = row.CustomerID;
        }

        if (row.ReceiptPath) {
            document.getElementById('uclReceiptFilePath').value = row.ReceiptPath;
            document.getElementById('uclReceiptDocId').value = row.ReceiptDocumentID || '';
            const successBox = document.getElementById('uclScanSuccess');
            const idleBox = document.getElementById('uclScanIdle');
            if (successBox && idleBox) {
                idleBox.style.display = 'none';
                successBox.style.display = 'block';
                const thumb = document.getElementById('uclReceiptThumb');
                if (thumb) {
                    thumb.src = row.ReceiptPath;
                    thumb.style.display = 'block';
                }
                const viewBtn = document.getElementById('uclReceiptViewBtn');
                if (viewBtn) viewBtn.href = row.ReceiptPath;
                const infoText = document.getElementById('uclReceiptInfoText');
                if (infoText) infoText.textContent = `Attached Raseed (${row.SerialNo || 'UCL-' + row.UCLID})`;
            }
        }

        calculateUCLFees();
        if (window.lucide && typeof lucide.createIcons === 'function') lucide.createIcons();
    } catch (err) {
        alert('Error: ' + err.message);
    }
}
window.openEditUCLModal = openEditUCLModal;

function onUCLCustomerSelectChange() {
    const sel = document.getElementById('uclCustomerSelect');
    if (!sel || !sel.value) return;

    const opt = sel.options[sel.selectedIndex];
    if (!opt) return;

    const name = opt.getAttribute('data-name') || '';
    const phone = opt.getAttribute('data-phone') || '';
    const aadhaar = opt.getAttribute('data-aadhaar') || '';

    if (name) document.getElementById('uclCustName').value = name;
    if (phone) document.getElementById('uclCustPhone').value = phone;
    if (aadhaar) {
        const cleanAadhaar = aadhaar.replace(/\D/g, '');
        document.getElementById('uclCustAadhaar').value = cleanAadhaar.length >= 4 ? cleanAadhaar.slice(-4) : cleanAadhaar;
    }
}
window.onUCLCustomerSelectChange = onUCLCustomerSelectChange;

