// ============================================================================
// REPORTS & UNIVERSAL AUDIT ANALYSIS ENGINE
// ============================================================================

let currentReportModule = 'all';
let currentReportPreset = 'this_month';
let reportStartDate = '';
let reportEndDate = '';
let reportSearchDebounceTimer = null;
let reportCurrentPage = 1;
const reportPageLimit = 20;
let allReportRecords = [];
let reportTotalRecords = 0;
let reportSummaryData = null;
let reportCharts = {};

function initReportDates() {
    const now = new Date();
    const y = now.getFullYear();
    const m = String(now.getMonth() + 1).padStart(2, '0');
    const d = String(now.getDate()).padStart(2, '0');
    reportStartDate = `${y}-${m}-01`;
    reportEndDate = `${y}-${m}-${d}`;

    const startInp = document.getElementById('repStartDate');
    const endInp = document.getElementById('repEndDate');
    if (startInp) startInp.value = reportStartDate;
    if (endInp) endInp.value = reportEndDate;
}

async function loadReports() {
    if (!reportStartDate || !reportEndDate) {
        initReportDates();
    }
    // Dynamic real-time sync of CSC Services list if not yet populated
    if ((!allCSCServices || allCSCServices.length === 0) && typeof loadCSCServices === 'function') {
        try {
            await loadCSCServices();
        } catch (e) {
            console.warn('Could not preload CSC services for reports:', e);
        }
    }
    // Customer list preload (Grahak filter + 360° links ke liye)
    if ((!allCustomersData || allCustomersData.length === 0)) {
        try {
            const cres = await fetch(API + '/customers').then(r => r.json()).catch(() => null);
            if (cres && cres.success) allCustomersData = cres.data || [];
        } catch (e) {
            console.warn('Could not preload customers for reports:', e);
        }
    }
    populateReportFilterDropdowns();
    await Promise.all([
        loadReportKPIs(),
        loadReportData()
    ]);
}

function populateReportFilterDropdowns() {
    // 1. Account Filter
    const accSel = document.getElementById('repAccountFilter');
    if (accSel && allAccounts && allAccounts.length > 0) {
        const curVal = accSel.value;
        accSel.innerHTML = '<option value="all">-- Sabhi Khate (All Accounts) --</option>' +
            allAccounts.map(a => `<option value="${a.AccountID}">${escapeHtml(a.AccountName)} (${escapeHtml(a.AccountType)})</option>`).join('');
        if (curVal) accSel.value = curVal;
    }

    // 2. Category Filter
    const catSel = document.getElementById('repCategoryFilter');
    if (catSel && allCategories && allCategories.length > 0) {
        const curVal = catSel.value;
        catSel.innerHTML = '<option value="all">-- Sabhi Categories --</option>' +
            allCategories.map(c => `<option value="${c.CategoryID}">${escapeHtml(c.CategoryName)} (${escapeHtml(c.CategoryType)})</option>`).join('');
        if (curVal) catSel.value = curVal;
    }

    // 3. Customer filter (Grahak 360° / ek grahak ka saara data)
    const custSel = document.getElementById('repCustomerFilter');
    if (custSel) {
        const curCust = custSel.value || 'all';
        const customers = (typeof allCustomersData !== 'undefined' && Array.isArray(allCustomersData)) ? allCustomersData : [];
        const sorted = customers.slice().sort((a, b) => String(a.CustomerName || '').localeCompare(String(b.CustomerName || ''), 'hi'));
        custSel.innerHTML = '<option value="all">-- Sabhi Grahak (All Customers) --</option>' +
            sorted.map(c => {
                const nm = escapeHtml(c.CustomerName || ('Customer #' + c.CustomerID));
                const ph = c.Phone ? ' • ' + escapeHtml(c.Phone) : '';
                return '<option value="' + c.CustomerID + '">' + nm + ph + '</option>';
            }).join('');
        if (curCust && Array.from(custSel.options).some(o => o.value === String(curCust))) {
            custSel.value = curCust;
        }
        if (custSel._ssInstance && typeof custSel._ssInstance.syncFromNative === 'function') {
            try { custSel._ssInstance.syncFromNative(); } catch (e) { }
        } else if (typeof window.refreshSearchableSelect === 'function') {
            try { window.refreshSearchableSelect(custSel); } catch (e) { }
        }
    }

    // 4. Module-specific Type options
    updateReportTypeFilterOptions();
}

function updateReportTypeFilterOptions() {
    const typeSel = document.getElementById('repTypeFilter');
    if (!typeSel) return;
    const curVal = typeSel.value;

    if (currentReportModule === 'all') {
        typeSel.innerHTML = `
            <option value="all">-- Sabhi Modules & Types --</option>
            <option value="Cashbook">Cashbook (Income/Expense)</option>
            <option value="CSC Application">CSC Center Applications</option>
            <option value="BC Banking">BC Banking (AEPS/ATM)</option>
            <option value="Udhaar (Debit)">Khata Udhaar (Debit)</option>
            <option value="Jama (Credit)">Khata Jama (Credit)</option>
            <option value="Income">Income (Aamadani)</option>
            <option value="Expense">Expense (Kharcha)</option>
            <option value="Transfer">Account Transfer</option>
        `;
    } else if (currentReportModule === 'transactions') {
        typeSel.innerHTML = `
            <option value="all">-- Sabhi Transaction Types --</option>
            <option value="Income">Income (Aamadani)</option>
            <option value="Expense">Expense (Kharcha)</option>
            <option value="Transfer">Transfer</option>
            <option value="Loan Given">Loan Diya</option>
            <option value="Loan Received">Loan Liya</option>
            <option value="Loan Repay">Loan Wapas</option>
        `;
    } else if (currentReportModule === 'csc') {
        typeSel.innerHTML = buildCSCServiceOptions(allCSCServices, '-- Sabhi CSC Services --', 'all');
        attachCSCTypeaheadToSelect(typeSel, () => {
            if (typeof applyReportsFilters === 'function') applyReportsFilters();
        });
    } else if (currentReportModule === 'bc') {
        typeSel.innerHTML = `
            <option value="all">-- Sabhi BC Services --</option>
            <option value="Cash Withdrawal">Cash Withdrawal (Nikaasi)</option>
            <option value="Cash Deposit">Cash Deposit (Jama)</option>
            <option value="Money Transfer">Money Transfer (DMT)</option>
            <option value="Mini Statement">Mini Statement</option>
            <option value="Balance Inquiry">Balance Inquiry</option>
            <option value="QR Pay">QR Pay</option>
        `;
    } else if (currentReportModule === 'khata') {
        typeSel.innerHTML = `
            <option value="all">-- Sabhi Khata Entries --</option>
            <option value="Gave">Udhaar Diya (Gave)</option>
            <option value="Got">Jama Mila (Got)</option>
        `;
    } else if (currentReportModule === 'loans') {
        typeSel.innerHTML = `
            <option value="all">-- Sabhi Loan Entries --</option>
            <option value="Loan Given">Loan Diya</option>
            <option value="Loan Received">Loan Liya</option>
            <option value="Loan Repay">Loan Wapas</option>
        `;
    } else if (currentReportModule === 'invoices') {
        typeSel.innerHTML = `
            <option value="all">-- Sabhi Invoices --</option>
            <option value="Paid">Paid</option>
            <option value="Unpaid">Unpaid</option>
            <option value="Partial">Partial</option>
        `;
    } else {
        typeSel.innerHTML = `<option value="all">-- Sabhi Records --</option>`;
    }
    if (curVal && Array.from(typeSel.options).some(o => o.value === curVal)) {
        typeSel.value = curVal;
    } else if (curVal && curVal !== 'all') {
        const matchOpt = Array.from(typeSel.options).find(o =>
            o.value.toLowerCase().includes(curVal.toLowerCase()) ||
            curVal.toLowerCase().includes(o.value.toLowerCase())
        );
        if (matchOpt) typeSel.value = matchOpt.value;
    }
}

async function loadReportKPIs() {
    try {
        const params = new URLSearchParams();
        if (reportStartDate) params.append('startDate', reportStartDate);
        if (reportEndDate) params.append('endDate', reportEndDate);
        params.append('_t', Date.now());

        const res = await fetch(`${API}/reports/kpis?${params.toString()}`);
        const json = await res.json();
        if (!json.success || !json.data) return;

        const d = json.data;
        const incEl = document.getElementById('repKpiIncome');
        const expEl = document.getElementById('repKpiExpense');
        const prfEl = document.getElementById('repKpiProfit');
        const cscEl = document.getElementById('repKpiCSC');
        const bcEl = document.getElementById('repKpiBC');
        const udhEl = document.getElementById('repKpiUdhaar');

        if (incEl) incEl.textContent = formatMoney(d.totalIncome || 0);
        if (expEl) expEl.textContent = formatMoney(d.totalExpense || 0);

        const netProf = d.netProfit || 0;
        if (prfEl) {
            prfEl.textContent = `${netProf >= 0 ? '+' : ''}${formatMoney(netProf)}`;
            prfEl.style.color = netProf >= 0 ? '#10b981' : '#ef4444';
        }

        if (cscEl) {
            cscEl.textContent = formatMoney(d.csc?.CSCOperatorProfit || 0);
            const sub = document.getElementById('repKpiCSCSub');
            if (sub) sub.textContent = `${d.csc?.CSCCount || 0} Aavedan | Kul Fees: ${formatMoney(d.csc?.CSCTotalFees || 0)}`;
        }

        if (bcEl) {
            bcEl.textContent = formatMoney(d.bc?.BCTotalVolume || 0);
            const sub = document.getElementById('repKpiBCSub');
            if (sub) sub.textContent = `Kamai: ${formatMoney(d.bc?.BCNetProfit || d.bc?.BCTotalCommission || 0)} (${d.bc?.BCCount || 0} Trx)`;
        }

        if (udhEl) {
            udhEl.textContent = formatMoney(d.marketUdhaar?.TotalMarketUdhaar || 0);
            const sub = document.getElementById('repKpiUdhaarSub');
            if (sub) sub.textContent = `Adv Jama: ${formatMoney(d.marketUdhaar?.TotalAdvanceJama || 0)}`;
        }
    } catch (err) {
        console.error('Error loading report KPIs:', err);
    }
}

async function loadReportData() {
    if (currentReportModule === 'charts') {
        await loadReportCharts();
        return;
    }

    const tbody = document.getElementById('reportsTableBody');
    if (tbody) {
        renderTableSkeleton(tbody, 10, 6);
    }

    try {
        const params = new URLSearchParams();
        params.append('module', currentReportModule);
        if (reportStartDate) params.append('startDate', reportStartDate);
        if (reportEndDate) params.append('endDate', reportEndDate);

        const searchVal = document.getElementById('repSearchInput')?.value.trim();
        if (searchVal) params.append('search', searchVal);

        const typeVal = document.getElementById('repTypeFilter')?.value;
        if (typeVal && typeVal !== 'all') params.append('type', typeVal);

        const accVal = document.getElementById('repAccountFilter')?.value;
        if (accVal && accVal !== 'all') params.append('accountId', accVal);

        const catVal = document.getElementById('repCategoryFilter')?.value;
        if (catVal && catVal !== 'all') params.append('categoryId', catVal);

        const statusVal = document.getElementById('repStatusFilter')?.value;
        if (statusVal && statusVal !== 'all') params.append('status', statusVal);

        const custVal = document.getElementById('repCustomerFilter')?.value;
        if (custVal && custVal !== 'all') params.append('customerId', custVal);

        const offset = (reportCurrentPage - 1) * reportPageLimit;
        params.append('limit', reportPageLimit);
        params.append('offset', offset);
        params.append('_t', Date.now());

        const res = await fetch(`${API}/reports/master?${params.toString()}`);
        const json = await res.json();
        if (!json.success || !json.data) throw new Error(json.error || 'Failed to load report feed');

        allReportRecords = (json.data.records || []).slice().sort((a, b) => {
            const da = a.RecordDate ? String(a.RecordDate).split('T')[0] : '';
            const db = b.RecordDate ? String(b.RecordDate).split('T')[0] : '';
            if (da !== db) return db.localeCompare(da);
            const ta = a.RecordTime || '00:00:00';
            const tb = b.RecordTime || '00:00:00';
            if (ta !== tb) return String(tb).localeCompare(String(ta));
            const sA = parseApiDate(a.SortDate);
            const sB = parseApiDate(b.SortDate);
            const sa = sA ? sA.getTime() : 0;
            const sb = sB ? sB.getTime() : 0;
            if (sa !== sb) return sb - sa;
            return (b.RecordID || 0) - (a.RecordID || 0);
        });
        reportTotalRecords = json.data.totalCount || 0;
        reportSummaryData = json.data.summary || {};

        renderReportTableRows();
        updateReportPaginationControls();
    } catch (err) {
        console.error('Error in loadReportData:', err);
        if (tbody) {
            tbody.innerHTML = `<tr><td colspan="10" style="text-align:center; padding: 24px; color: #ef4444;">Error loading report: ${escapeHtml(err.message)}</td></tr>`;
        }
    }
}

function renderReportTableRows() {
    const tbody = document.getElementById('reportsTableBody');
    if (!tbody) return;

    if (!allReportRecords || allReportRecords.length === 0) {
        tbody.innerHTML = `
            <tr>
                <td colspan="10" style="text-align: center; padding: 40px 20px;">
                    <div style="font-size: 38px; margin-bottom: 8px;">🔍</div>
                    <div style="font-size: 15px; font-weight: 700; color: var(--text-primary);">Koi Record Nahi Mila</div>
                    <div style="font-size: 12.5px; color: var(--text-muted); margin-top: 4px;">Chune gaye filters ya date range me koi entry darj nahi hai. Date ya filter badal kar dekhein.</div>
                </td>
            </tr>
        `;
        updateReportTableStats(0, 0, 0);
        return;
    }

    const startIdx = (reportCurrentPage - 1) * reportPageLimit;
    const html = allReportRecords.map((r, i) => {
        const sNo = startIdx + i + 1;
        const dateStr = r.RecordDate ? formatIndianDate(r.RecordDate) : '-';
        const timeStr = r.RecordTime ? formatTime(r.RecordTime) : (r.SortDate ? formatTime(r.SortDate) : '');
        const mod = r.SourceModule || 'General';
        const modClass = mod.toLowerCase().replace(/\s+/g, '');
        const amount = parseFloat(r.Amount) || 0;
        const profit = parseFloat(r.ProfitOrNet) || 0;

        let amtColor = 'var(--chip-green)';
        let amtSign = '+';
        if (r.EntryType === 'Expense' || r.EntryType === 'Udhaar (Debit)' || r.EntryType === 'Cash Withdrawal' || profit < 0) {
            amtColor = 'var(--chip-red)';
            amtSign = '-';
        } else if (r.EntryType === 'Transfer') {
            amtColor = 'var(--chip-blue)';
            amtSign = '↔';
        }

        let statusBadge = `<span class="badge" style="font-size: 11px;">${escapeHtml(r.Status || 'Done')}</span>`;
        if (r.Status === 'Completed' || r.Status === 'Success') {
            statusBadge = `<span class="badge" style="background: rgba(16, 185, 129, 0.15); color: #34d399; font-size: 11px;">✅ Success</span>`;
        } else if (r.Status === 'Pending' || r.Status === 'Applied' || r.Status === 'In Progress') {
            statusBadge = `<span class="badge" style="background: rgba(245, 158, 11, 0.15); color: #fbbf24; font-size: 11px;">⏳ ${escapeHtml(r.Status)}</span>`;
        } else if (r.Status === 'Failed' || r.Status === 'Rejected') {
            statusBadge = `<span class="badge" style="background: rgba(239, 68, 68, 0.15); color: #f87171; font-size: 11px;">❌ Failed</span>`;
        }

        return `
            <tr>
                <td class="cell-center font-mono" style="vertical-align: middle; text-align: center;">
                    <button type="button" 
                            class="csc-sn-pill uni-sn-pill" 
                            onclick="openUniversalRecordDetail('${escapeInlineArg(r.SourceModule || '')}', ${r.RecordID || 0}, '${escapeInlineArg(r.SNCode || '')}')" 
                            title="Universal Serial No: ${escapeHtml(r.SNCode || ('SN-' + (r.GlobalSerialNo || sNo)))} (Click karke Poori Detail Dekhein)">
                        <i data-lucide="file-text" width="12" height="12"></i>
                        <span>${escapeHtml(r.SNCode || ('SN-' + (r.GlobalSerialNo || sNo)))}</span>
                    </button>
                    ${r.ModuleCode ? `<div style="font-size: 10px; color: var(--text-muted); font-weight: 600; margin-top: 3px;">${escapeHtml(r.ModuleCode)}</div>` : ''}
                </td>
                <td>
                    <div style="font-weight: 600; font-size: 13px;">${dateStr}</div>
                    <div style="font-size: 11px; color: var(--text-muted); display: inline-flex; align-items: center; gap: 3px; margin-top: 2px;">
                        <i data-lucide="clock" width="11" height="11"></i> ${timeStr || '12:00 AM'}
                    </div>
                </td>
                <td class="cell-center">
                    <span class="mod-badge ${modClass}">${escapeHtml(mod)}</span>
                </td>
                <td>
                    <div style="font-weight: 600; font-size: 13.5px; color: var(--text-primary); cursor: pointer;" onclick="openReportItemDetail(${i})" title="Vivran dekhne ke liye click karein">
                        ${escapeHtml(r.Title || '-')}
                    </div>
                    <div style="font-size: 11px; color: var(--text-muted);">
                        ${escapeHtml(r.CategoryOrService || '')}
                    </div>
                </td>
                <td>
                    ${r.CustomerID ? `<button type="button" class="rep-entity-link" onclick="drillReportCustomer(${r.CustomerID})" title="Is grahak ka saara data dekhne ke liye click karein (360°)">${escapeHtml(r.EntityName || '-')}</button>` : `<div style="font-weight: 600; font-size: 13px;">${escapeHtml(r.EntityName || '-')}</div>`}
                    ${r.Phone ? `<div style="font-size: 11px; color: var(--text-muted);">📞 ${escapeHtml(r.Phone)}</div>` : ''}
                </td>
                <td class="font-mono" style="font-size: 12px; color: #38bdf8;">
                    ${r.RefNumber ? `<span style="padding: 2px 6px; border-radius: 4px; background: rgba(56, 189, 248, 0.1); border: 1px solid rgba(56, 189, 248, 0.2);">${escapeHtml(r.RefNumber)}</span>` : '-'}
                </td>
                <td>
                    <span style="font-size: 12px; font-weight: 500; color: var(--text-secondary);">${escapeHtml(r.EntryType || '-')}</span>
                    ${r.AccountName ? `<div style="font-size: 11px; color: var(--text-muted);">${escapeHtml(r.AccountName)}</div>` : ''}
                </td>
                <td style="text-align: right;">
                    <div style="font-weight: 800; font-size: 14.5px; color: ${amtColor};">
                        ${amtSign} ${formatMoney(amount)}
                    </div>
                    ${profit !== 0 && profit !== amount ? `<div style="font-size: 10.5px; color: ${profit > 0 ? '#34d399' : '#f87171'}; font-weight: 600;">Net: ${formatMoney(profit)}</div>` : ''}
                </td>
                <td class="cell-center">${statusBadge}</td>
                <td class="cell-center">
                    <div style="display:inline-flex; align-items:center; justify-content:center; gap:4px; flex-wrap:wrap;">
                        <button class="btn-ghost btn-sm" onclick="openReportItemDetail(${i})" title="Poora Vivran Dekhein" style="color: #6366f1;">
                            <i data-lucide="eye" width="14" height="14"></i>
                        </button>
                        ${r.CustomerID ? `<button class="btn-ghost btn-sm" onclick="drillReportCustomer(${r.CustomerID})" title="Is grahak ka saara data (360°)" style="color:#8b5cf6;"><i data-lucide="user-round-search" width="14" height="14"></i></button>` : ''}
                    </div>
                </td>
            </tr>
        `;
    }).join('');

    tbody.innerHTML = html;
    refreshIcons(tbody);

    const aggAmt = reportSummaryData?.totalAmount || allReportRecords.reduce((s, r) => s + (parseFloat(r.Amount) || 0), 0);
    const aggPrf = reportSummaryData?.totalProfit || allReportRecords.reduce((s, r) => s + (parseFloat(r.ProfitOrNet) || 0), 0);
    updateReportTableStats(reportTotalRecords, aggAmt, aggPrf);
}

function updateReportTableStats(total, sumAmount, sumProfit) {
    const countLbl = document.getElementById('repTableCountLabel');
    if (countLbl) {
        const start = total === 0 ? 0 : (reportCurrentPage - 1) * reportPageLimit + 1;
        const end = Math.min(reportCurrentPage * reportPageLimit, total);
        countLbl.textContent = `Record ${start} se ${end} (Kul Record: ${total})`;
    }

    const sumChip = document.getElementById('repTableSumChip');
    if (sumChip) {
        const curModule = document.getElementById('reportModuleFilter')?.value || 'all';
        const label = curModule === 'all'
            ? 'Kul Karobar (Gross Volume)'
            : (curModule === 'transactions' ? 'Kul Len-Den' :
                curModule === 'bc' ? 'Kul BC Turnover' :
                    curModule === 'csc' ? 'Kul CSC Shulk' :
                        curModule === 'khata' ? 'Kul Khata Rashi' :
                            curModule === 'invoices' ? 'Kul Bill Rashi' :
                                curModule === 'billpay' ? 'Kul Bill Bhugtan' : 'Kul Rashi');
        sumChip.textContent = `${label}: ${formatMoney(sumAmount || 0)}`;
        sumChip.title = curModule === 'all'
            ? 'Sabhi modules ka milakar kul len-den volume (Turnover)'
            : label;
    }

    const prfChip = document.getElementById('repTableProfitChip');
    if (prfChip) {
        if (sumProfit && sumProfit !== 0) {
            prfChip.style.display = 'inline-flex';
            prfChip.textContent = `Net Labh: ${sumProfit >= 0 ? '+' : ''}${formatMoney(sumProfit)}`;
            prfChip.style.color = sumProfit >= 0 ? '#10b981' : '#ef4444';
        } else {
            prfChip.style.display = 'none';
        }
    }
}

function updateReportPaginationControls() {
    const totalPages = Math.ceil(reportTotalRecords / reportPageLimit) || 1;
    const pageBadge = document.getElementById('repCurrentPageBadge');
    const infoLbl = document.getElementById('repPaginationInfo');
    const prevBtn = document.getElementById('repPrevBtn');
    const nextBtn = document.getElementById('repNextBtn');

    if (pageBadge) pageBadge.textContent = `Page ${reportCurrentPage} / ${totalPages}`;
    if (infoLbl) infoLbl.textContent = `Kul ${reportTotalRecords} records me se page ${reportCurrentPage} par hain`;
    if (prevBtn) prevBtn.disabled = reportCurrentPage <= 1;
    if (nextBtn) nextBtn.disabled = reportCurrentPage >= totalPages;
}

function changeReportsPage(delta) {
    const totalPages = Math.ceil(reportTotalRecords / reportPageLimit) || 1;
    const newPage = reportCurrentPage + delta;
    if (newPage >= 1 && newPage <= totalPages) {
        reportCurrentPage = newPage;
        loadReportData();
        const mc = document.getElementById('repTableContainer');
        if (mc) mc.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
}

function switchReportModule(mod, btn) {
    currentReportModule = mod;
    reportCurrentPage = 1;

    document.querySelectorAll('.reports-module-tabs .rep-tab').forEach(b => b.classList.remove('active'));
    if (btn) btn.classList.add('active');

    const tableHost = document.getElementById('repTableContainer');
    const filtersCard = document.getElementById('repFiltersCard');
    const chartsView = document.getElementById('repChartsContainer');

    if (mod === 'charts') {
        if (tableHost) tableHost.style.display = 'none';
        if (filtersCard) filtersCard.style.display = 'none';
        if (chartsView) chartsView.style.display = 'block';
        loadReportCharts();
    } else {
        if (tableHost) tableHost.style.display = 'block';
        if (filtersCard) filtersCard.style.display = 'block';
        if (chartsView) chartsView.style.display = 'none';
        updateReportTypeFilterOptions();
        loadReportData();
    }
}

function setReportsDatePreset(preset, btn) {
    currentReportPreset = preset;
    document.querySelectorAll('.date-presets-group .preset-pill').forEach(b => b.classList.remove('active'));
    if (btn) btn.classList.add('active');

    const now = new Date();
    const y = now.getFullYear();
    const m = now.getMonth();
    const d = now.getDate();

    function toYMD(dt) {
        return toLocalYMD(dt);
    }

    if (preset === 'today') {
        reportStartDate = toYMD(now);
        reportEndDate = toYMD(now);
    } else if (preset === 'yesterday') {
        const yest = new Date(y, m, d - 1);
        reportStartDate = toYMD(yest);
        reportEndDate = toYMD(yest);
    } else if (preset === 'this_week') {
        const dayOfWeek = now.getDay();
        const monday = new Date(y, m, d - (dayOfWeek === 0 ? 6 : dayOfWeek - 1));
        reportStartDate = toYMD(monday);
        reportEndDate = toYMD(now);
    } else if (preset === 'this_month') {
        reportStartDate = toYMD(new Date(y, m, 1));
        reportEndDate = toYMD(now);
    } else if (preset === 'last_month') {
        const firstDayLastMonth = new Date(y, m - 1, 1);
        const lastDayLastMonth = new Date(y, m, 0);
        reportStartDate = toYMD(firstDayLastMonth);
        reportEndDate = toYMD(lastDayLastMonth);
    } else if (preset === 'this_year') {
        reportStartDate = toYMD(new Date(y, 0, 1));
        reportEndDate = toYMD(now);
    } else if (preset === 'all') {
        reportStartDate = '';
        reportEndDate = '';
    }

    const startInp = document.getElementById('repStartDate');
    const endInp = document.getElementById('repEndDate');
    if (startInp) startInp.value = reportStartDate;
    if (endInp) endInp.value = reportEndDate;

    reportCurrentPage = 1;
    refreshReportsData();
}

function onCustomDateRangeChanged() {
    document.querySelectorAll('.date-presets-group .preset-pill').forEach(b => b.classList.remove('active'));
    currentReportPreset = 'custom';
    reportStartDate = document.getElementById('repStartDate')?.value || '';
    reportEndDate = document.getElementById('repEndDate')?.value || '';
    reportCurrentPage = 1;
    refreshReportsData();
}

function debounceReportsSearch() {
    if (reportSearchDebounceTimer) clearTimeout(reportSearchDebounceTimer);
    reportSearchDebounceTimer = setTimeout(() => {
        reportCurrentPage = 1;
        loadReportData();
    }, 280);
}

function applyReportsFilters() {
    reportCurrentPage = 1;
    loadReportData();
}

function resetReportsFilters() {
    const sInp = document.getElementById('repSearchInput');
    if (sInp) sInp.value = '';
    const tSel = document.getElementById('repTypeFilter');
    if (tSel) tSel.value = 'all';
    const aSel = document.getElementById('repAccountFilter');
    if (aSel) aSel.value = 'all';
    const cSel = document.getElementById('repCategoryFilter');
    if (cSel) cSel.value = 'all';
    const stSel = document.getElementById('repStatusFilter');
    if (stSel) stSel.value = 'all';
    const custSel = document.getElementById('repCustomerFilter');
    if (custSel) {
        custSel.value = 'all';
        if (custSel._ssInstance && typeof custSel._ssInstance.syncFromNative === 'function') {
            try { custSel._ssInstance.syncFromNative(); } catch (e) { }
        }
    }

    reportCurrentPage = 1;
    loadReportData();
}

async function refreshReportsData() {
    showUniversalLoader('Reports Update Ho Rahi Hain...', 'Live database se data sync kiya ja raha hai...', false, 0.4);
    try {
        await Promise.all([
            loadReportKPIs(),
            currentReportModule === 'charts' ? loadReportCharts() : loadReportData()
        ]);
        showToast('✅ Report data safalta se refresh ho gaya!', 'success', 'Reports Live');
    } catch (e) {
        showToast('Error: ' + e.message, 'error');
    } finally {
        hideUniversalLoader();
    }
}

// ============================================================================
// VISUAL CHARTS & DEEP ANALYTICS ENGINE
// ============================================================================
async function loadReportCharts() {
    try {
        const year = new Date().getFullYear();
        const yearLbl = document.getElementById('repAuditYearLabel');
        if (yearLbl) yearLbl.textContent = year;

        const res = await fetch(`${API}/reports/analytics?year=${year}`);
        const json = await res.json();
        if (!json.success || !json.data) return;

        const d = json.data;

        // 1. Bar Chart: Monthly Financial Trends (Income vs Expense vs Profit)
        const trendsCanvas = document.getElementById('repYearlyTrendsChart');
        if (trendsCanvas && typeof Chart !== 'undefined') {
            if (reportCharts.trends) reportCharts.trends.destroy();

            const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
            const incomeData = (d.monthlyTrends || []).map(m => m.TotalIncome || 0);
            const expenseData = (d.monthlyTrends || []).map(m => m.TotalExpense || 0);
            const profitData = (d.monthlyTrends || []).map(m => m.NetProfit || 0);

            reportCharts.trends = new Chart(trendsCanvas, {
                type: 'bar',
                data: {
                    labels: monthNames,
                    datasets: [
                        {
                            label: 'Total Inflow (₹)',
                            data: incomeData,
                            backgroundColor: 'rgba(16, 185, 129, 0.7)',
                            borderColor: '#10b981',
                            borderWidth: 1.5,
                            borderRadius: 4
                        },
                        {
                            label: 'Total Outflow (₹)',
                            data: expenseData,
                            backgroundColor: 'rgba(239, 68, 68, 0.7)',
                            borderColor: '#ef4444',
                            borderWidth: 1.5,
                            borderRadius: 4
                        },
                        {
                            label: 'Net Profit (₹)',
                            data: profitData,
                            backgroundColor: 'rgba(99, 102, 241, 0.8)',
                            borderColor: '#6366f1',
                            borderWidth: 1.5,
                            borderRadius: 4
                        }
                    ]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: {
                        legend: { position: 'top', labels: { color: '#94a3b8', font: { family: 'Segoe UI', size: 12 } } },
                        tooltip: {
                            callbacks: {
                                label: ctx => `${ctx.dataset.label}: ₹${Number(ctx.raw || 0).toLocaleString('en-IN')}`
                            }
                        }
                    },
                    scales: {
                        x: { grid: { color: 'rgba(255, 255, 255, 0.05)' }, ticks: { color: '#94a3b8' } },
                        y: {
                            grid: { color: 'rgba(255, 255, 255, 0.05)' },
                            ticks: {
                                color: '#94a3b8',
                                callback: val => `₹${Number(val).toLocaleString('en-IN')}`
                            }
                        }
                    }
                }
            });
        }

        // 2. Pie/Doughnut Chart: Top Expense Categories
        const catCanvas = document.getElementById('repCategoryPieChart');
        if (catCanvas && typeof Chart !== 'undefined') {
            if (reportCharts.catPie) reportCharts.catPie.destroy();

            const cats = d.topCategories || [];
            const catLabels = cats.map(c => c.CategoryName);
            const catValues = cats.map(c => c.TotalAmount);
            const catColors = cats.map(c => c.Color || '#6366f1');

            reportCharts.catPie = new Chart(catCanvas, {
                type: 'doughnut',
                data: {
                    labels: catLabels.length > 0 ? catLabels : ['No Expenses Yet'],
                    datasets: [{
                        data: catValues.length > 0 ? catValues : [1],
                        backgroundColor: catColors.length > 0 ? catColors : ['#334155'],
                        borderWidth: 2,
                        borderColor: 'var(--bg-card, #111827)'
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: {
                        legend: { position: 'right', labels: { color: '#94a3b8', font: { family: 'Segoe UI', size: 11.5 } } },
                        tooltip: {
                            callbacks: {
                                label: ctx => ` ${ctx.label}: ₹${Number(ctx.raw || 0).toLocaleString('en-IN')}`
                            }
                        }
                    }
                }
            });
        }

        // 3. Bar Chart: Top CSC Services
        const cscCanvas = document.getElementById('repCSCServicesChart');
        if (cscCanvas && typeof Chart !== 'undefined') {
            if (reportCharts.csc) reportCharts.csc.destroy();

            const cscList = d.topCSCServices || [];
            const cscLabels = cscList.map(s => s.ServiceType);
            const cscRevs = cscList.map(s => s.TotalRevenue);
            const cscProfits = cscList.map(s => s.TotalProfit);

            reportCharts.csc = new Chart(cscCanvas, {
                type: 'bar',
                data: {
                    labels: cscLabels.length > 0 ? cscLabels : ['No Data'],
                    datasets: [
                        {
                            label: 'Total Revenue (₹)',
                            data: cscRevs.length > 0 ? cscRevs : [0],
                            backgroundColor: 'rgba(6, 182, 212, 0.7)',
                            borderColor: '#06b6d4',
                            borderWidth: 1.5,
                            borderRadius: 4
                        },
                        {
                            label: 'Net Profit (₹)',
                            data: cscProfits.length > 0 ? cscProfits : [0],
                            backgroundColor: 'rgba(16, 185, 129, 0.8)',
                            borderColor: '#10b981',
                            borderWidth: 1.5,
                            borderRadius: 4
                        }
                    ]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    indexAxis: 'y',
                    plugins: {
                        legend: { position: 'top', labels: { color: '#94a3b8' } }
                    },
                    scales: {
                        x: { grid: { color: 'rgba(255, 255, 255, 0.05)' }, ticks: { color: '#94a3b8' } },
                        y: { grid: { color: 'rgba(255, 255, 255, 0.05)' }, ticks: { color: '#94a3b8' } }
                    }
                }
            });
        }

        // 4. Doughnut Chart: BC Banking Volume
        const bcCanvas = document.getElementById('repBCVolumeChart');
        if (bcCanvas && typeof Chart !== 'undefined') {
            if (reportCharts.bc) reportCharts.bc.destroy();

            const bcList = d.bcServiceBreakdown || [];
            const bcLabels = bcList.map(s => s.ServiceType);
            const bcVolumes = bcList.map(s => s.TotalVolume);

            reportCharts.bc = new Chart(bcCanvas, {
                type: 'doughnut',
                data: {
                    labels: bcLabels.length > 0 ? bcLabels : ['No BC Data'],
                    datasets: [{
                        data: bcVolumes.length > 0 ? bcVolumes : [1],
                        backgroundColor: ['#3b82f6', '#10b981', '#f59e0b', '#8b5cf6', '#ec4899', '#06b6d4'],
                        borderWidth: 2,
                        borderColor: 'var(--bg-card, #111827)'
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: {
                        legend: { position: 'right', labels: { color: '#94a3b8', font: { family: 'Segoe UI', size: 11.5 } } },
                        tooltip: {
                            callbacks: {
                                label: ctx => ` ${ctx.label}: ₹${Number(ctx.raw || 0).toLocaleString('en-IN')}`
                            }
                        }
                    }
                }
            });
        }

        // 5. Month-by-Month Detailed Financial Audit Table
        const auditTbody = document.getElementById('repMonthlyAuditTableBody');
        if (auditTbody) {
            const monthNames = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
            const auditRows = (d.monthlyTrends || []).map((m) => {
                const profit = m.NetProfit || 0;
                return `
                    <tr>
                        <td style="font-weight: 700; color: var(--text-primary);">${monthNames[m.MonthNumber - 1]}</td>
                        <td style="text-align: right; color: #10b981;">₹${Number(m.CashbookIncome || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 })}</td>
                        <td style="text-align: right; color: #ef4444;">₹${Number(m.CashbookExpense || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 })}</td>
                        <td style="text-align: right; color: #06b6d4;">₹${Number(m.CSCProfit || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 })}</td>
                        <td style="text-align: right; color: #3b82f6;">₹${Number(m.BCCommission || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 })}</td>
                        <td style="text-align: right; font-weight: 700; color: #34d399;">₹${Number(m.TotalIncome || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 })}</td>
                        <td style="text-align: right; font-weight: 700; color: #f87171;">₹${Number(m.TotalExpense || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 })}</td>
                        <td style="text-align: right; font-weight: 800; color: ${profit >= 0 ? '#10b981' : '#ef4444'};">
                            ${profit >= 0 ? '+' : ''}₹${Number(profit).toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                        </td>
                    </tr>
                `;
            }).join('');

            auditTbody.innerHTML = auditRows || '<tr><td colspan="8" style="text-align:center; padding: 16px;">No audit records found</td></tr>';
        }
    } catch (err) {
        console.error('Error rendering report charts:', err);
    }
}

