function testGrabberInApp() {
    const modalEl = document.getElementById('extensionModal') || document.getElementById('bookmarkletModal');
    if (modalEl) closeModal(modalEl.id);

    const input = document.getElementById('cmSampleTestInput');
    const text = (input && input.value ? input.value.trim() : '') || SAMPLE_AEPS_RECEIPT_TEXT;

    let parsed = null;
    if (typeof parseCSCApplication === 'function' && /आवेदन|प्रमाण|eDistrict|Aadhaar.*Card|PAN.*Card/i.test(text)) {
        parsed = parseCSCApplication(text);
        parsed.isCSCApplication = true;
    } else if (typeof parseReceipt === 'function') {
        parsed = parseReceipt(text);
    } else {
        const amtM = text.match(/(?:Rs\.?|INR|₹|Amount\s*[:=\t ]+)\s*([0-9,]+)/i);
        const bankM = text.match(/Bank\s*Name\s*[:=\t ]+([^\n\r]+)/i);
        const aadhM = text.match(/Aadhaar.*[:=\t ]+([xX0-9 -]+)/i);
        const mobM = text.match(/Mobile.*[:=\t ]+([0-9]{10})/i);
        const tidM = text.match(/(?:RRN|Tid|Txn\s*ID|Ref).*[:=\t ]+([0-9A-Za-z]+)/i);
        const nameM = text.match(/(?:Agent Name|Customer Name|Name)\s*[:=\t ]+([^\n\r]+)/i);
        const accM = text.match(/(?:Account\s*(?:No\.?|Number)|A\/c\s*No\.?)\s*[:=\t ]+([0-9A-Za-z]+)/i);

        const rawAmt = amtM ? parseFloat(amtM[1].replace(/,/g, '')) : 3000;
        const sType = detectBCServiceType(text);
        parsed = {
            ServiceType: sType,
            Amount: rawAmt,
            CommissionEarned: calculateDigipayCommission(rawAmt),
            BankName: bankM ? bankM[1].trim() : 'State Bank of India',
            Aadhaar: aadhM ? aadhM[1].replace(/\D/g, '').slice(-4) : '4999',
            Mobile: mobM ? mobM[1] : '9999999999',
            RRN_UTR: tidM ? tidM[1].trim() : '628617296619',
            AccountNumber: accM ? accM[1].trim() : '',
            CustomerName: nameM ? nameM[1].trim() : 'Walk-in Customer'
        };
    }

    handleGrabbedExtensionData(parsed);
}

// ============================================================================
// 🧩 DIRECT EXTENSION INTEGRATION (NO SEPARATE MODAL NEEDED!)
// Extension se click karne par project ka native modal seedha khulta hai
// saare logic, customer linking, family picker, commission calculation ke saath.
// ============================================================================
function handleGrabbedExtensionData(data) {
    if (!data) data = { ServiceType: 'Cash Withdrawal' };
    if (data.data) data = data.data;

    // If it's a citizen service application
    if (data.isCSCApplication || data.AckNumber || data.type === 'csc' ||
        (data.ServiceType && (data.ServiceType.includes('Certificate') || data.ServiceType.includes('PAN') || data.ServiceType.includes('Ration')))) {
        openGrabbedCSCModal(data);
    } else {
        openGrabbedBCModal(data);
    }
}

function openGrabbedBCModal(data = {}) {
    // 1. Switch to BC page so view is active
    const alreadyOnBC = !!(document.getElementById('page-bc') &&
        document.getElementById('page-bc').classList.contains('active'));
    if (typeof showPage === 'function') {
        showPage('bc');
    }

    // 2. Open project's native BC modal — delay agar page switch ho raha ho
    const delay = alreadyOnBC ? 0 : 250;
    let sType = data.ServiceType || 'Cash Withdrawal';
    if (sType === 'Aadhaar Pay') sType = 'Cash Withdrawal';
    setTimeout(() => {
        openBCModal(sType);

        // 3. Fill transaction amount & trigger input for live calculations
        if (data.Amount) {
            const amtEl = document.getElementById('bcAmount');
            if (amtEl) {
                amtEl.value = data.Amount;
                amtEl.dispatchEvent(new Event('input', { bubbles: true }));
            }
        }

        if (data.CommissionEarned !== undefined && data.CommissionEarned !== null && data.CommissionEarned !== '') {
            const commEl = document.getElementById('bcCommission');
            if (commEl) {
                commEl.value = parseFloat(data.CommissionEarned).toFixed(2);
                // Extension se aayi asli commission — auto-slab ise overwrite na kare
                commEl.setAttribute('data-user-overridden', '1');
            }
        }

        if (data.BankName) {
            const bankEl = document.getElementById('bcBankName');
            if (bankEl) bankEl.value = data.BankName;
        }

        const rrnVal = data.RRN_UTR || data.TxnId || data.RRN;
        if (rrnVal) {
            const rrnEl = document.getElementById('bcRRN');
            if (rrnEl) rrnEl.value = rrnVal;
        }

        if (data.AccountNumber) {
            const accEl = document.getElementById('bcAccountNumber');
            if (accEl) accEl.value = data.AccountNumber;
        }

        if (data.TransDate) {
            const dateEl = document.getElementById('bcTransDate');
            if (dateEl) dateEl.value = data.TransDate;
        }

        // 4. SMART CUSTOMER MATCHING & AUTO-LINK
        // Match with project's existing customer database (by Aadhaar / Phone / Name)
        let customerMatched = false;
        const cleanAadhaar = data.Aadhaar ? String(data.Aadhaar).replace(/\D/g, '') : '';
        const cleanMobile = data.Mobile ? String(data.Mobile).replace(/\D/g, '').slice(-10) : '';

        if (Array.isArray(allCustomersData) && allCustomersData.length > 0) {
            let matchedCustomer = null;

            // Priority 1: Full 12-digit Aadhaar
            if (cleanAadhaar.length === 12) {
                matchedCustomer = allCustomersData.find(c => c.AadhaarNumber && c.AadhaarNumber.replace(/\D/g, '') === cleanAadhaar);
            }
            // Priority 2: Mobile match + last 4 digits Aadhaar
            if (!matchedCustomer && cleanMobile && cleanAadhaar.length >= 4) {
                const last4 = cleanAadhaar.slice(-4);
                matchedCustomer = allCustomersData.find(c => {
                    const cPhone = c.Phone ? String(c.Phone).replace(/\D/g, '').slice(-10) : '';
                    const cUid = c.AadhaarNumber ? String(c.AadhaarNumber).replace(/\D/g, '').slice(-4) : '';
                    return cPhone === cleanMobile && cUid === last4;
                });
            }
            // Priority 3: Mobile match
            if (!matchedCustomer && cleanMobile.length === 10) {
                matchedCustomer = allCustomersData.find(c => {
                    const cPhone = c.Phone ? String(c.Phone).replace(/\D/g, '').slice(-10) : '';
                    return cPhone === cleanMobile;
                });
            }
            // Priority 4: Last 4 digits Aadhaar
            if (!matchedCustomer && cleanAadhaar.length === 4) {
                const matches = allCustomersData.filter(c => {
                    const cUid = c.AadhaarNumber ? String(c.AadhaarNumber).replace(/\D/g, '').slice(-4) : '';
                    return cUid === cleanAadhaar;
                });
                if (matches.length === 1) matchedCustomer = matches[0];
            }

            if (matchedCustomer) {
                customerMatched = true;
                const sel = document.getElementById('bcCustomerSelect');
                if (sel) {
                    if (sel._ssInstance) {
                        sel._ssInstance.setValue(matchedCustomer.CustomerID);
                    } else {
                        sel.value = matchedCustomer.CustomerID;
                    }
                }
                if (typeof onBCCustomerSelected === 'function') {
                    onBCCustomerSelected();
                }
            }
        }

        // 5. If customer not already in database, fill raw extracted values
        if (!customerMatched) {
            if (data.CustomerName && data.CustomerName !== 'Walk-in Customer') {
                const nameEl = document.getElementById('bcCustomerName');
                if (nameEl) nameEl.value = data.CustomerName;
            }
            if (cleanMobile) {
                const phoneEl = document.getElementById('bcCustomerPhone');
                if (phoneEl) {
                    phoneEl.value = cleanMobile;
                    if (typeof handleBCPhoneInput === 'function') handleBCPhoneInput(phoneEl);
                }
            }
            if (data.Aadhaar) {
                const aadhEl = document.getElementById('bcAadhaar');
                if (aadhEl) {
                    aadhEl.value = data.Aadhaar;
                    if (typeof handleBCAadhaarInput === 'function') handleBCAadhaarInput(aadhEl);
                }
            }
            if (data.DateOfBirth || data.DOB) {
                const dobEl = document.getElementById('bcCustomerDob');
                if (dobEl) dobEl.value = String(data.DateOfBirth || data.DOB).split('T')[0];
            }
        }

        // 6. Recalculate live profit & refresh icons
        if (typeof calculateBCProfit === 'function') calculateBCProfit();
        refreshIcons(document.getElementById('bcModal'));

        // 7. Success toast feedback
        const amtDisplay = data.Amount ? (' ₹' + Number(data.Amount).toLocaleString('en-IN')) : '';
        showToast(`⚡ Extension se receipt data direct modal me load ho gaya!${amtDisplay} Review karke Save karein.`, 'success');
    }, delay);
}

function openGrabbedCSCModal(data = {}) {
    if (typeof window.handleExtensionGrabbedEntry === 'function') {
        window.handleExtensionGrabbedEntry({ type: 'CSC', data });
        return;
    }
    const alreadyOnCSC = !!(document.getElementById('page-csc') &&
        document.getElementById('page-csc').classList.contains('active'));
    if (typeof showPage === 'function') {
        showPage('csc');
    }
    const delay = alreadyOnCSC ? 0 : 250;
    setTimeout(() => {
        openNewCSCModal();

        if (data.AckNumber) {
            const appNoEl = document.getElementById('cscAckNumber');
            if (appNoEl) appNoEl.value = data.AckNumber;
        }
        if (data.CustomerName) {
            const nameEl = document.getElementById('cscCustName');
            if (nameEl) nameEl.value = data.CustomerName;
        }
        if (data.CustomerPhone) {
            const phoneEl = document.getElementById('cscCustPhone');
            if (phoneEl) {
                phoneEl.value = data.CustomerPhone;
                if (typeof handleCSCPhoneInput === 'function') handleCSCPhoneInput(phoneEl);
            }
        }
        if (data.CustomerAadhaar) {
            const aadhEl = document.getElementById('cscCustAadhaar');
            if (aadhEl) {
                aadhEl.value = data.CustomerAadhaar;
                if (typeof handleCSCAadhaarInput === 'function') handleCSCAadhaarInput(aadhEl);
            }
        }
        if (data.DateOfBirth || data.DOB) {
            const dobEl = document.getElementById('cscCustDob');
            if (dobEl) dobEl.value = String(data.DateOfBirth || data.DOB).split('T')[0];
        }
        if (data.GovtFee != null) {
            const gFee = document.getElementById('cscGovtFee');
            if (gFee) gFee.value = data.GovtFee;
        }
        if (data.OperatorFee != null) {
            const oFee = document.getElementById('cscOperatorFee');
            if (oFee) oFee.value = data.OperatorFee;
        }
        if (data.PortalName) {
            const pEl = document.getElementById('cscPortalName');
            if (pEl) pEl.value = data.PortalName;
        }
        if (typeof calculateCSCFees === 'function') calculateCSCFees();
        refreshIcons(document.getElementById('cscNewAppModal'));

        showToast('⚡ CSC Aavedan direct modal me load ho gaya! Review karke Save karein.', 'success');
    }, delay);
}

// Event & PostMessage Listeners for Chrome Extension
window.addEventListener('message', (event) => {
    if (event.data && event.data.type === 'CM_OPEN_GRABBED_MODAL') {
        handleGrabbedExtensionData(event.data.data);
    }
});
document.addEventListener('CM_OPEN_GRABBED_MODAL', (e) => {
    handleGrabbedExtensionData(e.detail);
});

// URL Hash Grabbed Trigger (Jab extension se naye tab me open ho)
function checkUrlForGrabbedData() {
    try {
        const hash = window.location.hash || '';
        if (hash.startsWith('#grabbed=')) {
            const raw = decodeURIComponent(hash.substring('#grabbed='.length));
            const payload = JSON.parse(raw);
            history.replaceState(null, '', window.location.pathname + window.location.search);
            setTimeout(() => {
                if (typeof window.handleExtensionGrabbedEntry === 'function' && payload && (payload.data || payload.type)) {
                    window.handleExtensionGrabbedEntry(payload);
                } else if (typeof handleGrabbedExtensionData === 'function') {
                    handleGrabbedExtensionData((payload && payload.data) ? payload.data : payload);
                }
            }, 300);
        }
    } catch (e) {
        console.error('Error reading grabbed data from hash:', e);
    }
}
window.addEventListener('DOMContentLoaded', checkUrlForGrabbedData);
window.addEventListener('hashchange', checkUrlForGrabbedData);
setTimeout(checkUrlForGrabbedData, 400);

// Cross-World bridge listener (Chrome content script isolated world -> web app main world)
window.addEventListener('message', (e) => {
    if (e.data && e.data.type === 'cm-grabber-fill-project' && e.data.payload) {
        if (typeof window.handleExtensionGrabbedEntry === 'function') {
            window.handleExtensionGrabbedEntry(e.data.payload);
        }
    }
});

