// ─────────────────────────────────────────────────────────────────────────────
// 🔗 CHROME EXTENSION BRIDGE — Isolated World → Main World
// Extension ka content.js "isolated world" me chalta hai, isliye wo directly
// app ke functions call nahi kar sakta. Hum CustomEvent ka use karte hain.
// Extension 'cm-extension-open-modal' event dispatch karta hai →
// yahan listener pakad kar native modal open kar deta hai.
// ─────────────────────────────────────────────────────────────────────────────
document.addEventListener('cm-extension-open-modal', function (e) {
    const mode = (e && e.detail && e.detail.mode) || 'csc';
    if (mode === 'aeps') {
        // AEPS / Cash Withdrawal — same modal jo BC page par khulta hai
        if (typeof openGrabbedBCModal === 'function') {
            openGrabbedBCModal({ ServiceType: 'Cash Withdrawal' });
        }
    } else {
        // Naya CSC Aavedan — same modal jo CSC Work Tracker me khulta hai
        if (typeof openGrabbedCSCModal === 'function') {
            openGrabbedCSCModal({});
        } else if (typeof openNewCSCModal === 'function') {
            openNewCSCModal();
        }
    }
});

