// 4. Upload & Import Customers (Settings Pane)
async function uploadCustomerExcel() {
    const input = document.getElementById('custExcelFileInput');
    if (!input || !input.files || input.files.length === 0) {
        showToast('Kripya pehle Excel file chunein', 'warning');
        return;
    }

    const file = input.files[0];
    const btn = document.getElementById('btnUploadCustExcel');
    const origText = btn ? btn.innerHTML : '';
    if (btn) {
        btn.disabled = true;
        btn.innerHTML = '<i data-lucide="loader-2" class="spin"></i> Customers Import Ho Rahe Hain...';
        lucide.createIcons();
    }

    const formData = new FormData();
    formData.append('file', file);

    try {
        const res = await fetch(`${API}/customers/import/excel`, {
            method: 'POST',
            body: formData
        });
        const data = await res.json();

        if (data.success) {
            showToast(data.message || 'Customers kamyabi se import huye! ✅', 'success');
            renderCustomerImportResults(data, 'cust');
            if (typeof loadCustomersPage === 'function') loadCustomersPage();
        } else {
            showToast(`Import Error: ${data.error || 'Server error'}`, 'error');
        }
    } catch (err) {
        console.error('Customer Excel import failed:', err);
        showToast('Excel upload me network error aaya', 'error');
    } finally {
        if (btn) {
            btn.disabled = false;
            btn.innerHTML = origText;
            lucide.createIcons();
        }
    }
}

// 5. CSC Excel Export
function exportCSCExcel() {
    showToast('CSC Work Tracker Excel export shuru ho raha hai... 📊', 'info');
    const params = new URLSearchParams();

    // Filters table ke live state se lo (DOM me 'cscStatusFilter'/'cscServiceFilter'
    // jaise koi select element exist nahi karta - sirf tabs aur chips hain).
    const statusVal = (cscCurrentFilterStatus && cscCurrentFilterStatus !== 'all') ? cscCurrentFilterStatus : '';
    const servVal = (cscCurrentFilterService && cscCurrentFilterService !== 'all') ? cscCurrentFilterService : '';
    const payVal = (cscCurrentFilterPayment && cscCurrentFilterPayment !== 'all') ? cscCurrentFilterPayment : '';
    const qVal = (cscCurrentSearchQuery || '').trim();

    // 'pending_and_process' ek UI-only value hai - server ko 'ActivePending' chahiye
    if (statusVal === 'pending_and_process') params.append('status', 'ActivePending');
    else if (statusVal) params.append('status', statusVal);

    if (servVal) params.append('serviceType', servVal);
    if (payVal === 'due' || payVal === 'paid') params.append('paymentStatus', payVal);
    if (qVal) params.append('q', qVal);

    const qs = params.toString();
    window.open(`${API}/csc/export/excel${qs ? '?' + qs : ''}`, '_blank');
}

