// 9. Render Import Results Helper (Customers)
function renderCustomerImportResults(data, prefix = 'cust') {
    const box = document.getElementById(`${prefix}ImportResultBox`) || document.getElementById('quickCustResultBox');
    if (!box) return;
    box.style.display = 'block';

    const totalEl = document.getElementById(`${prefix}StatTotal`) || document.getElementById('quickCustStatTotal');
    const impEl = document.getElementById(`${prefix}StatImported`) || document.getElementById('quickCustStatImported');
    const skipEl = document.getElementById(`${prefix}StatSkipped`) || document.getElementById('quickCustStatSkipped');
    const errEl = document.getElementById(`${prefix}StatErrors`) || document.getElementById('quickCustStatErrors');

    if (totalEl) totalEl.textContent = data.totalRows || 0;
    if (impEl) impEl.textContent = data.importedCount || 0;
    if (skipEl) skipEl.textContent = data.skippedCount || 0;
    if (errEl) errEl.textContent = data.errorCount || 0;

    // Skipped list
    const skipBox = document.getElementById(`${prefix}SkippedContainer`) || document.getElementById('quickCustSkippedBox');
    const skipList = document.getElementById(`${prefix}SkippedList`) || document.getElementById('quickCustSkippedList');

    if (data.skipped && data.skipped.length > 0) {
        if (skipBox) skipBox.style.display = 'block';
        if (skipList) {
            skipList.innerHTML = data.skipped.map(s => `
                <div class="excel-log-item">
                    <div>
                        <b>Row ${s.row}:</b> ${escapeHtml(s.name || '')} 
                        <span style="color: #94a3b8; font-size: 11px;">(${s.phone ? '📞 ' + s.phone : ''}${s.aadhaar ? ' | 🪪 ' + s.aadhaar : ''})</span>
                    </div>
                    <span style="color: #fbbf24; font-size: 11px; text-align: right;">${escapeHtml(s.reason)}</span>
                </div>
            `).join('');
        }
    } else {
        if (skipBox) skipBox.style.display = 'none';
    }

    // Imported list
    const impBox = document.getElementById(`${prefix}ImportedContainer`);
    const impList = document.getElementById(`${prefix}ImportedList`);
    if (impBox && impList && data.imported && data.imported.length > 0) {
        impBox.style.display = 'block';
        impList.innerHTML = data.imported.map(m => `
            <div class="excel-log-item">
                <div>
                    <b>#${m.id}</b> — ${escapeHtml(m.name)} 
                    <span style="font-size: 11px; color: #34d399; margin-left: 6px;">(${m.relationship || 'Self'})</span>
                </div>
                <span style="color: #94a3b8; font-size: 11px;">${m.phone ? '📞 ' + m.phone : ''}</span>
            </div>
        `).join('');
    } else if (impBox) {
        impBox.style.display = 'none';
    }

    lucide.createIcons();
}

