// 11. Generic Drag and Drop Helpers
function handleDragOver(e, el) {
    e.preventDefault();
    e.stopPropagation();
    if (el) el.classList.add('dragover');
}

function handleDragLeave(e, el) {
    e.preventDefault();
    e.stopPropagation();
    if (el) el.classList.remove('dragover');
}

function handleDropFile(e, inputId, badgeId, btnId) {
    e.preventDefault();
    e.stopPropagation();
    const el = e.currentTarget;
    if (el) el.classList.remove('dragover');

    const dt = e.dataTransfer;
    if (!dt || !dt.files || dt.files.length === 0) return;

    const file = dt.files[0];
    const input = document.getElementById(inputId);
    if (input) {
        const dataTransfer = new DataTransfer();
        dataTransfer.items.add(file);
        input.files = dataTransfer.files;

        if (inputId.includes('Cust')) {
            if (inputId.startsWith('quick')) handleQuickCustomerFileSelect(input);
            else handleCustomerExcelSelect(input);
        } else {
            if (inputId.startsWith('quick')) handleQuickCSCFileSelect(input);
            else handleCSCExcelSelect(input);
        }
    }
}

